pure elemental real function cbrt(x)
implicit none
real, intent(in) :: x
real :: r, nswc_ai_r4
!-----------------------------------------------------------------------
!                   Cube root of a real number
!-----------------------------------------------------------------------
nswc_ai_r4 = x
if ( nswc_ai_r4 < 0 ) go to 30
if ( nswc_ai_r4 == 0 ) go to 10
go to 20
10 cbrt = 0.0
return
20 r = log(x)/3.0
cbrt = exp(r)
return
30 r = log(-x)/3.0
cbrt = -exp(r)
end function cbrt

