!
nswc_ai_r8 = x
if ( nswc_ai_r8 < 0 ) go to 30
if ( nswc_ai_r8 == 0 ) go to 10
go to 20
10 dcbrt = 0.d0
return
20 r = log(x)/3.d0
dcbrt = exp(r)
return
30 r = log(-x)/3.d0
dcbrt = -exp(r)
end function dcbrt

