if ( nswc_ai_r4 < 0 ) go to 6
if ( nswc_ai_r4 == 0 ) go to 8
go to 7
6 artnq = atan(y/x) + 6.2831853071795
return
7 artnq = atan(y/x)
return
8 artnq = 0.
end function artnq

