20 s = ((((((a2(1)*x + a2(2))*x + a2(3))*x + a2(4))*x &
   & + a2(5))*x + a2(6))*x + a2(7))
t = ((((((b2(1)*x + b2(2))*x + b2(3))*x + b2(4))*x &
   & + b2(5))*x + b2(6))*x + 1.d0)
