      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-----------------------------------------------------------------------
!             Computation of erf(x + h) - erf(x - h)
!-----------------------------------------------------------------------
!     c = 2/sqrt(pi)
!     p = ln(9*sqrt(pi))
!---------------------
!---------------------
!
!     **** eps is a machine dependent constant. Eps is the
!          smallest number such that 1.0 + eps .GT. 1.0 .
!
eps = spmpar(1)
!
!---------------------
aerf = 0.0
if (h == 0.0) return
!
ah = abs(h)
ax = abs(x)
xph = ax + ah
xmh = ax - ah
!
t = max(ah,ax)
t = t*t
if (1.6*t*t < eps) go to 140
if ((ax*ah)**2 < 0.5*eps) go to 150
if (ax <= ah) go to 100
!
if (xmh < 9.0) go to 5
if (xmh*xmh + p > -exparg(1)) return
5 if (4.0*ah*ax > -epsln(0)) go to 120
!
if (ax > 3.0*ah) go to 10
if (xph < 1.0) go to 110
go to 130
!-------------------------------------------------
!        For (ax less than or equal to .40)
!-------------------------------------------------
10 e = max(1.e-15,eps)
if (ax > 0.40) go to 30
h2 = xph*xph
a2 = xmh*xmh
x2 = ax + ax
st = 1.
hf = xmh
n = 0
n1 = 1
dn2 = 1.
s = 0.
20 n = n + 1
n1 = n1 + 2
dn2 = -dn2/n
st = h2*st + x2*hf
hf = a2*hf
t = st*dn2/n1
s = s + t
if (abs(t) > e*abs(s)) go to 20
s = 0.5 + (s + 0.5)
aerf = 2.0*c*ah*s
go to 45
!-------------------------------------------------
!        For (ax greater than .40)
!-------------------------------------------------
30 n = 1
j = 0
h2 = 0.
z = exp(-0.5*ax*ax)
u = 2.0*ah*c*z
h3 = z
v = 2.0*h*h
hf = 2.0*ax*ah
s = 0.
35 h2 = (hf*h3 - v*h2)/n
n = n + 1
h3 = (hf*h2 - v*h3)/n
n = n + 1
hg = h3/n
s = s + hg
if (abs(hg) > e*abs(s)) go to 35
if (j /= 0) go to 40
j = 1
go to 35
40 aerf = u*(s + z)
45 if (h < 0.0) aerf = -aerf
return
!-------------------------------------------------
!        Special cases
!-------------------------------------------------
100 if (xph < 5.8) go to 110
if (xmh > -5.6) go to 120
aerf = sign(2.0,h)
return
!
110 aerf = erf(xph) - erf(xmh)
if (h < 0.0) aerf = -aerf
return
!
120 aerf = erfc(xmh)
if (h < 0.0) aerf = -aerf
return
!
130 aerf = erfc(xmh) - erfc(xph)
if (h < 0.0) aerf = -aerf
return
!
140 aerf = 2.0*c*h*(0.5 + (0.5 - (x*x + h*h/3.0)))
return
!
!     The value is  2.0*exp(-x*x)*erf(h)
!
150 t = 2.0
x2 = x*x
if (x2 >= eps) t = 2.0*exp(-x2)
if (h*h >= 3.0*eps) go to 160
aerf = c*h*t
return
160 aerf = t*erf(h)
end function aerf

pure elemental double precision function daerf(x, h)
implicit none
intrinsic :: erf, erfc
double precision, intent(in) :: x, h
integer :: j
double precision :: ah, ax, a2, dn2, e, eps, hf, hg, h2, h3, n, n1, s, st, t, u, v, xmh, xph, x2, z
double precision, parameter :: c = 1.12837916709551257389615890312155d0
double precision, parameter :: p = 2.76959d0
interface
   pure elemental function depsln(l)
      implicit none
      integer, intent(in) :: l
      double precision :: depsln
   end function depsln
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
   pure elemental function dxparg(l)
      implicit none
      integer, intent(in) :: l
      double precision :: dxparg
   end function dxparg
end interface
!-----------------------------------------------------------------------
!             Computation of erf(x + h) - erf(x - h)
!-----------------------------------------------------------------------
!---------------------
!     c = 2/sqrt(pi)
!     p = ln(9*sqrt(pi))
!---------------------
!---------------------
!
!     **** eps is a machine dependent constant. Eps is the
!          smallest number such that 1.D0 + eps .GT. 1.D0 .
!
eps = dpmpar(1)
!
!---------------------
daerf = 0.d0
if (h == 0.d0) return
!
ah = abs(h)
ax = abs(x)
xph = ax + ah
xmh = ax - ah
!
t = max(ah,ax)
t = t*t
if (1.6d0*t*t < eps) go to 140
if ((ax*ah)**2 < 0.5d0*eps) go to 150
if (ax <= ah) go to 100
!
if (xmh < 9.d0) go to 5
if (xmh*xmh + p > -dxparg(1)) return
5 if (4.d0*ah*ax > -depsln(0)) go to 120
!
if (ax > 3.d0*ah) go to 10
if (xph < 1.d0) go to 110
go to 130
!-------------------------------------------------
!        For (ax less than or equal to .40)
!-------------------------------------------------
10 e = max(1.d-30,eps)
if (ax > 0.4d0) go to 30
h2 = xph*xph
a2 = xmh*xmh
x2 = ax + ax
st = 1.d0
hf = xmh
n = 0.d0
n1 = 1.d0
dn2 = 1.d0
s = 0.d0
20 n = n + 1.d0
n1 = n1 + 2.d0
dn2 = -dn2/n
st = h2*st + x2*hf
hf = a2*hf
t = st*dn2/n1
s = s + t
if (abs(t) > e*abs(s)) go to 20
s = 0.5d0 + (0.5d0 + s)
daerf = 2.d0*c*ah*s
go to 45
!-------------------------------------------------
!        For (ax greater than .40)
!-------------------------------------------------
30 n = 1.d0
j = 0
h2 = 0.d0
z = exp(-0.5d0*ax*ax)
u = 2.d0*ah*c*z
h3 = z
v = 2.d0*h*h
hf = 2.d0*ax*ah
s = 0.d0
35 h2 = (hf*h3 - v*h2)/n
n = n + 1.d0
h3 = (hf*h2 - v*h3)/n
n = n + 1.d0
hg = h3/n
s = s + hg
if (abs(hg) > e*abs(s)) go to 35
if (j /= 0) go to 40
j = 1
go to 35
40 daerf = u*(s + z)
45 if (h < 0.d0) daerf = -daerf
return
!-------------------------------------------------
!        Special cases
!-------------------------------------------------
100 if (xph < 8.5d0) go to 110
if (xmh > -8.3d0) go to 120
daerf = sign(2.d0,h)
return
!
110 daerf = erf(xph) - erf(xmh)
if (h < 0.d0) daerf = -daerf
return
!
120 daerf = erfc(xmh)
if (h < 0.d0) daerf = -daerf
return
!
130 daerf = erfc(xmh) - erfc(xph)
if (h < 0.d0) daerf = -daerf
return
!
140 daerf = 2.d0*c*h*(0.5d0 + (0.5d0 - (x*x + h*h/3.d0)))
return
!
!     The value is  2.0*exp(-x*x)*erf(h)
!
150 t = 2.d0
x2 = x*x
if (x2 >= eps) t = 2.d0*exp(-x2)
if (h*h >= 3.d0*eps) go to 160
daerf = c*h*t
return
160 daerf = t*erf(h)
end function daerf

pure elemental function pndf(x,ind)
implicit none
integer, intent(in) :: ind
real, intent(in) :: x
real :: t
real :: pndf
real, parameter :: a = .707106781186548
real, parameter :: c = .797884560802865
interface
   pure elemental function erfc1(ind,x)
      implicit none
      integer, intent(in) :: ind
      real, intent(in) :: x
      real :: erfc1
   end function erfc1
end interface
!     ---------------
!     a = 1/sqrt(2)
!     c = sqrt(2/pi)
!     ---------------
!     ---------------
t = a*x
if (ind /= 0) go to 20
if (x < -8.0) go to 10
pndf = 0.5*erfc1(0,-t)
return
10 pndf = c/erfc1(1,-t)
return
20 if (x > 8.0) go to 30
pndf = 0.5*erfc1(0,t)
return
30 pndf = c/erfc1(1,t)
end function pndf

pure elemental subroutine pni(p, q, d, w, ierr)
implicit none
integer, intent(inout) :: ierr
real, intent(in) :: d, p, q
real, intent(inout) :: w
real :: eps, t, u, v
real, parameter :: rt2 = 1.414213562373095
interface
   pure elemental function erfi(p,q)
      implicit none
      real, intent(in) :: p
      real, intent(in) :: q
      real :: erfi
   end function erfi
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-----------------------------------------------------------------------
!
!         Evaluation of the inverse normal distribution function
!
!                           ------------
!
!     Let F(t) = 1/(sqrt(2*pi)*exp(-t*t/2)). Then the function
!
!        Prob(X) = Integral from minus infinity to X of F(t)
!
!     Is the normal distribution function of zero mean and unit
!     variance. It is assumed that p .GT. 0, q .GT. 0, p + q = 1,
!     and d = p - 0.5. The value w is computed where prob(w) = p.
!
!     ierr is a variable that reports the status of the results.
!
!       ierr = 0  No input errors were detected. w was computed.
!       ierr = 1  Either p or q is incorrect.
!       ierr = 2  d IS INCORRECT.
!
!-----------------------------------------------------------------------
!     rt2 = sqrt(2)
!------------------------
!------------------------
t = min(p,q)
if (t <= 0.0) go to 10
eps = max(spmpar(1),1.e-15)
w = 0.5 + (0.5 - (p + q))
if (abs(w) > 2.0*eps) go to 10
!
u = abs(d + d)
v = t + t
w = erfi(u, v)
if (w < 0.0) go to 20
!
ierr = 0
w = rt2*w
if (d < 0.0) w = - w
return
!
!                         Error return
!
10 ierr = 1
return
20 ierr = 2
end subroutine pni

pure elemental subroutine dpni(p, q, d, w, ierr)
implicit none
