!-----------------------------------------------------------------------
!            Double precision computation of dawsons integral
!-----------------------------------------------------------------------
!----------------------------
!----------------------------
!----------------------------
!----------------------------
ax = abs(x)
if (ax >= 4.d0) go to 30
t = x*x
if (ax > 1.d0) go to 20
!
!                       abs(x) .LE. 1
!
dpdaw = x
if (t < eps) return
!
w = a(20)
do i = 1,19
   k = 20 - i
   w = t*w + a(k)
10 continue
end do
dpdaw = x * (0.75d0 + (0.25d0 + t*w))
return
!
!                    1 .LT. abs(x) .LT. 4
!
20 dpdaw = x * (.25d0 + dcsevl(.125d0*t - 1.d0, b, 45))
return
!
!                       abs(x) .GE. 4
!
30 dpdaw = dpdaw0(ax)/x
end function dpdaw

