   & .279648642639792e+00, .553413866010467e+00, 1.0]
real, parameter :: q(7) = [-.832979206704073e-03, .470059485860584e-02, .225211131035340e-01, -.170458969313360e+00, - &
   & .567902761974940e-01, .113062953091122e+01, 1.0]
