!                           -----------
!
!     c = A(1) - 1 Is also frequently needed. c has the value ...
!
!     data c /-.4227843350984671393934879099175975689578d+00/
!
!-----------------------------------------------------------------------
double precision, intent(in) :: x
double precision :: d, t, w, z, nswc_ai_r8
double precision, parameter :: a0 = .611609510448141581788d-08
double precision, parameter :: a1 = .624730830116465516210d-08
double precision, parameter :: b1 = .203610414066806987300d+00
double precision, parameter :: b2 = .266205348428949217746d-01
double precision, parameter :: b3 = .493944979382446875238d-03
double precision, parameter :: b4 = -.851419432440314906588d-05
double precision, parameter :: b5 = -.643045481779353022248d-05
double precision, parameter :: b6 = .992641840672773722196d-06
double precision, parameter :: b7 = -.607761895722825260739d-07
double precision, parameter :: b8 = .195755836614639731882d-09
double precision, parameter :: p0 = .6116095104481415817861d-08
double precision, parameter :: p1 = .6871674113067198736152d-08
double precision, parameter :: p2 = .6820161668496170657918d-09
double precision, parameter :: p3 = .4686843322948848031080d-10
double precision, parameter :: p4 = .1572833027710446286995d-11
double precision, parameter :: p5 = -.1249441572276366213222d-12
double precision, parameter :: p6 = .4343529937408594255178d-14
double precision, parameter :: q1 = .3056961078365221025009d+00
double precision, parameter :: q2 = .5464213086042296536016d-01
double precision, parameter :: q3 = .4956830093825887312020d-02
double precision, parameter :: q4 = .2692369466186361192876d-03
double precision, parameter :: c = -.422784335098467139393487909917598d+00
double precision, parameter :: c0 = .577215664901532860606512090082402d+00
double precision, parameter :: c1 = -.655878071520253881077019515145390d+00
double precision, parameter :: c2 = -.420026350340952355290039348754298d-01
double precision, parameter :: c3 = .166538611382291489501700795102105d+00
double precision, parameter :: c4 = -.421977345555443367482083012891874d-01
double precision, parameter :: c5 = -.962197152787697356211492167234820d-02
double precision, parameter :: c6 = .721894324666309954239501034044657d-02
double precision, parameter :: c7 = -.116516759185906511211397108401839d-02
double precision, parameter :: c8 = -.215241674114950972815729963053648d-03
double precision, parameter :: c9 = .128050282388116186153198626328164d-03
double precision, parameter :: c10 = -.201348547807882386556893914210218d-04
double precision, parameter :: c11 = -.125049348214267065734535947383309d-05
double precision, parameter :: c12 = .113302723198169588237412962033074d-05
double precision, parameter :: c13 = -.205633841697760710345015413002057d-06
!----------------------------
!----------------------------
!----------------------------
!     c = c0 - 1
!----------------------------
!----------------------------
!----------------------------
t = x
d = x - 0.5d0
if (d > 0.d0) t = d - 0.5d0
nswc_ai_r8 = t
if ( nswc_ai_r8 < 0 ) go to 40
if ( nswc_ai_r8 == 0 ) go to 10
go to 20
!
10 dgam1 = 0.d0
return
!------------
!
!                Case when 0 .LT. t .LE. 0.5
!
!              w is a minimax approximation for
!              the series A(15) + A(16)*t + ...
!
!------------
20 w = ((((((p6*t + p5)*t + p4)*t + p3)*t + p2)*t + p1)*t + p0)/ &
   & ((((q4*t + q3)*t + q2)*t + q1)*t + 1.d0)
z = (((((((((((((w*t + c13)*t + c12)*t + c11)*t + c10)*t + &
   & c9)*t + c8)*t + c7)*t + c6)*t + c5)*t + c4)*t + &
   & c3)*t + c2)*t + c1)*t + c0
!
if (d > 0.d0) go to 30
dgam1 = x*z
return
30 dgam1 = (t/x)*((z - 0.5d0) - 0.5d0)
return
!------------
!
!                Case when -0.5 .LE. t .LT. 0
!
!              w is a minimax approximation for
!              the series A(15) + A(16)*t + ...
!
!------------
40 w = (a1*t + a0)/((((((((b8*t + b7)*t + b6)*t + b5)*t + &
   & b4)*t + b3)*t + b2)*t + b1)*t + 1.d0)
z = (((((((((((((w*t + c13)*t + c12)*t + c11)*t + c10)*t + &
   & c9)*t + c8)*t + c7)*t + c6)*t + c5)*t + c4)*t + &
   & c3)*t + c2)*t + c1)*t + c
!
if (d > 0.d0) go to 50
dgam1 = x*((z + 0.5d0) + 0.5d0)
return
50 dgam1 = t*z/x
end function dgam1

pure elemental double precision function dgamln(a)
implicit none
double precision, intent(in) :: a
integer :: i, n
double precision :: x, w
double precision, parameter :: d = 0.41893853320467274178032973640562d0
interface
   pure elemental function dgmln1(x)
      implicit none
      double precision, intent(in) :: x
      double precision :: dgmln1
   end function dgmln1
   pure elemental function dpdel(x)
      implicit none
      double precision, intent(in) :: x
      double precision :: dpdel
   end function dpdel
end interface
!-----------------------------------------------------------------------
!
!           Evaluation of LN(gamma(a)) for positive A
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris
!          naval surface weapons center
!          Dahlgren, Virginia
!-----------------------------------------------------------------------
!     d = 0.5*(ln(2*pi) - 1)
!-----------------------------------------------------------------------
!--------------------------
!--------------------------
if (a >= 0.5d0) go to 10
dgamln = dgmln1(a) - log(a)
return
10 if (a > 2.5d0) go to 20
x = a - 1.d0
if (a < 1.d0) x = (a - 0.5d0) - 0.5d0
dgamln = dgmln1(x)
return
!
20 if (a >= 10.d0) go to 30
n = a - 1.5d0
x = a
w = 1.d0
do i = 1,n
   x = x - 1.d0
21 w = x*w
end do
dgamln = dgmln1(x - 1.d0) + log(w)
return
!
30 w = dpdel(a)
dgamln = (d + w) + (a - 0.5d0)*(log(a) - 1.d0)
end function dgamln

pure elemental double precision function dgmln1(x)
implicit none
!-----------------------------------------------------------------------
!     Evaluation of LN(gamma(1 + x)) for -0.5 .LE. x .LE. 1.5
!-----------------------------------------------------------------------
double precision, intent(in) :: x
double precision :: w
interface
   pure elemental function dgam1(x)
      implicit none
      double precision, intent(in) :: x
      double precision :: dgam1
   end function dgam1
   pure elemental function dlnrel(a)
      implicit none
      double precision, intent(in) :: a
      double precision :: dlnrel
   end function dlnrel
end interface
!-----------------------
w = dgam1(x)
dgmln1 = - dlnrel(w)
end function dgmln1

pure elemental subroutine cpsi(z, w)
implicit none
complex, intent(in) :: z
complex, intent(inout) :: w
integer :: j, k, l, m, max
real :: a, a1, a2, c1, c2, cn, eps, et, h1, h2, s, s1, s2, sn, t, u, w1, w2, x, y, y2
complex :: eta, eta2, sum
double precision :: ds1, ds2
real, parameter :: pi = 3.14159265358979324
real, parameter :: pi2 = 6.28318530717958648
real, parameter :: c0(12) = [.833333333333333e-01, -.833333333333333e-02, .396825396825397e-02, -.416666666666667e-02, &
   & .757575757575758e-02, -.210927960927961e-01, .833333333333333e-01, -.443259803921569e+00, .305395433027012e+01, - &
   & .264562121212121e+02, .281460144927536e+03, -.360751054639805e+04]
interface
   pure elemental function ipmpar(i)
      implicit none
      integer, intent(in) :: i
      integer :: ipmpar
   end function ipmpar
   pure elemental function rexp(x)
      implicit none
      real, intent(in) :: x
      real :: rexp
   end function rexp
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-----------------------------------------------------------------------
!           Evaluation of the complex digamma function
!-----------------------------------------------------------------------
!----------------------------
!     pi2 = 2*pi
!----------------------------
!----------------------------
!----------------------------
!
!     ****** max and eps are machine dependent constants.
!            Max is the largest positive integer that may
!            be used, and eps is the smallest real number
!            such that 1.0 + eps .GT. 1.0.
!
max = ipmpar(3)
eps = spmpar(1)
!
!----------------------------
x = real(z)
y = aimag(z)
if (x >= 0.0) go to 40
!-----------------------------------------------------------------------
!            Case when the real part of z is negative
!-----------------------------------------------------------------------
y = abs(y)
t = -pi2*y
et = exp(t)
!
!     SET  a1 = (1 + et)/2  AND  a2 = (1 - et)/2
!
a1 = 0.5*(1.0 + et)
if (t < -0.15) go to 10
a2 = -0.5*rexp(t)
go to 20
10 a2 = 0.5*(0.5 + (0.5 - et))
!
!     Compute sin(pi*X) and cos(pi*X), or -sin(pi*X) and -cos(pi*X)
!
20 if (abs(x) >= min(float(max), 1.0/eps)) go to 100
k = abs(x)
u = x + k
if (u <= -0.5) u = 0.5 + (0.5 + u)
u = pi*u
sn = sin(u)
cn = cos(u)
!
!     SET h1 + h2*I = pi*COT(pi*z)
!
s1 = a1*sn
s2 = a2*cn
c1 = a1*cn
c2 = -a2*sn
s = s1*s1 + s2*s2
h1 = pi*(s1*c1 + s2*c2)/s
h2 = pi*(s1*c2 - s2*c1)/s
!
if (aimag(z) < 0.0) go to 30
x = 1.0 - x
y = -y
go to 40
30 h2 = -h2
x = 1.0 - x
!-----------------------------------------------------------------------
!           Case when the real part of z is nonnegative
!-----------------------------------------------------------------------
40 t = x
y2 = y*y
a = x*x + y2
if (a == 0.0) go to 100
!
!     Let s1 + S2*I be the sum of the terms 1/(z+j) for j = 0,1,...,N-1
!
ds1 = 0.d0
ds2 = 0.d0
50 if (a >= 36.0) go to 51
ds1 = ds1 + dble(t/a)
ds2 = ds2 - dble(y/a)
t = t + 1.0
a = t*t + y2
go to 50
51 s1 = ds1
s2 = ds2
!
!     SET W1 + W2*I = log(z+N)
!
w1 = 0.5*log(a)
w2 = atan2(y,t)
!
!     Let a1 + a2*I be the asymptotic sum
!
eta = cmplx(t/a,-y/a)
eta2 = eta*eta
m = 12
l = m
sum = cmplx(c0(m),0.0)
do j = 2,m
   l = l - 1
   sum = cmplx(c0(l),0.0) + sum*eta2
end do
sum = cmplx(0.5,0.0)*eta + eta2*sum
a1 = real(sum)
a2 = aimag(sum)
!-----------------------------------------------------------------------
!                 Gathering together the results
!-----------------------------------------------------------------------
w1 = (w1 - s1) - a1
w2 = (w2 - a2) - s2
w = cmplx(w1,w2)
if (real(z) >= 0.0) return
w = cmplx(w1 - h1, w2 - h2)
return
!-----------------------------------------------------------------------
!             The requested value cannot be computed
!-----------------------------------------------------------------------
100 w = (0.0, 0.0)
end subroutine cpsi

pure real function psi(xx)
implicit none
real, intent(in) :: xx
integer :: i, m, n, nq
real :: aug, den, sgn, upper, w, x, xmax1, xmx0, xsmall, z
real, parameter :: piov4 = .785398163397448e0
double precision, parameter :: dx0 = 1.461632144968362341262659542325721325d0
real, parameter :: p1(7) = [.895385022981970e-02, .477762828042627e+01, .142441585084029e+03, .118645200713425e+04, &
   & .363351846806499e+04, .413810161269013e+04, .130560269827897e+04]
real, parameter :: q1(6) = [.448452573429826e+02, .520752771467162e+03, .221000799247830e+04, .364127349079381e+04, &
   & .190831076596300e+04, .691091682714533e-05]
real, parameter :: p2(4) = [-.212940445131011e+01, -.701677227766759e+01, -.448616543918019e+01, -.648157123766197e+00]
real, parameter :: q2(4) = [.322703493791143e+02, .892920700481861e+02, .546117738103215e+02, .777788548522962e+01]
interface
   pure elemental function ipmpar(i)
      implicit none
      integer, intent(in) :: i
      integer :: ipmpar
   end function ipmpar
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!---------------------------------------------------------------------
!
!                 Evaluation of the digamma function
!
!                           -----------
!
!     psi(xx) is assigned the value 0 when the digamma function CANNOT
!     be computed.
!
!     The main computation involves evaluation of rational Chebyshev
!     approximations published in math. Comp. 27, 123-127(1973) By
!     Cody, Strecok and Thacher.
!
!---------------------------------------------------------------------
!     Psi was written at Argonne National Laboratory for the funpack
!     package of special function subroutines. Psi was modified by
!     A.H. Morris (NSWC).
!---------------------------------------------------------------------
!---------------------------------------------------------------------
!
!     piov4 = pi/4
!     dx0 = Zero of psi to extended precision
!
!---------------------------------------------------------------------
!---------------------------------------------------------------------
!
!     Coefficients for rational approximation of
!     psi(x) / (x - X0),  0.5 .LE. x .LE. 3.0
!
!---------------------------------------------------------------------
!---------------------------------------------------------------------
!
!     Coefficients for rational approximation of
!     psi(x) - LN(x) + 1 / (2*x),  x .GT. 3.0
!
!---------------------------------------------------------------------
!---------------------------------------------------------------------
!
!     Machine dependent constants ...
!
!        xmax1  = The smallest positive floating point constant
!                 with entirely integer representation.  Also used
!                 as negative of lower bound on acceptable negative
!                 arguments and as the positive argument beyond which
!                 psi may be represented as ALOG(x).
!
!        xsmall = Absolute argument below which pi*cotan(PI*x)
!                 may be represented by 1/x.
!
!---------------------------------------------------------------------
xmax1 = ipmpar(3)
xmax1 = min(xmax1, 1.0/spmpar(1))
xsmall = 1.e-9
!---------------------------------------------------------------------
x = xx
aug = 0.0e0
if (x >= 0.5e0) go to 200
!---------------------------------------------------------------------
!     x .LT. 0.5,  use reflection formula
!     psi(1-x) = psi(x) + pi * cotan(pi*x)
!---------------------------------------------------------------------
if (abs(x) > xsmall) go to 100
if (x == 0.0e0) go to 400
!---------------------------------------------------------------------
!     0 .LT. abs(x) .LE. xsmall.  USE 1/x AS A SUBSTITUTE
!     for  pi*cotan(PI*x)
!---------------------------------------------------------------------
aug = -1.0e0 / x
go to 150
!---------------------------------------------------------------------
!     Reduction of argument for cotan
!---------------------------------------------------------------------
100 w = - x
sgn = piov4
if (w > 0.0e0) go to 120
w = - w
sgn = -sgn
!---------------------------------------------------------------------
!     Make an error exit if x .LE. -xmax1
!---------------------------------------------------------------------
120 if (w >= xmax1) go to 400
nq = int(w)
w = w - float(nq)
nq = int(w*4.0e0)
w = 4.0e0 * (w - float(nq) * .25e0)
!---------------------------------------------------------------------
!     w is now related to the fractional part of  4.0 * x.
!     Adjust argument to correspond to values in first
!     quadrant and determine sign
!---------------------------------------------------------------------
n = nq / 2
if ((n + n) /= nq) w = 1.0e0 - w
z = piov4 * w
m = n / 2
if ((m + m) /= n) sgn = - sgn
!---------------------------------------------------------------------
!     Determine final value for  -Pi*cotan(PI*x)
!---------------------------------------------------------------------
n = (nq + 1) / 2
m = n / 2
m = m + m
if (m /= n) go to 140
!---------------------------------------------------------------------
!     Check for singularity
!---------------------------------------------------------------------
if (z == 0.0e0) go to 400
!---------------------------------------------------------------------
!     Use cos/sin as a substitute for cotan, and
!     sin/cos as a substitute for tan
!---------------------------------------------------------------------
aug = sgn * ((cos(z) / sin(z)) * 4.0e0)
go to 150
140 aug = sgn * ((sin(z) / cos(z)) * 4.0e0)
150 x = 1.0e0 - x
200 if (x > 3.0e0) go to 300
!---------------------------------------------------------------------
!     0.5 .LE. x .LE. 3.0
!---------------------------------------------------------------------
den = x
upper = p1(1) * x
!
do i = 1, 5
   den = (den + q1(i)) * x
   upper = (upper + p1(i + 1)) * x
end do
!
den = (upper + p1(7)) / (den + q1(6))
xmx0 = dble(x) - dx0
psi = den * xmx0 + aug
return
!---------------------------------------------------------------------
!     IF x .GE. xmax1, PSI = LN(x)
!---------------------------------------------------------------------
300 if (x >= xmax1) go to 350
!---------------------------------------------------------------------
!     3.0 .LT. x .LT. xmax1
!---------------------------------------------------------------------
w = 1.0e0 / (x * x)
den = w
upper = p2(1) * w
!
do i = 1, 3
   den = (den + q2(i)) * w
   upper = (upper + p2(i + 1)) * w
end do
!
aug = upper / (den + q2(4)) - 0.5e0 / x + aug
350 psi = aug + log(x)
return
!---------------------------------------------------------------------
!     Error return
!---------------------------------------------------------------------
400 psi = 0.0e0
end function psi

pure subroutine dcpsi(z, w)
implicit none
double precision, intent(in) :: z(2)
double precision, intent(inout) :: w(2)
integer :: j, k, m, max
double precision :: a, a1, a2, cn, cut, c1, c2, eps, et, h1, h2, &
   & q1, q2, s, sn, s1, s2, t, t1, t2, u, u1, u2, v1, v2, w1, w2, x, y, &
   & y2
double precision, parameter :: pi = 3.141592653589793238462643383279502884197d0
double precision, parameter :: pi2 = 6.283185307179586476925286766559005768394d0
double precision, parameter :: c0(30) = [.8333333333333333333333333333333333333333d-01, - &
   & .8333333333333333333333333333333333333333d-02, .3968253968253968253968253968253968253968d-02, - &
   & .4166666666666666666666666666666666666667d-02, .7575757575757575757575757575757575757576d-02, - &
   & .2109279609279609279609279609279609279609d-01, .8333333333333333333333333333333333333333d-01, - &
   & .4432598039215686274509803921568627450980d+00, .3053954330270119743803954330270119743804d+01, - &
   & .2645621212121212121212121212121212121212d+02, .2814601449275362318840579710144927536232d+03, - &
   & .3607510546398046398046398046398046398046d+04, .5482758333333333333333333333333333333333d+05, - &
   & .9749368238505747126436781609195402298851d+06, .2005269579668807894614346227249453055905d+08, - &
   & .4723848677216299019607843137254901960784d+09, .1263572479591666666666666666666666666667d+11, - &
   & .3808793112524536881155302207933786881155d+12, .1285085049930508333333333333333333333333d+14, - &
   & .4824144835485017037158167036215816703622d+15, .2004031065651625273810842166323893898645d+17, - &
   & .9167743603195330775699275362318840579710d+18, .4597988834365650349043794326241134751773d+20, - &
   & .2518047192145109569708902332022552610788d+22, .1500173349215392873371144015151515151515d+24, - &
   & .9689957887463594065649794289465408805031d+25, .6764588237929282099094524230179847767567d+27, - &
   & .5089065946866228968976633291591192528736d+29, .4114728879255797869766548606761933615819d+31, - &
   & .3566658209537555610968457460865182898779d+33]
interface
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
   pure elemental function drexp(x)
      implicit none
      double precision, intent(in) :: x
      double precision :: drexp
   end function drexp
   pure elemental function ipmpar(i)
      implicit none
      integer, intent(in) :: i
      integer :: ipmpar
   end function ipmpar
end interface
!-----------------------------------------------------------------------
!           Evaluation of the complex digamma function
!-----------------------------------------------------------------------
!----------------------------
!     pi2 = 2*pi
!----------------------------
!----------------------------
!----------------------------
!
!     ****** max and eps are machine dependent constants.
!            Max is the largest positive integer that may
!            be used, and eps is the smallest real number
!            such that 1.D0 + eps .GT. 1.D0.
!
max = ipmpar(3)
eps = dpmpar(1)
!
!----------------------------
x = z(1)
y = z(2)
if (x >= 0.d0) go to 40
!-----------------------------------------------------------------------
!            Case when the real part of z is negative
!-----------------------------------------------------------------------
y = abs(y)
t = -pi2*y
et = exp(t)
!
!     SET  a1 = (1 + et)/2  AND  a2 = (1 - et)/2
!
a1 = 0.5d0*(1.d0 + et)
if (t < -0.15d0) go to 10
a2 = -0.5d0*drexp(t)
go to 20
10 a2 = 0.5d0*(0.5d0 + (0.5d0 - et))
!
!     Compute sin(pi*X) and cos(pi*X), or -sin(pi*X) and -cos(pi*X)
!
20 u = max
if (abs(x) >= min(u, 1.d0/eps)) go to 100
k = abs(x)
u = x + k
if (u <= -0.5d0) u = 0.5d0 + (0.5d0 + u)
u = pi*u
sn = sin(u)
cn = cos(u)
!
!     SET h1 + h2*I = pi*COT(pi*z)
!
s1 = a1*sn
s2 = a2*cn
c1 = a1*cn
c2 = -a2*sn
s = s1*s1 + s2*s2
h1 = pi*(s1*c1 + s2*c2)/s
h2 = pi*(s1*c2 - s2*c1)/s
!
if (z(2) < 0.d0) go to 30
x = 1.d0 - x
y = -y
go to 40
30 h2 = -h2
x = 1.d0 - x
!-----------------------------------------------------------------------
!           Case when the real part of z is nonnegative
!-----------------------------------------------------------------------
40 t = x
y2 = y*y
a = x*x + y2
if (a == 0.d0) go to 100
cut = 225.d0
if (eps > 1.d-30) cut = 144.d0
!
!     Let S1 + S2*I be the sum of the terms 1/(z+j) for j = 0,1,...,N-1
!
s1 = 0.d0
s2 = 0.d0
50 if (a >= cut) go to 51
s1 = s1 + t/a
s2 = s2 - y/a
t = t + 1.d0
a = t*t + y2
go to 50
51 continue
!
!     SET W1 + W2*I = log(z+N)
!
w1 = 0.5d0*log(a)
w2 = atan2(y,t)
!
!     Let a1 + a2*I be the asymptotic sum
!
u1 = t/a
u2 = -y/a
q1 = u1*u1 - u2*u2
q2 = 2.d0*u1*u2
v1 = q1
v2 = q2
a1 = 0.d0
a2 = 0.d0
m = 30
if (eps > 1.d-30) m = 25
do j = 1,m
   t1 = a1
   t2 = a2
   a1 = a1 + c0(j)*v1
   a2 = a2 + c0(j)*v2
   if (a1 /= t1) go to 60
   if (a2 == t2) go to 70
60 t1 = v1*q1 - v2*q2
   t2 = v1*q2 + v2*q1
   v1 = t1
61 v2 = t2
end do
!-----------------------------------------------------------------------
!                 Gathering together the results
!-----------------------------------------------------------------------
70 a1 = a1 + 0.5d0*u1
a2 = a2 + 0.5d0*u2
w(1) = (w1 - a1) - s1
w(2) = (w2 - a2) - s2
if (z(1) >= 0.d0) return
w(1) = w(1) - h1
w(2) = w(2) - h2
return
!-----------------------------------------------------------------------
!             The requested value cannot be computed
!-----------------------------------------------------------------------
100 w(1) = 0.d0
w(2) = 0.d0
end subroutine dcpsi

