!-----------------------------------------------------------------------
!
!     Computation of LN(gamma(b)/gamma(a+b)) for b .GE. 10
!
!                         --------
!
!     dlgdiv uses a series for the function DEL(x) where
!     LN(gamma(x)) = (x - 0.5)*LN(x) - x + 0.5*LN(2*PI) + DEL(x).
!     The series for del(x), which applies for x .GE. 10, was
!     derived by A.H. Morris from the Chebyshev series in the
!     SLATEC library obtained by Wayne Fullerton (Los Alamos).
!
!-----------------------------------------------------------------------
!--------------------------
!--------------------------
if (a <= b) go to 10
h = b/a
c = 1.d0/(1.d0 + h)
x = h/(1.d0 + h)
d = a + (b - 0.5d0)
go to 20
10 h = a/b
c = h/(1.d0 + h)
x = 1.d0/(1.d0 + h)
d = b + (a - 0.5d0)
!
!        COMPUTE (1 - x**N)/(1 - x) FOR N = 1,3,5,...
!            Store these values in s(1),s(2),...
!
20 x2 = x*x
s(1) = 1.d0
do j = 1,14
   s(j + 1) = 1.d0 + (x + x2*s(j))
21 continue
end do
!
!                SET w = DEL(b) - DEL(a + b)
!
t = (10.d0/b)**2
w = e(15)*s(15)
do j = 1,14
   k = 15 - j
   w = t*w + e(k)*s(k)
end do
w = w*(c/b)
!
!                    Combine the results
!
u = d*dlnrel(a/b)
v = a*(log(b) - 1.d0)
if (u <= v) go to 40
dlgdiv = (w - v) - u
return
40 dlgdiv = (w - u) - v
end function dlgdiv

