!-----------------------------------------------------------------------
!
!        Evaluation of the incomplete gamma ratio functions
!                      P(a,x) AND Q(a,x)
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris, Jr.
!        Naval Surface Warfare Center
!        Dahlgren, Virginia
!     revised ... jan 1992
!-------------------------
!-------------------------
!     alog10 = ln(10)
!     rtpi   = dsqrt(pi)
!-------------------------
!-------------------------
!
!     ****** E is a machine dependent constant. E is the smallest
!            floating point number for which 1.0 + E .GT. 1.0 .
!
e = dpmpar(1)
!
!-------------------------
if (a < 0.d0 .or. x < 0.d0) go to 400
if (a == 0.d0 .and. x == 0.d0) go to 410
ierr = 0
if (a*x == 0.d0) go to 331
!
e = dmax1(e,1.d-30)
big = 30.d0
if (e < 1.d-17) big = 50.d0
x0 = 45.d0
if (e < 1.d-17) x0 = 68.d0
!
!            Select the appropriate algorithm
!
if (a >= 1.d0) go to 10
if (a == 0.5d0) go to 320
if (x <= 2.d0) go to 110
r = drcomp(a,x)
if (r == 0.d0) go to 310
go to 170
!
10 if (a >= big) go to 20
if (a > x .or. x >= x0) go to 30
twoa = a + a
m = twoa
l = m
if (twoa /= l) go to 30
i = m/2
l = i
if (a == l) go to 140
go to 150
!
20 l = x/a
if (l == 0.d0) go to 300
s = 0.5d0 + (0.5d0 - l)
z = drlog(l)
if (z >= 700.d0/a) go to 330
y = a*z
rta = sqrt(a)
if (abs(s) <= 0.4d0) go to 200
!
30 r = drcomp(a,x)
if (r == 0.d0) go to 331
if (x <= dmax1(a,alog10)) go to 50
if (x < x0) go to 170
go to 80
!
!                 Taylor series for P/R
!
50 apn = a + 1.d0
t = x/apn
wk(1) = t
do n = 2,20
   apn = apn + 1.d0
   t = t*(x/apn)
   if (t < 1.d-3) go to 60
   wk(n) = t
end do
n = 20
!
60 sum = t
tol = 0.5d0*e
61 apn = apn + 1.d0
t = t*(x/apn)
sum = sum + t
if (t > tol) go to 61
!
max = n - 1
do m = 1,max
   n = n - 1
   sum = sum + wk(n)
end do
ans = (r/a)*(1.d0 + sum)
qans = 0.5d0 + (0.5d0 - ans)
return
!
!                 Asymptotic expansion
!
80 amn = a - 1.d0
t = amn/x
wk(1) = t
do n = 2,20
   amn = amn - 1.d0
   t = t*(amn/x)
   if (abs(t) <= 1.d-3) go to 90
   wk(n) = t
end do
n = 20
!
90 sum = t
91 if (abs(t) < e) go to 100
amn = amn - 1.d0
t = t*(amn/x)
sum = sum + t
go to 91
!
100 max = n - 1
do m = 1,max
   n = n - 1
   sum = sum + wk(n)
end do
qans = (r/x)*(1.d0 + sum)
ans = 0.5d0 + (0.5d0 - qans)
return
!
!             Taylor series for P(a,x)/x**a
!
110 l = 3.d0
c = x
sum = x/(a + 3.d0)
tol = 3.d0*e/(a + 1.d0)
120 l = l + 1.d0
c = -c*(x/l)
t = c/(a + l)
sum = sum + t
if (abs(t) > tol) go to 120
j = a*x*((sum/6.d0 - 0.5d0/(a + 2.d0))*x + 1.d0/(a + 1.d0))
!
z = a*log(x)
u = exp(z)
h = dgam1(a)
g = 1.d0 + h
ans = u*g*(0.5d0 + (0.5d0 - j))
qans = 0.5d0 + (0.5d0 - ans)
if (ans <= 0.9d0) return
!
l = drexp(z)
qans = (u*j - l)*g - h
if (qans <= 0.d0) go to 310
ans = 0.5d0 + (0.5d0 - qans)
return
!
!             Finite sums for Q when a .GE. 1
!                 and 2*a is an integer
!
140 sum = exp(-x)
t = sum
n = 1
c = 0.d0
go to 160
!
150 rtx = sqrt(x)
sum = derfc1(0,rtx)
t = exp(-x)/(rtpi*rtx)
n = 0
c = -0.5d0
!
160 if (n == i) go to 161
n = n + 1
c = c + 1.d0
t = (x*t)/c
sum = sum + t
go to 160
161 qans = sum
ans = 0.5d0 + (0.5d0 - qans)
return
!
!              Continued fraction expansion
!
170 tol = 8.d0*e
a2nm1 = 1.d0
a2n = 1.d0
b2nm1 = x
b2n = x + (1.d0 - a)
c = 1.d0
180 a2nm1 = x*a2n + c*a2nm1
b2nm1 = x*b2n + c*b2nm1
c = c + 1.d0
t = c - a
a2n = a2nm1 + t*a2n
b2n = b2nm1 + t*b2n
!
a2nm1 = a2nm1/b2n
b2nm1 = b2nm1/b2n
a2n = a2n/b2n
b2n = 1.d0
if (abs(a2n - a2nm1/b2nm1) >= tol*a2n) go to 180
!
qans = r*a2n
ans = 0.5d0 + (0.5d0 - qans)
return
!
!                 Minimax approximations
!
200 if (abs(s) <= 2.d0*e .and. a*e*e > 3.28d-3) go to 420
if (e < 1.d-17) go to 210
call dgr17(a, y, l, z, rta, ans, qans)
return
210 call dgr29(a, y, l, z, rta, ans, qans)
return
!
!                     Special cases
!
300 ans = 0.d0
qans = 1.d0
return
!
310 ans = 1.d0
qans = 0.d0
return
!
320 if (x >= 0.25d0) go to 321
ans = erf(sqrt(x))
qans = 0.5d0 + (0.5d0 - ans)
return
321 qans = derfc1(0,sqrt(x))
ans = 0.5d0 + (0.5d0 - qans)
return
!
330 if (abs(s) <= 2.d0*e) go to 420
331 if (x <= a) go to 300
go to 310
!
!                     Error return
!
400 ierr = 1
ans = 2.d0
return
!
410 ierr = 2
ans = 2.d0
return
!
420 ierr = 3
ans = 2.d0
end subroutine dgrat

