   & 1.74293213231963e-02, 1.65685837786612e-02, 1.57865285987918e-02, &
   & 1.50729501494096e-02, 1.44193250839955e-02, 1.38184805735342e-02/
!     ------------------------------------------------------------------
fn = fnu
iflw = 0
do jn = 1,in
   xx = x/fn
   wk(1) = 1.0e0 - xx*xx
   abw2 = abs(wk(1))
   wk(2) = sqrt(abw2)
   wk(7) = fn**con2
   if (abw2 > 0.27750e0) go to 80
!
!     Asymptotic expansion
!     cases near x=FN, abs(1.-(x/FN)**2).LE.0.2775
!     coefficients of asymptotic expansion by series
!
!     Zeta and truncation for A(ZETA) and B(ZETA) series
!
!     kmax is truncation index for A(ZETA) and B(ZETA) series=max(2,SA)
!
   sa = 0.0e0
   if (abw2 == 0.0e0) go to 10
   sa = tols/log(abw2)
10 sb = sa
   do i = 1,5
      akm = max(sa,2.0e0)
      kmax(i) = int(akm)
      sa = sa + sb
20    continue
   end do
   kb = kmax(5)
   klast = kb - 1
   sa = gama(kb)
   do k = 1,klast
      kb = kb - 1
      sa = sa*wk(1) + gama(kb)
30    continue
   end do
   z = wk(1)*sa
   az = abs(z)
   rtz = sqrt(az)
   wk(3) = con1*az*rtz
   wk(4) = wk(3)*fn
   wk(5) = rtz*wk(7)
   wk(6) = -wk(5)*wk(5)
   if (z <= 0.0e0) go to 35
   if (wk(4) > elim) go to 75
   wk(6) = -wk(6)
35 continue
   phi = sqrt(sqrt(sa + sa + sa + sa))
!
!     B(ZETA) FOR S=0
!
   kb = kmax(5)
   klast = kb - 1
   sb = beta(kb,1)
   do k = 1,klast
      kb = kb - 1
      sb = sb*wk(1) + beta(kb,1)
40    continue
   end do
   ksp1 = 1
   fn2 = fn*fn
   rfn2 = 1.0e0/fn2
   rden = 1.0e0
   asum = 1.0e0
   relb = tol*abs(sb)
   bsum = sb
   do ks = 1,4
      ksp1 = ksp1 + 1
      rden = rden*rfn2
!
!     A(ZETA) and B(ZETA) for S=1,2,3,4
!
      kstemp = 5 - ks
      kb = kmax(kstemp)
      klast = kb - 1
      sa = alfa(kb,ks)
      sb = beta(kb,ksp1)
      do k = 1,klast
         kb = kb - 1
         sa = sa*wk(1) + alfa(kb,ks)
         sb = sb*wk(1) + beta(kb,ksp1)
50       continue
      end do
      ta = sa*rden
      tb = sb*rden
      asum = asum + ta
      bsum = bsum + tb
      if (abs(ta) <= tol .and. abs(tb) <= relb) go to 70
60    continue
   end do
70 continue
   bsum = bsum/(fn*wk(7))
   go to 160
!
75 continue
   iflw = 1
   return
!
80 continue
   upol(1) = 1.0e0
   tau = 1.0e0/wk(2)
   t2 = 1.0e0/wk(1)
   if (wk(1) >= 0.0e0) go to 90
!
!     CASES FOR (x/FN).GT.sqrt(1.2775)
!
   wk(3) = abs(wk(2) - atan(wk(2)))
   wk(4) = wk(3)*fn
   rcz = -con1/wk(4)
   z32 = 1.5e0*wk(3)
   rtz = z32**con2
   wk(5) = rtz*wk(7)
   wk(6) = -wk(5)*wk(5)
   go to 100
90 continue
!
!     CASES FOR (x/FN).LT.sqrt(0.7225)
!
   wk(3) = abs(log((1.0e0 + wk(2))/xx) - wk(2))
   wk(4) = wk(3)*fn
   rcz = con1/wk(4)
   if (wk(4) > elim) go to 75
   z32 = 1.5e0*wk(3)
   rtz = z32**con2
   wk(7) = fn**con2
   wk(5) = rtz*wk(7)
   wk(6) = wk(5)*wk(5)
100 continue
   phi = sqrt((rtz + rtz)*tau)
   tb = 1.0e0
   asum = 1.0e0
   tfn = tau/fn
   upol(2) = (c(1)*t2 + c(2))*tfn
   crz32 = con548*rcz
   bsum = upol(2) + crz32
   relb = tol*abs(bsum)
   ap = tfn
   ks = 0
   kp1 = 2
   rzden = rcz
   l = 2
   do lr = 2,8,2
!
!     Compute two U polynomials for next A(ZETA) and B(ZETA)
!
      lrp1 = lr + 1
      do k = lr,lrp1
         ks = ks + 1
         kp1 = kp1 + 1
         l = l + 1
         s1 = c(l)
         do j = 2,kp1
            l = l + 1
            s1 = s1*t2 + c(l)
         end do
         ap = ap*tfn
         upol(kp1) = ap*s1
         cr(ks) = br(ks)*rzden
         rzden = rzden*rcz
         dr(ks) = ar(ks)*rzden
      end do
      suma = upol(lrp1)
      sumb = upol(lr + 2) + upol(lrp1)*crz32
      ju = lrp1
      do jr = 1,lr
         ju = ju - 1
         suma = suma + cr(jr)*upol(ju)
         sumb = sumb + dr(jr)*upol(ju)
      end do
      tb = -tb
      if (wk(1) > 0.0e0) tb = abs(tb)
      asum = asum + suma*tb
      bsum = bsum + sumb*tb
      if (abs(suma) <= tol .and. abs(sumb) <= relb) go to 150
   end do
150 tb = wk(5)
   if (wk(1) > 0.0e0) tb = -tb
   bsum = bsum/tb
!
160 continue
   call funjy(wk(6), wk(5), wk(4), fi, dfi)
   y(jn) = flgjy*phi*(fi*asum + dfi*bsum)/wk(7)
   fn = fn - flgjy
170 continue
end do
end subroutine asjy

