integer :: i, j
real :: ccv, cv, e1, e2, ec, f1, f2, rtrx, scv, t, temp1, temp2, tt
integer, parameter :: n1 = 14
integer, parameter :: n2 = 23
integer, parameter :: n3 = 19
integer, parameter :: n4 = 15
