!-----------------------------------------------------------------------
!     Calculates the Airy function ai and its derivative aip for
!     complex argument z by means of asymptotic expansions.
!-----------------------------------------------------------------------
!------------------------
!------------------------
!------------------------
!     c1 = pi**(-1/2)
!     c2 = (2*pi)**(-1/2)
!------------------------
!------------------------
!
!     Eps, xpos, and xneg are machine dependent constants. Eps is
!     the smallest number such that 1.0 + eps .GT. 1.0, xpos is the
!     the largest postive number for which exp(X) can be computed,
!     and xneg is the largest negative number for which exp(X) does
!     not underflow.
!
eps = spmpar(1)
xpos = exparg(0)
xneg = exparg(1)
!
!------------------------
ierr = 0
if (real(z) < 0.0) go to 30
!
!             -----   real(z) .GE. 0    -----
!
z1 = sqrt(z)
z2 = sqrt(z1)
z2r = 1.0/z2
call crec(real(z), aimag(z), u, v)
w = -1.5*cmplx(u,v)/z1
u = abs(real(w))
v = abs(aimag(w))
t = max(u,v)
if (ind /= 0) go to 10
!
if (t == 0.0) go to 90
u1 = u/t
v1 = v/t
r = u*u1 + v*v1
xm = xpos
if (real(w) < 0.0) xm = -xneg
if (u1 >= r*xm .or. v1 >= 0.1*r/eps) go to 90
zeta = z1*z/1.5
e = exp(-zeta)
!
10 m = 20
if (t > 30.0) m = 8
s1 = cmplx(c(m),0.0)
s2 = cmplx(d(m),0.0)
i = m
do k = 2,m
   i = i - 1
   s1 = c(i) + w*s1
   s2 = d(i) + w*s2
20 continue
end do
!
ai = 0.5*c1*z2r*s1
aip = - 0.5*c1*z2*s2
if (ind /= 0) return
ai = e*ai
aip = e*aip
return
!
!             -----   real(z) .LT. 0    -----
!
30 zz = -z
z1 = sqrt(zz)
z2 = sqrt(z1)
z2r = 1.0/z2
call crec(real(zz), aimag(zz), u, v)
w = 1.5*cmplx(u,v)/z1
u = abs(real(w))
v = abs(aimag(w))
t = max(u,v)
!
if (t == 0.0) go to 90
u1 = u/t
v1 = v/t
r = u*u1 + v*v1
if (ind /= 0) go to 40
if (v1 >= r*xpos .or. u1 >= 0.1*r/eps) go to 90
zeta = z1*zz/1.5
go to 50
40 e = (0.0, 0.0)
j = (0.0, -1.0)
if (aimag(z) < 0.0) j = (0.0, 1.0)
if (v1 > 0.5*r*abs(xneg)) go to 50
if (u1 >= 0.05*r/eps) go to 90
zeta = z1*zz/1.5
e = exp(2.0*j*zeta)
!
50 w2 = w*w
m = 15
if (t > 30.0) m = 5
m2 = m + m
i = m2 - 1
s1 = cmplx(c(i),0.0)
s2 = cmplx(c(m2),0.0)
s3 = cmplx(d(i),0.0)
s4 = cmplx(d(m2),0.0)
do k = 2,m
   i = i - 1
   s2 = c(i) - s2*w2
   s4 = d(i) - s4*w2
   i = i - 1
   s1 = c(i) - s1*w2
   s3 = d(i) - s3*w2
end do
s2 = w*s2
s4 = w*s4
!
if (ind /= 0) go to 70
cn = cos(zeta)
si = sin(zeta)
go to 80
70 cn = 0.5*(1.0 + e)
si = 0.5*(1.0 - e)*j
!
80 alpha = s1 - s2
beta = s1 + s2
ai = c2*z2r*(alpha*cn + beta*si)
alpha = s3 - s4
beta = s3 + s4
aip = c2*z2*(alpha*si - beta*cn)
return
!
!         RETURN WITH ZERO VALUES IF SCALING IS NEEDED
!
90 ai = (0.0, 0.0)
aip = (0.0, 0.0)
ierr = 1
end subroutine aia

