!------------------------------------------------------------
!     Calculates the Airy function bi and its derivative bip
!     for complex argument z in the intermediate range 1 .LE.
!     CABS(z) .LE. 10.0.
!------------------------------------------------------------
!
!     c1 = 1/sqrt(3)
!     sqt3 = sqrt(3)
!
!
ierr = 0
x = real(z)
y = aimag(z)
r = cpabs(x, y)
z1 = sqrt(z)
z2 = z1*z/1.5
e = exp(-z2)
e1 = 1.0/e
if (real(z) < 0.0) go to 10
!
!               ----  real(z) .GE. 0  ----
!
if (r < 8.9) go to 5
a = 0.156*r - 0.913
if (abs(y) < a*x .or. abs(y) > 0.58*x) go to 40
5 call ia(z2, w1, w2, w1m, w2m)
bi = c1*z1*(w1 + w1m)
bip = c1*z*(w2 + w2m)
if (ind == 0) return
go to 20
!
!               ----  real(z) .LT. 0  ----
!
10 if (r < 8.1) go to 15
if (abs(y) < 3.89*abs(x)) go to 40
15 zm = -z
z1 = sqrt(zm)
z2 = z1*zm/1.5
call ja(z2, w1, w2, w1m, w2m)
bi = c1*z1*(w1m - w1)
bip = c1*zm*(w2m + w2)
if (ind == 0) return
20 if (x >= c1*abs(y)) go to 30
bi = bi*e1
bip = bip*e1
return
30 bi = bi*e
bip = bip*e
return
40 call bia(ind, z, bi, bip, ierr)
end subroutine bii

