!
bi = c1*z2r*s1
bip = c1*z2*s2
if (ind /= 0) return
bi = e*bi
bip = e*bip
return
30 if (x < 0.0) go to 50
!
!          ----  PI/6 .LT. abs(ARG(z)) .LE. PI/2  ----
!
cz = z
if (y < 0.0) cz = conjg(cz)
zz = cz*ex3c
z1 = sqrt(zz)
z2 = sqrt(z1)
z2r = 1.0/z2
cf1 = c1*z2r*ex6
cf2 = c1*z2*ex6c
call crec(real(zz), aimag(zz), u, v)
w = 1.5*cmplx(u, v)/z1
u = abs(real(w))
v = abs(aimag(w))
t = max(u, v)
!
if (t == 0.0) go to 90
u1 = u/t
v1 = v/t
r = u*u1 + v*v1
if (ind /= 0) go to 40
if (v1 >= r*xpos .or. u1 >= 0.1*r/eps) go to 90
zeta = z1*zz/1.5
cn = cos(zeta - cln2)
si = sin(zeta - cln2)
go to 70
!
!        e = exp(-2*i*(zeta - CLN2)) IF abs(ARG(zz)) .LE. PI/3
!        e = exp( 2*i*(zeta - CLN2)) IF abs(ARG(zz)) .GT. PI/3
!
40 e = (0.0, 0.0)
j = (0.0, -1.0)
s = 1.0
ce = 1.0
cf = 0.5
if (aimag(zz) <= 0.0) go to 44
s = -1.0
ce = 0.5
cf = 2.0
44 if (v1 >= 0.5*r*abs(xneg)) go to 45
if (u1 >= 0.05*r/eps) go to 90
zeta = z1*zz/1.5
e = cf*exp(2.0*s*j*zeta)
45 cn = ce*c3*(1 + e)
si = ce*s*c3*(1 - e)*j
go to 70
!
!                  ----  real(z) .LT. 0  ----
!
50 zz = -z
if (y < 0.0) zz = conjg(zz)
z1 = sqrt(zz)
z2 = sqrt(z1)
z2r = 1.0/z2
cf1 = c2*z2r
cf2 = c2*z2
call crec(real(zz), aimag(zz), u, v)
w = 1.5*cmplx(u, v)/z1
u = abs(real(w))
v = abs(aimag(w))
t = max(u, v)
!
if (t == 0.0) go to 90
u1 = u/t
v1 = v/t
r = u*u1 + v*v1
if (ind /= 0) go to 60
if (v1 >= r*xpos .or. u1 >= 0.1*r/eps) go to 90
zeta = z1*zz/1.5
cn = cos(zeta)
si = sin(zeta)
go to 70
60 e = (0.0, 0.0)
j = (0.0, -1.0)
if (v1 >= 0.5*r*abs(xneg)) go to 65
if (u1 >= 0.05*r/eps) go to 90
zeta = z1*zz/1.5
e = exp(2.0*j*zeta)
65 cn = 0.5*(1.0 + e)
si = 0.5*(1.0 - e)*j
!
70 w2 = w*w
m = 15
t = max(abs(x), abs(y))
if (t > 30.0) m = 5
m2 = m + m
i = m2 - 1
s1 = cmplx(c(i), 0.0)
s2 = cmplx(c(m2), 0.0)
s3 = cmplx(d(i), 0.0)
s4 = cmplx(d(m2), 0.0)
do k = 2,m
   i = i - 1
   s2 = c(i) - s2*w2
   s4 = d(i) - s4*w2
   i = i - 1
   s1 = c(i) - s1*w2
   s3 = d(i) - s3*w2
end do
s2 = w*s2
s4 = w*s4
if (x >= 0.0) go to 81
alpha = s1 + s2
beta = s2 - s1
go to 82
81 alpha = s1 - s2
beta = s1 + s2
82 bi = cf1*(alpha*cn + beta*si)
if (x >= 0.0) go to 83
alpha = s3 - s4
beta = s3 + s4
go to 84
83 alpha = s3 + s4
beta = s4 - s3
84 bip = cf2*(alpha*cn + beta*si)
if (y >= 0.0) return
bi = conjg(bi)
bip = conjg(bip)
return
!
!            RETURN WITH ZERO VALUES IF SCALING IS NEEDED.
!
90 bi = (0.0, 0.0)
bip = (0.0, 0.0)
ierr = 1
end subroutine bia

subroutine ia(z, i1, i2, i1m, i2m)
implicit none
!-------------------------------------------------------------
!     Calculates the modified Bessel function of the first
!     kind for orders 1/3, 2/3, -1/3, and -2/3 and for complex
!     argument z, where -Pi .LT. arg(z) .LE. pi.  i1 and i2
!     are replaced by the functions of orders 1/3 and 2/3,
!     respectively, and i1m and i2m by the functions of orders
!     -1/3 and -2/3, respectively.
!-------------------------------------------------------------
complex :: z
complex, intent(inout) :: i1, i2, i1m, i2m
complex :: cz
complex, parameter :: ex13 = (5.0e-01, 8.66025403784439e-01)
complex, parameter :: ex13c = (5.0e-01, -8.66025403784439e-01)
complex, parameter :: ex23 = (-5.0e-01, 8.66025403784439e-01)
complex, parameter :: ex23c = (-5.0e-01, -8.66025403784439e-01)
!
!     ex13 = exp(i*pi/3)
!     ex13c = exp(-i*pi/3)
!     ex23 = exp(2*i*pi/3)
!     ex23c = exp(-2*i*pi/3)
!
if (real(z) >= 0.0) go to 20
cz = -z
!
!     Calculation of i1, i2, i1m, and i2m when real(cz) .GT. 0.
!
call imc(cz, i1, i2, i1m, i2m)
!
!     Final assembly
!
if (aimag(z) < 0.0) go to 10
i1 = ex13*i1
i2 = ex23*i2
i1m = ex13c*i1m
i2m = ex23c*i2m
return
10 i1 = ex13c*i1
i2 = ex23c*i2
i1m = ex13*i1m
i2m = ex23*i2m
return
20 call imc(z, i1, i2, i1m, i2m)
end subroutine ia

subroutine imc(z, i1, i2, i1m, i2m)
implicit none
complex :: z
complex, intent(inout) :: i1, i2, i1m, i2m
integer :: i, n, n1
real :: a, an, b, cfa, cfb, cn1, cn2, m
complex :: ia1, ia2, ia3, ib1, ib2, ib3, sz, zh, e, cf1, cf2, cf3, cf4
real, parameter :: c1 = .333333333333333e+00
real, parameter :: c2 = .666666666666667e+00
real, parameter :: gm1 = .892979511569248e+00
real, parameter :: gm2 = .902745292950932e+00
!----------------------------------------------------------------
!     Calculates the modified Bessel function of the first
!     kind for orders 1/3, 2/3, -1/3, and -2/3 and for complex
!     argument z. the Maclaurin expansion and backward recurrence
!     are used. i1 and i2 are replaced by the functions of orders
!     1/3 and 2/3, respectively, and i1m and i2m by the functions
!     of orders -1/3 and -2/3, respectively.  For greatest
!     accuracy, z should lie in the region real(z) .GE. 0.
!----------------------------------------------------------------
!
!     gm1 = gamma(4.0/3.0)
!     gm2 = gamma(5.0/3.0)
!
zh = 0.5*z
sz = zh*zh
a = real(zh)
b = aimag(zh)
an = aint(a*a + b*b)
cn1 = c1 + an
cn2 = c2 + an
!
!     Calculation of initial values for backward recurrence by
!     use of the Maclaurin expansion.
!
call bim(z, cn1, ia1)
call bim(z, cn1 + 1.0, ia2)
call bim(z, cn2, ib1)
call bim(z, cn2 + 1.0, ib2)
!
!     Backward recurrence
!
n = an
m = an
n1 = n + 1
do i = 1, n1
   ia3 = ia2
   ia2 = ia1
   ib3 = ib2
   ib2 = ib1
   cfa = (m + c1)*(m + c1 + 1.0)
   cfb = (m + c2)*(m + c2 + 1.0)
   m = m - 1.0
   ia1 = ia2 + (sz/cfa)*ia3
10 ib1 = ib2 + (sz/cfb)*ib3
end do
e = exp(c1*log(zh))
cf1 = e/gm1
cf2 = e*e/gm2
cf3 = c2*cf2/zh
cf4 = c1*cf1/zh
i1 = cf1*ia2
i2 = cf2*ib2
i1m = cf3*ib1
i2m = cf4*ia1
end subroutine imc

subroutine bim(z,cn,w)
implicit none
real, intent(in) :: cn
complex :: z
complex, intent(inout) :: w
real :: d, eps
real :: anorm
real :: m
complex :: sz, t
interface
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-------------------------------------------------------------
!     Calculates the modified Bessel function of the first kind
!     for real order cn .GT. -1 And complex argument z by means
!     of the Maclaurin expansion.  w is replaced by the
!     calculated value.
!-------------------------------------------------------------
!------------------
anorm(z) = max(abs(real(z)),abs(aimag(z)))
!-------------------------------------------------------------
!     Eps is a machine dependent constant.  Eps is the smallest
!     number such that 1 + eps .GT. 1.
!
eps = spmpar(1)
!
!-------------------------------------------------------------
sz = 0.25*z*z
!
!     Initialization of Maclaurin expansion
!
m = 1.0
t = sz/(cn + 1.0)
w = t
!
!     Summation of Maclaurin expansion
!
10 m = m + 1.0
d = m*(cn + m)
t = t*(sz/d)
w = w + t
if (anorm(t) > eps*anorm(w)) go to 10
!
w = w + 1.0
end subroutine bim

subroutine ja(z, i1, i2, i1m, i2m)
implicit none
!------------------------------------------------------------
!     Calculates the Bessel function of the first kind for
!     orders 1/3, 2/3, -1/3, and -2/3 and for complex argument
!     z, where -Pi .LT. arg(z) .LE. pi.  i1 and i2 are replaced
!     by the functions of orders 1/3 and 2/3, respectively, and
!     i1m and i2m by functions of orders -1/3 and -2/3,
!     respectively.
!--------------------------------------------------------------
complex :: z
complex, intent(inout) :: i1, i2, i1m, i2m
complex :: cz
complex, parameter :: ex13 = (5.0e-01, 8.66025403784439e-01)
complex, parameter :: ex13c = (5.0e-01, -8.66025403784439e-01)
complex, parameter :: ex23 = (-5.0e-01, 8.66025403784439e-01)
complex, parameter :: ex23c = (-5.0e-01, -8.66025403784439e-01)
!
!     ex13 = exp(i*pi/3)
!     ex13c = exp(-i*pi/3)
!     ex23 = exp(2*i*pi/3)
!     ex23c = exp(-2*i*pi/3)
!
if (real(z) >= 0.0) go to 20
cz = -z
!
!     Calculation of i1, i2, i1m, and i2m when real(cz) .GT. 0.0
!
call jmc(cz, i1, i2, i1m, i2m)
!
!     Final assembly
!
if (aimag(z) < 0.0) go to 10
i1 = ex13*i1
i2 = ex23*i2
i1m = ex13c*i1m
i2m = ex23c*i2m
return
10 i1 = ex13c*i1
i2 = ex23c*i2
i1m = ex13*i1m
i2m = ex23*i2m
return
20 call jmc(z, i1, i2, i1m, i2m)
end subroutine ja

subroutine jmc(z, i1, i2, i1m, i2m)
implicit none
complex :: z
complex, intent(inout) :: i1, i2, i1m, i2m
integer :: i, n, n1
real :: a, an, b, cfa, cfb, cn1, cn2, m
complex :: ia1, ia2, ia3, ib1, ib2, ib3, sz, zh, e, cf1, cf2, cf3, cf4
real, parameter :: c1 = .333333333333333e+00
real, parameter :: c2 = .666666666666667e+00
real, parameter :: gm1 = .892979511569248e+00
real, parameter :: gm2 = .902745292950932e+00
!----------------------------------------------------------------
!     Calculates the Bessel function of the first
!     kind for orders 1/3, 2/3, -1/3, and -2/3 and for complex
!     argument z. the Maclaurin expansion and backward recurrence
!     are used. i1 and i2 are replaced by the functions of orders
!     1/3 and 2/3, respectively, and i1m and i2m by the functions
!     of orders -1/3 and -2/3, respectively.  For greatest
!     accuracy, z should lie in the region real(z) .GE. 0.
!----------------------------------------------------------------
!
!     gm1 = gamma(4.0/3.0)
!     gm2 = gamma(5.0/3.0)
!
zh = 0.5*z
sz = zh*zh
a = real(zh)
b = aimag(zh)
an = aint(a*a + b*b)
cn1 = c1 + an
cn2 = c2 + an
!
!     Calculation of initial values for backward recurrence by
!     use of the Maclaurin expansion.
!
call bjm(z, cn1, ia1)
call bjm(z, cn1 + 1.0, ia2)
call bjm(z, cn2, ib1)
call bjm(z, cn2 + 1.0, ib2)
!
!     Backward recurrence
!
n = an
n1 = n + 1
m = an
do i = 1, n1
   ia3 = ia2
   ia2 = ia1
   ib3 = ib2
   ib2 = ib1
   cfa = (m + c1)*(m + c1 + 1.0)
   cfb = (m + c2)*(m + c2 + 1.0)
   m = m - 1.0
   ia1 = ia2 - (sz/cfa)*ia3
10 ib1 = ib2 - (sz/cfb)*ib3
end do
e = exp(c1*log(zh))
cf1 = e/gm1
cf2 = e*e/gm2
cf3 = c2*cf2/zh
cf4 = c1*cf1/zh
i1 = cf1*ia2
i2 = cf2*ib2
i1m = cf3*ib1
i2m = cf4*ia1
end subroutine jmc

subroutine bjm(z,cn,w)
implicit none
real, intent(in) :: cn
complex :: z
complex, intent(inout) :: w
real :: d, eps
real :: anorm
real :: m
complex :: sz, t
interface
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-------------------------------------------------------------
!     Calculates the Bessel function of the first kind
!     for real order cn .GT. -1 And complex argument z by means
!     of the Maclaurin expansion.  w is replaced by the
!     calculated value.
!-------------------------------------------------------------
!------------------
anorm(z) = max(abs(real(z)),abs(aimag(z)))
!-------------------------------------------------------------
!     Eps is a machine dependent constant.  Eps is the smallest
!     number such that 1 + eps .GT. 1.
!
eps = spmpar(1)
!
!-------------------------------------------------------------
sz = -0.25*z*z
!
!     Initialization of Maclaurin expansion
!
m = 1.0
t = sz/(cn + 1.0)
w = t
!
!     Summation of Maclaurin expansion
!
10 m = m + 1.0
d = m*(cn + m)
t = t*(sz/d)
w = w + t
if (anorm(t) > eps*anorm(w)) go to 10
!
w = w + 1.0
end subroutine bjm

subroutine ka(ind, z, k1, k2)
implicit none
integer, intent(in) :: ind
complex, intent(in) :: z
complex, intent(inout) :: k1, k2
integer :: ind1
real :: a, b
complex :: i1, i2, i1m, i2m, cz, e
real, parameter :: pi = 3.14159265358979e+00
complex, parameter :: ex13c = (5.0e-01, -8.66025403784439e-01)
complex, parameter :: ex23c = (-5.0e-01, -8.66025403784439e-01)
complex, parameter :: j = (0.0, 1.0)
interface
   pure elemental subroutine kml(ind,z,k1,k2)
      implicit none
      integer, intent(in) :: ind
      complex, intent(in) :: z
      complex, intent(inout) :: k1
      complex, intent(inout) :: k2
   end subroutine kml
end interface
!------------------------------------------------------------
!     Calculates the modified Bessel function of the second
!     kind for orders 1/3 and 2/3 and for complex argument z,
!     where -pi .LT. arg(z) .le pi.  k1 is replaced by the
!     function of order 1/3, and k2 by the function of order
!     2/3.
!------------------------------------------------------------
!
!     ex13c = exp(-pi*i/3)
!     ex23c = exp(-2*pi*i/3)
!
a = real(z)
b = aimag(z)
if (abs(b) < -0.5*a) go to 10
!
!            ----  abs(b) .GE. -0.5*a  ----
!
call kml(ind, z, k1, k2)
return
!
!            ----  abs(b) .LT. -0.5*a  ----
!
10 cz = -z
if (aimag(z) < 0.0) cz = conjg(cz)
ind1 = 0
call kml(ind1, cz, k1, k2)
call imc(cz, i1, i2, i1m, i2m)
k1 = ex13c*k1 - j*pi*i1
k2 = ex23c*k2 - j*pi*i2
if (ind == 0) go to 20
e = exp(z)
k1 = k1*e
k2 = k2*e
20 if (aimag(z) >= 0.0) return
k1 = conjg(k1)
k2 = conjg(k2)
end subroutine ka

pure elemental subroutine kml(ind, z, k1, k2)
implicit none
integer, intent(in) :: ind
complex, intent(in) :: z
complex, intent(inout) :: k1, k2
integer :: i, l, m
real :: a, ai, al, b, c, eps, r, th, x1, x2
complex :: bi, u1, u2, u3, s, e
real, parameter :: c1 = 1.25331413731550e+00
interface
   pure elemental subroutine capo(x,y,r,theta)
      implicit none
      real, intent(in) :: x
      real, intent(in) :: y
      real, intent(inout) :: r
      real, intent(inout) :: theta
   end subroutine capo
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!------------------------------------------------------------
!     Calculates the modified Bessel function of the second
!     kind for orders 1/3 and 2/3 and for complex argument z
!     by use of the Miller algorithm.  k1 is replaced by the
!     function of order 1/3, and k2 by the function of order
!     2/3.  For greatest accuracy, z should lie in the region
!     real(z) .GE. 0.
!------------------------------------------------------------
!
!     c1 = sqrt(pi/2)
!
eps = spmpar(1)
x1 = real(z)
x2 = aimag(z)
!
!     Calculation of m for use in Miller algorithm.
!
call capo(x1, x2, r, th)
a = 3.0/(1.0 + r)
b = 14.7/(28.0 + r)
c = 2.0/(c1*eps*(2.0*r)**(0.25))
m = (0.485/r)*(log(c) + r*cos(a*th)/(1.0 + 0.008*r))**2/ &
   & (2.0*cos(b*th))**2 + 1.5
!
!     Backward recurrence in Miller algorithm.
!
s = 0.0
u2 = 0.0
u1 = eps
l = m
do i = 1, m
   al = l
   u3 = u2
   u2 = u1
   ai = ((al - 0.5)**2 - 1.0/9.0)/(al*(al + 1.0))
   bi = 2.0*(al + z)/(al + 1.0)
   u1 = (bi*u2 - u3)/ai
   s = s + u1
10 l = l - 1
end do
!
!     Final assembly
!
k1 = c1*u1/(s*sqrt(z))
k2 = k1*(z + 1.0/6.0 - u2/u1)/z
if (ind /= 0) return
e = exp(-z)
k1 = k1*e
k2 = k2*e
end subroutine kml

