30 rtx = sqrt(x)
if (x > x0) go to 40
t = 16.0/(x*rtx)
w = ((((pn4*t + pn3)*t + pn2)*t + pn1)*t + pn0) / &
   & (((((pd5*t + pd4)*t + pd3)*t + pd2)*t + pd1)*t + pd0)
aie = w/sqrt(rtx)
