pure subroutine plcopy(a,ka,m,b,kb,n)
implicit none
integer, intent(in) :: ka, kb, m, n
real, intent(in) :: a(*)
real, intent(inout) :: b(*)
integer :: j, jmax, la, lb, mp1
!     ------------------------------------------------------------------
!     Copying real polynomials
!     ------------------------------------------------------------------
!
la = 1
lb = 1
jmax = min(m, n)
do j = 1,jmax
   b(lb) = a(la)
   la = la + ka
   lb = lb + kb
end do
if (jmax == n) return
!
mp1 = m + 1
do j = mp1,n
   b(lb) = 0.0
   lb = lb + kb
end do
end subroutine plcopy

pure subroutine dpcopy(a,ka,m,b,kb,n)
implicit none
integer, intent(in) :: ka, kb, m, n
double precision, intent(in) :: a(*)
double precision, intent(inout) :: b(*)
integer :: j, jmax, la, lb, mp1
!     ------------------------------------------------------------------
!     Copying double precision polynomials
!     ------------------------------------------------------------------
!
la = 1
lb = 1
jmax = min(m, n)
do j = 1,jmax
   b(lb) = a(la)
   la = la + ka
   lb = lb + kb
end do
if (jmax == n) return
!
mp1 = m + 1
do j = mp1,n
   b(lb) = 0.d0
   lb = lb + kb
end do
end subroutine dpcopy

pure subroutine padd(a,ka,l,b,kb,m,c,kc,n)
implicit none
integer, intent(in) :: ka, kb, kc, l, m, n
real, intent(in) :: a(*), b(*)
real, intent(inout) :: c(*)
integer :: i, la, lb, lc
!     ------------------------------------------------------------------
!     Addition of real polynomials
!     ------------------------------------------------------------------
!
la = 1
lb = 1
lc = 1
do i = 1,n
   c(lc) = 0.0
   if (i <= l) c(lc) = a(la)
   if (i <= m) c(lc) = c(lc) + b(lb)
   la = la + ka
   lb = lb + kb
   lc = lc + kc
end do
end subroutine padd

pure subroutine dpadd(a,ka,l,b,kb,m,c,kc,n)
implicit none
integer, intent(in) :: ka, kb, kc, l, m, n
double precision, intent(in) :: a(*), b(*)
double precision, intent(inout) :: c(*)
integer :: i, la, lb, lc
!     ------------------------------------------------------------------
!     Addition of double precision polynomials
!     ------------------------------------------------------------------
!
la = 1
lb = 1
lc = 1
do i = 1,n
   c(lc) = 0.d0
   if (i <= l) c(lc) = a(la)
   if (i <= m) c(lc) = c(lc) + b(lb)
   la = la + ka
   lb = lb + kb
   lc = lc + kc
end do
end subroutine dpadd

pure subroutine psubt(a,ka,l,b,kb,m,c,kc,n)
implicit none
integer, intent(in) :: ka, kb, kc, l, m, n
real, intent(in) :: a(*), b(*)
real, intent(inout) :: c(*)
integer :: i, la, lb, lc
!     ------------------------------------------------------------------
!     Subtraction of real polynomials
!     ------------------------------------------------------------------
!
la = 1
lb = 1
lc = 1
do i = 1,n
   c(lc) = 0.0
   if (i <= l) c(lc) = a(la)
   if (i <= m) c(lc) = c(lc) - b(lb)
   la = la + ka
   lb = lb + kb
   lc = lc + kc
end do
end subroutine psubt

pure subroutine dpsubt(a,ka,l,b,kb,m,c,kc,n)
implicit none
integer, intent(in) :: ka, kb, kc, l, m, n
double precision, intent(in) :: a(*), b(*)
double precision, intent(inout) :: c(*)
integer :: i, la, lb, lc
!     ------------------------------------------------------------------
!     Subtraction of double precision polynomials
!     ------------------------------------------------------------------
!
la = 1
lb = 1
lc = 1
do i = 1,n
   c(lc) = 0.d0
   if (i <= l) c(lc) = a(la)
   if (i <= m) c(lc) = c(lc) - b(lb)
   la = la + ka
   lb = lb + kb
   lc = lc + kc
end do
end subroutine dpsubt

pure subroutine pmult(a,ka,l,b,kb,m,c,kc,n)
implicit none
integer, intent(in) :: ka, kb, kc, l, m, n
real, intent(in) :: a(*), b(*)
real, intent(inout) :: c(*)
integer :: i, imax, imin, j, jmax, jmin, la, lb, lc
double precision :: dsum
!     ------------------------------------------------------------------
!     Multiplication of real polynomials
!     ------------------------------------------------------------------
!
lc = 1
jmax = min(l + m - 1, n)
do j = 1,jmax
   if (j <= l) go to 10
   imin = 1 + (j - l)
   la = 1 + (l - 1)*ka
   lb = 1 + (imin - 1)*kb
   go to 20
10 imin = 1
   la = 1 + (j - 1)*ka
   lb = 1
!
20 imax = min(j, m)
   dsum = 0.d0
   do i = imin,imax
      dsum = dsum + dble(a(la))*dble(b(lb))
      la = la - ka
      lb = lb + kb
   end do
   c(lc) = dsum
40 lc = lc + kc
end do
if (jmax == n) return
!
jmin = jmax + 1
do j = jmin,n
   c(lc) = 0.0
60 lc = lc + kc
end do
end subroutine pmult

pure subroutine dpmult(a,ka,l,b,kb,m,c,kc,n)
implicit none
integer, intent(in) :: ka, kb, kc, l, m, n
double precision, intent(in) :: a(*), b(*)
double precision, intent(inout) :: c(*)
integer :: i, imax, imin, j, jmax, jmin, la, lb, lc
double precision :: sum
!     ------------------------------------------------------------------
!     Multiplication of double precision polynomials
!     ------------------------------------------------------------------
!
lc = 1
jmax = min(l + m - 1, n)
do j = 1,jmax
   if (j <= l) go to 10
   imin = 1 + (j - l)
   la = 1 + (l - 1)*ka
   lb = 1 + (imin - 1)*kb
   go to 20
10 imin = 1
   la = 1 + (j - 1)*ka
   lb = 1
!
20 imax = min(j, m)
   sum = 0.d0
   do i = imin,imax
      sum = sum + a(la)*b(lb)
      la = la - ka
      lb = lb + kb
   end do
   c(lc) = sum
40 lc = lc + kc
end do
if (jmax == n) return
!
jmin = jmax + 1
do j = jmin,n
   c(lc) = 0.d0
60 lc = lc + kc
end do
end subroutine dpmult

pure subroutine pdiv(a,ka,l,b,kb,m,c,kc,n,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, kc, l, m, n
real, intent(in) :: a(*), b(*)
real, intent(inout) :: c(*)
integer :: i, ib, ic, imax, j, la, lc
real :: b0
double precision :: dsum
!     ------------------------------------------------------------------
!     Division of real polynomials
!     ------------------------------------------------------------------
!
b0 = b(1)
if (b0 == 0.0) go to 100
ierr = 0
c(1) = a(1)/b0
if (n == 1) return
!
!               Case when m = 1
!
if (m > 1) go to 20
la = 1
lc = 1
do j = 2,n
   la = la + ka
   lc = lc + kc
   c(lc) = 0.0
   if (j <= l) c(lc) = a(la)/b0
end do
return
!
!              Case when m .GT. 1
!
20 la = 1
lc = 1
do j = 2,n
   la = la + ka
   lc = lc + kc
   ib = 1
   ic = lc
   dsum = 0.d0
   if (j <= l) dsum = a(la)
   imax = min(j, m)
   do i = 2,imax
      ib = ib + kb
      ic = ic - kc
      dsum = dsum - dble(b(ib))*dble(c(ic))
   end do
   c(lc) = sngl(dsum)/b0
end do
return
!
!                Error return
!
100 ierr = 1
end subroutine pdiv

pure subroutine dpdiv(a,ka,l,b,kb,m,c,kc,n,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, kc, l, m, n
double precision, intent(in) :: a(*), b(*)
double precision, intent(inout) :: c(*)
integer :: i, ib, ic, imax, j, la, lc
double precision :: b0, sum
!     ------------------------------------------------------------------
!     Division of double precision polynomials
!     ------------------------------------------------------------------
!
b0 = b(1)
if (b0 == 0.d0) go to 100
ierr = 0
c(1) = a(1)/b0
if (n == 1) return
!
!               Case when m = 1
!
if (m > 1) go to 20
la = 1
lc = 1
do j = 2,n
   la = la + ka
   lc = lc + kc
   c(lc) = 0.d0
   if (j <= l) c(lc) = a(la)/b0
end do
return
!
!              Case when m .GT. 1
!
20 la = 1
lc = 1
do j = 2,n
   la = la + ka
   lc = lc + kc
   ib = 1
   ic = lc
   sum = 0.d0
   if (j <= l) sum = a(la)
   imax = min(j, m)
   do i = 2,imax
      ib = ib + kb
      ic = ic - kc
      sum = sum - b(ib)*c(ic)
   end do
   c(lc) = sum/b0
end do
return
!
!                Error return
!
100 ierr = 1
end subroutine dpdiv

pure subroutine plpwr(r,a,ka,m,b,kb,n,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, m, n
real, intent(in) :: r
real, intent(in) :: a(*)
real, intent(inout) :: b(*)
integer :: i, ia, ib, imax, j, lb
real :: a0, jm1
double precision :: coeff, dsum, rp1
!     ------------------------------------------------------------------
!     SET b = a**r WHERE A IS A REAL POLYNOMIAL
!     ------------------------------------------------------------------
!
a0 = a(1)
if (a0 <= 0.0) go to 100
ierr = 0
b(1) = a0**r
if (n == 1) return
!
!            Case when m = 1 Or r = 0
!
if (m > 1 .and. r /= 0.0) go to 20
lb = 1
do j = 2,n
   lb = lb + kb
   b(lb) = 0.0
end do
return
!
!                  General case
!
20 rp1 = dble(r) + 1.d0
lb = 1
do j = 2,n
   lb = lb + kb
   jm1 = j - 1
   ia = 1
   ib = lb
   coeff = -jm1
   dsum = 0.d0
   imax = min(j, m)
   do i = 2,imax
      ia = ia + ka
      ib = ib - kb
      coeff = coeff + rp1
      dsum = dsum + coeff*dble(a(ia))*dble(b(ib))
   end do
   b(lb) = sngl(dsum)/(jm1*a0)
end do
return
!
!                Error return
!
100 ierr = 1
end subroutine plpwr

pure subroutine dplpwr(r,a,ka,m,b,kb,n,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, m, n
double precision, intent(in) :: a(*)
double precision, intent(inout) :: b(*)
double precision, intent(in) :: r
integer :: i, ia, ib, imax, j, lb
double precision :: a0, coeff, jm1, rp1, sum
!     ------------------------------------------------------------------
!     Set b = a**r where A is a double precision polynomial
!     ------------------------------------------------------------------
!
a0 = a(1)
if (a0 <= 0.d0) go to 100
ierr = 0
b(1) = a0**r
if (n == 1) return
!
!            Case when m = 1 Or r = 0
!
if (m > 1 .and. r /= 0.d0) go to 20
lb = 1
do j = 2,n
   lb = lb + kb
   b(lb) = 0.d0
end do
return
!
!                  General case
!
20 rp1 = r + 1.d0
lb = 1
do j = 2,n
   lb = lb + kb
   jm1 = j - 1
   ia = 1
   ib = lb
   coeff = -jm1
   sum = 0.d0
   imax = min(j, m)
   do i = 2,imax
      ia = ia + ka
      ib = ib - kb
      coeff = coeff + rp1
      sum = sum + coeff*a(ia)*b(ib)
   end do
   b(lb) = sum/(jm1*a0)
end do
return
!
!                Error return
!
100 ierr = 1
end subroutine dplpwr

pure subroutine pinv(a, d, n, q)
implicit none
integer, intent(in) :: n
real, intent(in) :: a(n)
real, intent(inout) :: d(n), q(*)
integer :: i, j, jj, k, l, l0, ll, m
real :: s, sum, t, u
!-----------------------------------------------------------------------
!          Computation of the inverse of the power series
!                  sum (a(i)*X**i, i = 1,2,...)
!-----------------------------------------------------------------------
!----------------------------
!     num = (n*(n + 1))/2
!     real q(num)
!----------------------------
!
!                 Compute the coefficient matrix q
!
q(1) = 1.0
k = 2
do i = 2,n
   q(k) = 0.0
10 k = k + i
end do
!
jj = 1
do j = 2,n
   l0 = jj
   jj = (j*(j + 1))/2
   k = jj
   do i = j,n
      sum = 0.0
      m = i - j + 2
      ll = l0
      do l = j,i
         sum = sum + a(m)*q(ll)
         m = m - 1
         ll = ll + (l - 1)
      end do
      q(k) = sum
      k = k + i
   end do
end do
!
!              Compute the coefficients of the inverse
!
k = 1
do j = 1,n
   u = 1.0/(j*a(1)**j)
   sum = 0.0
   do l = 1,j
      sum = sum + u*q(k)
      s = l + j - 1
      t = l
      u = -(s*u)/(t*a(1))
      k = k + 1
   end do
   d(j) = sum
end do
end subroutine pinv

pure subroutine dpinv(a, d, n, q)
implicit none
integer, intent(in) :: n
double precision, intent(in) :: a(n)
double precision, intent(inout) :: d(n), q(*)
integer :: i, j, jj, k, l, l0, ll, m
double precision :: s, sum, t, u
!-----------------------------------------------------------------------
!          Computation of the inverse of the power series
!                  sum (a(i)*X**i, i = 1,2,...)
!-----------------------------------------------------------------------
!----------------------------
!     num = (n*(n + 1))/2
!     real q(num)
!----------------------------
!
!                 Compute the coefficient matrix q
!
q(1) = 1.d0
k = 2
do i = 2,n
   q(k) = 0.d0
10 k = k + i
end do
!
jj = 1
do j = 2,n
   l0 = jj
   jj = (j*(j + 1))/2
   k = jj
   do i = j,n
      sum = 0.d0
      m = i - j + 2
      ll = l0
      do l = j,i
         sum = sum + a(m)*q(ll)
         m = m - 1
         ll = ll + (l - 1)
      end do
      q(k) = sum
      k = k + i
   end do
end do
!
!              Compute the coefficients of the inverse
!
k = 1
do j = 1,n
   u = 1.d0/(j*a(1)**j)
   sum = 0.d0
   do l = 1,j
      sum = sum + u*q(k)
      s = l + j - 1
      t = l
      u = -(s*u)/(t*a(1))
      k = k + 1
   end do
   d(j) = sum
end do
end subroutine dpinv

subroutine mplnmv(mo, au, nc, ac, fv)
implicit none
integer, intent(in) :: mo, nc
real :: ac(*)
real, intent(in) :: au
real, intent(out) :: fv
integer :: k, l
real :: ql
!     ******************************************************************
!     Fortran subroutine for multiplex polynomial evaluation
!     ******************************************************************
!     mo = Mode of operation
!     au = ARGUMENT U
!     nc = Number of coefficients
!     ac = Array of coefficients
!     fv = FUNCTION V
!
!     mo = -1 For integral
!     mo =  0 For function
!     mo = +1 For first derivative
!     mo = +2 For second derivative
!
001 fv = 0.0
l = nc
if (mo < 0) go to 002
if (mo == 0) go to 004
if (mo == 1) go to 006
if (mo >= 2) go to 008
002 ql = nc
do k = 1,nc
   fv = ac(l)/ql + au*fv
   l = l - 1
   ql = ql - 1.0
003 continue
end do
fv = au*fv
return
004 do k = 1,nc
   fv = ac(l) + au*fv
   l = l - 1
end do
return
006 if (nc <= 1) return
ql = nc
do k = 2,nc
   ql = ql - 1.0
   fv = ql*ac(l) + au*fv
   l = l - 1
end do
return
008 if (nc <= 2) return
ql = nc
do k = 3,nc
   ql = ql - 1.0
   fv = ql*(ql - 1.0)*ac(l) + au*fv
   l = l - 1
end do
end subroutine mplnmv

pure real function csevl(x, a, n)
implicit none
integer, intent(in) :: n
real, intent(in) :: x
real, intent(in) :: a(n)
integer :: i, k
real :: s0, s1, s2, x2
!-----------------------------------------------------------------------
!          Evaluate the n term Chebyshev series A at x.
!          Only half of the first coefficient is used.
!-----------------------------------------------------------------------
!
if (n > 1) go to 10
csevl = 0.5 * a(1)
return
!
10 x2 = x + x
s0 = a(n)
s1 = 0.0
do i = 2,n
   s2 = s1
   s1 = s0
   k = n - i + 1
   s0 = x2*s1 - s2 + a(k)
end do
csevl = 0.5 * (s0 - s2)
end function csevl

pure double precision function dcsevl(x, a, n)
implicit none
integer, intent(in) :: n
double precision, intent(in) :: a(n), x
integer :: i, k
double precision :: x2, s0, s1, s2
!-----------------------------------------------------------------------
!          Evaluate the n term Chebyshev series A at x.
!          Only half of the first coefficient is used.
!-----------------------------------------------------------------------
!
if (n > 1) go to 10
dcsevl = 0.5d0 * a(1)
return
!
10 x2 = x + x
s0 = a(n)
s1 = 0.d0
do i = 2,n
   s2 = s1
   s1 = s0
   k = n - i + 1
   s0 = x2*s1 - s2 + a(k)
end do
dcsevl = 0.5d0 * (s0 - s2)
end function dcsevl

subroutine lgrngn(au, na, an)
implicit none
integer, intent(in) :: na
real, intent(inout) :: an(*)
real :: au(*)
integer :: k, m
real :: dm, tm
!     ******************************************************************
!     Fortran subroutine for Lagrangian normalization factors
!     ******************************************************************
!     au = COORDINATE ARGUMENTS  (N-ARRAY)
!     na = Number of arguments   (N)
!     an = NORMALIZATION FACTORS (N-ARRAY)
!
001 do k = 1,na
   tm = 1.0
   do m = 1,na
      if (m == k) go to 002
      dm = au(k) - au(m)
      tm = dm*tm
002   continue
   end do
   an(k) = tm
end do
end subroutine lgrngn

subroutine lgrngv(mo, na, qu, au, an, ff, df, sf)
implicit none
integer, intent(in) :: mo, na
real :: an(*), au(*)
real, intent(inout) :: df(*), ff(*)
real, intent(in) :: qu
real, intent(inout) :: sf(*)
integer :: k, l
real :: dm, rm, sm, tm
logical :: ln
!     ******************************************************************
!     Fortran subroutine for Lagrangian function evaluation
!     ******************************************************************
!     mo = Mode of operation
!     na = Number of stations
!     qu = Argument of functions
!     au = STATION COORDINATES                    (N-ARRAY)
!     an = NORMALIZATION FACTORS                  (N-ARRAY)
!     ff = LAGRANGIAN FUNCTIONS                   (N-ARRAY)
!     df = FIRST DERIVATIVES                      (N-ARRAY)
!     sf = SECOND DERIVATIVES                     (N-ARRAY)
!
!     call lgrngv (0, na, qu, au, an, ff)         for functions
!     call lgrngv (1, na, qu, au, an, ff, df)     for first derivatives
!     call lgrngv (2, na, qu, au, an, ff, df, sf) for second derivatives
!
001 ln = .true.
tm = 1.0
do k = 1,na
   if (qu /= au(k)) go to 002
   ln = .false.
   go to 003
002 dm = qu - au(k)
   tm = dm*tm
003 continue
end do
do k = 1,na
   if (ln) go to 005
   if (qu /= au(k)) go to 005
   ff(k) = tm
   go to 006
005 dm = qu - au(k)
   ff(k) = tm/dm
006 ff(k) = ff(k)/an(k)
end do
if (mo <= 0) go to 050
sm = 0.0
do k = 1,na
   df(k) = sm
   if (ln) go to 012
   if (qu == au(k)) go to 013
012 dm = qu - au(k)
   sm = sm + 1.0/dm
013 continue
end do
rm = sm
if (mo == 1) go to 040
sm = 0.0
do k = 1,na
   sf(k) = sm
   if (ln) go to 022
   if (qu == au(k)) go to 023
022 dm = qu - au(k)
   sm = sm + 2.0*df(k)/dm
023 continue
end do
sm = 0.0
tm = 0.0
l = na
if (ln) go to 034
do k = 1,na
   sf(l) = tm + sf(l) + 2.0*sm*df(l)
   if (qu == au(l)) go to 032
   sf(l) = 2.0*(sm + df(l))
   dm = qu - au(l)
   tm = tm + 2.0*sm/dm
   sm = sm + 1.0/dm
032 l = l - 1
end do
go to 036
034 do k = 1,na
   sf(l) = tm + sf(l) + 2.0*sm*df(l)
   dm = qu - au(l)
   tm = tm + 2.0*sm/dm
   sm = sm + 1.0/dm
   l = l - 1
end do
036 do k = 1,na
   sf(k) = ff(k)*sf(k)
end do
040 if (ln) go to 043
do k = 1,na
   if (qu /= au(k)) go to 041
   df(k) = rm
   ff(k) = 1.0
   go to 042
041 df(k) = ff(k)
   ff(k) = 0.0
042 continue
end do
return
043 sm = 0.0
l = na
do k = 1,na
   df(l) = ff(l)*(sm + df(l))
   sm = sm + 1.0/(qu - au(l))
   l = l - 1
end do
return
050 if (ln) go to 053
do k = 1,na
   ff(k) = 0.0
   if (qu /= au(k)) go to 052
   ff(k) = 1.0
052 continue
end do
053 return
end subroutine lgrngv

subroutine lgrngx(au, na, ac)
implicit none
integer, intent(in) :: na
real, intent(inout) :: ac(*)
real :: au(*)
integer :: i, j, k, l
real :: sm, td, tm
!     ******************************************************************
!     Fortran subroutine for Lagrangian polynomial expansion
!     ******************************************************************
!     au = COORDINATE ARGUMENTS    (N-ARRAY)
!     na = Number of arguments     (N)
!     ac = Polynomial coefficients (NX(N+1) array)
!
001 do i = 1,na
   k = (i - 1)*na
   l = k + i
   ac(l) = 1.0
   sm = 0.0
   do j = 1,i
      k = k + 1
      l = k + na
      ac(l) = sm - au(i)*ac(k)
      sm = ac(k)
002   continue
   end do
003 continue
end do
do i = 1,na
   k = na + na*na
   l = i*na
   ac(l) = 1.0
   do j = 2,na
      sm = au(i)*ac(l)
      l = l - 1
      ac(l) = sm + ac(k)
      k = k - 1
   end do
end do
do i = 1,na
   tm = 1.0
   do j = 1,na
      if (j == i) go to 006
      td = au(i) - au(j)
      tm = tm*td
006   continue
   end do
   k = (i - 1)*na
   do j = 1,na
      k = k + 1
      ac(k) = ac(k)/tm
   end do
end do
end subroutine lgrngx

subroutine orthos(au, ma, aa, na, ar)
implicit none
integer, intent(in) :: ma, na
real, intent(inout) :: aa(*), ar(*)
real :: au(*)
integer :: i, j, k, l, m
real :: rm, rn, sm, sn
!     ******************************************************************
!     Fortran subroutine for orthonormal polynomial synthesis
!     ******************************************************************
!     au = COORDINATE ARGUMENTS    (N ARRAY)
!     ma = Number of columns       (m)
!     aa = Matrix of polynomials   (NXM array)
!     na = Number of rows          (N)
!     ar = RECURRENCE COEFFICIENTS (2*m-2 ARRAY)
!
001 sn = na
rn = sqrt(sn)
do i = 1,na
   aa(i) = 1.0/rn
002 continue
end do
if (ma == 1) return
003 sm = 0.0
do i = 1,na
   sm = sm + au(i)
end do
ar(2) = sm/sn
sm = 0.0
l = na
do i = 1,na
   l = l + 1
   aa(l) = au(i) - ar(2)
   sm = sm + aa(l)*aa(l)
005 continue
end do
rm = sqrt(sm)
l = na
do i = 1,na
   l = l + 1
   aa(l) = aa(l)/rm
end do
sm = 0.0
l = na
do i = 1,na
   l = l + 1
   sm = sm + au(i)*aa(l)
end do
ar(1) = sm/rn
if (ma == 2) return
008 do m = 3,ma
   sm = 0.0
   k = (m - 2)*na
   do i = 1,na
      k = k + 1
      sm = sm + au(i)*aa(k)*aa(k)
   end do
   ar(2*m - 2) = sm
   sm = 0.0
   j = (m - 3)*na
   do i = 1,na
      j = j + 1
      k = j + na
      l = k + na
      aa(l) = au(i)*aa(k) - ar(2*m - 2)*aa(k) - ar(2*m - 5)*aa(j)
      sm = sm + aa(l)*aa(l)
   end do
   rm = sqrt(sm)
   l = (m - 1)*na
   do i = 1,na
      l = l + 1
      aa(l) = aa(l)/rm
   end do
   sm = 0.0
   k = (m - 2)*na
   do i = 1,na
      k = k + 1
      l = k + na
      sm = sm + au(i)*aa(k)*aa(l)
   end do
   ar(2*m - 3) = sm
end do
end subroutine orthos

subroutine orthov(mo, na, au, ar, nf, ff, df, sf)
implicit none
integer, intent(in) :: mo, na, nf
real :: ar(*)
real, intent(in) :: au
real, intent(inout) :: df(*), ff(*), sf(*)
integer :: k, l
real :: rn, sn
!     ******************************************************************
!     Fortran subroutine for orthonormal polynomial evaluation
!     ******************************************************************
!     mo = Mode of operation
!     na = Number of coordinates
!     au = Argument of functions
!     ar = RECURRENCE COEFFICIENTS                (2*M-2 ARRAY)
!     nf = Number of functions                    (M)
!     ff = ORTHONORMAL FUNCTIONS                  (M-ARRAY)
!     df = FIRST DERIVATIVES                      (M-ARRAY)
!     sf = SECOND DERIVATIVES                     (M-ARRAY)
!
!     call orthov (0, na, au, ar, nf, ff)         for functions
!     call orthov (1, na, au, ar, nf, ff, df)     for first derivatives
!     call orthov (2, na, au, ar, nf, ff, df, sf) for second derivatives
!
001 sn = na
rn = sqrt(sn)
ff(1) = 1.0/rn
if (nf <= 1) go to 003
ff(2) = (au - ar(2))*ff(1)/ar(1)
if (nf == 2) go to 003
l = 2
do k = 3,nf
   l = l + 2
   ff(k) = ((au - ar(l))*ff(k - 1) - ar(l - 3)*ff(k - 2))/ar(l - 1)
002 continue
end do
003 if (mo <= 0) return
df(1) = 0.0
if (nf <= 1) go to 005
df(2) = ff(1)/ar(1)
if (nf == 2) go to 005
l = 2
do k = 3,nf
   l = l + 2
   df(k) = (ff(k - 1) + (au - ar(l))*df(k - 1) - ar(l - 3)*df(k - 2))/ar(l - 1)
end do
005 if (mo == 1) return
sf(1) = 0.0
if (nf <= 1) go to 007
sf(2) = 0.0
if (nf == 2) go to 007
l = 2
do k = 3,nf
   l = l + 2
   sf(k) = (2.0*df(k - 1) + (au - ar(l))*sf(k - 1) - ar(l - 3)*sf(k - 2))/ar(l - 1)
end do
007 return
end subroutine orthov

subroutine orthox(na, ar, nc, ac)
implicit none
integer, intent(in) :: na, nc
real, intent(inout) :: ac(*)
real :: ar(*)
integer :: j, k, l, m, n
real :: rn, sn, tm
!     ******************************************************************
!     Fortran subroutine for orthonormal polynomial expansion
!     ******************************************************************
!     na = Number of arguments     (n)
!     ar = RECURRENCE COEFFICIENTS (2*m-2 ARRAY)
!     nc = Number of coefficients  (m)
!     ac = POLYNOMIAL COEFFICIENTS (m*m ARRAY)
!
001 do n = 1,nc
   ac(n) = 0.0
002 continue
end do
sn = na
rn = sqrt(sn)
ac(1) = 1.0/rn
if (nc == 1) return
003 tm = 0.0
l = nc
do n = 1,nc
   l = l + 1
   ac(l) = (tm - ar(2)*ac(n))/ar(1)
   tm = ac(n)
end do
if (nc == 2) return
005 do m = 3,nc
   tm = 0.0
   j = (m - 3)*nc
   do n = 1,nc
      j = j + 1
      k = j + nc
      l = k + nc
      ac(l) = (tm - ar(2*m - 2)*ac(k) - ar(2*m - 5)*ac(j))/ar(2*m - 3)
      tm = ac(k)
   end do
end do
end subroutine orthox

real function zeroin(f, ax, bx, aerr, rerr)
implicit none
!-----------------------------------------------------------------------
!
!         Finding a zero of the function f(X) in the interval (ax,bx)
!
!                       ------------------------
!
!  Input...
!
!  f      FUNCTION SUBPROGRAM WHICH EVALUATES f(X) FOR ANY X IN THE
!         closed interval (ax,bx). It is assumed that f is continuous,
!         and that f(ax) and f(bx) have different signs.
!  ax     LEFT ENDPOINT OF THE INTERVAL
!  bx     RIGHT ENDPOINT OF THE INTERVAL
!  aerr   THE ABSOLUTE ERROR TOLERANCE TO BE SATISFIED
!  rerr   THE RELATIVE ERROR TOLERANCE TO BE SATISFIED
!
!  Output...
!
!         Abcissa approximating a zero of f in the interval (ax,bx)
!
!-----------------------------------------------------------------------
!  zeroin is a slightly modified translation of the Algol procedure
!  zero given by richard Brent in algorithms for minimization without
!  derivatives, Prentice-Hall, inc. (1973).
!-----------------------------------------------------------------------
real :: f
real, intent(in) :: ax, bx, aerr, rerr
external f
real :: a, b, c, d, e, eps, fa, fb, fc, tol, xm, p, q, r, s, atol, &
   & rtol
interface
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!
!  Compute eps, the relative machine precision
!
eps = spmpar(1)
!
! Initialization
!
a = ax
b = bx
fa = f(a)
fb = f(b)
atol = 0.5*aerr
rtol = max(0.5*rerr,2.0*eps)
!
! Begin step
!
10 c = a
fc = fa
d = b - a
e = d
20 if (abs(fc) >= abs(fb)) go to 40
a = b
b = c
c = a
fa = fb
fb = fc
fc = fa
!
! Convergence test
!
40 tol = rtol*max(abs(b),abs(c)) + atol
xm = 0.5*(c - b)
if (abs(xm) <= tol) go to 90
if (fb == 0.0) go to 90
!
! Is bisection necessary
!
if (abs(e) < tol) go to 70
if (abs(fa) <= abs(fb)) go to 70
!
! Is quadratic interpolation possible
!
if (a /= c) go to 50
!
! Linear interpolation
!
s = fb/fc
p = (c - b)*s
q = 1.0 - s
go to 60
!
! Inverse quadratic interpolation
!
50 q = fa/fc
r = fb/fc
s = fb/fa
p = s*((c - b)*q*(q - r) - (b - a)*(r - 1.0))
q = (q - 1.0)*(r - 1.0)*(s - 1.0)
!
! Adjust signs
!
60 if (p > 0.0) q = -q
p = abs(p)
!
! Is interpolation acceptable
!
if (2.0*p >= (3.0*xm*q - abs(tol*q))) go to 70
if (p >= abs(0.5*e*q)) go to 70
e = d
d = p/q
go to 80
!
! Bisection
!
70 d = xm
e = d
!
! Complete step
!
80 a = b
fa = fb
if (abs(d) > tol) b = b + d
if (abs(d) <= tol) b = b + sign(tol,xm)
fb = f(b)
if ((fb*(fc/abs(fc))) > 0.0) go to 10
go to 20
!
! Done
!
90 zeroin = b
end function zeroin

double precision function dzero(f, ax, bx, aerr, rerr)
implicit none
!-----------------------------------------------------------------------
!
!         Finding a zero of the function f(X) in the interval (ax,bx)
!
!                       ------------------------
!
!  Input...
!
!  f      FUNCTION SUBPROGRAM WHICH EVALUATES f(X) FOR ANY X IN THE
!         closed interval (ax,bx). It is assumed that f is continuous,
!         and that f(ax) and f(bx) have different signs.
!  ax     LEFT ENDPOINT OF THE INTERVAL
!  bx     RIGHT ENDPOINT OF THE INTERVAL
!  aerr   THE ABSOLUTE ERROR TOLERANCE TO BE SATISFIED
!  rerr   THE RELATIVE ERROR TOLERANCE TO BE SATISFIED
!
!  Output...
!
!         Abcissa approximating a zero of f in the interval (ax,bx)
!
!-----------------------------------------------------------------------
!  dzero is a slightly modified translation of the Algol procedure
!  zero given by richard Brent in algorithms for minimization without
!  derivatives, Prentice-Hall, inc. (1973).
!-----------------------------------------------------------------------
double precision :: f
double precision, intent(in) :: ax, bx, aerr, rerr
external f
double precision :: a, b, c, d, e, eps, fa, fb, fc, tol, xm, p, q, &
   & r, s, atol, rtol
interface
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
end interface
!
!  Compute eps, the relative machine precision
!
eps = dpmpar(1)
!
! Initialization
!
a = ax
b = bx
fa = f(a)
fb = f(b)
atol = 0.5d0*aerr
rtol = max(0.5d0*rerr,2.d0*eps)
!
! Begin step
!
10 c = a
fc = fa
d = b - a
e = d
20 if (abs(fc) >= abs(fb)) go to 40
a = b
b = c
c = a
fa = fb
fb = fc
fc = fa
!
! Convergence test
!
40 tol = rtol*max(abs(b),abs(c)) + atol
xm = 0.5d0*(c - b)
if (abs(xm) <= tol) go to 90
if (fb == 0.d0) go to 90
!
! Is bisection necessary
!
if (abs(e) < tol) go to 70
if (abs(fa) <= abs(fb)) go to 70
!
! Is quadratic interpolation possible
!
if (a /= c) go to 50
!
! Linear interpolation
!
s = fb/fc
p = (c - b)*s
q = 1.d0 - s
go to 60
!
! Inverse quadratic interpolation
!
50 q = fa/fc
r = fb/fc
s = fb/fa
p = s*((c - b)*q*(q - r) - (b - a)*(r - 1.d0))
q = (q - 1.d0)*(r - 1.d0)*(s - 1.d0)
!
! Adjust signs
!
60 if (p > 0.d0) q = -q
p = abs(p)
!
! Is interpolation acceptable
!
if (2.d0*p >= (3.d0*xm*q - abs(tol*q))) go to 70
if (p >= abs(0.5d0*e*q)) go to 70
e = d
d = p/q
go to 80
!
! Bisection
!
70 d = xm
e = d
!
! Complete step
!
80 a = b
fa = fb
if (abs(d) > tol) b = b + d
if (abs(d) <= tol) b = b + sign(tol,xm)
fb = f(b)
if ((fb*(fc/abs(fc))) > 0.d0) go to 10
go to 20
!
! Done
!
90 dzero = b
end function dzero

subroutine hbrd(fcn,n,x,fvec,epsfcn,tol,info,wa,lwa)
implicit none
integer :: n
integer, intent(out) :: info
integer, intent(in) :: lwa
real, intent(in) :: epsfcn, tol
real, intent(inout) :: x(n), fvec(n), wa(lwa)
external fcn
integer :: index, j, lr, maxfev, ml, mode, mu, nfev, nprint
real :: xtol
real, parameter :: factor = 1.0e2
real, parameter :: one = 1.0e0
real, parameter :: zero = 0.0e0
!     **********
!
!     SUBROUTINE hbrd
!
!       The purpose of hbrd is to find a zero of a system of
!     n nonlinear functions in n variables by a modification
!     of the Powell hybrid method. This is done by using the
!     more general nonlinear equation solver hybrd. The user
!     must provide a subroutine which calculates the functions.
!     The Jacobian is then calculated by a forward-difference
!     approximation.
!
!     The subroutine statement is
!
!       subroutine hbrd(fcn,n,x,fvec,epsfcn,tol,info,wa,lwa)
!
!     Where
!
!       FCN is the name of the user-supplied subroutine which
!         calculates the functions. FCN must be declared
!         in an external statement in the user calling
!         program, and should be written as follows.
!
!         subroutine fcn(n,x,fvec,iflag)
!         integer n,iflag
!         real x(n),fvec(n)
!         ----------
!         Calculate the functions at x and
!         RETURN THIS VECTOR IN fvec.
!         ---------
!         return
!         end
!
!         The value of IFLAG should not be changed by FCN unless
!         the user wants to terminate the execution of hbrd.
!         In this case set IFLAG to a negative integer.
!
!       n is a positive integer input variable SET to the number
!         of functions and variables.
!
!       x is an array of length n. on input x must contain
!         an initial estimate of the solution vector. On output x
!         contains the final estimate of the solution vector.
!
!       fvec is an output array of length n which contains
!         the functions evaluated at the output x.
!
!       epsfcn is an input variable used in determining a suitable
!         step length for the forward-difference approximation. This
!         approximation assumes that the relative errors in the
!         functions are of the order of epsfcn. If epsfcn is less
!         than the machine precision, it is assumed that the relative
!         errors in the functions are of the order of the machine
!         precision.
!
!       tol is a nonnegative input variable. Termination occurs
!         when the algorithm estimates that the relative error
!         between x and the solution is at most tol.
!
!       Info is an integer output variable. If the user has
!         terminated execution, info is set to the (negative)
!         value of IFLAG. See description of FCN. Otherwise,
!         info is set as follows.
!
!         info = 0   Improper input parameters.
!
!         info = 1   Algorithm estimates that the relative error
!                    between x and the solution is at most tol.
!
!         info = 2   Number of calls to FCN has reached or exceeded
!                    200*(n+1).
!
!         info = 3   tol is too small. No further improvement in
!                    the approximate solution x is possible.
!
!         info = 4   Iteration is not making good progress.
!
!       wa is a work array of length lwa.
!
!       lwa is a positive integer input variable NOT less than
!         (n*(3*n+13))/2.
!
!     Subprograms called
!
!       User-supplied ...... FCN
!
!       MINPACK-supplied ... hybrd
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
info = 0
!
!     Check the input parameters for errors.
!
if (n <= 0 .or. epsfcn < zero .or. tol < zero .or. &
   & lwa < (n*(3*n + 13))/2) go to 20
!
!     CALL hybrd.
!
maxfev = 200*(n + 1)
xtol = tol
ml = n - 1
mu = n - 1
mode = 2
do j = 1, n
   wa(j) = one
end do
nprint = 0
lr = (n*(n + 1))/2
index = 6*n + lr
call hybrd(fcn,n,x,fvec,xtol,maxfev,ml,mu,epsfcn,wa(1),mode, &
   & factor,nprint,info,nfev,wa(index + 1),n,wa(6*n + 1),lr, &
   & wa(n + 1),wa(2*n + 1),wa(3*n + 1),wa(4*n + 1),wa(5*n + 1))
if (info == 5) info = 4
20 continue
!
!     Last card of subroutine hbrd.
!
end subroutine hbrd

subroutine hybrd(fcn,n,x,fvec,xtol,maxfev,ml,mu,epsfcn,diag, &
   & mode,factor,nprint,info,nfev,fjac,ldfjac,r,lr, &
   & qtf,wa1,wa2,wa3,wa4)
implicit none
integer :: n
integer, intent(in) :: maxfev, ml, mu, mode, nprint
integer, intent(out) :: info, nfev
integer, intent(in) :: ldfjac, lr
real, intent(in) :: xtol, epsfcn, factor
real, intent(inout) :: x(n), fvec(n), diag(n), fjac(ldfjac,n), &
   & r(lr), qtf(n), wa1(n), wa2(n), wa3(n)
real :: wa4(n)
external fcn
integer :: i, iflag, iter, j, jm1, l, msum, ncfail, ncsuc, nslow1, nslow2, iwa(1)
logical :: jeval, sing
real :: actred, delta, epsmch, fnorm, fnorm1, pnorm, prered, ratio, sum, temp, xnorm
real :: enorm
real, parameter :: one = 1.0e0
real, parameter :: p1 = 1.0e-1
real, parameter :: p5 = 5.0e-1
real, parameter :: p001 = 1.0e-3
real, parameter :: p0001 = 1.0e-4
real, parameter :: zero = 0.0e0
interface
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!     **********
!
!     SUBROUTINE hybrd
!
!     The purpose of hybrd is to find a zero of a system of
!     n nonlinear functions in n variables by a modification
!     of the Powell hybrid method. The user must provide A
!     subroutine which calculates the functions. The Jacobian is
!     then calculated by a forward-difference approximation.
!
!     The subroutine statement is
!
!       subroutine hybrd(fcn,n,x,fvec,xtol,maxfev,ml,mu,epsfcn,
!                        diag,mode,factor,nprint,info,nfev,fjac,
!                        ldfjac,R,lr,QTF,WA1,WA2,WA3,wa4)
!
!     Where
!
!       FCN is the name of the user-supplied subroutine which
!         calculates the functions. FCN must be declared
!         in an external statement in the user calling
!         program, and should be written as follows.
!
!         subroutine fcn(n,x,fvec,iflag)
!         integer n,iflag
!         real x(n),fvec(n)
!         ----------
!         Calculate the functions at x and
!         RETURN THIS VECTOR IN fvec.
!         ---------
!         return
!         end
!
!         The value of iflag should not be changed by FCN unless
!         the user wants to terminate execution of hybrd.
!         In this case set iflag to a negative integer.
!
!       n is a positive integer input variable SET to the number
!         of functions and variables.
!
!       x is an array of length n. on input x must contain
!         an initial estimate of the solution vector. On output x
!         contains the final estimate of the solution vector.
!
!       fvec is an output array of length n which contains
!         the functions evaluated at the output x.
!
!       xtol is a nonnegative input variable. Termination
!         occurs when the relative error between two consecutive
!         iterates is at most xtol.
!
!       maxfev is a positive integer input variable. Termination
!         occurs when the number of calls to FCN is at least maxfev
!         by the end of an iteration.
!
!       ml is a nonnegative integer input variable which specifies
!         the number of subdiagonals within the band of the
!         Jacobian matrix. If the Jacobian is not banded, set
!         ml to at least n - 1.
!
!       mu is a nonnegative integer input variable which specifies
!         the number of superdiagonals within the band of the
!         Jacobian matrix. If the Jacobian is not banded, set
!         mu to at least n - 1.
!
!       epsfcn is an input variable used in determining a suitable
!         step length for the forward-difference approximation. This
!         approximation assumes that the relative errors in the
!         functions are of the order of epsfcn. If epsfcn is less
!         than the machine precision, it is assumed that the relative
!         errors in the functions are of the order of the machine
!         precision.
!
!       Diag is an array of length n. if mode = 1 (see
!         below), diag is internally set. If mode = 2, diag
!         must contain positive entries that serve as
!         multiplicative scale factors for the variables.
!
!       Mode is an integer input variable. If mode = 1, the
!         variables will be scaled internally. If mode = 2,
!         the scaling is specified by the input diag. Other
!         values of mode are equivalent to mode = 1.
!
!       Factor is a positive input variable used in determining the
!         initial step bound. This bound is set to the product of
!         factor and the Euclidean norm of diag*x if nonzero, or else
!         to factor itself. In most cases factor should lie in the
!         interval (.1,100.). 100. Is a generally recommended value.
!
!       nprint is an integer input variable that enables controlled
!         printing of iterates if it is positive. In this case,
!         FCN is called with iflag = 0 At the beginning of the first
!         iteration and every nprint iterations thereafter and
!         immediately prior to return, with x and fvec available
!         for printing. If nprint is not positive, no special calls
!         of FCN with iflag = 0 Are made.
!
!       Info is an integer output variable. If the user has
!         terminated execution, info is set to the (negative)
!         value of iflag. See description of FCN. Otherwise,
!         info is set as follows.
!
!         info = 0   Improper input parameters.
!
!         info = 1   Relative error between two consecutive iterates
!                    is at most xtol.
!
!         info = 2   Number of calls to FCN has reached or exceeded
!                    maxfev.
!
!         info = 3   xtol is too small. No further improvement in
!                    the approximate solution x is possible.
!
!         info = 4   Iteration is not making good progress, as
!                    measured by the improvement from the last
!                    five Jacobian evaluations.
!
!         info = 5   Iteration is not making good progress, as
!                    measured by the improvement from the last
!                    ten iterations.
!
!       nfev is an integer output variable SET to the number of
!         calls to FCN.
!
!       fjac is an output n by n array which contains the
!         orthogonal matrix Q produced by the QR factorization
!         of the final approximate Jacobian.
!
!       ldfjac is a positive integer input variable NOT less than n
!         which specifies the leading dimension of the array fjac.
!
!       R is an output array of length lr which contains the
!         upper triangular matrix produced by the QR factorization
!         of the final approximate Jacobian, stored rowwise.
!
!       lr is a positive integer input variable NOT less than
!         (n*(n+1))/2.
!
!       QTF is an output array of length n which contains
!         the vector (Q transpose)*fvec.
!
!       WA1, WA2, WA3, and wa4 are work arrays of length n.
!
!     Subprograms called
!
!       User-supplied ...... FCN
!
!       MINPACK-supplied ... dogleg,spmpar,enorm,fdjac1,
!                            qform,qrfac,r1mpyq,r1updt
!
!       Fortran-supplied ... abs,AMAX1,AMIN1,MIN0,mod
!
!     Argonne National Laboratory. MINPACK project. March 1980.
!     Burton S. Garbow, kenneth E. Hillstrom, jorge j. more
!
!     **********
!
!     epsmch is the machine precision.
!
epsmch = spmpar(1)
!
info = 0
iflag = 0
nfev = 0
!
!     Check the input parameters for errors.
!
if (n <= 0 .or. xtol < zero .or. maxfev <= 0 &
   & .or. ml < 0 .or. mu < 0 .or. factor <= zero &
   & .or. ldfjac < n .or. lr < (n*(n + 1))/2) go to 300
if (mode /= 2) go to 20
do j = 1, n
   if (diag(j) <= zero) go to 300
10 continue
end do
20 continue
!
!     Evaluate the function at the starting point
!     and calculate its norm.
!
iflag = 1
call fcn(n,x,fvec,iflag)
nfev = 1
if (iflag < 0) go to 300
fnorm = enorm(n,fvec)
!
!     Determine the number of calls to FCN needed to compute
!     the Jacobian matrix.
!
msum = min(ml + mu + 1,n)
!
!     Initialize iteration counter and monitors.
!
iter = 1
ncsuc = 0
ncfail = 0
nslow1 = 0
nslow2 = 0
!
!     Beginning of the outer loop.
!
30 continue
jeval = .true.
!
!        Calculate the Jacobian matrix.
!
iflag = 2
call fdjac1(fcn,n,x,fvec,fjac,ldfjac,iflag,ml,mu,epsfcn,wa1, &
   & wa2)
nfev = nfev + msum
if (iflag < 0) go to 300
!
!        Compute the QR factorization of the Jacobian.
!
call qrfac(n,n,fjac,ldfjac,.false.,iwa,1,wa1,wa2,wa3)
!
!        On the first iteration and if mode is 1, scale according
!        to the norms of the columns of the initial Jacobian.
!
if (iter /= 1) go to 70
if (mode == 2) go to 50
do j = 1, n
   diag(j) = wa2(j)
   if (wa2(j) == zero) diag(j) = one
end do
50 continue
!
!        On the first iteration, calculate the norm of the scaled x
!        and initialize the step bound delta.
!
do j = 1, n
   wa3(j) = diag(j)*x(j)
end do
xnorm = enorm(n,wa3)
delta = factor*xnorm
if (delta == zero) delta = factor
70 continue
!
!        Form (Q transpose)*fvec and store in QTF.
!
do i = 1, n
   qtf(i) = fvec(i)
end do
do j = 1, n
   if (fjac(j,j) == zero) go to 110
   sum = zero
   do i = j, n
      sum = sum + fjac(i,j)*qtf(i)
   end do
   temp = -sum/fjac(j,j)
   do i = j, n
      qtf(i) = qtf(i) + fjac(i,j)*temp
   end do
110 continue
end do
!
!        Copy the triangular factor of the QR factorization into R.
!
sing = .false.
do j = 1, n
   l = j
   jm1 = j - 1
   if (jm1 < 1) go to 140
   do i = 1, jm1
      r(l) = fjac(i,j)
      l = l + n - i
   end do
140 continue
   r(l) = wa1(j)
   if (wa1(j) == zero) sing = .true.
end do
!
!        Accumulate the orthogonal factor in fjac.
!
call qform(n,n,fjac,ldfjac,wa1)
!
!        Rescale if necessary.
!
if (mode == 2) go to 170
do j = 1, n
   diag(j) = max(diag(j),wa2(j))
end do
170 continue
!
!        Beginning of the inner loop.
!
180 continue
!
!           If requested, call FCN to enable printing of iterates.
!
if (nprint <= 0) go to 190
iflag = 0
if (mod(iter - 1,nprint) == 0) call fcn(n,x,fvec,iflag)
if (iflag < 0) go to 300
190 continue
!
!           Determine the direction P.
!
call dogleg(n,r,lr,diag,qtf,delta,wa1,wa2,wa3)
!
!           Store the direction P and x + P. calculate the norm of P.
!
do j = 1, n
   wa1(j) = -wa1(j)
   wa2(j) = x(j) + wa1(j)
   wa3(j) = diag(j)*wa1(j)
end do
pnorm = enorm(n,wa3)
!
!           On the first iteration, adjust the initial step bound.
!
if (iter == 1) delta = min(delta,pnorm)
!
!           Evaluate the function at x + P and calculate its norm.
!
iflag = 1
call fcn(n,wa2,wa4,iflag)
nfev = nfev + 1
if (iflag < 0) go to 300
fnorm1 = enorm(n,wa4)
!
!           Compute the scaled actual reduction.
!
actred = -one
if (fnorm1 < fnorm) actred = one - (fnorm1/fnorm)**2
!
!           Compute the scaled predicted reduction.
!
l = 1
do i = 1, n
   sum = zero
   do j = i, n
      sum = sum + r(l)*wa1(j)
      l = l + 1
   end do
   wa3(i) = qtf(i) + sum
end do
temp = enorm(n,wa3)
prered = zero
if (temp < fnorm) prered = one - (temp/fnorm)**2
!
!           Compute the ratio of the actual to the predicted
!           reduction.
!
ratio = zero
if (prered > zero) ratio = actred/prered
!
!           Update the step bound.
!
if (ratio >= p1) go to 230
ncsuc = 0
ncfail = ncfail + 1
delta = p5*delta
go to 240
230 continue
ncfail = 0
ncsuc = ncsuc + 1
if (ratio >= p5 .or. ncsuc > 1) &
   & delta = max(delta,pnorm/p5)
if (abs(ratio - one) <= p1) delta = pnorm/p5
240 continue
!
!           Test for successful iteration.
!
if (ratio < p0001) go to 260
!
!           Successful iteration. Update x, fvec, and their norms.
!
do j = 1, n
   x(j) = wa2(j)
   wa2(j) = diag(j)*x(j)
   fvec(j) = wa4(j)
end do
xnorm = enorm(n,wa2)
fnorm = fnorm1
iter = iter + 1
260 continue
!
!           Determine the progress of the iteration.
!
nslow1 = nslow1 + 1
if (actred >= p001) nslow1 = 0
if (jeval) nslow2 = nslow2 + 1
if (actred >= p1) nslow2 = 0
!
!           Test for convergence.
!
if (delta <= xtol*xnorm .or. fnorm == zero) info = 1
if (info /= 0) go to 300
!
!           Tests for termination and stringent tolerances.
!
if (nfev >= maxfev) info = 2
if (p1*max(p1*delta,pnorm) <= epsmch*xnorm) info = 3
if (nslow2 == 5) info = 4
if (nslow1 == 10) info = 5
if (info /= 0) go to 300
!
!           Criterion for recalculating Jacobian approximation
!           by forward differences.
!
if (ncfail == 2) go to 290
!
!           Calculate the rank one modification to the Jacobian
!           and update QTF if necessary.
!
do j = 1, n
   sum = zero
   do i = 1, n
      sum = sum + fjac(i,j)*wa4(i)
   end do
   wa2(j) = (sum - wa3(j))/pnorm
   wa1(j) = diag(j)*((diag(j)*wa1(j))/pnorm)
   if (ratio >= p0001) qtf(j) = sum
end do
!
!           Compute the QR factorization of the updated Jacobian.
!
call r1updt(n,n,r,lr,wa1,wa2,wa3,sing)
call r1mpyq(n,n,fjac,ldfjac,wa2,wa3)
call r1mpyq(1,n,qtf,1,wa2,wa3)
!
!           END OF THE INNER LOOP.
!
jeval = .false.
go to 180
290 continue
!
!        END OF THE OUTER LOOP.
!
go to 30
300 continue
!
!     Termination, either normal or user imposed.
!
if (iflag < 0) info = iflag
iflag = 0
if (nprint > 0) call fcn(n,x,fvec,iflag)
!
!     Last card of subroutine hybrd.
!
end subroutine hybrd

pure subroutine qdcrt(a, z)
implicit none
real, intent(in) :: a(3)
complex, intent(inout) :: z(2)
real :: d, eps, r, w, x, y
interface
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-----------------------------------------------------------------------
!
!        qdcrt computes the roots of the real polynomial
!              a(1) + a(2)*z + a(3)*z**2
!     and stores the results in z. it is assumed that a(3)
!     is nonzero.
!
!-----------------------------------------------------------------------
!-----------------------------------------------------------------------
!
!     ***** eps is a machine dependent constant. Eps is the
!           smallest number such that 1.0 + eps .GT. 1.0.
!
eps = spmpar(1)
!
!-------------------
if (a(1) == 0.0) go to 40
d = a(2)*a(2) - 4.0*a(1)*a(3)
if (abs(d) <= 2.0*eps*a(2)*a(2)) go to 20
r = sqrt(abs(d))
if (d < 0.0) go to 30
!
!                 Distinct real roots
!
if (a(2) /= 0.0) go to 10
x = abs(0.5*r/a(3))
z(1) = cmplx(x, 0.0)
z(2) = cmplx(-x, 0.0)
return
10 w = -(a(2) + sign(r,a(2)))
z(1) = cmplx(2.0*a(1)/w, 0.0)
z(2) = cmplx(0.5*w/a(3), 0.0)
return
!
!                  Equal real roots
!
20 z(1) = cmplx(-0.5*a(2)/a(3), 0.0)
z(2) = z(1)
return
!
!                   complex roots
!
30 x = -0.5*a(2)/a(3)
y = abs(0.5*r/a(3))
z(1) = cmplx(x, y)
z(2) = cmplx(x,-y)
return
!
!                 Case when a(1) = 0
!
40 z(1) = (0.0, 0.0)
z(2) = cmplx(-a(2)/a(3), 0.0)
end subroutine qdcrt

pure subroutine dqdcrt(a, zr, zi)
implicit none
!-----------------------------------------------------------------------
!
!        dqdcrt computes the roots of the real polynomial
!                a(1) + a(2)*Z + a(3)*Z**2
!     and stores the results in zr and zi. It is assumed that
!     a(3) is nonzero.
!
!-----------------------------------------------------------------------
double precision, intent(in) :: a(3)
double precision, intent(inout) :: zr(2), zi(2)
double precision :: d, eps, r, w
interface
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
end interface
!-----------------------------------------------------------------------
!
!     ***** eps is a machine dependent constant. Eps is the
!           smallest number such that 1.D0 + eps .GT. 1.D0.
!
eps = dpmpar(1)
!
!-------------------
if (a(1) == 0.d0) go to 40
d = a(2)*a(2) - 4.d0*a(1)*a(3)
if (abs(d) <= 2.d0*eps*a(2)*a(2)) go to 20
r = sqrt(abs(d))
if (d < 0.d0) go to 30
!
!                 Distinct real roots
!
zi(1) = 0.d0
zi(2) = 0.d0
if (a(2) /= 0.d0) go to 10
zr(1) = abs(0.5d0*r/a(3))
zr(2) = -zr(1)
return
10 w = -(a(2) + sign(r,a(2)))
zr(1) = 2.d0*a(1)/w
zr(2) = 0.5d0*w/a(3)
return
!
!                  Equal real roots
!
20 zr(1) = -0.5d0*a(2)/a(3)
zr(2) = zr(1)
zi(1) = 0.d0
zi(2) = 0.d0
return
!
!                   complex roots
!
30 zr(1) = -0.5d0*a(2)/a(3)
zr(2) = zr(1)
zi(1) = abs(0.5d0*r/a(3))
zi(2) = -zi(1)
return
!
!                 Case when a(1) = 0
!
40 zr(1) = 0.d0
zr(2) = -a(2)/a(3)
zi(1) = 0.d0
zi(2) = 0.d0
end subroutine dqdcrt

pure subroutine cbcrt(a, z)
implicit none
real, intent(in) :: a(4)
complex, intent(inout) :: z(3)
real :: arg, c, cf, d, eps, p, p1, q, q1, r, r1, ra, rb, rq, rt, s, sf, sq, sum, t, t1, tol, w, w1, w2, x, x1, x2, x3, y, y1, y2, &
   & y3, aq(3)
real, parameter :: rt3 = 1.7320508075689
interface
   pure elemental function cbrt(x)
      implicit none
      real, intent(in) :: x
      real :: cbrt
   end function cbrt
   pure subroutine qdcrt(a,z)
      implicit none
      real, intent(in) :: a(3)
      complex, intent(inout) :: z(2)
   end subroutine qdcrt
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-----------------------------------------------------------------------
!
!        cbcrt computes the roots of the real polynomial
!              a(1) + a(2)*z + a(3)*z**2 + a(4)*z**3
!     and stores the results in z. it is assumed that a(4)
!     is nonzero.
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris
!        naval surface weapons center
!        Dahlgren, Virginia
!-----------------------------------------------------------------------
!-------------------
!-----------------------------------------------------------------------
!
!     ***** eps is a machine dependent constant. Eps is the
!           smallest number such that 1.0 + eps .GT. 1.0.
!
eps = spmpar(1)
!
!-------------------
if (a(1) == 0.0) go to 100
p = a(3)/(3.0*a(4))
q = a(2)/a(4)
r = a(1)/a(4)
tol = 4.0*eps
!
c = 0.0
t = a(2) - p*a(3)
if (abs(t) > tol*abs(a(2))) c = t/a(4)
!
t = 2.0*p*p - q
if (abs(t) <= tol*abs(q)) t = 0.0
d = r + p*t
if (abs(d) <= tol*abs(r)) go to 110
!
!           SET  SQ = (a(4)/S)**2 * (c**3/27 + d**2/4)
!
s = max(abs(a(1)),abs(a(2)),abs(a(3)))
p1 = a(3)/(3.0*s)
q1 = a(2)/s
r1 = a(1)/s
!
t1 = q - 2.25*p*p
if (abs(t1) <= tol*abs(q)) t1 = 0.0
w = 0.25*r1*r1
w1 = 0.5*p1*r1*t
w2 = q1*q1*t1/27.0
if (w1 < 0.0) go to 10
w = w + w1
sq = w + w2
go to 12
10 if (w2 < 0.0) go to 11
w = w + w2
sq = w + w1
go to 12
11 sq = w + (w1 + w2)
12 if (abs(sq) <= tol*w) sq = 0.0
rq = abs(s/a(4))*sqrt(abs(sq))
if (sq >= 0.0) go to 40
!
!                   All roots are real
!
arg = atan2(rq, -0.5*d)
cf = cos(arg/3.0)
sf = sin(arg/3.0)
rt = sqrt(-c/3.0)
y1 = 2.0*rt*cf
y2 = -rt*(cf + rt3*sf)
y3 = -(d/y1)/y2
!
x1 = y1 - p
x2 = y2 - p
x3 = y3 - p
if (abs(x1) <= abs(x2)) go to 20
t = x1
x1 = x2
x2 = t
20 if (abs(x2) <= abs(x3)) go to 30
t = x2
x2 = x3
x3 = t
if (abs(x1) <= abs(x2)) go to 30
t = x1
x1 = x2
x2 = t
!
30 w = x3
if (abs(x2) < 0.1*abs(x3)) go to 70
if (abs(x1) < 0.1*abs(x2)) x1 = - (r/x3)/x2
z(1) = cmplx(x1, 0.0)
z(2) = cmplx(x2, 0.0)
z(3) = cmplx(x3, 0.0)
return
!
!                  Real and complex roots
!
40 ra = cbrt(-0.5*d - sign(rq,d))
rb = -c/(3.0*ra)
t = ra + rb
w = -p
x = -p
if (abs(t) <= tol*abs(ra)) go to 41
w = t - p
x = -0.5*t - p
if (abs(x) <= tol*abs(p)) x = 0.0
41 t = abs(ra - rb)
y = 0.5*rt3*t
!
if (t <= tol*abs(ra)) go to 60
if (abs(x) < abs(y)) go to 50
s = abs(x)
t = y/x
go to 51
50 s = abs(y)
t = x/y
51 if (s < 0.1*abs(w)) go to 70
w1 = w/s
sum = 1.0 + t*t
if (w1*w1 < 0.01*sum) w = - ((r/sum)/s)/s
z(1) = cmplx(w,0.0)
z(2) = cmplx(x, y)
z(3) = cmplx(x,-y)
return
!
!               At least two roots are equal
!
60 if (abs(x) < abs(w)) go to 61
if (abs(w) < 0.1*abs(x)) w = - (r/x)/x
z(1) = cmplx(w, 0.0)
z(2) = cmplx(x, 0.0)
z(3) = z(2)
return
61 if (abs(x) < 0.1*abs(w)) go to 70
z(1) = cmplx(x, 0.0)
z(2) = z(1)
z(3) = cmplx(w, 0.0)
return
!
!     Here W is much larger in magnitude than the other roots.
!     As a result, the other roots may be exceedingly inaccurate
!     because of roundoff error. To deal with this, a quadratic
!     is formed whose roots are the same as the smaller roots of
!     the cubic. This quadratic is then solved.
!
!     This code was written by william L. Davis (NSWC).
!
70 aq(1) = a(1)
aq(2) = a(2) + a(1)/w
aq(3) = -a(4)*w
call qdcrt(aq, z)
z(3) = cmplx(w, 0.0)
!
if (aimag(z(1)) == 0.0) return
z(3) = z(2)
z(2) = z(1)
z(1) = cmplx(w, 0.0)
return
!-----------------------------------------------------------------------
!
!                  Case when a(1) = 0
!
100 z(1) = (0.0, 0.0)
call qdcrt(a(2), z(2))
return
!
!                   Case when d = 0
!
110 z(1) = cmplx(-p, 0.0)
w = sqrt(abs(c))
if (c < 0.0) go to 120
z(2) = cmplx(-p, w)
z(3) = cmplx(-p,-w)
return
!
120 if (p /= 0.0) go to 130
z(2) = cmplx(w, 0.0)
z(3) = cmplx(-w, 0.0)
return
!
130 x = -(p + sign(w,p))
z(3) = cmplx(x, 0.0)
t = 3.0*a(1)/(a(3)*x)
if (abs(p) > abs(t)) go to 131
z(2) = cmplx(t, 0.0)
return
131 z(2) = z(1)
z(1) = cmplx(t, 0.0)
end subroutine cbcrt

pure subroutine dcbcrt(a, zr, zi)
implicit none
!-----------------------------------------------------------------------
!
!        dcbcrt computes the roots of the real polynomial
!              a(1) + a(2)*Z + a(3)*Z**2 + a(4)*Z**3
!     and stores the results in zr and zi. It is assumed that
!     a(4) is nonzero.
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris
!        naval surface weapons center
!        Dahlgren, Virginia
!-----------------------------------------------------------------------
double precision, intent(in) :: a(4)
double precision, intent(inout) :: zr(3), zi(3)
double precision :: aq(3), arg, c, cf, d, eps, p, p1, q, q1, r, ra, rb, rq, rt, r1, s, sf, sq, sum, t, tol, t1, w, w1, w2, x, x1, &
   & x2, x3, y, y1, y2, y3
double precision, parameter :: rt3 = 1.732050807568877293527446341505872366943d0
interface
   pure elemental function dcbrt(x)
      implicit none
      double precision, intent(in) :: x
      double precision :: dcbrt
   end function dcbrt
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
   pure subroutine dqdcrt(a,zr,zi)
      implicit none
      double precision, intent(in) :: a(3)
      double precision, intent(inout) :: zr(2)
      double precision, intent(inout) :: zi(2)
   end subroutine dqdcrt
end interface
!-------------------
!-----------------------------------------------------------------------
!
!     ***** eps is a machine dependent constant. Eps is the
!           smallest number such that 1.D0 + eps .GT. 1.D0.
!
eps = dpmpar(1)
!
!-------------------
if (a(1) == 0.d0) go to 100
p = a(3)/(3.d0*a(4))
q = a(2)/a(4)
r = a(1)/a(4)
tol = 4.d0*eps
!
c = 0.d0
t = a(2) - p*a(3)
if (abs(t) > tol*abs(a(2))) c = t/a(4)
!
t = 2.d0*p*p - q
if (abs(t) <= tol*abs(q)) t = 0.d0
d = r + p*t
if (abs(d) <= tol*abs(r)) go to 110
!
!           SET  SQ = (a(4)/S)**2 * (c**3/27 + d**2/4)
!
s = max(abs(a(1)),abs(a(2)),abs(a(3)))
p1 = a(3)/(3.d0*s)
q1 = a(2)/s
r1 = a(1)/s
!
t1 = q - 2.25d0*p*p
if (abs(t1) <= tol*abs(q)) t1 = 0.d0
w = 0.25d0*r1*r1
w1 = 0.5d0*p1*r1*t
w2 = q1*q1*t1/27.d0
if (w1 < 0.d0) go to 10
w = w + w1
sq = w + w2
go to 12
10 if (w2 < 0.d0) go to 11
w = w + w2
sq = w + w1
go to 12
11 sq = w + (w1 + w2)
12 if (abs(sq) <= tol*w) sq = 0.d0
rq = abs(s/a(4))*sqrt(abs(sq))
if (sq >= 0.d0) go to 40
!
!                   All roots are real
!
arg = atan2(rq, -0.5d0*d)
cf = cos(arg/3.d0)
sf = sin(arg/3.d0)
rt = sqrt(-c/3.d0)
y1 = 2.d0*rt*cf
y2 = -rt*(cf + rt3*sf)
y3 = -(d/y1)/y2
!
x1 = y1 - p
x2 = y2 - p
x3 = y3 - p
if (abs(x1) <= abs(x2)) go to 20
t = x1
x1 = x2
x2 = t
20 if (abs(x2) <= abs(x3)) go to 30
t = x2
x2 = x3
x3 = t
if (abs(x1) <= abs(x2)) go to 30
t = x1
x1 = x2
x2 = t
!
30 w = x3
if (abs(x2) < 0.1d0*abs(x3)) go to 70
if (abs(x1) < 0.1d0*abs(x2)) x1 = - (r/x3)/x2
zr(1) = x1
zr(2) = x2
zr(3) = x3
zi(1) = 0.d0
zi(2) = 0.d0
zi(3) = 0.d0
return
!
!                  Real and complex roots
!
40 ra = dcbrt(-0.5d0*d - sign(rq,d))
rb = -c/(3.d0*ra)
t = ra + rb
w = -p
x = -p
if (abs(t) <= tol*abs(ra)) go to 41
w = t - p
x = -0.5d0*t - p
if (abs(x) <= tol*abs(p)) x = 0.d0
41 t = abs(ra - rb)
y = 0.5d0*rt3*t
!
if (t <= tol*abs(ra)) go to 60
if (abs(x) < abs(y)) go to 50
s = abs(x)
t = y/x
go to 51
50 s = abs(y)
t = x/y
51 if (s < 0.1d0*abs(w)) go to 70
w1 = w/s
sum = 1.d0 + t*t
if (w1*w1 < 1.d-2*sum) w = - ((r/sum)/s)/s
zr(1) = w
zr(2) = x
zr(3) = x
zi(1) = 0.d0
zi(2) = y
zi(3) = -y
return
!
!               At least two roots are equal
!
60 zi(1) = 0.d0
zi(2) = 0.d0
zi(3) = 0.d0
if (abs(x) < abs(w)) go to 61
if (abs(w) < 0.1d0*abs(x)) w = - (r/x)/x
zr(1) = w
zr(2) = x
zr(3) = x
return
61 if (abs(x) < 0.1d0*abs(w)) go to 70
zr(1) = x
zr(2) = x
zr(3) = w
return
!
!     Here W is much larger in magnitude than the other roots.
!     As a result, the other roots may be exceedingly inaccurate
!     because of roundoff error. To deal with this, a quadratic
!     is formed whose roots are the same as the smaller roots of
!     the cubic. This quadratic is then solved.
!
!     This code was written by william L. Davis (NSWC).
!
70 aq(1) = a(1)
aq(2) = a(2) + a(1)/w
aq(3) = -a(4)*w
call dqdcrt(aq, zr, zi)
zr(3) = w
zi(3) = 0.d0
!
if (zi(1) == 0.d0) return
zr(3) = zr(2)
zi(3) = zi(2)
zr(2) = zr(1)
zi(2) = zi(1)
zr(1) = w
zi(1) = 0.d0
return
!-----------------------------------------------------------------------
!
!                  Case when a(1) = 0
!
100 zr(1) = 0.d0
zi(1) = 0.d0
call dqdcrt(a(2), zr(2), zi(2))
return
!
!                   Case when d = 0
!
110 zr(1) = -p
zi(1) = 0.d0
w = sqrt(abs(c))
if (c < 0.d0) go to 120
zr(2) = -p
zr(3) = zr(2)
zi(2) = w
zi(3) = -w
return
!
120 if (p /= 0.d0) go to 130
zr(2) = w
zr(3) = -w
zi(2) = 0.d0
zi(3) = 0.d0
return
!
130 x = -(p + sign(w,p))
zr(3) = x
zi(2) = 0.d0
zi(3) = 0.d0
t = 3.d0*a(1)/(a(3)*x)
if (abs(p) > abs(t)) go to 131
zr(2) = t
return
131 zr(2) = zr(1)
zr(1) = t
end subroutine dcbcrt

pure subroutine qtcrt(a, z)
implicit none
real, intent(in) :: a(5)
complex, intent(inout) :: z(4)
real :: b, b2, c, d, e, h, p, q, r, t, u, v, v1, v2, x, x1, x2, x3, y, temp(4), nswc_ai_r4
complex :: w
interface
   pure subroutine aord(a,n)
      implicit none
      integer, intent(in) :: n
      real, intent(inout) :: a(n)
   end subroutine aord
   pure subroutine cbcrt(a,z)
      implicit none
      real, intent(in) :: a(4)
      complex, intent(inout) :: z(3)
   end subroutine cbcrt
end interface
!-----------------------------------------------------------------------
!
!         qtcrt computes the roots of the real polynomial
!               a(1) + a(2)*z + ... + a(5)*z**4
!         and stores the results in z. it is assumed that a(5)
!         is nonzero.
!
!-----------------------------------------------------------------------
!     Written by Alfred h. Morris
!        naval surface weapons center
!        Dahlgren, Virginia
!-----------------------------------------------------------------------
!
if (a(1) == 0.0) go to 100
b = a(4)/(4.0*a(5))
c = a(3)/a(5)
d = a(2)/a(5)
e = a(1)/a(5)
b2 = b*b
!
p = 0.5*(c - 6.0*b2)
q = d - 2.0*b*(c - 4.0*b2)
r = b2*(c - 3.0*b2) - b*d + e
!
!          Solve the resolvent cubic equation. The cubic has
!          at least one nonnegative real root. If W1, W2, W3
!          are the roots of the cubic then the roots of the
!          originial equation are
!
!             z = -b + csqrt(w1) + csqrt(w2) + csqrt(w3)
!
!          Where the signs of the square roots are chosen so
!          THAT CSQRT(W1) * CSQRT(W2) * CSQRT(W3) = -q/8.
!
temp(1) = -q*q/64.0
temp(2) = 0.25*(p*p - r)
temp(3) = p
temp(4) = 1.0
call cbcrt(temp,z)
if (aimag(z(2)) /= 0.0) go to 60
!
!               The resolvent cubic has only real roots
!                reorder the roots in increasing order
!
x1 = real(z(1))
x2 = real(z(2))
x3 = real(z(3))
if (x1 <= x2) go to 10
t = x1
x1 = x2
x2 = t
10 if (x2 <= x3) go to 20
t = x2
x2 = x3
x3 = t
if (x1 <= x2) go to 20
t = x1
x1 = x2
x2 = t
!
20 u = 0.0
if (x3 > 0.0) u = sqrt(x3)
if (x2 <= 0.0) go to 41
if (x1 >= 0.0) go to 30
if (abs(x1) > x2) go to 40
x1 = 0.0
!
30 x1 = sqrt(x1)
x2 = sqrt(x2)
if (q > 0.0) x1 = -x1
temp(1) = (( x1 + x2) + u) - b
temp(2) = ((-x1 - x2) + u) - b
temp(3) = (( x1 - x2) - u) - b
temp(4) = ((-x1 + x2) - u) - b
call aord(temp,4)
if (abs(temp(1)) >= 0.1*abs(temp(4))) go to 31
t = temp(2)*temp(3)*temp(4)
if (t /= 0.0) temp(1) = e/t
31 z(1) = cmplx(temp(1), 0.0)
z(2) = cmplx(temp(2), 0.0)
z(3) = cmplx(temp(3), 0.0)
z(4) = cmplx(temp(4), 0.0)
return
!
40 v1 = sqrt(abs(x1))
v2 = 0.0
go to 50
41 v1 = sqrt(abs(x1))
v2 = sqrt(abs(x2))
if (q < 0.0) u = -u
!
50 x = -u - b
y = v1 - v2
z(1) = cmplx(x, y)
z(2) = cmplx(x,-y)
x = u - b
y = v1 + v2
z(3) = cmplx(x, y)
z(4) = cmplx(x,-y)
return
!
!                The resolvent cubic has complex roots
!
60 t = real(z(1))
x = 0.0
nswc_ai_r4 = t
if ( nswc_ai_r4 < 0 ) go to 61
if ( nswc_ai_r4 == 0 ) go to 70
go to 62
61 h = abs(real(z(2))) + abs(aimag(z(2)))
if (abs(t) <= h) go to 70
go to 80
62 x = sqrt(t)
if (q > 0.0) x = -x
!
70 w = sqrt(z(2))
u = 2.0*real(w)
v = 2.0*abs(aimag(w))
t = x - b
x1 = t + u
x2 = t - u
if (abs(x1) <= abs(x2)) go to 71
t = x1
x1 = x2
x2 = t
71 u = -x - b
h = u*u + v*v
if (x1*x1 < 0.01*min(x2*x2,h)) x1 = e/(x2*h)
z(1) = cmplx(x1, 0.0)
z(2) = cmplx(x2, 0.0)
z(3) = cmplx(u, v)
z(4) = cmplx(u,-v)
return
!
80 v = sqrt(abs(t))
z(1) = cmplx(-b, v)
z(2) = cmplx(-b,-v)
z(3) = z(1)
z(4) = z(2)
return
!
!                         Case when a(1) = 0
!
100 z(1) = (0.0, 0.0)
call cbcrt(a(2), z(2))
end subroutine qtcrt

pure subroutine dqtcrt(a, zr, zi)
implicit none
!-----------------------------------------------------------------------
!
!         dqtcrt computes the roots of the real polynomial
!               a(1) + a(2)*Z + ... + a(5)*Z**4
!         and stores the results in zr and zi. It is assumed
!         that a(5) is nonzero.
!
!-----------------------------------------------------------------------
!     Written by Alfred h. Morris
!        naval surface weapons center
!        Dahlgren, Virginia
!-----------------------------------------------------------------------
double precision, intent(in) :: a(5)
double precision, intent(inout) :: zr(4), zi(4)
double precision :: b, b2, c, d, e, h, p, q, r, t, temp(4), u, v, v1, v2, w(2), x, x1, x2, x3, nswc_ai_r8
interface
   pure subroutine daord(a,n)
      implicit none
      integer, intent(in) :: n
      double precision, intent(inout) :: a(n)
   end subroutine daord
   pure subroutine dcbcrt(a,zr,zi)
      implicit none
      double precision, intent(in) :: a(4)
      double precision, intent(inout) :: zr(3)
      double precision, intent(inout) :: zi(3)
   end subroutine dcbcrt
   pure subroutine dcsqrt(z,w)
      implicit none
      double precision, intent(in) :: z(2)
      double precision, intent(inout) :: w(2)
   end subroutine dcsqrt
end interface
!
if (a(1) == 0.d0) go to 100
b = a(4)/(4.d0*a(5))
c = a(3)/a(5)
d = a(2)/a(5)
e = a(1)/a(5)
b2 = b*b
!
p = 0.5d0*(c - 6.d0*b2)
q = d - 2.d0*b*(c - 4.d0*b2)
r = b2*(c - 3.d0*b2) - b*d + e
!
!          Solve the resolvent cubic equation. The cubic has
!          at least one nonnegative real root. If W1, W2, W3
!          are the roots of the cubic then the roots of the
!          originial equation are
!
!             z = -b + csqrt(w1) + csqrt(w2) + csqrt(w3)
!
!          Where the signs of the square roots are chosen so
!          THAT CSQRT(W1) * CSQRT(W2) * CSQRT(W3) = -q/8.
!
temp(1) = -q*q/64.d0
temp(2) = 0.25d0*(p*p - r)
temp(3) = p
temp(4) = 1.d0
call dcbcrt(temp, zr, zi)
if (zi(2) /= 0.d0) go to 60
!
!               The resolvent cubic has only real roots
!                reorder the roots in increasing order
!
x1 = zr(1)
x2 = zr(2)
x3 = zr(3)
if (x1 <= x2) go to 10
t = x1
x1 = x2
x2 = t
10 if (x2 <= x3) go to 20
t = x2
x2 = x3
x3 = t
if (x1 <= x2) go to 20
t = x1
x1 = x2
x2 = t
!
20 u = 0.d0
if (x3 > 0.d0) u = sqrt(x3)
if (x2 <= 0.d0) go to 41
if (x1 >= 0.d0) go to 30
if (abs(x1) > x2) go to 40
x1 = 0.d0
!
30 x1 = sqrt(x1)
x2 = sqrt(x2)
if (q > 0.d0) x1 = -x1
zr(1) = (( x1 + x2) + u) - b
zr(2) = ((-x1 - x2) + u) - b
zr(3) = (( x1 - x2) - u) - b
zr(4) = ((-x1 + x2) - u) - b
call daord(zr, 4)
if (abs(zr(1)) >= 0.1d0*abs(zr(4))) go to 31
t = zr(2)*zr(3)*zr(4)
if (t /= 0.d0) zr(1) = e/t
31 zi(1) = 0.d0
zi(2) = 0.d0
zi(3) = 0.d0
zi(4) = 0.d0
return
!
40 v1 = sqrt(abs(x1))
v2 = 0.d0
go to 50
41 v1 = sqrt(abs(x1))
v2 = sqrt(abs(x2))
if (q < 0.d0) u = -u
!
50 zr(1) = -u - b
zi(1) = v1 - v2
zr(2) = zr(1)
zi(2) = -zi(1)
zr(3) = u - b
zi(3) = v1 + v2
zr(4) = zr(3)
zi(4) = -zi(3)
return
!
!                The resolvent cubic has complex roots
!
60 t = zr(1)
x = 0.d0
nswc_ai_r8 = t
if ( nswc_ai_r8 < 0 ) go to 61
if ( nswc_ai_r8 == 0 ) go to 70
go to 62
61 h = abs(zr(2)) + abs(zi(2))
if (abs(t) <= h) go to 70
go to 80
62 x = sqrt(t)
if (q > 0.d0) x = -x
!
70 w(1) = zr(2)
w(2) = zi(2)
call dcsqrt(w, w)
u = 2.d0*w(1)
v = 2.d0*abs(w(2))
t = x - b
x1 = t + u
x2 = t - u
if (abs(x1) <= abs(x2)) go to 71
t = x1
x1 = x2
x2 = t
71 u = -x - b
h = u*u + v*v
if (x1*x1 < 1.d-2*min(x2*x2,h)) x1 = e/(x2*h)
zr(1) = x1
zr(2) = x2
zi(1) = 0.d0
zi(2) = 0.d0
zr(3) = u
zr(4) = u
zi(3) = v
zi(4) = -v
return
!
80 v = sqrt(abs(t))
zr(1) = -b
zr(2) = -b
zr(3) = -b
zr(4) = -b
zi(1) = v
zi(2) = -v
zi(3) = v
zi(4) = -v
return
!
!                         Case when a(1) = 0
!
100 zr(1) = 0.d0
zi(1) = 0.d0
call dcbcrt(a(2), zr(2), zi(2))
end subroutine dqtcrt

subroutine drpoly(op, ideg, zeror, zeroi, num, wk, dwk)
implicit none
integer :: ideg
integer, intent(inout) :: num
double precision :: op(*)
double precision, intent(inout) :: zeror(ideg), zeroi(ideg), &
   & dwk(*)
real, intent(inout) :: wk(*)
integer :: idp1, p, qp, k, qk, svk, tmp
!
!     This subroutine finds the zeros of a real polynomial.
!
!     op          - Double precision array of length ideg + 1.
!                   On input this array contains the coefficients
!                   in order of decreasing powers.
!
!     ideg        - Integer degree of the polynomial.
!
!     zeror,zeroi - Double precision arrays if length ideg.
!                   On output these arrays contain the real and
!                   imaginary parts of the zeros.
!
!     num         - Variable that reports the status of the results.
!                   If num = -1 Then the leading coefficient of the
!                   polynomial is 0 or ideg .LT. 1. Otherwise, num
!                   is the number of zeros that were obtained. If
!                   num .GE. 1 then the real and imaginary parts of
!                   the zeros are stored in zeror(J) and zeroi(J)
!                   FOR J = 1,...,num.
!
!     wk          - Real array of length ideg + 1. The array is
!                   a work space for the routine.
!
!     DWK         - Double precision array of length 6*(ideg + 1).
!                   The array is a work space for the routine.
!
!     The subroutine uses single precision calculations for scaling,
!     bounds, and error calculations. All other calculations are done
!     in double precision.
!
!
!
if (ideg < 1) go to 10
!
!     Partition the workspace DWK and obtain the zeros
!
idp1 = ideg + 1
!
p = 1
qp = p + idp1
k = qp + idp1
qk = k + idp1
svk = qk + idp1
tmp = svk + idp1
!
call drply1(op,ideg,idp1,zeror,zeroi,dwk(p),dwk(qp),dwk(k), &
   & dwk(qk),dwk(svk),dwk(tmp),wk,num)
return
!
!     Error return
!
10 num = -1
end subroutine drpoly

subroutine drply1(op,ideg,idp1,zeror,zeroi,p,qp,k,qk,svk, &
   & temp,pt,num)
implicit none
integer :: ideg, idp1, num
double precision :: op(idp1), zeror(ideg), zeroi(ideg), p(idp1), &
   & qp(idp1), k(idp1), qk(idp1), svk(idp1), temp(idp1)
real :: pt(idp1)
integer :: i, j, jj, l, n, nm1, nn, nz, cnt
double precision :: aa, bb, cc, factor, t
real :: lo, max, min, xx, yy, cosr, sinr, x, xxx, sc, bnd, xm, ff, &
   & df, dx, base, smalno, infin
logical :: zerok
real :: eta, are, mre
double precision :: sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi
interface
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
   pure elemental function ipmpar(i)
      implicit none
      integer, intent(in) :: i
      integer :: ipmpar
   end function ipmpar
   pure elemental subroutine quadpl(a,b1,c,sr,si,lr,li)
      implicit none
      double precision, intent(in) :: a
      double precision, intent(in) :: b1
      double precision, intent(in) :: c
      double precision, intent(inout) :: sr
      double precision, intent(inout) :: si
      double precision, intent(inout) :: lr
      double precision, intent(inout) :: li
   end subroutine quadpl
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-------------------------
!
!
!-------------------------
common /global/  sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi, eta, are, mre
!-------------------------
!     The following statements set the machine constants used
!     in the code. The meaning of the constants are ...
!
!     eta     THE SMALLEST POSITIVE NUMBER SUCH THAT
!             1.D0 + eta is greater than 1.D0
!     SMALNO  the smallest positive floating point number.
!             If the exponent range differs in single and
!             double precision then SMALNO and infin
!             should indicate the smaller range.
!     INFIN   THE LARGEST POSITIVE FLOATING POINT NUMBER.
!     BASE    THE BASE OF THE FLOATING POINT ARITHMETICS
!             being used.
!
eta = dpmpar(1)
smalno = spmpar(2)
infin = spmpar(3)
base = ipmpar(4)
!-------------------------
!
!     Are and mre refer to the unit error in + and *
!     respectively. They are assumed to be the same as eta.
!
are = eta
mre = eta
lo = smalno/eta
!
!     Initialization of constants for shift rotation
!
xx = .70710678
yy = -xx
cosr = -.069756474
sinr = .99756405
n = ideg
nn = idp1
num = 0
!
!     Algorithm fails if the leading coefficient is zero.
!
if (op(1) /= 0.d0) go to 10
num = -1
return
!
!     Remove the zeros at the origin if any
!
10 if (op(nn) /= 0.0d0) go to 20
num = num + 1
zeror(num) = 0.d0
zeroi(num) = 0.d0
nn = nn - 1
n = n - 1
go to 10
!
!     Make a copy of the coefficients
!
20 do i = 1,nn
   p(i) = op(i)
end do
!
!     Start the algorithm for obtaining a zero
!
40 if (n > 2) go to 60
if (n < 1) return
!
!     Calculate the final zero or pair of zeros
!
num = ideg
if (n == 2) go to 50
zeror(ideg) = -p(2)/p(1)
zeroi(ideg) = 0.0d0
return
50 call quadpl(p(1), p(2), p(3), zeror(ideg - 1), zeroi(ideg - 1), &
   & zeror(ideg), zeroi(ideg))
return
!
!     Find largest and smallest moduli of coefficients.
!
60 max = 0.0
min = infin
do i = 1,nn
   x = abs(sngl(p(i)))
   if (x > max) max = x
   if (x /= 0.0 .and. x < min) min = x
end do
!
!     Scale if there are large or very small coefficients.
!     Computes a scale factor to multiply the
!     coefficients of the polynomial. The scaling is done
!     to avoid overflow and to avoid undetected underflow
!     interfering with the convergence criterion.
!     The factor is a power of the base.
!
sc = lo/min
if (sc > 1.0) go to 80
if (max < 10.0) go to 110
if (sc == 0.0) sc = smalno
go to 90
80 if (infin/sc < max) go to 110
90 l = log(sc)/log(base) + 0.5
factor = dble(base)**l
if (factor == 1.d0) go to 110
do i = 1,nn
   p(i) = factor*p(i)
end do
!
!     Compute lower bound on moduli of zeros.
!
110 do i = 1,nn
   pt(i) = abs(sngl(p(i)))
end do
pt(nn) = -pt(nn)
!
!     Compute upper estimate of bound
!
x = exp((log(-pt(nn)) - log(pt(1)))/float(n))
if (pt(n) == 0.0) go to 130
!
!     If the Newton step at the origin is better then use it.
!
xm = -pt(nn)/pt(n)
if (xm < x) x = xm
!
!     Chop the interval (0,x) until ff .LE. 0.
!
130 xm = x*.1
ff = pt(1)
do i = 2,nn
   ff = ff*xm + pt(i)
end do
if (ff <= 0.0) go to 150
x = xm
go to 130
150 dx = x
!
!     Do Newton iteration until x converges to two decimal places.
!
160 if (abs(dx/x) <= 0.005) go to 180
ff = pt(1)
df = ff
do i = 2,n
   ff = ff*x + pt(i)
   df = df*x + ff
end do
ff = ff*x + pt(nn)
dx = ff/df
x = x - dx
go to 160
180 bnd = x
!
!     Compute the derivative as the intial K polynomial
!     and do 5 steps with no shift.
!
nm1 = n - 1
do i = 2,n
   k(i) = float(nn - i)*p(i)/float(n)
end do
k(1) = p(1)
aa = p(nn)
bb = p(n)
zerok = k(n) == 0.d0
do jj = 1,5
   cc = k(n)
   if (zerok) go to 210
!
!     Use scaled form of recurrence if value of K at 0 is nonzero.
!
   t = -aa/cc
   do i = 1,nm1
      j = nn - i
      k(j) = t*k(j - 1) + p(j)
   end do
   k(1) = p(1)
   zerok = abs(k(n)) <= abs(bb)*eta*10.
   go to 230
!
!     Use unscaled form of recurrence
!
210 do i = 1,nm1
      j = nn - i
      k(j) = k(j - 1)
   end do
   k(1) = 0.d0
   zerok = k(n) == 0.d0
230 continue
end do
!
!     Save K for restarts with new shifts
!
do i = 1,n
   temp(i) = k(i)
end do
!
!     Loop to select the quadratic  corresponding to each
!     new shift
!
do cnt = 1,20
!
!     Quadratic corresponds to a double shift to A
!     non-real point and its complex conjugate. The point
!     has modulus bnd and amplitude rotated by 94 degrees
!     from the previous shift.
!
   xxx = cosr*xx - sinr*yy
   yy = sinr*xx + cosr*yy
   xx = xxx
   sr = bnd*xx
   si = bnd*yy
   u = -2.0d0*sr
   v = bnd
!
!     Second stage calculation, fixed quadratic. The second stage
!     jumps directly to one of the third stage iterations.
!
   call fxshfr(20*cnt, nz, nn, p, qp, k, qk, svk)
   if (nz /= 0) go to 300
!
!     If the iteration is unsuccessful another quadratic
!     is chosen after restoring K.
!
   do i = 1,n
      k(i) = temp(i)
   end do
end do
!
!     Convergence was not achieved after 20 shifts.
!
return
!
!     Store the zeros obtained and deflate the polynomial.
!
300 num = num + 1
zeror(num) = szr
zeroi(num) = szi
nn = nn - nz
n = nn - 1
do i = 1,nn
   p(i) = qp(i)
end do
if (nz == 1) go to 40
num = num + 1
zeror(num) = lzr
zeroi(num) = lzi
go to 40
end subroutine drply1

subroutine fxshfr(l2, nz, nn, p, qp, k, qk, svk)
implicit none
integer :: nn
double precision :: p(nn), qp(nn), k(nn), qk(nn), svk(nn)
integer :: l2, nz
integer :: n, type, i, j, iflag
double precision :: svu, svv, ui, vi, s
real :: betas, betav, oss, ovv, ss, vv, ts, tv, ots, otv, tvv, tss
logical :: vpass, spass, vtry, stry
real :: eta, are, mre
double precision :: sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi
!
!     Computes up to  l2  fixed shift k-polynomials,
!     testing for convergence in the linear or quadratic
!     case. Initiates one of the variable SHIFT
!     iterations and returns with the number of zeros
!     found.
!
!     l2 - Limit of fixed shift steps
!     nz - Number of zeros found
!
!
common /global/  sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi, eta, are, mre
!
n = nn - 1
nz = 0
betav = .25
betas = .25
oss = sr
ovv = v
!
!     Evaluate polynomial by synthetic division
!
call quadsd(nn, u, v, p, qp, a, b)
call calcsc(type, n, k, qk)
do j = 1,l2
!
!     Calculate next k polynomial and estimate v
!
   call nextk(type, n, qp, k, qk)
   call calcsc(type, n, k, qk)
   call newest(type, ui, vi, nn, p, k)
   vv = vi
!
!     Estimate s
!
   ss = 0.0
   if (k(n) /= 0.d0) ss = -p(nn)/k(n)
   tv = 1.0
   ts = 1.0
   if (j == 1 .or. type == 3) go to 70
!
!     Compute relative measures of convergence of s and v
!     sequences
!
   if (vv /= 0.0) tv = abs((vv - ovv)/vv)
   if (ss /= 0.0) ts = abs((ss - oss)/ss)
!
!     If decreasing, multiply two most recent
!     convergence measures
!
   tvv = 1.0
   if (tv < otv) tvv = tv*otv
   tss = 1.0
   if (ts < ots) tss = ts*ots
!
!     Compare with convergence criteria
!
   vpass = tvv < betav
   spass = tss < betas
   if (.not.(spass .or. vpass)) go to 70
!
!     At least one sequence has passed the convergence
!     test. Store variables before iterating
!
   svu = u
   svv = v
   do i = 1,n
      svk(i) = k(i)
   end do
   s = ss
!
!     Choose iteration according to the fastest
!     converging sequence
!
   vtry = .false.
   stry = .false.
   if (spass .and. ((.not.vpass) .or. &
      & tss < tvv)) go to 40
20 call quadit(ui, vi, nz, nn, p, qp, k, qk)
   if (nz > 0) return
!
!     Quadratic iteration has failed. Flag that it has
!     been tried and decrease the convergence criterion.
!
   vtry = .true.
   betav = betav*0.25
!
!     Try linear iteration if it has not been tried and
!     the s sequence is converging
!
   if (stry .or. (.not.spass)) go to 50
   do i = 1,n
      k(i) = svk(i)
   end do
40 call realit(s, nz, iflag, nn, p, qp, k, qk)
   if (nz > 0) return
!
!     Linear iteration has failed. Flag that it has been
!     tried and decrease the convergence criterion
!
   stry = .true.
   betas = betas*0.25
   if (iflag == 0) go to 50
!
!     If linear iteration signals an almost double real
!     zero attempt quadratic interation
!
   ui = -(s + s)
   vi = s*s
   go to 20
!
!     Restore variables
!
50 u = svu
   v = svv
   do i = 1,n
      k(i) = svk(i)
   end do
!
!     Try quadratic iteration if it has not been tried
!     and the v sequence is converging
!
   if (vpass .and. (.not.vtry)) go to 20
!
!     Recompute qp and scalar values to continue the
!     second stage
!
   call quadsd(nn, u, v, p, qp, a, b)
   call calcsc(type, n, k, qk)
70 ovv = vv
   oss = ss
   otv = tv
   ots = ts
end do
end subroutine fxshfr

subroutine quadit(uu, vv, nz, nn, p, qp, k, qk)
implicit none
integer :: nn
double precision :: uu, vv, p(nn), qp(nn), k(nn), qk(nn)
integer :: nz
integer :: n, type, i, j
double precision :: ui, vi
real :: mp, omp, ee, relstp, t, zm
logical :: tried
real :: eta, are, mre
double precision :: sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi
interface
   pure elemental subroutine quadpl(a,b1,c,sr,si,lr,li)
      implicit none
      double precision, intent(in) :: a
      double precision, intent(in) :: b1
      double precision, intent(in) :: c
      double precision, intent(inout) :: sr
      double precision, intent(inout) :: si
      double precision, intent(inout) :: lr
      double precision, intent(inout) :: li
   end subroutine quadpl
end interface
!
!     Variable-shift k-polynomial iteration for A
!     quadratic factor converges only if the zeros are
!     equimodular or nearly so.
!
!     uu,vv - Coefficients of starting quadratic
!     nz - Number of zero found
!
!
common /global/  sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi, eta, are, mre
!
n = nn - 1
nz = 0
tried = .false.
u = uu
v = vv
j = 0
! Main loop
10 call quadpl(1.d0, u, v, szr, szi, lzr, lzi)
!
!     RETURN IF ROOTS OF THE QUADRATIC ARE REAL AND NOT CLOSE
!     to multiple or nearly equal and of opposite sign
!
if (abs(abs(szr) - abs(lzr)) > 1.d-2*abs(lzr)) &
   & return
!
!     Evaluate polynomial by quadratic synthetic division
!
call quadsd(nn, u, v, p, qp, a, b)
mp = abs(a - szr*b) + abs(szi*b)
!
!     Compute a rigorous bound on the rounding error in
!     EVALUTING p
!
zm = sqrt(abs(sngl(v)))
ee = 2.0*abs(sngl(qp(1)))
t = -szr*b
do i = 2,n
   ee = ee*zm + abs(sngl(qp(i)))
20 continue
end do
ee = ee*zm + abs(sngl(a) + t)
ee = (5.0*mre + 4.0*are)*ee - (5.0*mre + 2.0*are)* &
   & (abs(sngl(a) + t) + abs(sngl(b))*zm) + &
   & 2.0*are*abs(t)
!
!     Iteration has converged sufficiently if the
!     polynomial value is less than 20 times this bound
!
if (mp > 20.0*ee) go to 30
nz = 2
return
30 j = j + 1
!
!     STOP ITERATION AFTER 20 STEPS
!
if (j > 20) return
if (j < 2) go to 50
if (relstp > 0.01 .or. mp < omp .or. tried) go to 50
!
!     A cluster appears to be stalling the convergence.
!     Five fixed shift steps are taken with A u,v close
!     to the cluster
!
if (relstp < eta) relstp = eta
relstp = sqrt(relstp)
u = u - u*relstp
v = v + v*relstp
call quadsd(nn, u, v, p, qp, a, b)
do i = 1,5
   call calcsc(type, n, k, qk)
   call nextk(type, n, qp, k, qk)
end do
tried = .true.
j = 0
50 omp = mp
!
!     Calculate next k polynomial and new u and v
!
call calcsc(type, n, k, qk)
call nextk(type, n, qp, k, qk)
call calcsc(type, n, k, qk)
call newest(type, ui, vi, nn, p, k)
!
!     If vi is zero the iteration is not converging
!
if (vi == 0.d0) return
relstp = abs((vi - v)/vi)
u = ui
v = vi
go to 10
end subroutine quadit

subroutine realit(sss, nz, iflag, nn, p, qp, k, qk)
implicit none
integer :: iflag, nn, nz
double precision :: sss, p(nn), qp(nn), k(nn), qk(nn)
integer :: i, j, n
double precision :: pv, kv, t, s
real :: ms, mp, omp, ee
real :: eta, are, mre
double precision :: sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi
!
!     Variable-shift H polynomial iteration for a real zero.
!
!     sss   - Starting iterate
!     nz    - Number of zero found
!     iflag - Flag to indicate a pair of zeros near the real
!             axis.
!
!
common /global/  sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi, eta, are, mre
!
n = nn - 1
nz = 0
s = sss
iflag = 0
j = 0
!
!     Evaluate p at s
!
10 pv = p(1)
qp(1) = pv
do i = 2,nn
   pv = pv*s + p(i)
   qp(i) = pv
20 continue
end do
mp = abs(pv)
!
!     Compute a rigorous bound on the error in evaluating p
!
ms = abs(s)
ee = (mre/(are + mre))*abs(sngl(qp(1)))
do i = 2,nn
   ee = ee*ms + abs(sngl(qp(i)))
end do
!
!     Iteration has converged sufficiently if the
!     polynomial value is less than 20 times this bound
!
if (mp > 20.0*((are + mre)*ee - mre*mp)) go to 40
nz = 1
szr = s
szi = 0.d0
return
40 j = j + 1
!
!     STOP ITERATION AFTER 10 STEPS
!
if (j > 10) return
if (j < 2) go to 50
if (abs(t) > 1.d-3*abs(s - t) .or. mp <= omp) &
   & go to 50
!
!     A cluster of zeros near the real axis has been
!     encountered return with iflag set to initiate A
!     quadratic iteration
!
iflag = 1
sss = s
return
!
!     RETURN IF THE POLYNOMIAL VALUE HAS INCREASED
!     significantly
!
50 omp = mp
!
!     Compute t, the next polynomial, and the new iterate
!
kv = k(1)
qk(1) = kv
do i = 2,n
   kv = kv*s + k(i)
   qk(i) = kv
end do
if (abs(kv) <= abs(k(n))*10.*eta) go to 80
!
!     Use the scaled form of the recurrence if the value
!     of k at s is nonzero
!
t = -pv/kv
k(1) = qp(1)
do i = 2,n
   k(i) = t*qk(i - 1) + qp(i)
end do
go to 100
!
!     Use unscaled form
!
80 k(1) = 0.0d0
do i = 2,n
   k(i) = qk(i - 1)
end do
100 kv = k(1)
do i = 2,n
   kv = kv*s + k(i)
end do
t = 0.d0
if (abs(kv) > abs(k(n))*10.*eta) t = -pv/kv
s = s + t
go to 10
end subroutine realit

subroutine calcsc(type, n, k, qk)
implicit none
integer :: n
integer :: type
double precision :: k(n), qk(n)
double precision :: tol
real :: eta, are, mre
double precision :: sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi
!
!     This routine calculates scalar quantities used to
!     compute the next k polynomial and new estimates of
!     the quadratic coefficients.
!
!     type - Integer variable SET here indicating how the
!            calculations are normalized to avoid overflow
!
!
common /global/  sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi, eta, are, mre
!
!     Synthetic division of k by the quadratic 1,u,v
!
call quadsd(n, u, v, k, qk, c, d)
tol = 100.0*eta
if (abs(c) > tol*abs(k(n))) go to 10
if (abs(d) > tol*abs(k(n - 1))) go to 10
type = 3
!
!     type=3 Indicates the quadratic is almost a factor of k
!
return
10 if (abs(d) < abs(c)) go to 20
type = 2
!
!     type=2 Indicates that all formulas are divided by d
!
e = a/d
f = c/d
g = u*b
h = v*b
a3 = (a + g)*e + h*(b/d)
a1 = b*f - a
a7 = (f + u)*a + h
return
20 type = 1
!
!     type=1 Indicates that all formulas are divided by c
!
e = a/c
f = d/c
g = u*e
h = v*b
a3 = a*e + (h/c + g)*b
a1 = b - a*(d/c)
a7 = a + g*d + h*f
end subroutine calcsc

subroutine nextk(type, n, qp, k, qk)
implicit none
integer :: n
integer :: type
double precision :: qp(n), k(n), qk(n)
integer :: i
double precision :: temp
real :: eta, are, mre
double precision :: sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi
!
!     Computes the next k polynomials using the scalars
!     computed in calcsc.
!
common /global/  sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi, eta, are, mre
!
if (type == 3) go to 40
temp = a
if (type == 1) temp = b
if (abs(a1) > abs(temp)*eta*10.) go to 20
!
!     If a1 is nearly zero then use a special form of the
!     recurrence
!
k(1) = 0.d0
k(2) = -a7*qp(1)
do i = 3,n
   k(i) = a3*qk(i - 2) - a7*qp(i - 1)
10 continue
end do
return
!
!     Use scaled form of the recurrence
!
20 a7 = a7/a1
a3 = a3/a1
k(1) = qp(1)
k(2) = qp(2) - a7*qp(1)
do i = 3,n
   k(i) = a3*qk(i - 2) - a7*qp(i - 1) + qp(i)
end do
return
!
!     Use unscaled form of the recurrence if type is 3
!
40 k(1) = 0.d0
k(2) = 0.d0
do i = 3,n
   k(i) = qk(i - 2)
end do
end subroutine nextk

subroutine newest(type, uu, vv, nn, p, k)
implicit none
integer :: nn
integer :: type
double precision :: uu, vv, p(nn), k(nn)
integer :: n
double precision :: a4, a5, b1, b2, c1, c2, c3, c4, temp
real :: eta, are, mre
double precision :: sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi
!
!     Compute new estimates of the quadratic coefficients
!     using the scalars computed in calcsc.
!
!
common /global/  sr, si, u, v, a, b, c, d, a1, a2, a3, a6, a7, &
   & e, f, g, h, szr, szi, lzr, lzi, eta, are, mre
!
!     Use formulas appropriate to setting of type.
!
n = nn - 1
if (type == 3) go to 30
if (type == 2) go to 10
a4 = a + u*b + h*f
a5 = c + (u + v*f)*d
go to 20
10 a4 = (a + g)*f + h
a5 = (f + u)*c + v*d
!
!     Evaluate new quadratic coefficients.
!
20 b1 = -k(n)/p(nn)
b2 = -(k(n - 1) + b1*p(n))/p(nn)
c1 = v*b2*a1
c2 = b1*a7
c3 = b1*b1*a3
c4 = c1 - c2 - c3
temp = a5 + b1*a4 - c4
if (temp == 0.d0) go to 30
uu = u - (u*(c3 + c2) + v*(b1*a1 + b2*a7))/temp
vv = v*(1.d0 + c4/temp)
return
!
!     If type=3 The quadratic is zeroed
!
30 uu = 0.d0
vv = 0.d0
end subroutine newest

pure subroutine quadsd(nn, u, v, p, q, a, b)
implicit none
integer, intent(in) :: nn
double precision, intent(in) :: p(nn)
double precision, intent(inout) :: q(nn)
double precision, intent(in) :: u, v
double precision, intent(out) :: a, b
integer :: i
double precision :: c
!
!     Divides p by the quadratic  1,u,v  placing the
!     quotient in q and the remainder in A,b.
!
!
b = p(1)
q(1) = b
a = p(2) - u*b
q(2) = a
do i = 3,nn
   c = p(i) - u*a - v*b
   q(i) = c
   b = a
   a = c
end do
end subroutine quadsd

pure elemental subroutine quadpl(a, b1, c, sr, si, lr, li)
implicit none
!
!     Calculate the zeros of the quadratic a*Z**2+b1*Z+c.
!     The quadratic formula, modified to avoid overflow,
!     is used to find the larger zero if the zeros are
!     real, and both zeros if the zeros are complex.
!     The smaller real zero is found directly from the
!     product of the zeros c/a.
!
double precision, intent(in) :: a, b1, c
double precision, intent(inout) :: sr, si, lr, li
double precision :: b, d, e
!
if (a /= 0.d0) go to 20
sr = 0.d0
if (b1 /= 0.d0) sr = -c/b1
lr = 0.d0
10 si = 0.d0
li = 0.d0
return
!
20 if (c /= 0.d0) go to 30
sr = 0.d0
lr = -b1/a
go to 10
!
!     Compute discriminant avoiding overflow
!
30 b = b1/2.d0
if (abs(b) < abs(c)) go to 40
e = 1.d0 - (a/b)*(c/b)
d = sqrt(abs(e))*abs(b)
go to 50
40 e = a
if (c < 0.d0) e = -a
e = b*(b/abs(c)) - e
d = sqrt(abs(e))*sqrt(abs(c))
50 if (e < 0.d0) go to 60
!
!     real zeros
!
if (b >= 0.d0) d = -d
lr = (-b + d)/a
sr = 0.d0
if (lr /= 0.d0) sr = (c/lr)/a
go to 10
!
!     Complex conjugate zeros
!
60 sr = -b/a
lr = sr
si = abs(d/a)
li = -si
end subroutine quadpl

subroutine dcpoly(opr,opi,ideg,zeror,zeroi,num,wk)
implicit none
integer, intent(inout) :: num
integer :: ideg
double precision, intent(in) :: opr(*), opi(*)
double precision, intent(inout) :: zeror(ideg), zeroi(ideg), wk(*)
integer :: idp1, pr, pi, qpr, qpi, hr, hi, qhr, qhi, shr, shi
!
!     This subroutine finds the zeros of a complex polynomial.
!
!     opr,opi     - DOUBLE PRECISION ARRAYS OF LENGTH ideg + 1.
!                   On input these arrays contain the real and imaginary
!                   parts of the coefficients in order of decreasing
!                   powers.
!
!     ideg        - Integer degree of the polynomial.
!
!     zeror,zeroi - Double precision arrays of length ideg.
!                   On output these arrays contain the real and
!                   imaginary parts of the zeros.
!
!     num         - Variable that reports the status of the results.
!                   If num = -1 Then the leading coefficient of the
!                   polynomial is 0 or ideg .LT. 1. Otherwise, num
!                   is the number of zeros that were obtained. If
!                   num .GE. 1 then the real and imaginary parts of
!                   the zeros are stored in zeror(J) and zeroi(J)
!                   FOR J = 1,...,num.
!
!     wk          - Double precision array of length 10*(ideg + 1).
!                   The array is a work space for the routine.
!
!     The code has been written to reduce the chance of overflow
!     occurring. If it does occur, there is still a possibility that
!     the zerofinder will work provided the overflowed quantity is
!     replaced by a large number.
!
!
!
if (ideg < 1) go to 10
!
!     Partition the workspace and obtain the zeros
!
idp1 = ideg + 1
!
pr = 1
pi = pr + idp1
qpr = pi + idp1
qpi = qpr + idp1
hr = qpi + idp1
hi = hr + idp1
qhr = hi + idp1
qhi = qhr + idp1
shr = qhi + idp1
shi = shr + idp1
!
call dcply1(opr,opi,ideg,idp1,zeror,zeroi,wk(pr),wk(pi), &
   & wk(qpr),wk(qpi),wk(hr),wk(hi),wk(qhr),wk(qhi), &
   & wk(shr),wk(shi),num)
return
!
!     Error return
!
10 num = -1
end subroutine dcpoly

subroutine dcply1(opr,opi,ideg,idp1,zeror,zeroi,pr,pi,qpr,qpi, &
   & hr,hi,qhr,qhi,shr,shi,num)
implicit none
integer :: ideg
integer, intent(in) :: idp1
integer, intent(out) :: num
double precision, intent(in) :: opr(idp1), opi(idp1)
double precision, intent(inout) :: zeror(ideg), zeroi(ideg), &
   & pr(idp1), pi(idp1), qpr(idp1), qpi(idp1), hr(idp1), hi(idp1), &
   & qhr(idp1), qhi(idp1), shr(idp1), shi(idp1)
integer :: i, nn
double precision :: sr, si, tr, ti, pvr, pvi, are, mre, eta, infin
double precision :: xx, yy, cosr, sinr, smalno, base, xxx, zr, zi, bnd, scalcp
logical :: conv
integer :: cnt1, cnt2
interface
   pure elemental subroutine cdivid(ar,ai,br,bi,cr,ci)
      implicit none
      double precision, intent(in) :: ar
      double precision, intent(in) :: ai
      double precision, intent(in) :: br
      double precision, intent(in) :: bi
      double precision, intent(inout) :: cr
      double precision, intent(inout) :: ci
   end subroutine cdivid
   pure elemental function dcpabs(x,y)
      implicit none
      double precision, intent(in) :: x
      double precision, intent(in) :: y
      double precision :: dcpabs
   end function dcpabs
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
   pure elemental function ipmpar(i)
      implicit none
      integer, intent(in) :: i
      integer :: ipmpar
   end function ipmpar
end interface
!-------------------------
!-------------------------
!     The following statements set the machine constants used
!     in the code. The meaning of the constants are ...
!
!     eta     THE SMALLEST POSITIVE NUMBER SUCH THAT
!             1.D0 + eta is greater than 1.D0
!     smalno  the smallest positive floating point number.
!     INFIN   THE LARGEST POSITIVE FLOATING POINT NUMBER.
!     BASE    THE BASE OF THE FLOATING POINT ARITHMETIC
!             being used.
!
eta = dpmpar(1)
smalno = dpmpar(2)
infin = dpmpar(3)
base = ipmpar(4)
!-------------------------
!
!     Initialization
!
are = eta
mre = 2.d0*sqrt(2.d0)*eta
xx = .70710678
yy = -xx
cosr = -.069756474
sinr = .99756405
num = 0
nn = idp1
!
!     The algorithm fails if the leading coefficient is zero
!
if (opr(1) /= 0.d0 .or. opi(1) /= 0.d0) go to 10
num = -1
return
!
!     Remove the zeros at the origin if any.
!
10 if (opr(nn) /= 0.d0 .or. opi(nn) /= 0.d0) go to 20
num = num + 1
zeror(num) = 0.d0
zeroi(num) = 0.d0
nn = nn - 1
go to 10
!
!     Make a copy of the coefficients.
!
20 if (nn < 2) return
do i = 1,nn
   pr(i) = opr(i)
   pi(i) = opi(i)
   shr(i) = dcpabs(pr(i),pi(i))
end do
!
!     Scale the polynomial.
!
bnd = scalcp(nn,shr,eta,infin,smalno,base)
if (bnd == 1.d0) go to 40
do i = 1,nn
   pr(i) = bnd*pr(i)
   pi(i) = bnd*pi(i)
end do
!
!     Start the algorithm for obtaining a zero.
!
40 if (nn > 2) go to 50
!
num = ideg
call cdivid(-pr(2),-pi(2),pr(1),pi(1),zeror(ideg), &
   & zeroi(ideg))
return
!
!     Calculate BND, a lower bound on the modulus of the zeros.
!
50 do i = 1,nn
   shr(i) = dcpabs(pr(i),pi(i))
end do
call cauchy(nn,bnd,shr,shi)
!
!     Outer loop to control two major passes with different
!     sequences of shifts.
!
do cnt1 = 1,2
!
!     First stage calculation. No shift.
!
   call noshft(5,nn,tr,ti,eta,pr,pi,hr,hi)
!
!     Inner loop to select a shift.
!
   do cnt2 = 1,9
!
!     The shift is chosen with modulus BND and amplitude rotated
!     by 94 degrees from the previous shift.
!
      xxx = cosr*xx - sinr*yy
      yy = sinr*xx + cosr*yy
      xx = xxx
      sr = bnd*xx
      si = bnd*yy
!
!     Second stage calculation, fixed shift. The second stage jumps
!     directly to the third stage iteration.
!
      call fxshft(10*cnt2,zr,zi,conv,nn,pr,pi,hr,hi,qpr,qpi, &
         & qhr,qhi,shr,shi,sr,si,tr,ti,pvr,pvi, &
         & are,mre,eta,infin)
      if (conv) go to 100
!
!     If the iteration is unsuccessful another shift is chosen.
!
   end do
!
!     If 9 shifts fail, the outer loop is repeated with another
!     sequence of shifts.
!
end do
return
!
!     A zero has been obtained. Store the zero and deflate
!     the polynomial.
!
100 num = num + 1
zeror(num) = zr
zeroi(num) = zi
nn = nn - 1
do i = 1,nn
   pr(i) = qpr(i)
   pi(i) = qpi(i)
end do
go to 40
end subroutine dcply1

pure double precision function scalcp(nn,pt,eta,infin,smalno,base)
implicit none
integer, intent(in) :: nn
double precision, intent(in) :: pt(nn), eta, infin, smalno, base
integer :: i, l
double precision :: hi, lo, max, min, x, sc
!
!     Returns a scale factor to multiply the coefficients of the
!     polynomial. The scaling is done to avoid overflow and to avoid
!     undetected underflow interfering with the convergence criterion.
!     The factor is a power of the base.
!
!     pt - Modulus of the coefficients of P
!     eta,infin,smalno,base - Constants describing the
!            floating point arithmetic.
!
!
!     Find the largest and smallest moduli of coefficients.
!
hi = sqrt(infin)
lo = smalno/eta
max = 0.d0
min = infin
do i = 1,nn
   x = pt(i)
   if (x > max) max = x
   if (x /= 0.d0 .and. x < min) min = x
end do
!
!     Scale only if there are very large or very small coefficients.
!
scalcp = 1.d0
sc = lo/min
if (sc > 1.d0) go to 20
if (max <= hi) return
sc = 1.d0/(sqrt(max)*sqrt(min))
go to 30
20 if (infin/sc < max) return
30 l = log(sc)/log(base) + 0.5d0
scalcp = base**l
end function scalcp

pure subroutine cauchy(nn,bnd,pt,q)
implicit none
integer, intent(in) :: nn
double precision, intent(inout) :: q(nn), pt(nn)
double precision, intent(inout) :: bnd
integer :: i, n
double precision :: x, xm, f, dx, df
!
!     Cauchy computes a lower bound bnd on the moduli of the zeros
!     of a polynomial. pt is the modulus of the coefficients.
!
!
pt(nn) = -pt(nn)
!
!     Compute upper estimate of bound.
!
n = nn - 1
x = exp((log(-pt(nn)) - log(pt(1)))/dble(float(n)))
if (pt(n) == 0.d0) go to 20
!
!     If the Newton step at the origin is better then use it.
!
xm = -pt(nn)/pt(n)
if (xm < x) x = xm
!
!     Chop the interval (0,x) until f .LE. 0.
!
20 xm = 0.1d0*x
f = pt(1)
do i = 2,nn
   f = f*xm + pt(i)
end do
if (f <= 0.d0) go to 40
x = xm
go to 20
40 dx = x
!
!     Do Newton iteration until x converges to two decimal places.
!
50 if (abs(dx/x) <= 0.005d0) go to 70
q(1) = pt(1)
do i = 2,nn
   q(i) = q(i - 1)*x + pt(i)
end do
f = q(nn)
df = q(1)
do i = 2,n
   df = df*x + q(i)
end do
dx = f/df
x = x - dx
go to 50
!
70 bnd = x
end subroutine cauchy

pure subroutine noshft(l1,nn,tr,ti,eta,pr,pi,hr,hi)
implicit none
integer, intent(in) :: l1, nn
double precision, intent(inout) :: tr, ti
double precision, intent(in) :: eta, pr(nn), pi(nn)
double precision, intent(inout) :: hr(nn), hi(nn)
integer :: i, j, jj, n, nm1
double precision :: dn, t1, t2, xni
interface
   pure elemental subroutine cdivid(ar,ai,br,bi,cr,ci)
      implicit none
      double precision, intent(in) :: ar
      double precision, intent(in) :: ai
      double precision, intent(in) :: br
      double precision, intent(in) :: bi
      double precision, intent(inout) :: cr
      double precision, intent(inout) :: ci
   end subroutine cdivid
   pure elemental function dcpabs(x,y)
      implicit none
      double precision, intent(in) :: x
      double precision, intent(in) :: y
      double precision :: dcpabs
   end function dcpabs
end interface
!
!     Computes the derivative polynomial as the initial H
!     polynomial and computes l1 no-shift H polynomials.
!
!
n = nn - 1
nm1 = n - 1
dn = n
do i = 1,n
   xni = nn - i
   hr(i) = xni*pr(i)/dn
   hi(i) = xni*pi(i)/dn
10 continue
end do
!
do jj = 1,l1
   if (dcpabs(hr(n),hi(n)) <= 10.d0*eta*dcpabs(pr(n),pi(n))) &
      & go to 30
   call cdivid(-pr(nn),-pi(nn),hr(n),hi(n),tr,ti)
   do i = 1,nm1
      j = nn - i
      t1 = hr(j - 1)
      t2 = hi(j - 1)
      hr(j) = tr*t1 - ti*t2 + pr(j)
      hi(j) = tr*t2 + ti*t1 + pi(j)
   end do
   hr(1) = pr(1)
   hi(1) = pi(1)
   go to 50
!
!     If the constant term is essentially zero, shift H coefficients.
!
30 do i = 1,nm1
      j = nn - i
      hr(j) = hr(j - 1)
      hi(j) = hi(j - 1)
   end do
   hr(1) = 0.d0
   hi(1) = 0.d0
50 continue
end do
end subroutine noshft

pure subroutine fxshft(l2,zr,zi,conv,nn,pr,pi,hr,hi,qpr,qpi, &
   & qhr,qhi,shr,shi,sr,si,tr,ti,pvr,pvi, &
   & are,mre,eta,infin)
implicit none
integer, intent(in) :: l2, nn
double precision, intent(inout) :: sr, si, tr, ti, pvr, pvi
double precision, intent(in) :: are, mre, eta, infin, pr(nn), &
   & pi(nn)
double precision, intent(inout) :: qpr(nn), qpi(nn), hr(nn), &
   & hi(nn), qhr(nn), qhi(nn), shr(nn), shi(nn)
double precision, intent(inout) :: zr, zi
logical, intent(inout) :: conv
integer :: i, j, n
double precision :: otr, oti, svsr, svsi
logical :: test, pasd, bool
interface
   pure subroutine calct(bool,n,sr,si,tr,ti,pvr,pvi,are,hr,hi,qhr, &
      & qhi)
      implicit none
      integer, intent(in) :: n
      logical, intent(inout) :: bool
      double precision, intent(in) :: sr
      double precision, intent(in) :: si
      double precision, intent(inout) :: tr
      double precision, intent(inout) :: ti
      double precision, intent(in) :: pvr
      double precision, intent(in) :: pvi
      double precision, intent(in) :: are
      double precision, intent(in) :: hr(n)
      double precision, intent(in) :: hi(n)
      double precision, intent(inout) :: qhr(n)
      double precision, intent(inout) :: qhi(n)
   end subroutine calct
   pure elemental function dcpabs(x,y)
      implicit none
      double precision, intent(in) :: x
      double precision, intent(in) :: y
      double precision :: dcpabs
   end function dcpabs
   pure subroutine nexth(bool,n,tr,ti,hr,hi,qpr,qpi,qhr,qhi)
      implicit none
      integer, intent(in) :: n
      logical, intent(in) :: bool
      double precision, intent(in) :: tr
      double precision, intent(in) :: ti
      double precision, intent(inout) :: hr(n)
      double precision, intent(inout) :: hi(n)
      double precision, intent(in) :: qpr(n)
      double precision, intent(in) :: qpi(n)
      double precision, intent(in) :: qhr(n)
      double precision, intent(in) :: qhi(n)
   end subroutine nexth
   pure subroutine polyev(n,sr,si,pr,pi,qr,qi,pvr,pvi)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: sr
      double precision, intent(in) :: si
      double precision, intent(in) :: pr(n)
      double precision, intent(in) :: pi(n)
      double precision, intent(inout) :: qr(n)
      double precision, intent(inout) :: qi(n)
      double precision, intent(out) :: pvr
      double precision, intent(out) :: pvi
   end subroutine polyev
   pure subroutine vrshft(l3,zr,zi,conv,nn,pr,pi,hr,hi,qpr,qpi,qhr, &
      & qhi,sr,si,tr,ti,pvr,pvi,are,mre,eta,infin)
      implicit none
      integer, intent(in) :: nn
      integer, intent(in) :: l3
      double precision, intent(inout) :: zr
      double precision, intent(inout) :: zi
      logical, intent(out) :: conv
      double precision, intent(in) :: pr(nn)
      double precision, intent(in) :: pi(nn)
      double precision, intent(inout) :: hr(nn)
      double precision, intent(inout) :: hi(nn)
      double precision, intent(inout) :: qpr(nn)
      double precision, intent(inout) :: qpi(nn)
      double precision, intent(inout) :: qhr(nn)
      double precision, intent(inout) :: qhi(nn)
      double precision, intent(out) :: sr
      double precision, intent(out) :: si
      double precision, intent(inout) :: tr
      double precision, intent(inout) :: ti
      double precision, intent(inout) :: pvr
      double precision, intent(inout) :: pvi
      double precision, intent(in) :: are
      double precision, intent(in) :: mre
      double precision, intent(in) :: eta
      double precision, intent(in) :: infin
   end subroutine vrshft
end interface
!
!     Computes l2 fixed-shift H polynomials and tests for convergence.
!     Initiates a variable-shift iteration and returns with the
!     approximate zero if successful.
!
!     l2 - Limit of fixed-shift steps
!     zr,zi - Approximate zero if conv is .TRUE.
!     conv - Logical variable indicating convergence of stage 3
!            iteration
!
!
n = nn - 1
!
!     Evaluate P at S
!
call polyev(nn,sr,si,pr,pi,qpr,qpi,pvr,pvi)
test = .true.
pasd = .false.
!
!     CALCULATE T = -P(S)/H(S)
!
call calct(bool,n,sr,si,tr,ti,pvr,pvi,are,hr,hi,qhr,qhi)
!
!     Main loop for one second stage step.
!
do j = 1,l2
   otr = tr
   oti = ti
!
!     Compute next H polynomial and new T.
!
   call nexth(bool,n,tr,ti,hr,hi,qpr,qpi,qhr,qhi)
   call calct(bool,n,sr,si,tr,ti,pvr,pvi,are,hr,hi,qhr,qhi)
   zr = sr + tr
   zi = si + ti
!
!     Test for convergence unless stage 3 has failed once or this
!     is the last H polynomial.
!
   if (bool .or. (.not. test) .or. j == l2) go to 50
   if (dcpabs(tr - otr,ti - oti) >= 0.5d0*dcpabs(zr,zi)) &
      & go to 40
   if (.not. pasd) go to 30
!
!     The weak convergence test has been passed twice. Start the
!     third shift iteration after saving the current H polynomial
!     and shift.
!
   do i = 1,n
      shr(i) = hr(i)
      shi(i) = hi(i)
10    continue
   end do
   svsr = sr
   svsi = si
   call vrshft(10,zr,zi,conv,nn,pr,pi,hr,hi,qpr,qpi,qhr, &
      & qhi,sr,si,tr,ti,pvr,pvi,are,mre,eta,infin)
   if (conv) return
!
!     The iteration failed to converge. Turn off testing and restore
!     H,S,PV AND T.
!
   test = .false.
   do i = 1,n
      hr(i) = shr(i)
      hi(i) = shi(i)
   end do
   sr = svsr
   si = svsi
   call polyev(nn,sr,si,pr,pi,qpr,qpi,pvr,pvi)
   call calct(bool,n,sr,si,tr,ti,pvr,pvi,are,hr,hi,qhr,qhi)
   go to 50
!
30 pasd = .true.
   go to 50
!
40 pasd = .false.
50 continue
end do
!
!     Attempt an iteration with final H polynomial from second stage.
!
call vrshft(10,zr,zi,conv,nn,pr,pi,hr,hi,qpr,qpi,qhr,qhi, &
   & sr,si,tr,ti,pvr,pvi,are,mre,eta,infin)
end subroutine fxshft

pure subroutine vrshft(l3,zr,zi,conv,nn,pr,pi,hr,hi,qpr,qpi,qhr,qhi, &
   & sr,si,tr,ti,pvr,pvi,are,mre,eta,infin)
implicit none
integer, intent(in) :: l3, nn
double precision, intent(out) :: sr, si
double precision, intent(inout) :: tr, ti, pvr, pvi
double precision, intent(in) :: are, mre, eta, infin, pr(nn), &
   & pi(nn)
double precision, intent(inout) :: qpr(nn), qpi(nn), hr(nn), &
   & hi(nn), qhr(nn), qhi(nn)
double precision, intent(inout) :: zr, zi
logical, intent(out) :: conv
integer :: i, j, n
double precision :: mp, ms, omp, relstp, r1, r2, tp
logical :: b, bool
interface
   pure subroutine calct(bool,n,sr,si,tr,ti,pvr,pvi,are,hr,hi,qhr, &
      & qhi)
      implicit none
      integer, intent(in) :: n
      logical, intent(inout) :: bool
      double precision, intent(in) :: sr
      double precision, intent(in) :: si
      double precision, intent(inout) :: tr
      double precision, intent(inout) :: ti
      double precision, intent(in) :: pvr
      double precision, intent(in) :: pvi
      double precision, intent(in) :: are
      double precision, intent(in) :: hr(n)
      double precision, intent(in) :: hi(n)
      double precision, intent(inout) :: qhr(n)
      double precision, intent(inout) :: qhi(n)
   end subroutine calct
   pure elemental function dcpabs(x,y)
      implicit none
      double precision, intent(in) :: x
      double precision, intent(in) :: y
      double precision :: dcpabs
   end function dcpabs
   pure function errev(nn,qr,qi,ms,mp,are,mre)
      implicit none
      integer, intent(in) :: nn
      double precision, intent(in) :: qr(nn)
      double precision, intent(in) :: qi(nn)
      double precision, intent(in) :: ms
      double precision, intent(in) :: mp
      double precision, intent(in) :: are
      double precision, intent(in) :: mre
      double precision :: errev
   end function errev
   pure subroutine nexth(bool,n,tr,ti,hr,hi,qpr,qpi,qhr,qhi)
      implicit none
      integer, intent(in) :: n
      logical, intent(in) :: bool
      double precision, intent(in) :: tr
      double precision, intent(in) :: ti
      double precision, intent(inout) :: hr(n)
      double precision, intent(inout) :: hi(n)
      double precision, intent(in) :: qpr(n)
      double precision, intent(in) :: qpi(n)
      double precision, intent(in) :: qhr(n)
      double precision, intent(in) :: qhi(n)
   end subroutine nexth
   pure subroutine polyev(n,sr,si,pr,pi,qr,qi,pvr,pvi)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: sr
      double precision, intent(in) :: si
      double precision, intent(in) :: pr(n)
      double precision, intent(in) :: pi(n)
      double precision, intent(inout) :: qr(n)
      double precision, intent(inout) :: qi(n)
      double precision, intent(out) :: pvr
      double precision, intent(out) :: pvi
   end subroutine polyev
end interface
!
!     Carries out the third stage iteration.
!
!     l3 - Limit of steps in stage 3.
!     zr,zi - On entry contain the initial iterate. If the
!             iteration converges zr,zi contain the final
!             iterate on exit.
!     conv  - The value is .TRUE. if the iteration converges.
!
!
conv = .false.
b = .false.
sr = zr
si = zi
n = nn - 1
!
!     Main loop for stage 3.
!
do i = 1,l3
!
!     Evaluate P at S and test for convergence.
!
   call polyev(nn,sr,si,pr,pi,qpr,qpi,pvr,pvi)
   mp = dcpabs(pvr,pvi)
   ms = dcpabs(sr,si)
   if (mp > 20.d0*errev(nn,qpr,qpi,ms,mp,are,mre)) &
      & go to 10
!
!     Polynomial value is smaller than a bound on the error
!     in evaluating P. terminate the iteration.
!
   conv = .true.
   zr = sr
   zi = si
   return
!
10 if (i == 1) go to 40
   if (b .or. mp < omp .or. relstp >= 0.05d0) &
      & go to 30
!
!     Iteration has stalled. Probably a cluster of zeros. Do 5 fixed
!     shift steps into the cluster to force one zero to dominate.
!
   tp = relstp
   b = .true.
   if (relstp < eta) tp = eta
   r1 = sqrt(tp)
   r2 = sr*(1.d0 + r1) - si*r1
   si = sr*r1 + si*(1.d0 + r1)
   sr = r2
   call polyev(nn,sr,si,pr,pi,qpr,qpi,pvr,pvi)
   do j = 1,5
      call calct(bool,n,sr,si,tr,ti,pvr,pvi,are,hr,hi,qhr,qhi)
      call nexth(bool,n,tr,ti,hr,hi,qpr,qpi,qhr,qhi)
20    continue
   end do
   omp = infin
   go to 50
!
!     Exit if the polynomial value increases significantly.
!
30 if (0.1d0*mp > omp) return
!
!     Calculate the next iterate.
!
40 omp = mp
!
50 call calct(bool,n,sr,si,tr,ti,pvr,pvi,are,hr,hi,qhr,qhi)
   call nexth(bool,n,tr,ti,hr,hi,qpr,qpi,qhr,qhi)
   call calct(bool,n,sr,si,tr,ti,pvr,pvi,are,hr,hi,qhr,qhi)
   if (bool) go to 60
   relstp = dcpabs(tr,ti)/dcpabs(sr,si)
   sr = sr + tr
   si = si + ti
60 continue
end do
end subroutine vrshft

pure subroutine calct(bool,n,sr,si,tr,ti,pvr,pvi,are,hr,hi,qhr,qhi)
implicit none
integer, intent(in) :: n
logical, intent(inout) :: bool
double precision, intent(in) :: sr, si
double precision, intent(inout) :: tr, ti
double precision, intent(in) :: pvr, pvi, are, hr(n), hi(n)
double precision, intent(inout) :: qhr(n), qhi(n)
double precision :: hvr, hvi
interface
   pure elemental subroutine cdivid(ar,ai,br,bi,cr,ci)
      implicit none
      double precision, intent(in) :: ar
      double precision, intent(in) :: ai
      double precision, intent(in) :: br
      double precision, intent(in) :: bi
      double precision, intent(inout) :: cr
      double precision, intent(inout) :: ci
   end subroutine cdivid
   pure elemental function dcpabs(x,y)
      implicit none
      double precision, intent(in) :: x
      double precision, intent(in) :: y
      double precision :: dcpabs
   end function dcpabs
   pure subroutine polyev(n,sr,si,pr,pi,qr,qi,pvr,pvi)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: sr
      double precision, intent(in) :: si
      double precision, intent(in) :: pr(n)
      double precision, intent(in) :: pi(n)
      double precision, intent(inout) :: qr(n)
      double precision, intent(inout) :: qi(n)
      double precision, intent(out) :: pvr
      double precision, intent(out) :: pvi
   end subroutine polyev
end interface
!
!     This subroutine computes T = -P(S)/H(S)
!
!     bool - Logical variable, which is set to .TRUE. if H(S) is
!            essentially zero.
!
!
!     Evaluate H(S)
!
call polyev(n,sr,si,hr,hi,qhr,qhi,hvr,hvi)
bool = dcpabs(hvr,hvi) <= 10.d0*are*dcpabs(hr(n),hi(n))
if (bool) go to 10
call cdivid(-pvr,-pvi,hvr,hvi,tr,ti)
return
10 tr = 0.d0
ti = 0.d0
end subroutine calct

pure subroutine nexth(bool,n,tr,ti,hr,hi,qpr,qpi,qhr,qhi)
implicit none
integer, intent(in) :: n
logical, intent(in) :: bool
double precision, intent(in) :: tr, ti
double precision, intent(inout) :: hr(n), hi(n)
double precision, intent(in) :: qpr(n), qpi(n), qhr(n), qhi(n)
integer :: j
double precision :: t1, t2
!
!     Calculates the next shifted H polynomial.
!
!     bool - Logical variable. If .TRUE. H(S) is essentially zero.
!
!
if (bool) go to 20
do j = 2,n
   t1 = qhr(j - 1)
   t2 = qhi(j - 1)
   hr(j) = tr*t1 - ti*t2 + qpr(j)
   hi(j) = tr*t2 + ti*t1 + qpi(j)
end do
hr(1) = qpr(1)
hi(1) = qpi(1)
return
!
!     If H(S) is zero then replace H with QH.
!
20 do j = 2,n
   hr(j) = qhr(j - 1)
   hi(j) = qhi(j - 1)
end do
hr(1) = 0.d0
hi(1) = 0.d0
end subroutine nexth

pure subroutine polyev(n,sr,si,pr,pi,qr,qi,pvr,pvi)
implicit none
integer, intent(in) :: n
double precision, intent(in) :: pr(n), pi(n)
double precision, intent(inout) :: qr(n), qi(n)
double precision, intent(in) :: sr, si
double precision, intent(out) :: pvr, pvi
integer :: i
double precision :: t
!
!     Evaluates a polynomial P at S by the Horner recurrence algo.,
!     placing the partial sums in Q and the computed value in PV.
!
!
qr(1) = pr(1)
qi(1) = pi(1)
pvr = qr(1)
pvi = qi(1)
do i = 2,n
   t = pvr*sr - pvi*si + pr(i)
   pvi = pvr*si + pvi*sr + pi(i)
   pvr = t
   qr(i) = pvr
   qi(i) = pvi
end do
end subroutine polyev

pure double precision function errev(nn,qr,qi,ms,mp,are,mre)
implicit none
integer, intent(in) :: nn
double precision, intent(in) :: qr(nn), qi(nn), ms, mp, are, mre
integer :: i
double precision :: e
interface
   pure elemental function dcpabs(x,y)
      implicit none
      double precision, intent(in) :: x
      double precision, intent(in) :: y
      double precision :: dcpabs
   end function dcpabs
end interface
!
!     Bounds the error in evaluating the polynomial by the Horner
!     recurrence algorithm.
!
!     QR,qi   - THE PARTIAL SUMS
!     ms      - Modulus of the point
!     mp      - Modulus of the polynomial value
!     are,mre - Error bounds on complex addition and multiplication
!
!
e = dcpabs(qr(1),qi(1))*mre/(are + mre)
do i = 1,nn
   e = e*ms + dcpabs(qr(i),qi(i))
end do
errev = e*(are + mre) - mp*mre
end function errev

pure subroutine rbnd(n, c, w, abserr, relerr, klust, ker)
implicit none
integer, intent(inout) :: ker
integer, intent(in) :: n
complex, intent(in) :: w(n)
integer, intent(inout) :: klust(n)
real, intent(in) :: c(*)
real, intent(inout) :: abserr(n), relerr(n)
integer :: j, jp1, k, l, m, nm1, np1
real :: b, cert, dist, eps, olderr, p, power, r, rat, wnrm, wrad
complex :: z
double precision :: xr, xi, vr, vi, vt
logical :: shrunk
interface
   pure elemental function cpabs(x,y)
      implicit none
      real, intent(in) :: x
      real, intent(in) :: y
      real :: cpabs
   end function cpabs
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-----------------------------------------------------------------------
!
!     Abstract
!
!         This routine computes error bounds and cluster counts
!         for approximate zeros of a polynomial with real coefficients.
!         The zeros may have been computed by any appropriate routine.
!         The method used is based on the fact that the value of A
!         polynomial at any point is equal to the leading coefficient
!         times the product of the distances from that point to each
!         of the zeros.  Given the value of the polynomial at an
!         approximate zero, rbnd computes for each approximate zero
!         the radius of a circle about that approximate zero which
!         contains a true zero of the polynomial.  Using the known
!         distribution of approximate zeros, an iterative procedure
!         is used to shrink the radii of the circles.
!
!     Description of arguments
!
!         Input---
!
!         n      - Degree of the polynomial (number of zeros).
!         c      - Real array of n+1 coefficients of the polynomial
!                  c(1) + c(2)*z + ... + c(n+1)*z**n
!         w      - Complex array of n approximate zeros.
!
!         Output--
!
!         abserr - Real array of n absolute error bounds.  abserr(I) is
!                  the absolute error bound in the zero (WR(I),WI(I)).
!         relerr - Real array of n relative error bounds.  relerr(I) is
!                  the relative error bound in the zero (WR(I),WI(I)).
!         klust  - Integer array of cluster counts for zeros.  The true
!                  zero corresponding to I-TH approximate zero lies in
!                  a circle of radius abserr(I). klust(I) is the number
!                  of circles including the I-TH circle which overlap
!                  the I-TH circle.  The cluster count often indicates
!                  the multiplicity of a zero.
!         ker    - An error flag
!                --normal code
!                  0  means the bounds and counts were computed.
!                --Abnormal codes
!                  1  n (DEGREE) must be .GE. 1
!                  2  leading coefficient is zero
!
!-------------------
!     Written by carl b. bailey and modified by william r. gavin
!        Sandia Laboratories
!        albuquerque, new mexico
!        January 1976
!     modified by A.H. Morris (NSWC)
!-----------------------------------------------------------------------
!-----------------------------------------------------------------------
!
!     ****** eps is a machine dependent constant. Eps is the
!            smallest number such that 1 + eps .GT. 1.
!
eps = spmpar(1)
!
!-----------------------------------------------------------------------
if (n < 1) go to 200
np1 = n + 1
power = 1.0/float(n)
p = abs(c(np1))
if (p == 0.0) go to 210
rat = 4.0*eps*abs(c(1))/p
!
do l = 1,n
   xr = real(w(l))
   xi = aimag(w(l))
   vr = c(np1)
   vi = 0.0d0
   do j = 1,n
      m = np1 - j
      vt = xr*vr - xi*vi + dble(c(m))
      vi = xr*vi + xi*vr
      vr = vt
   end do
   b = max(rat,cpabs(sngl(vr),sngl(vi))/p)
!
!        Save product of distances temporarily
!
   relerr(l) = b
   abserr(l) = b ** power
end do
!
30 shrunk = .false.
do j = 1,n
   if (abserr(j) == 0.0) go to 50
   p = 1.0
   m = n
   do k = 1,n
      if (k == j) go to 40
      z = w(j) - w(k)
      dist = cpabs(real(z),aimag(z))
      cert = dist - abserr(k)
      if (cert < abserr(j)) go to 40
      p = p*cert
      m = m - 1
40    continue
   end do
   olderr = abserr(j)
   abserr(j) = relerr(j)/p
   if (m > 1) abserr(j) = abserr(j)**(1.0/float(m))
   if (abserr(j) < olderr*0.99) shrunk = .true.
50 continue
end do
if (shrunk) go to 30
!
do j = 1,n
   klust(j) = 1
   wrad = abserr(j)
   wnrm = cpabs(real(w(j)),aimag(w(j)))
   if (wrad /= 0.0) go to 60
   r = 0.0
   go to 80
60 if (wnrm /= 0.0) go to 70
   r = -1.0
   go to 80
70 r = wrad/wnrm
80 relerr(j) = r
end do
!
nm1 = n - 1
do j = 1,nm1
   jp1 = j + 1
   do k = jp1,n
      z = w(j) - w(k)
      dist = cpabs(real(z),aimag(z))
      if (dist > (abserr(j) + abserr(k))) go to 90
      klust(j) = klust(j) + 1
      klust(k) = klust(k) + 1
90    continue
   end do
end do
ker = 0
return
!
!             Error return
!
200 ker = 1
return
210 ker = 2
end subroutine rbnd

pure subroutine cbnd(n, c, w, abserr, relerr, klust, ker)
implicit none
integer, intent(inout) :: ker
integer, intent(in) :: n
complex, intent(in) :: c(*), w(n)
integer, intent(inout) :: klust(n)
real, intent(inout) :: abserr(n), relerr(n)
integer :: j, jp1, k, l, m, nm1, np1
real :: b, cert, dist, eps, olderr, p, power, r, rat, wnrm, wrad
complex :: z
double precision :: xr, xi, vr, vi, vt
logical :: shrunk
interface
   pure elemental function cpabs(x,y)
      implicit none
      real, intent(in) :: x
      real, intent(in) :: y
      real :: cpabs
   end function cpabs
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!-----------------------------------------------------------------------
!
!     Abstract
!
!         This routine computes error bounds and cluster counts for
!         approximate zeros of a polynomial with complex coefficients.
!         The zeros may have been computed by any appropriate routine.
!         The method used is based on the fact that the value of A
!         polynomial at any point is equal to the leading coefficient
!         times the product of the distances from that point to each
!         of the zeros.  Given the value of the polynomial at an
!         approximate zero, cbnd computes for each approximate zero
!         the radius of a circle about that approximate zero which
!         contains a true zero of the polynomial.  Using the known
!         distribution of approximate zeros, an iterative procedure
!         is used to shrink the radii of the circles.
!
!     Description of arguments
!
!         Input---
!
!         n      - Degree of the polynomial (number of zeros).
!         c      - Complex array of n+1 coefficients of the polynomial
!                  c(1) + c(2)*z + ... + c(n+1)*z**n
!         w      - Complex array of n approximate zeros.
!
!         Output--
!
!         abserr - Real array of absolute error bounds.  abserr(I) is
!                  the absolute error bound in the zero (WR(I),WI(I)).
!         relerr - Real array of relative error bounds.  relerr(I) is
!                  the relative error bound in the zero (WR(I),WI(I)).
!         klust  - Integer array of cluster counts for zeros.  The true
!                  zero corresponding to I-TH approximate zero lies in
!                  a circle of radius abserr(I).  klust(I) is the number
!                  of circles including the I-TH circle which overlap
!                  the I-TH circle.  The cluster count often indicates
!                  the multiplicity of a zero.
!         ker    - An error code
!                --normal codes
!                  0  means the bounds and counts were computed.
!                --Abnormal codes
!                  1  n (DEGREE) must be .GE. 1
!                  2  leading coefficient is zero
!
!-------------------
!     Written by carl b. bailey and modified by william r. gavin
!        Sandia Laboratories
!        albuquerque, new mexico
!        January 1976
!     modified by A.H. Morris (NSWC)
!-----------------------------------------------------------------------
!-----------------------------------------------------------------------
!
!     ****** eps is a machine dependent constant. Eps is the
!            smallest number such that 1 + eps .GT. 1.
!
eps = spmpar(1)
!
!-----------------------------------------------------------------------
if (n < 1) go to 200
np1 = n + 1
power = 1.0/float(n)
p = cpabs(real(c(np1)),aimag(c(np1)))
if (p == 0.0) go to 210
rat = 4.0*eps*cpabs(real(c(1)),aimag(c(1)))/p
!
do l = 1,n
   xr = real(w(l))
   xi = aimag(w(l))
   vr = real(c(np1))
   vi = aimag(c(np1))
   do j = 1,n
      m = np1 - j
      vt = xr*vr - xi*vi + dble(real(c(m)))
      vi = xr*vi + xi*vr + dble(aimag(c(m)))
      vr = vt
   end do
   b = max(rat,cpabs(sngl(vr),sngl(vi))/p)
!
!        Save product of distances temporarily
!
   relerr(l) = b
   abserr(l) = b ** power
end do
!
30 shrunk = .false.
do j = 1,n
   if (abserr(j) == 0.0) go to 50
   p = 1.0
   m = n
   do k = 1,n
      if (k == j) go to 40
      z = w(j) - w(k)
      dist = cpabs(real(z),aimag(z))
      cert = dist - abserr(k)
      if (cert < abserr(j)) go to 40
      p = p*cert
      m = m - 1
40    continue
   end do
   olderr = abserr(j)
   abserr(j) = relerr(j)/p
   if (m > 1) abserr(j) = abserr(j)**(1.0/float(m))
   if (abserr(j) < olderr*0.99) shrunk = .true.
50 continue
end do
if (shrunk) go to 30
!
do j = 1,n
   klust(j) = 1
   wrad = abserr(j)
   wnrm = cpabs(real(w(j)),aimag(w(j)))
   if (wrad /= 0.0) go to 60
   r = 0.0
   go to 80
60 if (wnrm /= 0.0) go to 70
   r = -1.0
   go to 80
70 r = wrad/wnrm
80 relerr(j) = r
end do
!
nm1 = n - 1
do j = 1,nm1
   jp1 = j + 1
   do k = jp1,n
      z = w(j) - w(k)
      dist = cpabs(real(z),aimag(z))
      if (dist > (abserr(j) + abserr(k))) go to 90
      klust(j) = klust(j) + 1
      klust(k) = klust(k) + 1
90    continue
   end do
end do
ker = 0
return
!
!             Error return
!
200 ker = 1
return
210 ker = 2
end subroutine cbnd

pure subroutine  scopy(n,sx,incx,sy,incy)
implicit none
!
!     Copies a vector, X, to a vector, Y.
!     Uses unrolled loops for increments equal to 1.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sx(*)
real, intent(inout) :: sy(*)
integer, intent(in) :: incx, incy
integer, intent(in) :: n
integer :: i, ix, iy, m, mp1
!
if (n <= 0) return
if (incx == 1.and.incy == 1) go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if (incx < 0) ix = (-n + 1)*incx + 1
if (incy < 0) iy = (-n + 1)*incy + 1
do i = 1,n
   sy(iy) = sx(ix)
   ix = ix + incx
   iy = iy + incy
end do
return
!
!        Code for both increments equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,7)
if ( m == 0 ) go to 40
do i = 1,m
   sy(i) = sx(i)
end do
if ( n < 7 ) return
40 mp1 = m + 1
do i = mp1,n,7
   sy(i) = sx(i)
   sy(i + 1) = sx(i + 1)
   sy(i + 2) = sx(i + 2)
   sy(i + 3) = sx(i + 3)
   sy(i + 4) = sx(i + 4)
   sy(i + 5) = sx(i + 5)
   sy(i + 6) = sx(i + 6)
end do
end subroutine scopy

