double precision, intent(inout) :: dy(*)
integer, intent(in) :: incx, incy
integer, intent(in) :: n
integer :: i, ix, iy, m, mp1
!
if (n <= 0) return
if (incx == 1.and.incy == 1) go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if (incx < 0) ix = (-n + 1)*incx + 1
if (incy < 0) iy = (-n + 1)*incy + 1
do i = 1,n
   dy(iy) = dx(ix)
   ix = ix + incx
   iy = iy + incy
end do
return
!
!        Code for both increments equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,7)
if ( m == 0 ) go to 40
do i = 1,m
   dy(i) = dx(i)
end do
if ( n < 7 ) return
40 mp1 = m + 1
do i = mp1,n,7
   dy(i) = dx(i)
   dy(i + 1) = dx(i + 1)
   dy(i + 2) = dx(i + 2)
   dy(i + 3) = dx(i + 3)
   dy(i + 4) = dx(i + 4)
   dy(i + 5) = dx(i + 5)
   dy(i + 6) = dx(i + 6)
end do
end subroutine dcopy

pure subroutine  ccopy(n,cx,incx,cy,incy)
implicit none
!
!     Copies a vector, X, to a vector, Y.
!     Jack dongarra, LINPACK, 3/11/78.
!
complex, intent(in) :: cx(*)
complex, intent(inout) :: cy(*)
integer, intent(in) :: incx, incy
integer, intent(in) :: n
integer :: i, ix, iy
!
if (n <= 0) return
if (incx == 1.and.incy == 1) go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if (incx < 0) ix = (-n + 1)*incx + 1
if (incy < 0) iy = (-n + 1)*incy + 1
do i = 1,n
   cy(iy) = cx(ix)
   ix = ix + incx
