   cx(i) = ctemp
end do
end subroutine csrot

pure subroutine srotmg(sd1,sd2,sx1,sy1,sparam)
implicit none
real, intent(inout) :: sd1, sd2, sparam(5), sx1
real, intent(in) :: sy1
real :: sflag, sh11, sh12, sh21, sh22, sp1, sp2, sq1, sq2, stemp, su, nswc_ai_r4
real, parameter :: zero = 0.e0
real, parameter :: one = 1.e0
real, parameter :: two = 2.e0
real, parameter :: gam = 4096.e0
real, parameter :: gamsq = 1.67772e7
real, parameter :: rgamsq = 5.96046e-8
!
!     Construct the modified Givens transformation matrix H which zeros
!     the second component of the 2-vector  (sqrt(sd1)*sx1,sqrt(sd2)*
!     sy1)**T.
!     With sparam(1)=sflag, H has one of the following forms..
!
!     sflag=-1.e0     sflag=0.e0        sflag=1.e0     sflag=-2.e0
!
!       (sh11  sh12)    (1.E0  sh12)    (sh11  1.E0)    (1.E0  0.E0)
!     h=(          )    (          )    (          )    (          )
!       (sh21  sh22),   (sh21  1.E0),   (-1.E0 sh22),   (0.E0  1.E0).
!
!     Locations 2-4 of sparam contain sh11,sh21,sh12, and sh22
!     respectively. (Values of 1.E0, -1.E0, or 0.E0 implied by the
!     value of sparam(1) are not stored in sparam.)
!
!     It is assumed that gamsq = gam*gam and rgamsq = one/(gam*gam).
!     The values of gamsq and rgamsq set in the data statement may be
!     inexact.  This is OK as they are only used for testing the size
!     of sd1 and sd2.  All actual scaling of data is done using gam.
!
!
!
if (sd1 < zero) go to 60
sp2 = sd2*sy1
if (sp2 /= zero) go to 20
sflag = -two
go to 260
!
!     Regular-case..
!
20 sp1 = sd1*sx1
sq1 = sp1*sx1
sq2 = sp2*sy1
!
if (abs(sq1) <= abs(sq2)) go to 40
sh21 = -sy1/sx1
sh12 = sp2/sp1
!
su = one - sh12*sh21
if (su <= zero) go to 60
!
sflag = zero
sh11 = one
sh22 = one
sd1 = sd1/su
sd2 = sd2/su
sx1 = sx1*su
!         Go scale-check..
go to 100
!
40 continue
if (sd2 < zero) go to 60
sflag = one
sh11 = sp1/sp2
sh21 = -one
sh12 = one
sh22 = sx1/sy1
!
su = one + sh11*sh22
stemp = sd2/su
sd2 = sd1/su
sd1 = stemp
sx1 = sy1*su
!         Go scale-check
go to 100
!
!     Procedure..zero-H-D-and-sx1..
!
60 continue
sflag = -one
sh11 = zero
sh12 = zero
sh21 = zero
sh22 = zero
!
sd1 = zero
sd2 = zero
sx1 = zero
go to 250
!
!     Procedure..scale-check
!
100 continue
110 continue
if (sd1 > rgamsq) go to 130
if (sd1 == zero) go to 160
sflag = -one
sd1 = sd1*(gam*gam)
sx1 = sx1/gam
sh11 = sh11/gam
sh12 = sh12/gam
go to 110
!
130 continue
140 continue
if (sd1 < gamsq) go to 160
sflag = -one
sd1 = sd1/(gam*gam)
sx1 = sx1*gam
sh11 = sh11*gam
sh12 = sh12*gam
go to 140
!
160 continue
170 continue
if (abs(sd2) > rgamsq) go to 190
if (sd2 == zero) go to 220
sflag = -one
sd2 = sd2*(gam*gam)
sh21 = sh21/gam
sh22 = sh22/gam
go to 170
!
190 continue
200 continue
if (abs(sd2) < gamsq) go to 220
sflag = -one
sd2 = sd2/(gam*gam)
sh21 = sh21*gam
sh22 = sh22*gam
go to 200
!
220 continue
nswc_ai_r4 = sflag
if ( nswc_ai_r4 < 0 ) go to 250
if ( nswc_ai_r4 == 0 ) go to 230
go to 240
230 continue
sparam(3) = sh21
sparam(4) = sh12
go to 260
240 continue
sparam(2) = sh11
sparam(5) = sh22
go to 260
250 continue
sparam(2) = sh11
sparam(3) = sh21
sparam(4) = sh12
sparam(5) = sh22
260 continue
sparam(1) = sflag
end subroutine srotmg

subroutine srotm(n,sx,incx,sy,incy,sparam)
implicit none
integer, intent(in) :: incx, incy, n
real :: sparam(5)
real, intent(inout) :: sx(*), sy(*)
integer :: i, kx, ky, nsteps
real :: sflag, sh11, sh12, sh21, sh22, w, z, nswc_ai_r4
real, parameter :: zero = 0.e0
real, parameter :: two = 2.e0
!
!     Apply the modified Givens transformation, H, to the 2 by n matrix
!
!     (sx**T), where **T indicates transpose. The elements of sx are in
!     (sy**T)
!
!     sx(LX+i*incx), i = 0 TO n-1, WHERE LX = 1 IF incx .GE. 0, ELSE
!     LX = (-incx)*n, and similarly for sy using using LY and incy.
!
!     With sparam(1)=sflag, H has one of the following forms..
!
!     sflag=-1.e0     sflag=0.e0        sflag=1.e0     sflag=-2.e0
!
!       (sh11  sh12)    (1.E0  sh12)    (sh11  1.E0)    (1.E0  0.E0)
!     h=(          )    (          )    (          )    (          )
!       (sh21  sh22),   (sh21  1.E0),   (-1.E0 sh22),   (0.E0  1.E0).
!
!
!
sflag = sparam(1)
if (n <= 0 .or.(sflag + two == zero)) go to 140
if (.not.(incx == incy.and. incx > 0)) go to 70
!
nsteps = n*incx
nswc_ai_r4 = sflag
if ( nswc_ai_r4 < 0 ) go to 50
if ( nswc_ai_r4 == 0 ) go to 10
go to 30
10 continue
sh21 = sparam(3)
sh12 = sparam(4)
do i = 1,nsteps,incx
   w = sx(i)
   z = sy(i)
   sx(i) = w + z*sh12
   sy(i) = w*sh21 + z
end do
go to 140
30 continue
sh11 = sparam(2)
sh22 = sparam(5)
do i = 1,nsteps,incx
   w = sx(i)
   z = sy(i)
   sx(i) = w*sh11 + z
   sy(i) = -w + sh22*z
end do
go to 140
50 continue
sh11 = sparam(2)
sh21 = sparam(3)
sh12 = sparam(4)
sh22 = sparam(5)
do i = 1,nsteps,incx
   w = sx(i)
   z = sy(i)
   sx(i) = w*sh11 + z*sh12
   sy(i) = w*sh21 + z*sh22
end do
go to 140
70 continue
kx = 1
ky = 1
if (incx < 0) kx = 1 + (1 - n)*incx
if (incy < 0) ky = 1 + (1 - n)*incy
!
nswc_ai_r4 = sflag
if ( nswc_ai_r4 < 0 ) go to 120
if ( nswc_ai_r4 == 0 ) go to 80
go to 100
80 continue
sh21 = sparam(3)
sh12 = sparam(4)
do i = 1,n
   w = sx(kx)
   z = sy(ky)
   sx(kx) = w + z*sh12
   sy(ky) = w*sh21 + z
   kx = kx + incx
   ky = ky + incy
end do
go to 140
100 continue
sh11 = sparam(2)
sh22 = sparam(5)
do i = 1,n
   w = sx(kx)
   z = sy(ky)
   sx(kx) = w*sh11 + z
   sy(ky) = -w + sh22*z
   kx = kx + incx
   ky = ky + incy
end do
go to 140
120 continue
sh11 = sparam(2)
sh21 = sparam(3)
sh12 = sparam(4)
sh22 = sparam(5)
do i = 1,n
   w = sx(kx)
   z = sy(ky)
   sx(kx) = w*sh11 + z*sh12
   sy(ky) = w*sh21 + z*sh22
   kx = kx + incx
   ky = ky + incy
end do
140 continue
end subroutine srotm

pure subroutine drotmg(dd1,dd2,dx1,dy1,dparam)
implicit none
!
