dh21 = -one
dh12 = one
dh22 = dx1/dy1
!
du = one + dh11*dh22
dtemp = dd2/du
dd2 = dd1/du
dd1 = dtemp
dx1 = dy1*du
!         Go scale-check
go to 100
!
!     Procedure..zero-H-D-and-dx1..
!
60 continue
dflag = -one
dh11 = zero
dh12 = zero
dh21 = zero
dh22 = zero
!
dd1 = zero
dd2 = zero
dx1 = zero
go to 250
!
!     Procedure..scale-check
!
100 continue
110 continue
if (dd1 > rgamsq) go to 130
if (dd1 == zero) go to 160
dflag = -one
dd1 = dd1*(gam*gam)
dx1 = dx1/gam
dh11 = dh11/gam
dh12 = dh12/gam
go to 110
!
130 continue
140 continue
if (dd1 < gamsq) go to 160
dflag = -one
dd1 = dd1/(gam*gam)
dx1 = dx1*gam
dh11 = dh11*gam
dh12 = dh12*gam
go to 140
!
160 continue
170 continue
if (abs(dd2) > rgamsq) go to 190
if (dd2 == zero) go to 220
dflag = -one
