dh21 = dh21/gam
dh22 = dh22/gam
go to 170
!
190 continue
200 continue
if (abs(dd2) < gamsq) go to 220
dflag = -one
dd2 = dd2/(gam*gam)
dh21 = dh21*gam
dh22 = dh22*gam
go to 200
!
220 continue
nswc_ai_r8 = dflag
if ( nswc_ai_r8 < 0 ) go to 250
if ( nswc_ai_r8 == 0 ) go to 230
go to 240
230 continue
dparam(3) = dh21
dparam(4) = dh12
go to 260
240 continue
dparam(2) = dh11
dparam(5) = dh22
go to 260
250 continue
dparam(2) = dh11
dparam(3) = dh21
dparam(4) = dh12
dparam(5) = dh22
260 continue
