pure real function sdot(n,sx,incx,sy,incy)
implicit none
!
!     Forms the dot product of two vectors.
!     Uses unrolled loops for increments equal to one.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sx(*), sy(*)
integer, intent(in) :: incx, incy
integer, intent(in) :: n
real :: stemp
integer :: i, ix, iy, m, mp1
!
stemp = 0.0e0
sdot = 0.0e0
if (n <= 0) return
if (incx == 1.and.incy == 1) go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if (incx < 0) ix = (-n + 1)*incx + 1
if (incy < 0) iy = (-n + 1)*incy + 1
do i = 1,n
   stemp = stemp + sx(ix)*sy(iy)
   ix = ix + incx
   iy = iy + incy
end do
sdot = stemp
return
!
!        Code for both increments equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,5)
if ( m == 0 ) go to 40
do i = 1,m
   stemp = stemp + sx(i)*sy(i)
end do
if ( n < 5 ) go to 60
40 mp1 = m + 1
do i = mp1,n,5
   stemp = stemp + sx(i)*sy(i) + sx(i + 1)*sy(i + 1) + &
      & sx(i + 2)*sy(i + 2) + sx(i + 3)*sy(i + 3) + sx(i + 4)*sy(i + 4)
end do
60 sdot = stemp
end function sdot

pure double precision function ddot(n,dx,incx,dy,incy)
implicit none
!
!     Forms the dot product of two vectors.
!     Uses unrolled loops for increments equal to one.
!     Jack dongarra, LINPACK, 3/11/78.
!
double precision, intent(in) :: dx(*), dy(*)
integer, intent(in) :: incx, incy
integer, intent(in) :: n
double precision :: dtemp
integer :: i, ix, iy, m, mp1
!
ddot = 0.0d0
dtemp = 0.0d0
if (n <= 0) return
if (incx == 1.and.incy == 1) go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if (incx < 0) ix = (-n + 1)*incx + 1
if (incy < 0) iy = (-n + 1)*incy + 1
do i = 1,n
   dtemp = dtemp + dx(ix)*dy(iy)
   ix = ix + incx
   iy = iy + incy
end do
ddot = dtemp
return
!
!        Code for both increments equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,5)
if ( m == 0 ) go to 40
do i = 1,m
   dtemp = dtemp + dx(i)*dy(i)
end do
if ( n < 5 ) go to 60
40 mp1 = m + 1
do i = mp1,n,5
   dtemp = dtemp + dx(i)*dy(i) + dx(i + 1)*dy(i + 1) + &
      & dx(i + 2)*dy(i + 2) + dx(i + 3)*dy(i + 3) + dx(i + 4)*dy(i + 4)
end do
60 ddot = dtemp
end function ddot

pure complex function cdotc(n,cx,incx,cy,incy)
implicit none
!
!     Forms the dot product of two vectors, conjugating the first
!     vector.
!     Jack dongarra, LINPACK,  3/11/78.
!
complex, intent(in) :: cx(*), cy(*)
integer, intent(in) :: incx, incy
integer, intent(in) :: n
complex :: ctemp
integer :: i, ix, iy
!
ctemp = (0.0,0.0)
cdotc = (0.0,0.0)
if (n <= 0) return
if (incx == 1.and.incy == 1) go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if (incx < 0) ix = (-n + 1)*incx + 1
if (incy < 0) iy = (-n + 1)*incy + 1
do i = 1,n
   ctemp = ctemp + conjg(cx(ix))*cy(iy)
   ix = ix + incx
   iy = iy + incy
end do
cdotc = ctemp
return
!
!        Code for both increments equal to 1
!
20 do i = 1,n
   ctemp = ctemp + conjg(cx(i))*cy(i)
end do
cdotc = ctemp
end function cdotc

