   ctemp = ctemp + cx(i)*cy(i)
end do
cdotu = ctemp
end function cdotu

pure subroutine  sscal(n,sa,sx,incx)
implicit none
!
!     Scales a vector BY a constant.
!     Uses unrolled loops for increment equal to 1.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sa
real, intent(inout) :: sx(*)
integer, intent(in) :: incx
integer, intent(in) :: n
integer :: i, m, mp1, nincx
!
if (n <= 0) return
if (incx == 1) go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
   sx(i) = sa*sx(i)
end do
return
!
!        Code for increment equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,5)
if ( m == 0 ) go to 40
do i = 1,m
   sx(i) = sa*sx(i)
end do
if ( n < 5 ) return
40 mp1 = m + 1
do i = mp1,n,5
   sx(i) = sa*sx(i)
   sx(i + 1) = sa*sx(i + 1)
   sx(i + 2) = sa*sx(i + 2)
   sx(i + 3) = sa*sx(i + 3)
   sx(i + 4) = sa*sx(i + 4)
end do
end subroutine sscal

pure subroutine  dscal(n,da,dx,incx)
implicit none
!
!     Scales a vector BY a constant.
!     Uses unrolled loops for increment equal to one.
!     Jack dongarra, LINPACK, 3/11/78.
!
double precision, intent(in) :: da
double precision, intent(inout) :: dx(*)
integer, intent(in) :: incx
integer, intent(in) :: n
integer :: i, m, mp1, nincx
!
if (n <= 0) return
if (incx == 1) go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
   dx(i) = da*dx(i)
end do
return
!
!        Code for increment equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,5)
if ( m == 0 ) go to 40
do i = 1,m
   dx(i) = da*dx(i)
end do
if ( n < 5 ) return
40 mp1 = m + 1
do i = mp1,n,5
   dx(i) = da*dx(i)
   dx(i + 1) = da*dx(i + 1)
   dx(i + 2) = da*dx(i + 2)
   dx(i + 3) = da*dx(i + 3)
   dx(i + 4) = da*dx(i + 4)
end do
end subroutine dscal

pure subroutine  cscal(n,ca,cx,incx)
implicit none
!
!     Scales a vector BY a constant.
!     Jack dongarra, LINPACK,  3/11/78.
!
complex, intent(in) :: ca
complex, intent(inout) :: cx(*)
integer, intent(in) :: incx, n
integer :: i, nincx
!
if (n <= 0) return
if (incx == 1) go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
   cx(i) = ca*cx(i)
end do
return
!
!        Code for increment equal to 1
!
20 do i = 1,n
   cx(i) = ca*cx(i)
end do
end subroutine cscal

pure subroutine  csscal(n,sa,cx,incx)
implicit none
!
!     Scales a complex vector BY a real constant.
!     Jack dongarra, LINPACK, 3/11/78.
!
complex, intent(inout) :: cx(*)
real, intent(in) :: sa
integer, intent(in) :: incx, n
integer :: i, nincx
!
if (n <= 0) return
if (incx == 1) go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
   cx(i) = cmplx(sa*real(cx(i)),sa*aimag(cx(i)))
end do
return
!
!        Code for increment equal to 1
!
20 do i = 1,n
   cx(i) = cmplx(sa*real(cx(i)),sa*aimag(cx(i)))
end do
end subroutine csscal

pure subroutine saxpy(n,sa,sx,incx,sy,incy)
implicit none
!
!     Constant times a vector plus a vector.
!     Uses unrolled loop for increments equal to one.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sx(*)
real, intent(inout) :: sy(*)
real, intent(in) :: sa
integer, intent(in) :: incx, incy
integer, intent(in) :: n
integer :: i, ix, iy, m, mp1
!
if (n <= 0) return
if (sa == 0.0) return
if (incx == 1.and.incy == 1) go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if (incx < 0) ix = (-n + 1)*incx + 1
if (incy < 0) iy = (-n + 1)*incy + 1
do i = 1,n
   sy(iy) = sy(iy) + sa*sx(ix)
   ix = ix + incx
   iy = iy + incy
end do
return
!
!        Code for both increments equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,4)
if ( m == 0 ) go to 40
do i = 1,m
   sy(i) = sy(i) + sa*sx(i)
end do
if ( n < 4 ) return
40 mp1 = m + 1
do i = mp1,n,4
   sy(i) = sy(i) + sa*sx(i)
   sy(i + 1) = sy(i + 1) + sa*sx(i + 1)
   sy(i + 2) = sy(i + 2) + sa*sx(i + 2)
   sy(i + 3) = sy(i + 3) + sa*sx(i + 3)
end do
end subroutine saxpy

pure subroutine daxpy(n,da,dx,incx,dy,incy)
implicit none
!
!     Constant times a vector plus a vector.
!     Uses unrolled loops for increments equal to one.
!     Jack dongarra, LINPACK, 3/11/78.
!
double precision, intent(in) :: dx(*)
double precision, intent(inout) :: dy(*)
double precision, intent(in) :: da
integer, intent(in) :: incx, incy
integer, intent(in) :: n
integer :: i, ix, iy, m, mp1
!
if (n <= 0) return
if (da == 0.0d0) return
if (incx == 1.and.incy == 1) go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if (incx < 0) ix = (-n + 1)*incx + 1
if (incy < 0) iy = (-n + 1)*incy + 1
do i = 1,n
   dy(iy) = dy(iy) + da*dx(ix)
   ix = ix + incx
   iy = iy + incy
end do
return
!
!        Code for both increments equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,4)
if ( m == 0 ) go to 40
do i = 1,m
   dy(i) = dy(i) + da*dx(i)
end do
if ( n < 4 ) return
40 mp1 = m + 1
do i = mp1,n,4
   dy(i) = dy(i) + da*dx(i)
   dy(i + 1) = dy(i + 1) + da*dx(i + 1)
   dy(i + 2) = dy(i + 2) + da*dx(i + 2)
   dy(i + 3) = dy(i + 3) + da*dx(i + 3)
end do
end subroutine daxpy

pure subroutine caxpy(n,ca,cx,incx,cy,incy)
implicit none
!
!     Constant times a vector plus a vector.
!     Jack dongarra, LINPACK, 3/11/78.
!
complex, intent(in) :: cx(*)
complex, intent(inout) :: cy(*)
complex, intent(in) :: ca
integer, intent(in) :: incx, incy
integer, intent(in) :: n
integer :: i, ix, iy
!
if (n <= 0) return
if (abs(real(ca)) + abs(aimag(ca)) == 0.0 ) return
if (incx == 1.and.incy == 1) go to 20
!
!        Code for unequal increments or equal increments
!          not equal to 1
!
ix = 1
iy = 1
if (incx < 0) ix = (-n + 1)*incx + 1
if (incy < 0) iy = (-n + 1)*incy + 1
do i = 1,n
   cy(iy) = cy(iy) + ca*cx(ix)
   ix = ix + incx
   iy = iy + incy
end do
return
!
!        Code for both increments equal to 1
!
20 do i = 1,n
   cy(i) = cy(i) + ca*cx(i)
end do
end subroutine caxpy

pure real function sasum(n,sx,incx)
implicit none
!
!     Takes the sum of the absolute values.
!     Uses unrolled loops for increment equal to one.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sx(*)
integer, intent(in) :: incx
integer, intent(in) :: n
real :: stemp
integer :: i, m, mp1, nincx
!
sasum = 0.0e0
stemp = 0.0e0
if (n <= 0) return
if (incx == 1) go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
   stemp = stemp + abs(sx(i))
end do
sasum = stemp
return
!
!        Code for increment equal to 1
!
!
!        Clean-up loop
!
20 m = mod(n,6)
if ( m == 0 ) go to 40
do i = 1,m
   stemp = stemp + abs(sx(i))
end do
if ( n < 6 ) go to 60
40 mp1 = m + 1
do i = mp1,n,6
   stemp = stemp + abs(sx(i)) + abs(sx(i + 1)) + abs(sx(i + 2)) &
      & + abs(sx(i + 3)) + abs(sx(i + 4)) + abs(sx(i + 5))
end do
60 sasum = stemp
end function sasum

