!
!
!        Clean-up loop
!
20 m = mod(n,6)
if ( m == 0 ) go to 40
do i = 1,m
   dtemp = dtemp + abs(dx(i))
end do
if ( n < 6 ) go to 60
40 mp1 = m + 1
do i = mp1,n,6
   dtemp = dtemp + abs(dx(i)) + abs(dx(i + 1)) + abs(dx(i + 2)) &
      & + abs(dx(i + 3)) + abs(dx(i + 4)) + abs(dx(i + 5))
end do
60 dasum = dtemp
