pure real function scasum(n,cx,incx)
implicit none
!
!     Takes the sum of the absolute values of a complex vector and
!     returns a single precision result.
!     Jack dongarra, LINPACK, 3/11/78.
!
complex, intent(in) :: cx(*)
integer, intent(in) :: incx, n
real :: stemp
integer :: i, nincx
!
scasum = 0.0e0
stemp = 0.0e0
if (n <= 0) return
if (incx == 1) go to 20
!
!        Code for increment not equal to 1
!
nincx = n*incx
do i = 1,nincx,incx
   stemp = stemp + abs(real(cx(i))) + abs(aimag(cx(i)))
end do
scasum = stemp
return
!
!        Code for increment equal to 1
!
20 do i = 1,n
   stemp = stemp + abs(real(cx(i))) + abs(aimag(cx(i)))
end do
scasum = stemp
end function scasum

pure real function snrm2( n, sx, incx)
implicit none
integer, intent(in) :: incx, n
real, intent(in) :: sx(*)
integer :: i, j, nn, next
real :: hitest, sum, xmax
real, parameter :: zero = 0.0e0
real, parameter :: one = 1.0e0
real, parameter :: cutlo = 4.441e-16
real, parameter :: cuthi = 1.304e19
!
!     Euclidean norm of the n-vector stored in sx() with storage
!     increment incx .
!     If    n .LE. 0 return with result = 0.
!     If n .GE. 1 then incx must be .GE. 1
!
!           C.L.Lawson, 1978 jan 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     hopefully applicable to all machines.
!         cutlo = Maximum of  sqrt(U/EPS)  over all known machines.
!         cuthi = Minimum of  sqrt(V)      over all known machines.
!     Where
!         eps = Smallest no. such that eps + 1. .GT. 1.
!         U   = Smallest positive no.   (underflow limit)
!         V   = Largest  no.            (overflow  limit)
!
!     Brief outline of algorithm..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     Move to phase 2 when a component is nonzero and .LE. cutlo
!     move to phase 3 when a component is .GT. cutlo
!     move to phase 4 when a component is .GE. cuthi/M
!     where M = n for X() real and M = 2*n for complex.
!
!     Values for cutlo and cuthi..
!     From the environmental parameters listed in the IMSL converter
!     document the limiting values are as follows..
!     cutlo, S.P.   U/eps = 2**(-102) for  Honeywell.  Close seconds are
!                   Univac and DEC at 2**(-103)
!                   THUS cutlo = 2**(-51) = 4.44089E-16
!     cuthi, S.P.   V = 2**127 for Univac, Honeywell, and DEC.
!                   THUS cuthi = 2**(63.5) = 1.30438E19
!     cutlo, D.P.   U/eps = 2**(-67) for Honeywell and DEC.
!                   THUS cutlo = 2**(-33.5) = 8.23181D-11
!     cuthi, D.P.   SAME AS S.P.  cuthi = 1.30438D19
!     DATA cutlo, cuthi / 8.232D-11,  1.304D19 /
!     DATA cutlo, cuthi / 4.441E-16,  1.304E19 /
!
if (n > 0) go to 10
snrm2 = zero
go to 300
!
10 next = 30
sum = zero
nn = n * incx
!                                                 Begin main loop
i = 1
20 select case ( next )
case ( 30 )
   go to 30
case ( 50 )
   go to 50
case ( 70 )
   go to 70
case ( 110 )
   go to 110
end select
30 if ( abs(sx(i)) > cutlo) go to 85
next = 50
xmax = zero
!
!                        Phase 1.  Sum is zero
!
50 if ( sx(i) == zero) go to 200
if ( abs(sx(i)) > cutlo) go to 85
!
!                                Prepare for phase 2.
next = 70
go to 105
!
!                                Prepare for phase 4.
!
100 i = j
next = 110
sum = (sum / sx(i)) / sx(i)
105 xmax = abs(sx(i))
go to 115
!
!                   Phase 2.  Sum is small.
!                             Scale to avoid destructive underflow.
!
70 if ( abs(sx(i)) > cutlo ) go to 75
!
!                     Common code for phases 2 and 4.
!                     In phase 4 sum is large.  Scale to avoid overflow.
!
110 if ( abs(sx(i)) <= xmax ) go to 115
sum = one + sum * (xmax / sx(i))**2
xmax = abs(sx(i))
go to 200
!
115 sum = sum + (sx(i)/xmax)**2
go to 200
!
!
!                  Prepare for phase 3.
!
75 sum = (sum * xmax) * xmax
!
!
!     For real or D.P. set hitest = cuthi/n
!     for complex      set hitest = cuthi/(2*n)
!
85 hitest = cuthi/float( n )
!
!                   Phase 3.  Sum is mid-range.  No scaling.
!
do j = i,nn,incx
   if (abs(sx(j)) >= hitest) go to 100
95 sum = sum + sx(j)**2
end do
snrm2 = sqrt( sum )
go to 300
!
200 continue
i = i + incx
if ( i <= nn ) go to 20
!
!              END OF MAIN LOOP.
!
!              Compute square root and adjust for scaling.
!
snrm2 = xmax * sqrt(sum)
300 continue
end function snrm2

pure double precision function dnrm2( n, dx, incx)
implicit none
integer, intent(in) :: incx, n
double precision, intent(in) :: dx(*)
integer :: i, j, nn, next
double precision :: hitest, sum, xmax
double precision, parameter :: zero = 0.0d0
double precision, parameter :: one = 1.0d0
double precision, parameter :: cutlo = 8.232d-11
double precision, parameter :: cuthi = 1.304d19
!
!     Euclidean norm of the n-vector stored in dx() with storage
!     increment incx .
!     If    n .LE. 0 return with result = 0.
!     If n .GE. 1 then incx must be .GE. 1
!
!           C.L.Lawson, 1978 jan 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     hopefully applicable to all machines.
!         cutlo = Maximum of  dsqrt(U/EPS)  over all known machines.
!         cuthi = Minimum of  dsqrt(V)      over all known machines.
!     Where
!         eps = Smallest no. such that eps + 1. .GT. 1.
!         U   = Smallest positive no.   (underflow limit)
!         V   = Largest  no.            (overflow  limit)
!
!     Brief outline of algorithm..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     Move to phase 2 when a component is nonzero and .LE. cutlo
!     move to phase 3 when a component is .GT. cutlo
!     move to phase 4 when a component is .GE. cuthi/M
!     where M = n for X() real and M = 2*n for complex.
!
!     Values for cutlo and cuthi..
!     From the environmental parameters listed in the IMSL converter
!     document the limiting values are as follows..
!     cutlo, S.P.   U/eps = 2**(-102) for  Honeywell.  Close seconds are
!                   Univac and DEC at 2**(-103)
!                   THUS cutlo = 2**(-51) = 4.44089E-16
!     cuthi, S.P.   V = 2**127 for Univac, Honeywell, and DEC.
!                   THUS cuthi = 2**(63.5) = 1.30438E19
!     cutlo, D.P.   U/eps = 2**(-67) for Honeywell and DEC.
!                   THUS cutlo = 2**(-33.5) = 8.23181D-11
!     cuthi, D.P.   SAME AS S.P.  cuthi = 1.30438D19
!     DATA cutlo, cuthi / 8.232D-11,  1.304D19 /
!     DATA cutlo, cuthi / 4.441E-16,  1.304E19 /
!
if (n > 0) go to 10
dnrm2 = zero
go to 300
!
10 next = 30
sum = zero
nn = n * incx
!                                                 Begin main loop
i = 1
20 select case ( next )
case ( 30 )
   go to 30
case ( 50 )
   go to 50
case ( 70 )
   go to 70
case ( 110 )
   go to 110
end select
30 if ( abs(dx(i)) > cutlo) go to 85
next = 50
xmax = zero
!
!                        Phase 1.  Sum is zero
!
50 if ( dx(i) == zero) go to 200
if ( abs(dx(i)) > cutlo) go to 85
!
!                                Prepare for phase 2.
next = 70
go to 105
!
!                                Prepare for phase 4.
!
100 i = j
next = 110
sum = (sum / dx(i)) / dx(i)
105 xmax = abs(dx(i))
go to 115
!
!                   Phase 2.  Sum is small.
!                             Scale to avoid destructive underflow.
!
70 if ( abs(dx(i)) > cutlo ) go to 75
!
!                     Common code for phases 2 and 4.
!                     In phase 4 sum is large.  Scale to avoid overflow.
!
110 if ( abs(dx(i)) <= xmax ) go to 115
sum = one + sum * (xmax / dx(i))**2
xmax = abs(dx(i))
go to 200
!
115 sum = sum + (dx(i)/xmax)**2
go to 200
!
!
!                  Prepare for phase 3.
!
75 sum = (sum * xmax) * xmax
!
!
!     For real or D.P. set hitest = cuthi/n
!     for complex      set hitest = cuthi/(2*n)
!
85 hitest = cuthi/float( n )
!
!                   Phase 3.  Sum is mid-range.  No scaling.
!
do j = i,nn,incx
   if (abs(dx(j)) >= hitest) go to 100
95 sum = sum + dx(j)**2
end do
dnrm2 = sqrt( sum )
go to 300
!
200 continue
i = i + incx
if ( i <= nn ) go to 20
!
!              END OF MAIN LOOP.
!
!              Compute square root and adjust for scaling.
!
dnrm2 = xmax * sqrt(sum)
300 continue
end function dnrm2

pure real function scnrm2( n, cx, incx)
implicit none
integer, intent(in) :: incx, n
complex, intent(in) :: cx(*)
integer :: i, nn, next
logical :: imag, scale
real :: hitest, sum, xmax, absx
real, parameter :: zero = 0.0e0
real, parameter :: one = 1.0e0
real, parameter :: cutlo = 4.441e-16
real, parameter :: cuthi = 1.304e19
!
!     Unitary norm of the complex n-vector stored in cx() with storage
!     increment incx .
!     If    n .LE. 0 return with result = 0.
!     If n .GE. 1 then incx must be .GE. 1
!
!           C.L.Lawson , 1978 jan 08
!
!     FOUR PHASE METHOD     USING TWO BUILT-IN CONSTANTS THAT ARE
!     hopefully applicable to all machines.
!         cutlo = Maximum of  sqrt(U/EPS)  over all known machines.
!         cuthi = Minimum of  sqrt(V)      over all known machines.
!     Where
!         eps = Smallest no. such that eps + 1. .GT. 1.
!         U   = Smallest positive no.   (underflow limit)
!         V   = Largest  no.            (overflow  limit)
!
!     Brief outline of algorithm..
!
!     PHASE 1    SCANS ZERO COMPONENTS.
!     Move to phase 2 when a component is nonzero and .LE. cutlo
!     move to phase 3 when a component is .GT. cutlo
!     move to phase 4 when a component is .GE. cuthi/M
!     where M = n for X() real and M = 2*n for complex.
!
!     Values for cutlo and cuthi..
!     From the environmental parameters listed in the IMSL converter
!     document the limiting values are as follows..
!     cutlo, S.P.   U/eps = 2**(-102) for  Honeywell.  Close seconds are
!                   Univac and DEC at 2**(-103)
!                   THUS cutlo = 2**(-51) = 4.44089E-16
!     cuthi, S.P.   V = 2**127 for Univac, Honeywell, and DEC.
!                   THUS cuthi = 2**(63.5) = 1.30438E19
!     cutlo, D.P.   U/eps = 2**(-67) for Honeywell and DEC.
!                   THUS cutlo = 2**(-33.5) = 8.23181D-11
!     cuthi, D.P.   SAME AS S.P.  cuthi = 1.30438D19
!     DATA cutlo, cuthi / 8.232D-11,  1.304D19 /
!     DATA cutlo, cuthi / 4.441E-16,  1.304E19 /
!
if (n > 0) go to 10
scnrm2 = zero
go to 300
!
10 next = 30
sum = zero
nn = n * incx
!                                                 Begin main loop
do i = 1,nn,incx
   absx = abs(real(cx(i)))
   imag = .false.
   select case ( next )
   case ( 30 )
      go to 30
   case ( 50 )
      go to 50
   case ( 70 )
      go to 70
   case ( 90 )
      go to 90
   case ( 110 )
      go to 110
   end select
30 if ( absx > cutlo) go to 85
   next = 50
   scale = .false.
!
!                        Phase 1.  Sum is zero
!
50 if ( absx == zero) go to 200
   if ( absx > cutlo) go to 85
!
!                                Prepare for phase 2.
   next = 70
   go to 105
!
!                                Prepare for phase 4.
!
100 next = 110
   sum = (sum / absx) / absx
105 scale = .true.
   xmax = absx
   go to 115
!
!                   Phase 2.  Sum is small.
!                             Scale to avoid destructive underflow.
!
70 if ( absx > cutlo ) go to 75
!
!                     Common code for phases 2 and 4.
!                     In phase 4 sum is large.  Scale to avoid overflow.
!
110 if ( absx <= xmax ) go to 115
   sum = one + sum * (xmax / absx)**2
   xmax = absx
   go to 200
!
115 sum = sum + (absx/xmax)**2
   go to 200
!
!
!                  Prepare for phase 3.
!
75 sum = (sum * xmax) * xmax
!
85 next = 90
   scale = .false.
!
!     For real or D.P. set hitest = cuthi/n
!     for complex      set hitest = cuthi/(2*n)
!
   hitest = cuthi/float( n )
   hitest = hitest * 0.5
!
!                   Phase 3.  Sum is mid-range.  No scaling.
!
90 if (absx >= hitest) go to 100
   sum = sum + absx**2
200 continue
!                  Control selection of real and imaginary parts.
!
   if (imag) go to 210
   absx = abs(aimag(cx(i)))
   imag = .true.
   select case ( next )
   case ( 50 )
      go to 50
   case ( 70 )
      go to 70
   case ( 90 )
      go to 90
   case ( 110 )
      go to 110
   end select
!
210 continue
end do
!
!              END OF MAIN LOOP.
!              Compute square root and adjust for scaling.
!
scnrm2 = sqrt(sum)
if (scale) scnrm2 = scnrm2 * xmax
300 continue
end function scnrm2

pure integer function isamax(n,sx,incx)
implicit none
!
!     Finds the index of element having max. Absolute value.
!     Jack dongarra, LINPACK, 3/11/78.
!
real, intent(in) :: sx(*)
integer, intent(in) :: incx
integer, intent(in) :: n
real :: smax
integer :: i, ix
!
isamax = 0
if ( n < 1 ) return
isamax = 1
if (n == 1) return
if (incx == 1) go to 20
!
