real, intent(inout) :: a(ka,n)
real, intent(in) :: b(*)
integer :: i, ii, im1, j, jj, l
!
a(1,1) = b(1)
if (n < 2) return
l = (n*(n + 1))/2
!
j = n
do jj = 2,n
   i = j
   do ii = 1,j
      a(i,j) = b(l)
      i = i - 1
10    l = l - 1
   end do
11 j = j - 1
end do
!
do i = 2,n
   im1 = i - 1
   do j = 1,im1
20    a(i,j) = a(j,i)
   end do
end do
end subroutine mcvsf

