      real, intent(inout) :: h(n)
      real, intent(inout) :: w(n)
      real, intent(inout) :: eb(n)
      integer, intent(inout) :: ic(n)
      integer, intent(inout) :: ir(m)
   end subroutine u11ls
   pure subroutine u11us(a,mda,m,n,ub,db,mode,np,krank,ksure,h,w,eb, &
      & ir,ic)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: m
      integer, intent(in) :: mda
      real, intent(inout) :: a(mda,n)
      real, intent(inout) :: ub(m)
      real, intent(inout) :: db(m)
      integer, intent(in) :: mode
      integer, intent(in) :: np
      integer, intent(out) :: krank
      integer, intent(inout) :: ksure
      real, intent(inout) :: h(m)
      real, intent(inout) :: w(m)
      real, intent(inout) :: eb(m)
      integer, intent(inout) :: ir(m)
      integer, intent(inout) :: ic(n)
   end subroutine u11us
end interface
!-----------------------------------------------------------------------
!
!          Upper and lower bounds of the rank of a real matrix
!
!-----------------------------------------------------------------------
!     real work(5*m0)  where m0 = 5*min0(m,n)
!     integer iwork(m + n)
!--------------------
!
m0 = min(m,n)
!
!     Define the relative and absolute tolerance lists
!
m1 = 1
m2 = m1 + m0
m3 = m2 + m0
m4 = m3 + m0
m5 = m4 + m0
!
eps = 10.0*spmpar(1)
rerr = max(eps,re)
!
imax = m5 - 1
do i = m4,imax
   work(i) = rerr
end do
imax = imax + m0
do i = m5,imax
   work(i) = ae
end do
!
!     Factor the matrix a
!
if (m < n) go to 40
!
call u11ls(a,mda,m,n,work(m4),work(m5),1,0,krank,ksure, &
   & work(m1),work(m2),work(m3),iwork(m1),iwork(m2))
return
!
40 call u11us(a,mda,m,n,work(m4),work(m5),1,0,krank,ksure, &
   & work(m1),work(m2),work(m3),iwork(m1),iwork(m2))
end subroutine rnk

pure subroutine drnk(a, mda, m, n, re, ae, krank, ksure, work, iwork)
implicit none
integer, intent(inout) :: krank, ksure
integer, intent(in) :: m, mda, n
double precision, intent(inout) :: a(mda,n)
double precision, intent(in) :: re, ae
double precision, intent(inout) :: work(*)
integer, intent(inout) :: iwork(*)
integer :: i, imax, m0, m1, m2, m3, m4, m5
double precision :: eps, rerr
interface
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
   pure subroutine du11ls(a,mda,m,n,ub,db,mode,np,krank,ksure,h,w,eb &
      & ,ic,ir)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: m
      integer, intent(in) :: mda
      double precision, intent(inout) :: a(mda,n)
      double precision, intent(inout) :: ub(n)
      double precision, intent(inout) :: db(n)
      integer, intent(in) :: mode
      integer, intent(in) :: np
      integer, intent(out) :: krank
      integer, intent(inout) :: ksure
      double precision, intent(inout) :: h(n)
      double precision, intent(inout) :: w(n)
      double precision, intent(inout) :: eb(n)
      integer, intent(inout) :: ic(n)
      integer, intent(inout) :: ir(m)
   end subroutine du11ls
   pure subroutine du11us(a,mda,m,n,ub,db,mode,np,krank,ksure,h,w,eb &
      & ,ir,ic)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: m
      integer, intent(in) :: mda
      double precision, intent(inout) :: a(mda,n)
      double precision, intent(inout) :: ub(m)
      double precision, intent(inout) :: db(m)
      integer, intent(in) :: mode
      integer, intent(in) :: np
      integer, intent(out) :: krank
      integer, intent(inout) :: ksure
      double precision, intent(inout) :: h(m)
      double precision, intent(inout) :: w(m)
      double precision, intent(inout) :: eb(m)
      integer, intent(inout) :: ir(m)
      integer, intent(inout) :: ic(n)
   end subroutine du11us
end interface
!-----------------------------------------------------------------------
!
!              Upper and lower bounds of the rank of A
!                      double precision matrix
!
!-----------------------------------------------------------------------
!     double precision work(5*m0)  where m0 = 5*min0(m,n)
!     integer iwork(m + n)
!--------------------
!
m0 = min(m,n)
!
!     Define the relative and absolute tolerance lists
!
m1 = 1
m2 = m1 + m0
m3 = m2 + m0
m4 = m3 + m0
m5 = m4 + m0
!
eps = 10.d0*dpmpar(1)
rerr = max(eps,re)
!
imax = m5 - 1
do i = m4,imax
   work(i) = rerr
end do
imax = imax + m0
do i = m5,imax
   work(i) = ae
end do
!
!     Factor the matrix a
!
if (m < n) go to 40
!
call du11ls(a,mda,m,n,work(m4),work(m5),1,0,krank,ksure, &
   & work(m1),work(m2),work(m3),iwork(m1),iwork(m2))
return
!
40 call du11us(a,mda,m,n,work(m4),work(m5),1,0,krank,ksure, &
   & work(m1),work(m2),work(m3),iwork(m1),iwork(m2))
end subroutine drnk

pure subroutine crout(mo,n,m,a,ka,b,kb,d,index,temp)
implicit none
integer, intent(inout) :: index(*)
integer, intent(in) :: ka, kb, m, mo, n
real, intent(inout) :: a(ka,n), b(*), d, temp(*)
integer :: i, im1, j, jp1, k, kj, km1, kp1, l, lj, maxb, nj, nm1, nmj, nmk, onej
real :: p, t
double precision :: dsum
!-----------------------------------------------------------------------
!     crout procedure for inverting matrices and solving equations
!-----------------------------------------------------------------------
!     A is a matrix of order n where n is greater than or equal to 1.
!     If mo=0 Then the inverse of A is computed and stored in A. if mo
!     is not 0 then the inverse is not computed.
!
!     If m is greater than 0 then b is a matrix having n rows and m
!     columns. In this case AX=b is solved and the solution X is stored
!     in b. if m=0 Then there are no equations to be solved.
!
!     ka = The length of the columns of the array a
!     kb = The length of the columns of the array b (if m.GT.0)
!
!     The determinant d of A is always computed. If d=0 Then the
!     routine immediately terminates.
!
!     Index is an array of dimension n-1 or larger that is used by the
!     routine for keeping track of the row interchanges that are made.
!     If mo is not 0 then this array is not needed.
!
!     Temp is an array of dimension n or larger that is used when A
!     is inverted. If mo is not 0 then this array is not needed.
!-----------------------------------------------------------------------
!
if (n < 2) go to 200
d = 1.0
nm1 = n - 1
do k = 1,nm1
   kp1 = k + 1
!
!               Search for the k-TH pivot element
!
   p = abs(a(k,k))
   l = k
   do i = kp1,n
      t = abs(a(i,k))
      if (p >= t) go to 10
      p = t
      l = i
10    continue
   end do
!
   p = a(l,k)
   d = p*d
   if (d == 0.0) return
   if (mo == 0) index(k) = l
   if (k == l) go to 40
   d = -d
!
!                  Interchanging rows k and l
!
   do j = 1,n
      t = a(k,j)
      a(k,j) = a(l,j)
20    a(l,j) = t
   end do
!
   if (m <= 0) go to 40
   kj = k
   lj = l
   do j = 1,m
      t = b(kj)
      b(kj) = b(lj)
      b(lj) = t
      kj = kj + kb
30    lj = lj + kb
   end do
!
!                  Compute the k-TH row of U
!
40 if (k > 1) go to 50
   do j = kp1,n
41    a(k,j) = a(k,j)/p
   end do
   go to 60
!
50 do j = kp1,n
      dsum = a(k,j)
      do l = 1,km1
51       dsum = dsum - dble(a(k,l))*dble(a(l,j))
      end do
      a(k,j) = sngl(dsum)/p
   end do
!
!               Compute the (k+1)-ST column of l
!
60 do i = kp1,n
      dsum = a(i,kp1)
      do l = 1,k
61       dsum = dsum - dble(a(i,l))*dble(a(l,kp1))
      end do
      a(i,kp1) = dsum
   end do
!
   km1 = k
end do
!
!                 Check the n-TH pivot element
!
d = a(n,n)*d
if (d == 0.0) return
!
!                 Solving the equation LY = b
!
if (m <= 0) go to 120
maxb = kb*m
do onej = 1,maxb,kb
   kj = onej
   b(kj) = b(kj)/a(1,1)
   do k = 2,n
      kj = kj + 1
      dsum = b(kj)
      km1 = k - 1
      lj = onej
      do l = 1,km1
         dsum = dsum - dble(a(k,l))*dble(b(lj))
100      lj = lj + 1
      end do
101   b(kj) = sngl(dsum)/a(k,k)
   end do
end do
!
!                 Solving the equation UX = Y
!
do nj = n,maxb,kb
   kj = nj
   do nmk = 1,nm1
      k = n - nmk
      lj = kj
      kj = kj - 1
      dsum = b(kj)
      kp1 = k + 1
      do l = kp1,n
         dsum = dsum - dble(a(k,l))*dble(b(lj))
110      lj = lj + 1
      end do
      b(kj) = dsum
   end do
end do
!
!               Replace l with the inverse of l
!
120 if (mo /= 0) return
do j = 1,nm1
   a(j,j) = 1.0/a(j,j)
   jp1 = j + 1
   do i = jp1,n
      dsum = 0.d0
      im1 = i - 1
      do l = j,im1
130      dsum = dsum + dble(a(i,l))*dble(a(l,j))
      end do
131   a(i,j) = -sngl(dsum)/a(i,i)
   end do
end do
a(n,n) = 1.0/a(n,n)
!
!           Solve UX = Y where Y is the inverse of l
!
do nmk = 1,nm1
   k = n - nmk
   kp1 = k + 1
   do j = kp1,n
      temp(j) = a(k,j)
140   a(k,j) = 0.0
   end do
!
   do j = 1,n
      dsum = a(k,j)
      do l = kp1,n
150      dsum = dsum - dble(temp(l))*dble(a(l,j))
      end do
      a(k,j) = dsum
   end do
end do
!
!                    Column interchanges
!
do nmj = 1,nm1
   j = n - nmj
   k = index(j)
   if (j == k) go to 161
   do i = 1,n
      t = a(i,j)
      a(i,j) = a(i,k)
160   a(i,k) = t
   end do
161 continue
end do
return
!
!                      Case when n = 1
!
200 d = a(1,1)
if (d == 0.0) return
if (mo == 0) a(1,1) = 1.0/d
!
if (m <= 0) return
maxb = kb*m
do kj = 1,maxb,kb
210 b(kj) = b(kj)/d
end do
end subroutine crout

pure subroutine krout(mo,n,m,a,ka,b,kb,ierr,index,temp)
implicit none
integer, intent(inout) :: ierr, index(*)
integer, intent(in) :: ka, kb, m, mo, n
real, intent(inout) :: a(ka,n), b(*), temp(*)
integer :: i, im1, j, jp1, k, kj, km1, kp1, l, lj, maxb, nj, nm1, nmj, nmk, onej
real :: d, p, t
double precision :: dsum
!-----------------------------------------------------------------------
!     crout procedure for inverting matrices and solving equations
!-----------------------------------------------------------------------
!     A is a matrix of order n where n is greater than or equal to 1.
!     If mo=0 Then the inverse of A is computed and stored in A. if mo
!     is not 0 then the inverse is not computed.
!
!     If m is greater than 0 then b is a matrix having n rows and m
!     columns. In this case AX=b is solved and the solution X is stored
!     in b. if m=0 Then there are no equations to be solved.
!
!     ka = The length of the columns of the array a
!     kb = The length of the columns of the array b (if m.GT.0)
!
!     ierr is a variable that reports the status of the results. When
!     the routine terminates ierr has one of the following values ...
!        ierr =  0   The requested task was performed.
!        ierr = -1   Either n, ka, or kb is incorrect.
!        ierr =  k   the k-TH pivot element is 0.
!
!     Index is an array of dimension n-1 or larger that is used by the
!     routine for keeping track of the row interchanges that are made.
!     If mo is not 0 then this array is not needed.
!
!     Temp is an array of dimension n or larger that is used when A
!     is inverted. If mo is not 0 then this array is not needed.
!-----------------------------------------------------------------------
!
if (n < 1 .or. ka < n) go to 320
if (m <= 0) go to 5
if (kb < n) go to 320
!
5 ierr = 0
if (n < 2) go to 200
nm1 = n - 1
do k = 1,nm1
   kp1 = k + 1
!
!               Search for the k-TH pivot element
!
   p = abs(a(k,k))
   l = k
   do i = kp1,n
      t = abs(a(i,k))
      if (p >= t) go to 10
      p = t
      l = i
10    continue
   end do
   if (p == 0.0) go to 300
!
   p = a(l,k)
   if (mo == 0) index(k) = l
   if (k == l) go to 40
!
!                  Interchanging rows k and l
!
   do j = 1,n
      t = a(k,j)
      a(k,j) = a(l,j)
20    a(l,j) = t
   end do
!
   if (m <= 0) go to 40
   kj = k
   lj = l
   do j = 1,m
      t = b(kj)
      b(kj) = b(lj)
      b(lj) = t
      kj = kj + kb
30    lj = lj + kb
   end do
!
!                  Compute the k-TH row of U
!
40 if (k > 1) go to 50
   do j = kp1,n
41    a(k,j) = a(k,j)/p
   end do
   go to 60
!
50 do j = kp1,n
      dsum = a(k,j)
      do l = 1,km1
51       dsum = dsum - dble(a(k,l))*dble(a(l,j))
      end do
      a(k,j) = sngl(dsum)/p
   end do
!
!               Compute the (k+1)-ST column of l
!
60 do i = kp1,n
      dsum = a(i,kp1)
      do l = 1,k
61       dsum = dsum - dble(a(i,l))*dble(a(l,kp1))
      end do
      a(i,kp1) = dsum
   end do
!
   km1 = k
end do
!
!                 Check the n-TH pivot element
!
if (a(n,n) == 0.0) go to 310
!
!                 Solving the equation LY = b
!
if (m <= 0) go to 120
maxb = kb*m
do onej = 1,maxb,kb
   kj = onej
   b(kj) = b(kj)/a(1,1)
   do k = 2,n
      kj = kj + 1
      dsum = b(kj)
      km1 = k - 1
      lj = onej
      do l = 1,km1
         dsum = dsum - dble(a(k,l))*dble(b(lj))
100      lj = lj + 1
      end do
101   b(kj) = sngl(dsum)/a(k,k)
   end do
end do
!
!                 Solving the equation UX = Y
!
do nj = n,maxb,kb
   kj = nj
   do nmk = 1,nm1
      k = n - nmk
      lj = kj
      kj = kj - 1
      dsum = b(kj)
      kp1 = k + 1
      do l = kp1,n
         dsum = dsum - dble(a(k,l))*dble(b(lj))
110      lj = lj + 1
      end do
      b(kj) = dsum
   end do
end do
!
!               Replace l with the inverse of l
!
120 if (mo /= 0) return
do j = 1,nm1
   a(j,j) = 1.0/a(j,j)
   jp1 = j + 1
   do i = jp1,n
      dsum = 0.d0
      im1 = i - 1
      do l = j,im1
130      dsum = dsum + dble(a(i,l))*dble(a(l,j))
      end do
131   a(i,j) = -sngl(dsum)/a(i,i)
   end do
end do
a(n,n) = 1.0/a(n,n)
!
!           Solve UX = Y where Y is the inverse of l
!
do nmk = 1,nm1
   k = n - nmk
   kp1 = k + 1
   do j = kp1,n
      temp(j) = a(k,j)
140   a(k,j) = 0.0
   end do
!
   do j = 1,n
      dsum = a(k,j)
      do l = kp1,n
150      dsum = dsum - dble(temp(l))*dble(a(l,j))
      end do
      a(k,j) = dsum
   end do
end do
!
!                    Column interchanges
!
do nmj = 1,nm1
   j = n - nmj
   k = index(j)
   if (j == k) go to 161
   do i = 1,n
      t = a(i,j)
      a(i,j) = a(i,k)
160   a(i,k) = t
   end do
161 continue
end do
return
!
!                      Case when n = 1
!
200 d = a(1,1)
if (d == 0.0) go to 310
if (mo == 0) a(1,1) = 1.0/d
!
if (m <= 0) return
maxb = kb*m
do kj = 1,maxb,kb
210 b(kj) = b(kj)/d
end do
return
!
!                  k-TH pivot element is 0
!
300 ierr = k
return
310 ierr = n
return
!
!                        Input error
!
320 ierr = -1
end subroutine krout

pure subroutine dec(n, ndim, a, ip, ier)
implicit none
!-----------------------------------------------------------------------
! Matrix triangularization by Gaussian elimination.
! Input..
!    n = Order of matrix.
!    ndim = Declared dimension of array  a .
!    a = Matrix to be triangularized.
! Output..
!    a(i,j), i.LE.j = Upper triangular factor, U .
!    a(i,j), i.GT.j = Multipliers = Lower triangular factor, i - L.
!    ip(k), k.LT.n = Index of k-TH pivot row.
!    ip(n) = (-1)**(number of interchanges) or O .
!    ier = 0 If a nonsingular, or k if a found to be
!          singular at stage k.
! Use  sol  to obtain solution of linear system.
! determ(a) = ip(n)*a(1,1)*a(2,2)*...*a(n,n).
! If ip(n)=0, A is singular, sol will divide by zero.
! Interchanges finished in U , only partly in L .
!
! Reference..
! C. B. Moler, algorithm 423, linear equation solver,
! comm. Assoc. COMPUT. Mach., 15 (1972), P. 274.
!-----------------------------------------------------------------------
integer, intent(out) :: ier
integer, intent(inout) :: ip
integer, intent(in) :: n, ndim
real, intent(inout) :: a(ndim,n)
integer :: i, j, k, kp1, m, nm1
real :: t
dimension ip(n)
!
ier = 0
ip(n) = 1
if (n == 1) go to 70
nm1 = n - 1
do k = 1,nm1
   kp1 = k + 1
!  Find the pivot in column k.  search rows k to n. --------------------
   m = k
   do i = kp1,n
10    if (abs(a(i,k)) > abs(a(m,k))) m = i
   end do
   ip(k) = m
!  Interchange elements in rows k and m. -------------------------------
   t = a(m,k)
   if (m == k) go to 20
   ip(n) = -ip(n)
   a(m,k) = a(k,k)
   a(k,k) = t
20 if (t == 0.0) go to 80
!  Store multipliers in a(i,k), i = k+1,...,n. -------------------------
   t = 1.0/t
   do i = kp1,n
30    a(i,k) = -a(i,k)*t
   end do
!  Apply multipliers to other columns of A. ----------------------------
   do j = kp1,n
      t = a(m,j)
      a(m,j) = a(k,j)
      a(k,j) = t
      if (t == 0.0) go to 50
      do i = kp1,n
40       a(i,j) = a(i,j) + a(i,k)*t
      end do
50    continue
   end do
end do
70 k = n
if (a(n,n) == 0.0) go to 80
return
80 ier = k
ip(n) = 0
end subroutine dec

subroutine sol(n, ndim, a, b, ip)
implicit none
!-----------------------------------------------------------------------
! Solution of linear system, a*X = b .
! Input..
!   n = Order of matrix.
!   ndim = Declared dimension of array  a .
!   a = Triangularized matrix obtained from DEC.
!   b = Right hand side vector.
!   ip = Pivot vector obtained from DEC.
! Do not use if DEC has set ier .NE. 0.
! Output..
!   b = Solution vector, X .
!-----------------------------------------------------------------------
integer :: ip
integer, intent(in) :: n, ndim
real :: a(ndim, n)
real, intent(inout) :: b(n)
integer :: i, k, kb, km1, kp1, m, nm1
real :: t
dimension ip(n)
!
if (n == 1) go to 50
nm1 = n - 1
!  Apply row permutations and multipliers to b. ------------------------
do k = 1,nm1
   kp1 = k + 1
   m = ip(k)
   t = b(m)
   b(m) = b(k)
   b(k) = t
   do i = kp1,n
10    b(i) = b(i) + a(i,k)*t
   end do
end do
!  Back solve. ---------------------------------------------------------
do kb = 1,nm1
   km1 = n - kb
   k = km1 + 1
   b(k) = b(k)/a(k,k)
   t = -b(k)
   do i = 1,km1
30    b(i) = b(i) + a(i,k)*t
   end do
end do
50 b(1) = b(1)/a(1,1)
end subroutine sol

pure subroutine npivot(n, m, a, ka, b, kb, d, ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, m, n
real, intent(inout) :: d
real, intent(inout) :: a(ka,n), b(*)
integer :: j, jl, k, kl, l, maxb
real :: pivot, t
!-----------------------------------------------------------------------
!     Matrix inversion/equation solving without pivot search
!-----------------------------------------------------------------------
!
ierr = 0
maxb = kb*m
do k = 1,n
!
!     Examine the pivot element
!
   pivot = a(k,k)
   d = d*pivot
   if (pivot /= 0.0) go to 10
   ierr = 1
   return
!
!     Divide the pivot row by the pivot element
!
10 a(k,k) = 1.0
   do l = 1,n
      a(k,l) = a(k,l)/pivot
   end do
   if (m <= 0) go to 40
!
   do kl = k,maxb,kb
      b(kl) = b(kl)/pivot
   end do
!
!     Reduce the non-pivot rows
!
40 do j = 1,n
      if (j == k) go to 70
      t = a(j,k)
      a(j,k) = 0.0
      do l = 1,n
         a(j,l) = a(j,l) - a(k,l)*t
      end do
      if (m <= 0) go to 70
!
      kl = k
      do jl = j,maxb,kb
         b(jl) = b(jl) - b(kl)*t
         kl = kl + kb
      end do
70    continue
   end do
!
end do
end subroutine npivot

pure subroutine slv(n, m, a, ka, b, kb, ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, m, n
real, intent(inout) :: a(ka,n), b(kb,m)
integer :: i, ip1, j, jp1, k, l, nm1
real :: p, sum, t
!     ------------------------------------------------------------------
!     Partial pivot solution of a*X = b where A is a matrix of
!     order n and b is a matrix having n rows and m columns.
!     The solution matrix X is stored in b.
!
!     ierr is a variable that reports the status of the results.
!        ierr = 0   The equations have been solved.
!        ierr = j   the j-TH pivot element was found to be 0.
!     ------------------------------------------------------------------
ierr = 0
nm1 = n - 1
if (nm1 == 0) go to 140
do j = 1,nm1
!
!     Search for the j-TH pivot element
!
   p = 0.0
   do i = j,n
      t = abs(a(i,j))
      if (t <= p) go to 10
      p = t
      l = i
10    continue
   end do
   if (p == 0.0) go to 210
   if (j == l) go to 40
!
!     Interchange rows j and l
!
   do k = j,n
      t = a(j,k)
      a(j,k) = a(l,k)
      a(l,k) = t
   end do
   do k = 1,m
      t = b(j,k)
      b(j,k) = b(l,k)
      b(l,k) = t
   end do
!
!     Eliminate the coefficients of X(j) in rows i = j+1,...,n
!
40 p = a(j,j)
   jp1 = j + 1
   do i = jp1,n
      t = a(i,j)/p
      do k = jp1,n
50       a(i,k) = a(i,k) - t*a(j,k)
      end do
      do k = 1,m
60       b(i,k) = b(i,k) - t*b(j,k)
      end do
   end do
end do
if (a(n,n) == 0.0) go to 220
!
!     Backsolve the triangular set of equations
!
do j = 1,m
100 b(n,j) = b(n,j)/a(n,n)
end do
!
do l = 1,nm1
   i = n - l
   ip1 = i + 1
   do j = 1,m
      sum = b(i,j)
      do k = ip1,n
110      sum = sum - a(i,k)*b(k,j)
      end do
120   b(i,j) = sum/a(i,i)
   end do
end do
return
!
!     Case when n = 1
!
140 if (a(1,1) == 0.0) go to 200
do j = 1,m
150 b(1,j) = b(1,j)/a(1,1)
end do
return
!
!     Error return
!
200 ierr = 1
return
210 ierr = j
return
220 ierr = n
end subroutine slv

pure subroutine dpslv(n, m, a, ka, b, kb, ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, m, n
double precision, intent(inout) :: a(ka,n), b(kb,m)
integer :: i, j, k, km1, kp1, l, nm1
double precision :: p, t
!     ------------------------------------------------------------------
!     Partial pivot solution of a*X = b where A is a matrix of
!     order n and b is a matrix having n rows and m columns.
!     The solution matrix X is stored in b.
!
!     ierr is a variable that reports the status of the results.
!        ierr = 0   The equations have been solved.
!        ierr = j   the j-TH pivot element was found to be 0.
!     ------------------------------------------------------------------
ierr = 0
nm1 = n - 1
if (nm1 == 0) go to 140
do k = 1,nm1
!
!     Search for the k-TH pivot element
!
   p = 0.d0
   do i = k,n
      t = abs(a(i,k))
      if (p >= t) go to 10
      p = t
      l = i
10    continue
   end do
   if (p == 0.d0) go to 210
   if (k == l) go to 40
!
!     Interchange rows k and l
!
   do j = k,n
      t = a(k,j)
      a(k,j) = a(l,j)
      a(l,j) = t
   end do
   do j = 1,m
      t = b(k,j)
      b(k,j) = b(l,j)
      b(l,j) = t
   end do
!
!     Eliminate the coefficients of X(k) in rows i = k+1,...,n
!
40 p = a(k,k)
   kp1 = k + 1
   do i = kp1,n
      t = a(i,k)/p
      do j = kp1,n
50       a(i,j) = a(i,j) - t*a(k,j)
      end do
      do j = 1,m
60       b(i,j) = b(i,j) - t*b(k,j)
      end do
   end do
end do
if (a(n,n) == 0.d0) go to 220
!
!     Backsolve the triangular set of equations
!
do j = 1,m
   k = n
   km1 = nm1
   do l = 2,n
      b(k,j) = b(k,j)/a(k,k)
      t = b(k,j)
      do i = 1,km1
100      b(i,j) = b(i,j) - t*a(i,k)
      end do
      k = km1
110   km1 = k - 1
   end do
120 b(1,j) = b(1,j)/a(1,1)
end do
return
!
!     Case when n = 1
!
140 if (a(1,1) == 0.d0) go to 200
do j = 1,m
150 b(1,j) = b(1,j)/a(1,1)
end do
return
!
!     Error return
!
200 ierr = 1
return
210 ierr = k
return
220 ierr = n
end subroutine dpslv

subroutine mslv(mo,n,m,a,ka,b,kb,det,rcond,ierr,ipvt,wk)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, m, mo, n
real, intent(inout) :: a(ka,n), b(*)
real, intent(inout) :: det(2), rcond
real, intent(inout) :: wk(n)
integer, intent(inout) :: ipvt(n)
integer :: j, job, onej
real :: t
!-----------------------------------------------------------------------
!     Partial pivot Gauss procedure for inverting real matrices
!     and solving real equations
!-----------------------------------------------------------------------
!
!          Matrix factorization and computation of rcond
!
ierr = 0
call sgeco(a, ka, n, ipvt, rcond, wk)
t = 1.0 + rcond
if (t == 1.0) go to 30
!
!                  Solution of the equation AX=b
!
if (m < 1) go to 20
onej = 1
do j = 1,m
   call sgesl(a, ka, n, ipvt, b(onej), 0)
   onej = onej + kb
10 continue
end do
!
!             Calculation of det and the inverse of A
!
20 job = 10
if (mo == 0) job = 11
call sgedi(a, ka, n, ipvt, det, wk, job)
return
!
!                  The problem cannot be solved
!
30 ierr = 1
end subroutine mslv

subroutine mslv1(mo,n,m,a,ka,b,kb,ierr,ipvt,wk)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, m, mo, n
real, intent(inout) :: a(ka,n), b(*), wk(*)
integer, intent(inout) :: ipvt(n)
integer :: j, onej
real :: det(2)
!-----------------------------------------------------------------------
!     Partial pivot Gauss procedure for inverting real matrices
!     and solving real equations
!-----------------------------------------------------------------------
!
if (n < 1 .or. ka < n) go to 40
if (m <= 0) go to 10
if (kb < n) go to 40
!
!                      Matrix factorization
!
10 call sgefa(a, ka, n, ipvt, ierr)
if (ierr /= 0) return
!
!                  Solution of the equation AX=b
!
if (m <= 0) go to 30
onej = 1
do j = 1,m
   call sgesl(a, ka, n, ipvt, b(onej), 0)
   onej = onej + kb
end do
!
!                 Calculation of the inverse of A
!
30 if (mo == 0) call sgedi(a, ka, n, ipvt, det, wk, 1)
return
!
!                          Error return
!
40 ierr = -1
end subroutine mslv1

subroutine slvmp(mo, n, a, ka, b, x, wk, iwk, ierr)
implicit none
integer, intent(inout) :: ierr, iwk
integer, intent(in) :: ka, mo, n
real :: a(ka,n), b(n)
real, intent(inout) :: wk(*), x(n)
integer :: i, ir
!     ******************************************************************
!     Solution of real linear equations with iterative improvement
!     ******************************************************************
dimension iwk(n)
!     -------------------
!     dimension wk(n*n + n)
!     -------------------
if (mo /= 0) go to 10
!
!             Compute the LU decomposition of A
!
call mcopy(n, n, a, ka, wk, n)
call sgefa(wk, n, n, iwk, ierr)
if (ierr == 0) go to 10
ierr = -ierr
return
!
!            Solve the system of equations AX = b
!
10 do i = 1,n
11 x(i) = b(i)
end do
!
ir = n*n + 1
call sgesl(wk, n, n, iwk, x, 0)
call luimp(a, ka, n, wk(1), n, iwk, b, x, wk(ir), ierr)
end subroutine slvmp

subroutine luimp(a, ka, n, q, kq, ipvt, b, x, r, ind)
implicit none
integer, intent(out) :: ind
integer :: ipvt
integer, intent(in) :: ka, kq, n
real :: a(ka,n), b(n), q(kq,n)
real, intent(inout) :: r(n), x(n)
integer :: i, j
real :: eps, eps2, rat, ratio, rnrm, xnrm
double precision :: dsum
interface
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
! ----------------------------------------------------------------------
!     Purpose
!       given an approximate solution x of a linear system AX = b
!       obtained using sgeco or sgefa. luimp attempts to compute
!       an improved solution correct to machine precision.
!
!     Parameters
!
!       A    AN ARRAY OF DIMENSION (ka,n) CONTAINING THE MATRIX
!            A of order n.
!       q    AN ARRAY OF DIMENSION (kq,n) CONTAINING THE LU
!            decomposition of a produced by sgeco or sgefa.
!       ipvt an array of dimension n containing the permutation
!            information given by sgeco or sgefa.
!       b    the right hand side of the equation AX = b.
!       x    on input x is the approximate solution of AX = b to
!            be improved. On output x is the solution obtained.
!       r    AN ARRAY FOR INTERNAL USE BY THE ROUTINE.
!       Ind  variable that reports the status of the results.
!            ind = 0 If improvement of x is successful with A
!            gain in accuracy of at least 50 per cent each
!            iteration. Otherwise ind = 1.
!
!     Method
!       luimp executes the iteration cycle
!            (1)  AR = b - AX
!            (2)  x = x + r
!       with an initial given x. the residual vector b - AX is
!       computed to high accuracy using double precision. sgesl
!       is then used to solve (1).
!
! ----------------------------------------------------------------------
dimension ipvt(n)
!
!     ********** eps is a machine dependent parameter. Assign eps
!                the value U where U is the smallest floating point
!                number such that 1.0 + U .GT. 1.0.
!
eps = spmpar(1)
!
ind = 0
xnrm = 0.0
do i = 1,n
10 xnrm = xnrm + x(i)*x(i)
end do
if (xnrm == 0.0) return
eps2 = eps*eps
ratio = 1.0
!
!                  Compute the residual vector
!
20 do i = 1,n
   dsum = b(i)
   do j = 1,n
21    dsum = dsum - dble(a(i,j))*dble(x(j))
   end do
22 r(i) = dsum
end do
!
!                  Find the correction vector
!
call sgesl(q, kq, n, ipvt, r, 0)
rnrm = 0.0
do i = 1,n
30 rnrm = rnrm + r(i)*r(i)
end do
if (rnrm <= eps2*xnrm) return
!
!                Form a new approximate solution
!
do i = 1,n
40 x(i) = x(i) + r(i)
end do
xnrm = 0.0
do i = 1,n
41 xnrm = xnrm + x(i)*x(i)
end do
!
if (xnrm == 0.0) return
rat = ratio
ratio = rnrm/xnrm
if (ratio <= 0.25*rat) go to 20
!
if (ratio > min(rat,4.0*eps2)) ind = 1
end subroutine luimp

pure subroutine sgeco(a,lda,n,ipvt,rcond,z)
implicit none
integer, intent(in) :: lda, n
integer, intent(inout) :: ipvt(*)
real, intent(inout) :: a(lda,*), z(*)
real, intent(inout) :: rcond
real :: ek, t, wk, wkm, anorm, s, sm, ynorm
integer :: info, j, k, kb, kp1, l
interface
   pure function sasum(n,sx,incx)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real :: sasum
   end function sasum
   pure subroutine saxpy(n,sa,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine saxpy
   pure function sdot(n,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(in) :: sy(*)
      integer, intent(in) :: incy
      real :: sdot
   end function sdot
   pure subroutine sgefa(a,lda,n,ipvt,info)
      implicit none
      integer, intent(in) :: lda
      real, intent(inout) :: a(lda,*)
      integer, intent(in) :: n
      integer, intent(inout) :: ipvt(*)
      integer, intent(out) :: info
   end subroutine sgefa
   pure subroutine sscal(n,sa,sx,incx)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(inout) :: sx(*)
      integer, intent(in) :: incx
   end subroutine sscal
end interface
!
!     sgeco factors a real matrix BY Gaussian elimination
!     and estimates the condition of the matrix.
!
!     If  rcond  is not needed, sgefa is slightly faster.
!     To solve  a*X = B , follow sgeco by sgesl.
!     To compute  inverse(a)*C , follow sgeco by sgesl.
!     To compute  determinant(a) , follow sgeco by sgedi.
!     To compute  inverse(a) , follow sgeco by sgedi.
!
!     On entry
!
!        A       real(lda, n)
!                the matrix to be factored.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!     On return
!
!        A       AN UPPER TRIANGULAR MATRIX AND THE MULTIPLIERS
!                which were used to obtain it.
!                The factorization can be written  a = l*U  where
!                l  is a product of permutation and unit lower
!                triangular matrices and  U  is upper triangular.
!
!        ipvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        rcond   REAL
!                an estimate of the reciprocal condition of  A .
!                For the system  a*X = B , relative perturbations
!                in  A  and  B  of size  epsilon  may cause
!                relative perturbations in  X  of size  epsilon/rcond .
!                If  rcond  is so small that the logical expression
!                           1.0 + rcond .EQ. 1.0
!                is true, then  A  may be singular to working
!                precision.  In particular,  rcond  is zero  if
!                exact singularity is detected or the estimate
!                underflows.
!
!        z       real(n)
!                a work vector whose contents are usually unimportant.
!                If  A  is close to a singular matrix, then  z  is
!                an approximate null vector in the sense that
!                norm(a*z) = rcond*norm(a)*norm(z) .
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     LINPACK sgefa
!     BLAS saxpy,sdot,sscal,sasum
!     Fortran abs,AMAX1,sign
!
!     Internal variables
!
!
!
!     Compute 1-norm of A
!
anorm = 0.0e0
do j = 1, n
   anorm = max(anorm,sasum(n,a(1,j),1))
end do
!
!     Factor
!
call sgefa(a,lda,n,ipvt,info)
!
!     rcond = 1/(norm(a)*(estimate of norm(inverse(a)))) .
!     ESTIMATE = NORM(z)/NORM(Y) WHERE  a*z = Y  AND  TRANS(a)*Y = E .
!     Trans(a)  is the transpose of A .  The components of  E  are
!     chosen to cause maximum local growth in the elements of W  where
!     trans(U)*W = E .  The vectors are frequently rescaled to avoid
!     overflow.
!
!     SOLVE TRANS(U)*W = E
!
ek = 1.0e0
do j = 1, n
   z(j) = 0.0e0
end do
do k = 1, n
   if (z(k) /= 0.0e0) ek = sign(ek,-z(k))
   if (abs(ek - z(k)) <= abs(a(k,k))) go to 30
   s = abs(a(k,k))/abs(ek - z(k))
   call sscal(n,s,z,1)
   ek = s*ek
30 continue
   wk = ek - z(k)
   wkm = -ek - z(k)
   s = abs(wk)
   sm = abs(wkm)
   if (a(k,k) == 0.0e0) go to 40
   wk = wk/a(k,k)
   wkm = wkm/a(k,k)
   go to 50
40 continue
   wk = 1.0e0
   wkm = 1.0e0
50 continue
   kp1 = k + 1
   if (kp1 > n) go to 90
   do j = kp1, n
      sm = sm + abs(z(j) + wkm*a(k,j))
      z(j) = z(j) + wk*a(k,j)
      s = s + abs(z(j))
   end do
   if (s >= sm) go to 80
   t = wkm - wk
   wk = wkm
   do j = kp1, n
      z(j) = z(j) + t*a(k,j)
   end do
80 continue
90 continue
   z(k) = wk
end do
s = 1.0e0/sasum(n,z,1)
call sscal(n,s,z,1)
!
!     SOLVE TRANS(l)*Y = W
!
do kb = 1, n
   k = n + 1 - kb
   if (k < n) z(k) = z(k) + sdot(n - k,a(k + 1,k),1,z(k + 1),1)
   if (abs(z(k)) <= 1.0e0) go to 110
   s = 1.0e0/abs(z(k))
   call sscal(n,s,z,1)
110 continue
   l = ipvt(k)
   t = z(l)
   z(l) = z(k)
   z(k) = t
end do
s = 1.0e0/sasum(n,z,1)
call sscal(n,s,z,1)
!
ynorm = 1.0e0
!
!     SOLVE l*V = Y
!
do k = 1, n
   l = ipvt(k)
   t = z(l)
   z(l) = z(k)
   z(k) = t
   if (k < n) call saxpy(n - k,t,a(k + 1,k),1,z(k + 1),1)
   if (abs(z(k)) <= 1.0e0) go to 130
   s = 1.0e0/abs(z(k))
   call sscal(n,s,z,1)
   ynorm = s*ynorm
130 continue
end do
s = 1.0e0/sasum(n,z,1)
call sscal(n,s,z,1)
ynorm = s*ynorm
!
!     SOLVE  U*z = V
!
do kb = 1, n
   k = n + 1 - kb
   if (abs(z(k)) <= abs(a(k,k))) go to 150
   s = abs(a(k,k))/abs(z(k))
   call sscal(n,s,z,1)
   ynorm = s*ynorm
150 continue
   if (a(k,k) /= 0.0e0) z(k) = z(k)/a(k,k)
   if (a(k,k) == 0.0e0) z(k) = 1.0e0
   t = -z(k)
   call saxpy(k - 1,t,a(1,k),1,z(1),1)
end do
!     MAKE ZNORM = 1.0
s = 1.0e0/sasum(n,z,1)
call sscal(n,s,z,1)
ynorm = s*ynorm
!
if (anorm /= 0.0e0) rcond = ynorm/anorm
if (anorm == 0.0e0) rcond = 0.0e0
end subroutine sgeco

pure subroutine sgefa(a,lda,n,ipvt,info)
implicit none
integer, intent(in) :: lda, n
integer, intent(inout) :: ipvt(*)
integer, intent(out) :: info
real, intent(inout) :: a(lda,*)
real :: t
integer :: j, k, kp1, l, nm1
interface
   pure function isamax(n,sx,incx)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      integer :: isamax
   end function isamax
   pure subroutine saxpy(n,sa,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine saxpy
   pure subroutine sscal(n,sa,sx,incx)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(inout) :: sx(*)
      integer, intent(in) :: incx
   end subroutine sscal
end interface
!
!     sgefa factors a real matrix BY Gaussian elimination.
!
!     sgefa is usually called by sgeco, but it can be called
!     directly with a saving in time if  RCOND  is not needed.
!     (Time for sgeco) = (1 + 9/n)*(time for sgefa) .
!
!     On entry
!
!        A       real(lda, n)
!                the matrix to be factored.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!     On return
!
!        A       AN UPPER TRIANGULAR MATRIX AND THE MULTIPLIERS
!                which were used to obtain it.
!                The factorization can be written  a = l*U  where
!                l  is a product of permutation and unit lower
!                triangular matrices and  U  is upper triangular.
!
!        ipvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        INFO    INTEGER
!                = 0  Normal value.
!                = k  if  U(k,k) .EQ. 0.0 .  this is not an error
!                     condition for this subroutine, but it does
!                     indicate that sgesl or sgedi will divide by zero
!                     if called.  Use  RCOND  in sgeco for a reliable
!                     indication of singularity.
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS saxpy,sscal,isamax
!
!     Internal variables
!
!
!
!     Gaussian elimination with partial pivoting
!
info = 0
nm1 = n - 1
if (nm1 < 1) go to 70
do k = 1, nm1
   kp1 = k + 1
!
!        Find l = Pivot index
!
   l = isamax(n - k + 1,a(k,k),1) + k - 1
   ipvt(k) = l
!
!        Zero pivot implies this column already triangularized
!
   if (a(l,k) == 0.0e0) go to 40
!
!           Interchange if necessary
!
   if (l == k) go to 10
   t = a(l,k)
   a(l,k) = a(k,k)
   a(k,k) = t
10 continue
!
!           Compute multipliers
!
   t = -1.0e0/a(k,k)
   call sscal(n - k,t,a(k + 1,k),1)
!
!           Row elimination with column indexing
!
   do j = kp1, n
      t = a(l,j)
      if (l == k) go to 20
      a(l,j) = a(k,j)
      a(k,j) = t
20    continue
      call saxpy(n - k,t,a(k + 1,k),1,a(k + 1,j),1)
   end do
   go to 50
40 continue
   info = k
50 continue
end do
70 continue
ipvt(n) = n
if (a(n,n) == 0.0e0) info = n
end subroutine sgefa

pure subroutine sgesl(a,lda,n,ipvt,b,job)
implicit none
integer, intent(in) :: lda, n, ipvt(*), job
real, intent(in) :: a(lda,*)
real, intent(inout) :: b(*)
real :: t
integer :: k, kb, l, nm1
interface
   pure subroutine saxpy(n,sa,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine saxpy
   pure function sdot(n,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(in) :: sy(*)
      integer, intent(in) :: incy
      real :: sdot
   end function sdot
end interface
!
!     sgesl solves the real system
!     a * X = b  OR  TRANS(a) * X = b
!     using the factors computed by sgeco or sgefa.
!
!     On entry
!
!        A       real(lda, n)
!                the output from sgeco or sgefa.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!        ipvt    INTEGER(n)
!                the pivot vector from sgeco or sgefa.
!
!        b       real(n)
!                the right hand side vector.
!
!        JOB     INTEGER
!                = 0         To solve  a*X = b ,
!                = Nonzero   to solve  trans(a)*X = b  where
!                            trans(a)  is the transpose.
!
!     On return
!
!        b       THE SOLUTION VECTOR  X .
!
!     Error condition
!
!        A division by zero will occur if the input factor contains A
!        zero on the diagonal.  Technically this indicates singularity
!        but it is often caused by improper arguments or improper
!        setting of lda .  It will not occur if the subroutines are
!        called correctly and if sgeco has set RCOND .GT. 0.0
!        or sgefa has set info .EQ. 0 .
!
!     To compute  inverse(a) * C  where  C  is a matrix
!     with  P  columns
!           call sgeco(a,lda,n,ipvt,rcond,z)
!           if (rcond is too small) go to ...
!           do 10 j = 1, p
!              call sgesl(a,lda,n,ipvt,c(1,j),0)
!        10 continue
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS saxpy,sdot
!
!     Internal variables
!
!
nm1 = n - 1
if (job /= 0) go to 50
!
!        job = 0 , SOLVE  a * X = b
!        first solve  l*Y = b
!
if (nm1 < 1) go to 30
do k = 1, nm1
   l = ipvt(k)
   t = b(l)
   if (l == k) go to 10
   b(l) = b(k)
   b(k) = t
10 continue
   call saxpy(n - k,t,a(k + 1,k),1,b(k + 1),1)
end do
30 continue
!
!        Now solve  U*X = Y
!
do kb = 1, n
   k = n + 1 - kb
   b(k) = b(k)/a(k,k)
   t = -b(k)
   call saxpy(k - 1,t,a(1,k),1,b(1),1)
end do
go to 100
50 continue
!
!        job = NONZERO, SOLVE  TRANS(a) * X = b
!        first solve  trans(U)*Y = b
!
do k = 1, n
   t = sdot(k - 1,a(1,k),1,b(1),1)
   b(k) = (b(k) - t)/a(k,k)
end do
!
!        Now solve trans(l)*X = Y
!
if (nm1 < 1) go to 90
do kb = 1, nm1
   k = n - kb
   b(k) = b(k) + sdot(n - k,a(k + 1,k),1,b(k + 1),1)
   l = ipvt(k)
   if (l == k) go to 70
   t = b(l)
   b(l) = b(k)
   b(k) = t
70 continue
end do
90 continue
100 continue
end subroutine sgesl

subroutine sgedi(a,lda,n,ipvt,det,work,job)
implicit none
integer, intent(in) :: lda, n, ipvt(*), job
real, intent(inout) :: a(lda,*), det(2), work(*)
real :: t, ten
integer :: i, j, k, kb, kp1, l, nm1
!
!     sgedi computes the determinant and inverse of a matrix
!     using the factors computed by sgeco or sgefa.
!
!     On entry
!
!        A       real(lda, n)
!                the output from sgeco or sgefa.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!        ipvt    INTEGER(n)
!                the pivot vector from sgeco or sgefa.
!
!        WORK    real(n)
!                work vector.  Contents destroyed.
!
!        JOB     INTEGER
!                = 11   Both determinant and inverse.
!                = 01   Inverse only.
!                = 10   Determinant only.
!
!     On return
!
!        A       INVERSE OF ORIGINAL MATRIX IF REQUESTED.
!                Otherwise unchanged.
!
!        det     real(2)
!                determinant of original matrix IF requested.
!                Otherwise not referenced.
!                determinant = det(1) * 10.0**det(2)
!                WITH  1.0 .LE. abs(det(1)) .LT. 10.0
!                OR  det(1) .EQ. 0.0 .
!
!     Error condition
!
!        A division by zero will occur if the input factor contains
!        a zero on the diagonal and the inverse is requested.
!        It will not occur if the subroutines are called correctly
!        and if sgeco has set RCOND .GT. 0.0 or sgefa has set
!        INFO .EQ. 0 .
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS saxpy,sscal,sswap
!     Fortran abs,mod
!
!     Internal variables
!
!
!
!     Compute determinant
!
if (job/10 == 0) go to 70
det(1) = 1.0e0
det(2) = 0.0e0
ten = 10.0e0
do i = 1, n
   if (ipvt(i) /= i) det(1) = -det(1)
   det(1) = a(i,i)*det(1)
!        ...Exit
   if (det(1) == 0.0e0) go to 60
10 if (abs(det(1)) >= 1.0e0) go to 20
   det(1) = ten*det(1)
   det(2) = det(2) - 1.0e0
   go to 10
20 continue
30 if (abs(det(1)) < ten) go to 40
   det(1) = det(1)/ten
   det(2) = det(2) + 1.0e0
   go to 30
40 continue
50 continue
end do
60 continue
70 continue
!
!     Compute inverse(U)
!
if (mod(job,10) == 0) go to 150
do k = 1, n
   a(k,k) = 1.0e0/a(k,k)
   t = -a(k,k)
   call sscal(k - 1,t,a(1,k),1)
   kp1 = k + 1
   if (n < kp1) go to 90
   do j = kp1, n
      t = a(k,j)
      a(k,j) = 0.0e0
      call saxpy(k,t,a(1,k),1,a(1,j),1)
   end do
90 continue
end do
!
!        Form inverse(U)*inverse(l)
!
nm1 = n - 1
if (nm1 < 1) go to 140
do kb = 1, nm1
   k = n - kb
   kp1 = k + 1
   do i = kp1, n
      work(i) = a(i,k)
      a(i,k) = 0.0e0
   end do
   do j = kp1, n
      t = work(j)
      call saxpy(n,t,a(1,j),1,a(1,k),1)
   end do
   l = ipvt(k)
   if (l /= k) call sswap(n,a(1,k),1,a(1,l),1)
end do
140 continue
150 continue
end subroutine sgedi

subroutine dmslv(mo,n,m,a,ka,b,kb,det,rcond,ierr,ipvt,wk)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, m, mo, n
double precision, intent(inout) :: a(ka,n), b(*)
double precision, intent(inout) :: det(2), rcond
double precision, intent(inout) :: wk(n)
integer, intent(inout) :: ipvt(n)
integer :: j, job, onej
double precision :: t
!-----------------------------------------------------------------------
!     Partial pivot Gauss procedure for inverting double precision
!     real matrices and solving double precision real equations
!-----------------------------------------------------------------------
!
!          Matrix factorization and computation of rcond
!
ierr = 0
call dgeco(a, ka, n, ipvt, rcond, wk)
t = 1.d0 + rcond
if (t == 1.d0) go to 30
!
!                  Solution of the equation AX=b
!
if (m < 1) go to 20
onej = 1
do j = 1,m
   call dgesl(a, ka, n, ipvt, b(onej), 0)
   onej = onej + kb
10 continue
end do
!
!             Calculation of det and the inverse of A
!
20 job = 10
if (mo == 0) job = 11
call dgedi(a, ka, n, ipvt, det, wk, job)
return
!
!                  The problem cannot be solved
!
30 ierr = 1
end subroutine dmslv

subroutine dmslv1(mo,n,m,a,ka,b,kb,ierr,ipvt,wk)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, m, mo, n
double precision, intent(inout) :: a(ka,n), b(*), wk(*)
integer, intent(inout) :: ipvt(n)
integer :: j, onej
double precision :: det(2)
!-----------------------------------------------------------------------
!     Partial pivot Gauss procedure for inverting double precision
!     real matrices and solving double precision real equations
!-----------------------------------------------------------------------
!
if (n < 1 .or. ka < n) go to 40
if (m <= 0) go to 10
if (kb < n) go to 40
!
!                      Matrix factorization
!
10 call dgefa(a, ka, n, ipvt, ierr)
if (ierr /= 0) return
!
!                  Solution of the equation AX=b
!
if (m <= 0) go to 30
onej = 1
do j = 1,m
   call dgesl(a, ka, n, ipvt, b(onej), 0)
   onej = onej + kb
end do
!
!                 Calculation of the inverse of A
!
30 if (mo == 0) call dgedi(a, ka, n, ipvt, det, wk, 1)
return
!
!                          Error return
!
40 ierr = -1
end subroutine dmslv1

pure subroutine dgeco(a,lda,n,ipvt,rcond,z)
implicit none
integer, intent(in) :: lda, n
integer, intent(inout) :: ipvt(*)
double precision, intent(inout) :: a(lda,*), z(*)
double precision, intent(inout) :: rcond
double precision :: ek, t, wk, wkm, anorm, s, sm, ynorm
integer :: info, j, k, kb, kp1, l
interface
   pure function dasum(n,dx,incx)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision :: dasum
   end function dasum
   pure subroutine daxpy(n,da,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
   end subroutine daxpy
   pure function ddot(n,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(in) :: dy(*)
      integer, intent(in) :: incy
      double precision :: ddot
   end function ddot
   pure subroutine dgefa(a,lda,n,ipvt,info)
      implicit none
      integer, intent(in) :: lda
      double precision, intent(inout) :: a(lda,*)
      integer, intent(in) :: n
      integer, intent(inout) :: ipvt(*)
      integer, intent(out) :: info
   end subroutine dgefa
   pure subroutine dscal(n,da,dx,incx)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(inout) :: dx(*)
      integer, intent(in) :: incx
   end subroutine dscal
end interface
!
!     dgeco factors a double precision matrix BY Gaussian elimination
!     and estimates the condition of the matrix.
!
!     If  rcond  is not needed, dgefa is slightly faster.
!     To solve  a*X = B , follow dgeco by dgesl.
!     To compute  inverse(a)*C , follow dgeco by dgesl.
!     To compute  determinant(a) , follow dgeco by dgedi.
!     To compute  inverse(a) , follow dgeco by dgedi.
!
!     On entry
!
!        A       DOUBLE PRECISION(lda, n)
!                the matrix to be factored.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!     On return
!
!        A       AN UPPER TRIANGULAR MATRIX AND THE MULTIPLIERS
!                which were used to obtain it.
!                The factorization can be written  a = l*U  where
!                l  is a product of permutation and unit lower
!                triangular matrices and  U  is upper triangular.
!
!        ipvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        rcond   DOUBLE PRECISION
!                an estimate of the reciprocal condition of  A .
!                For the system  a*X = B , relative perturbations
!                in  A  and  B  of size  epsilon  may cause
!                relative perturbations in  X  of size  epsilon/rcond .
!                If  rcond  is so small that the logical expression
!                           1.0 + rcond .EQ. 1.0
!                is true, then  A  may be singular to working
!                precision.  In particular,  rcond  is zero  if
!                exact singularity is detected or the estimate
!                underflows.
!
!        z       DOUBLE PRECISION(n)
!                a work vector whose contents are usually unimportant.
!                If  A  is close to a singular matrix, then  z  is
!                an approximate null vector in the sense that
!                norm(a*z) = rcond*norm(a)*norm(z) .
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     LINPACK dgefa
!     BLAS daxpy,ddot,dscal,dasum
!     Fortran dabs,DMAX1,DSIGN
!
!     Internal variables
!
!
!
!     Compute 1-norm of A
!
anorm = 0.0d0
do j = 1, n
   anorm = max(anorm,dasum(n,a(1,j),1))
end do
!
!     Factor
!
call dgefa(a,lda,n,ipvt,info)
!
!     rcond = 1/(norm(a)*(estimate of norm(inverse(a)))) .
!     ESTIMATE = NORM(z)/NORM(Y) WHERE  a*z = Y  AND  TRANS(a)*Y = E .
!     Trans(a)  is the transpose of A .  The components of  E  are
!     chosen to cause maximum local growth in the elements of W  where
!     trans(U)*W = E .  The vectors are frequently rescaled to avoid
!     overflow.
!
!     SOLVE TRANS(U)*W = E
!
ek = 1.0d0
do j = 1, n
   z(j) = 0.0d0
end do
do k = 1, n
   if (z(k) /= 0.0d0) ek = sign(ek,-z(k))
   if (abs(ek - z(k)) <= abs(a(k,k))) go to 30
   s = abs(a(k,k))/abs(ek - z(k))
   call dscal(n,s,z,1)
   ek = s*ek
30 continue
   wk = ek - z(k)
   wkm = -ek - z(k)
   s = abs(wk)
   sm = abs(wkm)
   if (a(k,k) == 0.0d0) go to 40
   wk = wk/a(k,k)
   wkm = wkm/a(k,k)
   go to 50
40 continue
   wk = 1.0d0
   wkm = 1.0d0
50 continue
   kp1 = k + 1
   if (kp1 > n) go to 90
   do j = kp1, n
      sm = sm + abs(z(j) + wkm*a(k,j))
      z(j) = z(j) + wk*a(k,j)
      s = s + abs(z(j))
   end do
   if (s >= sm) go to 80
   t = wkm - wk
   wk = wkm
   do j = kp1, n
      z(j) = z(j) + t*a(k,j)
   end do
80 continue
90 continue
   z(k) = wk
end do
s = 1.0d0/dasum(n,z,1)
call dscal(n,s,z,1)
!
!     SOLVE TRANS(l)*Y = W
!
do kb = 1, n
   k = n + 1 - kb
   if (k < n) z(k) = z(k) + ddot(n - k,a(k + 1,k),1,z(k + 1),1)
   if (abs(z(k)) <= 1.0d0) go to 110
   s = 1.0d0/abs(z(k))
   call dscal(n,s,z,1)
110 continue
   l = ipvt(k)
   t = z(l)
   z(l) = z(k)
   z(k) = t
end do
s = 1.0d0/dasum(n,z,1)
call dscal(n,s,z,1)
!
ynorm = 1.0d0
!
!     SOLVE l*V = Y
!
do k = 1, n
   l = ipvt(k)
   t = z(l)
   z(l) = z(k)
   z(k) = t
   if (k < n) call daxpy(n - k,t,a(k + 1,k),1,z(k + 1),1)
   if (abs(z(k)) <= 1.0d0) go to 130
   s = 1.0d0/abs(z(k))
   call dscal(n,s,z,1)
   ynorm = s*ynorm
130 continue
end do
s = 1.0d0/dasum(n,z,1)
call dscal(n,s,z,1)
ynorm = s*ynorm
!
!     SOLVE  U*z = V
!
do kb = 1, n
   k = n + 1 - kb
   if (abs(z(k)) <= abs(a(k,k))) go to 150
   s = abs(a(k,k))/abs(z(k))
   call dscal(n,s,z,1)
   ynorm = s*ynorm
150 continue
   if (a(k,k) /= 0.0d0) z(k) = z(k)/a(k,k)
   if (a(k,k) == 0.0d0) z(k) = 1.0d0
   t = -z(k)
   call daxpy(k - 1,t,a(1,k),1,z(1),1)
end do
!     MAKE ZNORM = 1.0
s = 1.0d0/dasum(n,z,1)
call dscal(n,s,z,1)
ynorm = s*ynorm
!
if (anorm /= 0.0d0) rcond = ynorm/anorm
if (anorm == 0.0d0) rcond = 0.0d0
end subroutine dgeco

pure subroutine dgefa(a,lda,n,ipvt,info)
implicit none
integer, intent(in) :: lda, n
integer, intent(inout) :: ipvt(*)
integer, intent(out) :: info
double precision, intent(inout) :: a(lda,*)
double precision :: t
integer :: j, k, kp1, l, nm1
interface
   pure subroutine daxpy(n,da,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
   end subroutine daxpy
   pure subroutine dscal(n,da,dx,incx)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(inout) :: dx(*)
      integer, intent(in) :: incx
   end subroutine dscal
   pure function idamax(n,dx,incx)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      integer :: idamax
   end function idamax
end interface
!
!     dgefa factors a double precision matrix BY Gaussian elimination.
!
!     dgefa is usually called by dgeco, but it can be called
!     directly with a saving in time if  RCOND  is not needed.
!     (Time for dgeco) = (1 + 9/n)*(time for dgefa) .
!
!     On entry
!
!        A       DOUBLE PRECISION(lda, n)
!                the matrix to be factored.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!     On return
!
!        A       AN UPPER TRIANGULAR MATRIX AND THE MULTIPLIERS
!                which were used to obtain it.
!                The factorization can be written  a = l*U  where
!                l  is a product of permutation and unit lower
!                triangular matrices and  U  is upper triangular.
!
!        ipvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        INFO    INTEGER
!                = 0  Normal value.
!                = k  if  U(k,k) .EQ. 0.0 .  this is not an error
!                     condition for this subroutine, but it does
!                     indicate that dgesl or dgedi will divide by zero
!                     if called.  Use  RCOND  in dgeco for a reliable
!                     indication of singularity.
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS daxpy,dscal,idamax
!
!     Internal variables
!
!
!
!     Gaussian elimination with partial pivoting
!
info = 0
nm1 = n - 1
if (nm1 < 1) go to 70
do k = 1, nm1
   kp1 = k + 1
!
!        Find l = Pivot index
!
   l = idamax(n - k + 1,a(k,k),1) + k - 1
   ipvt(k) = l
!
!        Zero pivot implies this column already triangularized
!
   if (a(l,k) == 0.0d0) go to 40
!
!           Interchange if necessary
!
   if (l == k) go to 10
   t = a(l,k)
   a(l,k) = a(k,k)
   a(k,k) = t
10 continue
!
!           Compute multipliers
!
   t = -1.0d0/a(k,k)
   call dscal(n - k,t,a(k + 1,k),1)
!
!           Row elimination with column indexing
!
   do j = kp1, n
      t = a(l,j)
      if (l == k) go to 20
      a(l,j) = a(k,j)
      a(k,j) = t
20    continue
      call daxpy(n - k,t,a(k + 1,k),1,a(k + 1,j),1)
   end do
   go to 50
40 continue
   info = k
50 continue
end do
70 continue
ipvt(n) = n
if (a(n,n) == 0.0d0) info = n
end subroutine dgefa

pure subroutine dgesl(a,lda,n,ipvt,b,job)
implicit none
integer, intent(in) :: lda, n, ipvt(*), job
double precision, intent(in) :: a(lda,*)
double precision, intent(inout) :: b(*)
double precision :: t
integer :: k, kb, l, nm1
interface
   pure subroutine daxpy(n,da,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
   end subroutine daxpy
   pure function ddot(n,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(in) :: dy(*)
      integer, intent(in) :: incy
      double precision :: ddot
   end function ddot
end interface
!
!     dgesl solves the double precision system
!     a * X = b  OR  TRANS(a) * X = b
!     using the factors computed by dgeco or dgefa.
!
!     On entry
!
!        A       DOUBLE PRECISION(lda, n)
!                the output from dgeco or dgefa.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!        ipvt    INTEGER(n)
!                the pivot vector from dgeco or dgefa.
!
!        b       DOUBLE PRECISION(n)
!                the right hand side vector.
!
!        JOB     INTEGER
!                = 0         To solve  a*X = b ,
!                = Nonzero   to solve  trans(a)*X = b  where
!                            trans(a)  is the transpose.
!
!     On return
!
!        b       THE SOLUTION VECTOR  X .
!
!     Error condition
!
!        A division by zero will occur if the input factor contains A
!        zero on the diagonal.  Technically this indicates singularity
!        but it is often caused by improper arguments or improper
!        setting of lda .  It will not occur if the subroutines are
!        called correctly and if dgeco has set RCOND .GT. 0.0
!        or dgefa has set info .EQ. 0 .
!
!     To compute  inverse(a) * C  where  C  is a matrix
!     with  P  columns
!           call dgeco(a,lda,n,ipvt,rcond,z)
!           if (rcond is too small) go to ...
!           do 10 j = 1, p
!              call dgesl(a,lda,n,ipvt,c(1,j),0)
!        10 continue
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS daxpy,ddot
!
!     Internal variables
!
!
nm1 = n - 1
if (job /= 0) go to 50
!
!        job = 0 , SOLVE  a * X = b
!        first solve  l*Y = b
!
if (nm1 < 1) go to 30
do k = 1, nm1
   l = ipvt(k)
   t = b(l)
   if (l == k) go to 10
   b(l) = b(k)
   b(k) = t
10 continue
   call daxpy(n - k,t,a(k + 1,k),1,b(k + 1),1)
end do
30 continue
!
!        Now solve  U*X = Y
!
do kb = 1, n
   k = n + 1 - kb
   b(k) = b(k)/a(k,k)
   t = -b(k)
   call daxpy(k - 1,t,a(1,k),1,b(1),1)
end do
go to 100
50 continue
!
!        job = NONZERO, SOLVE  TRANS(a) * X = b
!        first solve  trans(U)*Y = b
!
do k = 1, n
   t = ddot(k - 1,a(1,k),1,b(1),1)
   b(k) = (b(k) - t)/a(k,k)
end do
!
!        Now solve trans(l)*X = Y
!
if (nm1 < 1) go to 90
do kb = 1, nm1
   k = n - kb
   b(k) = b(k) + ddot(n - k,a(k + 1,k),1,b(k + 1),1)
   l = ipvt(k)
   if (l == k) go to 70
   t = b(l)
   b(l) = b(k)
   b(k) = t
70 continue
end do
90 continue
100 continue
end subroutine dgesl

subroutine dgedi(a,lda,n,ipvt,det,work,job)
implicit none
integer, intent(in) :: lda, n, ipvt(*), job
double precision, intent(inout) :: a(lda,*), det(2), work(*)
double precision :: t, ten
integer :: i, j, k, kb, kp1, l, nm1
!
!     dgedi computes the determinant and inverse of a matrix
!     using the factors computed by dgeco or dgefa.
!
!     On entry
!
!        A       DOUBLE PRECISION(lda, n)
!                the output from dgeco or dgefa.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!        ipvt    INTEGER(n)
!                the pivot vector from dgeco or dgefa.
!
!        WORK    DOUBLE PRECISION(n)
!                work vector.  Contents destroyed.
!
!        JOB     INTEGER
!                = 11   Both determinant and inverse.
!                = 01   Inverse only.
!                = 10   Determinant only.
!
!     On return
!
!        A       INVERSE OF ORIGINAL MATRIX IF REQUESTED.
!                Otherwise unchanged.
!
!        det     DOUBLE PRECISION(2)
!                determinant of original matrix IF requested.
!                Otherwise not referenced.
!                determinant = det(1) * 10.0**det(2)
!                WITH  1.0 .LE. dabs(det(1)) .LT. 10.0
!                OR  det(1) .EQ. 0.0 .
!
!     Error condition
!
!        A division by zero will occur if the input factor contains
!        a zero on the diagonal and the inverse is requested.
!        It will not occur if the subroutines are called correctly
!        and if dgeco has set RCOND .GT. 0.0 or dgefa has set
!        INFO .EQ. 0 .
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS daxpy,dscal,dswap
!     Fortran dabs,mod
!
!     Internal variables
!
!
!
!     Compute determinant
!
if (job/10 == 0) go to 70
det(1) = 1.0d0
det(2) = 0.0d0
ten = 10.0d0
do i = 1, n
   if (ipvt(i) /= i) det(1) = -det(1)
   det(1) = a(i,i)*det(1)
!        ...Exit
   if (det(1) == 0.0d0) go to 60
10 if (abs(det(1)) >= 1.0d0) go to 20
   det(1) = ten*det(1)
   det(2) = det(2) - 1.0d0
   go to 10
20 continue
30 if (abs(det(1)) < ten) go to 40
   det(1) = det(1)/ten
   det(2) = det(2) + 1.0d0
   go to 30
40 continue
50 continue
end do
60 continue
70 continue
!
!     Compute inverse(U)
!
if (mod(job,10) == 0) go to 150
do k = 1, n
   a(k,k) = 1.0d0/a(k,k)
   t = -a(k,k)
   call dscal(k - 1,t,a(1,k),1)
   kp1 = k + 1
   if (n < kp1) go to 90
   do j = kp1, n
      t = a(k,j)
      a(k,j) = 0.0d0
      call daxpy(k,t,a(1,k),1,a(1,j),1)
   end do
90 continue
end do
!
!        Form inverse(U)*inverse(l)
!
nm1 = n - 1
if (nm1 < 1) go to 140
do kb = 1, nm1
   k = n - kb
   kp1 = k + 1
   do i = kp1, n
      work(i) = a(i,k)
      a(i,k) = 0.0d0
   end do
   do j = kp1, n
      t = work(j)
      call daxpy(n,t,a(1,j),1,a(1,k),1)
   end do
   l = ipvt(k)
   if (l /= k) call dswap(n,a(1,k),1,a(1,l),1)
end do
140 continue
150 continue
end subroutine dgedi

subroutine arceco(n, array, mtrstr, nmblks, pivot, b, x, iflag)
implicit none
integer, intent(inout) :: iflag
integer, intent(in) :: n, nmblks
real, intent(inout) :: array(*), b(*), x(*)
integer, intent(inout) :: mtrstr(3,*), pivot(*)
!
!***************************************************************
!
!  This program solves the linear system  A*x = b  where  A is
!  an almost block diagonal matrix.  The method implemented is
!  based on Gauss elimination with alternate row and column
!  elimination with partial pivoting, which produces a stable
!  decomposition of the matrix  A  without introducing fill-in.
!
!***************************************************************
!
!               *****  PARAMETERS  *****
!
!       *** On entry ...
!
!                n     - INTEGER
!                         the order of the linear system, where
!                           n = sum(mtrstr(1,k),k=1,nmblks)
!
!                array - real(NUMELS)
!                         where
!                          numels = sum(mtrstr(1,k)*mtrstr(2,k),
!                               k=1,nmblks).
!                         Contains the entries of the almost
!                         block diagonal matrix  A  whose block
!                         structure is given by the integer array
!                         mtrstr. The elements of A are stored by
!                         columns, in blocks corresponding to the
!                         given structure.
!
!               mtrstr - INTEGER(3,nmblks)
!                         describes the block structure of  A ...
!                           mtrstr(1,K)  = Number of rows in
!                                            block K.
!                           mtrstr(2,K)  = Number of columns in
!                                            block K.
!                           mtrstr(3,K)  = Number of columns
!                                          overlapped by block K
!                                          and block (K+1).
!                        mtrstr must satisfy some restrictions.
!                         In order that A be square, we need
!                         sum(mtrstr(1,K),K=1,nmblks) = n =
!                         sum((mtrstr(2,K)-mtrstr(3,K)),K=1,nmblks).
!                        In addition, to ensure that three success-
!                         ive blocks do not have columns in common,
!                         mtrstr must satisfy
!                         mtrstr(3,K-1)+mtrstr(3,K).LE.mtrstr(2,K),
!                         FOR K = 2,nmblks.
!                        Finally,  A R C E C O,  sets
!                         mtrstr(3,nmblks) = 0, IN ARCECD.
!
!               nmblks - INTEGER
!                         total number of blocks in  A
!
!                pivot - Integer(n)
!                         work space
!
!                    b - real(n)
!                         the right hand side vector
!
!                    x - real(n)
!                         work space
!
!       *** On return  ...
!
!                array - real(NUMELS)
!                         contains the modified alternate row
!                         and column decomposition of  A (if
!                         iflag = 0)
!
!                pivot - Integer(n)
!                         records the pivoting indices deter-
!                         mined in the decomposition
!
!                    x - real(n)
!                         the solution vector (if iflag = 0)
!
!                iflag - INTEGER
!                         =  1,if input parameters are invalid
!                         = -1, if matrix is singular
!                         =  0, OTHERWISE
!
!***************************************************************
!
!               *****  Auxiliary programs  *****
!
!            arcedc(array,mtrstr,nmblks,pivot,iflag)
!               - Decomposes the matrix  A  using modified
!                 alternate row and column elimination
!                 with partial pivoting, and is used for
!                 this purpose in  A R C E C O.
!                 The arguments are all as in A R C E C O.
!
!            arcesl(array,mtrstr,nmblks,pivot,b,x)
!               - Solves the system  A*x = b  once  A  is
!                 decomposed.
!                 The arguments are all as in A R C E C O .
!
!***************************************************************
!
!               *****  Block structure of  A  *****
!
!  The nmblks blocks of A are stored consecutively in the one
!  dimensional matrix  array, the entries of  A  being stored
!  as follows ...
!
!       IN array(1)     THE (1,1) ENTRY OF THE TOP BLOCK,
!
!       In array(INDEX) the (1,1) entry of the ith block where
!                       index = 1 + sum(mtrstr(1,j)*mtrstr(2,j),
!                               j=1,i-1), i=2,nmblks.
!
!***************************************************************
!
!       The subroutine  A R C E C O  automatically solves the
!  input system when iflag=0.  A R C E C O  is called only once
!  for a given system. The solution for a sequence of P right
!  hand sides can be obtained by one call to  A R C E C O  and
!  P-1 calls to arcesl only. Since the arrays array and
!  pivot contain, respectively, the decomposition of the given
!  coefficient matrix and pivoting information on return from
!  A R C E C O , they must not be altered between successive
!  calls to arcesl with the same right hand sides. For the
!  same reason, if the user wishes to save the coefficient
!  matrix, the array array must be copied before a call
!  TO  A R C E C O .
!
!**********************************************************************
call arcedc(n, array, mtrstr, nmblks, pivot, iflag)
if (iflag /= 0) return
call arcesl(array, mtrstr, nmblks, pivot, b, x)
end subroutine arceco

pure subroutine arcedc(n, array, mtrstr, nmblks, pivot, iflag)
implicit none
integer, intent(inout) :: iflag, mtrstr(3,*)
integer, intent(in) :: n, nmblks
real, intent(inout) :: array(*)
integer, intent(inout) :: pivot(*)
integer :: index1, index2, index3, indpiv, isum1, isum2, k, &
   & nclblk, nclpiv, novrlp, nrwbk2, nrwblk, nrwpiv
real :: pivmax
real, parameter :: zero = 0.0
interface
   pure subroutine arcepc(topblk,nrwtop,novrlp,botblk,nrwbot, &
      & nclpiv,pivot,pivmax,iflag)
      implicit none
      integer, intent(in) :: nrwbot
      integer, intent(in) :: novrlp
      integer, intent(in) :: nrwtop
      real, intent(inout) :: topblk(nrwtop,novrlp)
      real, intent(inout) :: botblk(nrwbot,novrlp)
      integer, intent(in) :: nclpiv
      integer, intent(inout) :: pivot(nrwtop)
      real, intent(inout) :: pivmax
      integer, intent(inout) :: iflag
   end subroutine arcepc
   pure subroutine arcepr(block,nrwblk,nclblk,nrwpiv,pivot, &
      & pivmax,iflag)
      implicit none
      integer, intent(in) :: nclblk
      integer, intent(in) :: nrwblk
      real, intent(inout) :: block(nrwblk,nclblk)
      integer, intent(in) :: nrwpiv
      integer, intent(inout) :: pivot(nrwblk)
      real, intent(inout) :: pivmax
      integer, intent(inout) :: iflag
   end subroutine arcepr
end interface
!
!***************************************************************
!
!  A R C E D C supervises the modified alternate row and column
!  decomposition with partial pivoting of the almost block
!  DIAGONAL MATRIX  A   STORED IN THE ARRAYS A R R A Y  AND
!  M T R S T R .
!
!***************************************************************
!
!               *****  PARAMETERS  *****
!
!       *** On entry ...
!
!                n     - INTEGER
!                         the order of the linear system, where
!                           n = sum(mtrstr(1,k),k=1,nmblks)
!
!                array - real(NUMELS)
!                         where
!                          numels = sum(mtrstr(1,k)*mtrstr(2,k),
!                               k=1,nmblks).
!                         Contains the entries of the almost
!                         block diagonal matrix  A  whose block
!                         structure is given by the integer array
!                         mtrstr. The elements of A are stored by
!                         columns, in blocks corresponding to the
!                         given structure.
!               mtrstr - INTEGER(3,nmblks)
!                         describes the block structure of  A ...
!                           mtrstr(1,k)  = Number of rows in
!                                            block k.
!                           mtrstr(2,k)  = Number of columns in
!                                            block k.
!                           mtrstr(3,k)  = Number of columns
!                                          overlapped by block k
!                                          and block (k+1).
!                        mtrstr must satisfy some restrictions.
!                         In order that A be square, we need
!                         sum(mtrstr(1,k),k=1,nmblks) = n =
!                         sum((mtrstr(2,k)-mtrstr(3,k)),k=1,nmblks).
!                        In addition, to ensure that three success-
!                         ive blocks do not have columns in common,
!                         mtrstr must satisfy
!                         mtrstr(3,k-1)+mtrstr(3,k).LE.mtrstr(2,k),
!                         FOR k = 2,nmblks.
!                        Finally,  A R C E C O,  sets
!                         mtrstr(3,nmblks) = 0, IN ARCECD.
!
!               nmblks - INTEGER
!                         total number of blocks
!
!                pivot - Integer(n)
!                         work space
!
!       *** On return  ...
!
!                array - real(NUMELS)
!                         contains the modified alternate row
!                         and column decomposition of  A (if
!                         iflag = 0)
!
!                pivot - Integer(n)
!                         records the pivoting indices deter-
!                         mined in the decomposition
!
!                iflag - INTEGER
!                         =  1, if input parameters are invalid
!                         = -1, if matrix is singular
!                         =  0, OTHERWISE
!
!***************************************************************
!
!               *****  Auxiliary programs  *****
!
!       arcepr(BLOCK,NRWBLK,NCLBLK,NRWPIV,pivot,pivmax,iflag)
!        carries out the row eliminations
!
!       arcepc(TOPBLK,NRWTOP,NOVRLP,BOTBLK,NRWBOT,NCLPIV,
!            PIVOT,pivmax,iflag)
!        carries out the column eliminations
!
!***************************************************************
!
!
!***************************************************************
!
!       ****  Check validity of the input parameters....
!
!            If parameters are invalid then terminate at 7,
!                                      ELSE CONTINUE AT 8.
!
!***************************************************************
!
!
mtrstr(3,nmblks) = 0
do k = 2,nmblks
   if (mtrstr(3,k - 1) + mtrstr(3,k) > mtrstr(2,k)) go to 30
end do
isum1 = 0
isum2 = 0
do k = 1,nmblks
   isum1 = isum1 + mtrstr(1,k)
   isum2 = isum2 + mtrstr(2,k) - mtrstr(3,k)
end do
if (isum1 /= isum2) go to 30
if (isum1 /= n) go to 30
!
!Ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
!          Parameters are acceptable - Continue at 8
!
!Ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
go to 40
30 continue
!
!Cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
!        Parameters are invalid.  Set iflag = 1, and terminate
!
!Cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
iflag = 1
return
40 continue
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C  internal parameters ...
!       C
!       C       index1  POINTER TO THE ELEMENT IN THE COLUMN
!       C               WHERE ROW PIVOTING STARTS.
!       C
!       C       index2  POINTER TO THE ELEMENT IN THE COLUMN
!       C               WHERE COLUMN PIVOTING STARTS.
!       C
!       C       index3  POINTER TO 1ST ELEMENT IN 1ST COLUMN
!       C               OF NEXT BLOCK.
!       C
!       C       indpiv  POINTER TO 1ST ELEMENT OF BLOCK OF PIVOT
!       C
!       C       NRWBLK  NUMBER OF ROWS IN BLOCK.
!       C
!       C       NRWBK2  NUMBER OF ROWS IN NEXT BLOCK.
!       C
!       C       NRWPIV  NUMBER OF ROW ELIMINATIONS.
!       C
!       C       NCLBLK  NUMBER OF COLUMNS IN BLOCK TO BE
!       C               ROW PIVOTED.
!       C
!       C       NCLPIV  NUMBER OF COLUMN ELIMINATIONS.
!       C
!       C       NOVRLP  NUMBER OF COLUMNS OVERLAPPED BY THE
!       C               CURRENT BLOCK AND THE NEXT BLOCK.
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
pivmax = zero
iflag = 0
index1 = 1
indpiv = 1
nrwblk = mtrstr(1,1)
nclblk = mtrstr(2,1)
novrlp = mtrstr(3,1)
nrwpiv = nclblk - novrlp
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       CALL arcepr TO PERFORM NRWPIV ROW ELIMINATIONS
!       C               ON TOP BLOCK.
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
if (nrwpiv > 0) call arcepr(array(index1), nrwblk, nclblk, &
   & nrwpiv, pivot(indpiv), pivmax, iflag)
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       IF MATRIX SINGULAR RETURN.
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
if (iflag < 0) return
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       NOW DO DECOMPOSITION PROCEEDING ONE BLOCK AT A
!       C               TIME.
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
do k = 2,nmblks
   indpiv = indpiv + nrwpiv
   index2 = index1 + nrwblk*nrwpiv
   index3 = index2 + nrwblk*novrlp
   nclpiv = nrwblk - nrwpiv
   nrwbk2 = mtrstr(1,k)
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C  call arcepc to perform NCLPIV column eliminations.
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (nclpiv == 0) go to 50
   call arcepc(array(index2), nrwblk, novrlp, array(index3), &
      & nrwbk2, nclpiv, pivot(indpiv), pivmax, iflag)
!
!             Cccccccccccccccccccccccccccccccccccccccccccccccccc
!             C
!             C    IF MATRIX IS SINGULAR RETURN.
!             C
!             cccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (iflag < 0) return
50 continue
   nrwblk = nrwbk2
   index1 = index3 + nrwblk*nclpiv
   nclblk = mtrstr(2,k) - nclpiv
   novrlp = mtrstr(3,k)
   nrwpiv = nclblk - novrlp
   indpiv = indpiv + nclpiv
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    CALL arcepr TO PERFORM NRWPIV ROW ELIMINATIONS.
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (nrwpiv == 0) go to 60
   call arcepr(array(index1), nrwblk, nclblk, nrwpiv, &
      & pivot(indpiv), pivmax, iflag)
!             Cccccccccccccccccccccccccccccccccccccccccccccccccc
!             C
!             C    IF MATRIX IS SINGULAR RETURN.
!             C
!             cccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (iflag < 0) return
60 continue
end do
end subroutine arcedc

pure subroutine arcepr(block, nrwblk, nclblk, nrwpiv, pivot, pivmax, &
   & iflag)
implicit none
integer, intent(inout) :: iflag
integer, intent(in) :: nclblk, nrwblk, nrwpiv
integer, intent(inout) :: pivot(nrwblk)
real, intent(inout) :: block(nrwblk,nclblk)
real, intent(inout) :: pivmax
integer :: i1, j, j1, jplus1, l1, max
real :: rowmax, tempiv, rowpiv, swap
!
!***************************************************************
!
!  A R C E P R  performs  nrwpiv  row eliminations on the matrix
!               block
!
!***************************************************************
!
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C        PERFORM nrwpiv ROW ELIMINATIONS...
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
do j = 1,nrwpiv
   jplus1 = j + 1
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    DETERMINE ROW PIVOT AND PIVOT INDEX
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   max = j
   rowmax = abs(block(j,j))
   if (j == nrwblk) go to 30
   do i1 = jplus1,nrwblk
      tempiv = abs(block(i1,j))
      if (tempiv <= rowmax) go to 10
      rowmax = tempiv
      max = i1
10    continue
   end do
30 continue
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    TEST FOR SINGULARITY ...
!          C
!          C             IF SINGULAR THEN TERMINATE AT 90,
!          C                         ELSE CONTINUE.
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (pivmax + rowmax == pivmax) go to 100
   pivmax = amax1(pivmax,rowmax)
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    IF NECESSARY INTERCHANGE ROWS
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   pivot(j) = max
   if (j == max) go to 50
   do j1 = j,nclblk
      swap = block(max,j1)
      block(max,j1) = block(j,j1)
      block(j,j1) = swap
   end do
50 continue
   if (j == nrwblk) return
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    COMPUTE THE MULTIPLIERS
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   rowpiv = block(j,j)
   do i1 = jplus1,nrwblk
      block(i1,j) = block(i1,j)/rowpiv
   end do
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    PERFORM ROW ELIMINATIONS WITH COLUMN INDEXING
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   do j1 = jplus1,nclblk
      do l1 = jplus1,nrwblk
         block(l1,j1) = block(l1,j1) - block(l1,j)*block(j,j1)
      end do
   end do
end do
return
100 continue
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       matrix is singular - Set iflag = -1.
!       C                            TERMINATE AT 90.
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
iflag = -1
end subroutine arcepr

pure subroutine arcepc(topblk, nrwtop, novrlp, botblk, nrwbot, nclpiv, &
   & pivot, pivmax, iflag)
implicit none
integer, intent(inout) :: iflag
integer, intent(in) :: nclpiv, novrlp, nrwbot, nrwtop
real, intent(inout) :: topblk(nrwtop,novrlp), &
   & botblk(nrwbot,novrlp)
real, intent(inout) :: pivmax
integer, intent(inout) :: pivot(nrwtop)
integer :: i, i1, i2, iplus1, j, j1, jplus1, l1, max
real :: colmax, colmlt, tempiv, swap
!
!***************************************************************
!
!     A R C E P C performs nclpiv column eliminations on the
!                 matrices topblk and BOTBLK
!***************************************************************
!
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       PERFORM THE COLUMN ELIMINATIONS ON A LOOP.
!       C
!       ccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
do j = 1,nclpiv
   i = nrwtop - nclpiv + j
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    DETERMINE COLUMN PIVOT AND PIVOT INDEX
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   max = j
   colmax = abs(topblk(i,j))
   if (j == novrlp) go to 30
   jplus1 = j + 1
   do j1 = jplus1,novrlp
      tempiv = abs(topblk(i,j1))
      if (tempiv <= colmax) go to 10
      colmax = tempiv
      max = j1
10    continue
   end do
30 continue
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    TEST FOR SINGULARITY ...
!          C
!          C             IF SINGULAR THEN TERMINATE AT 110,
!          C                         ELSE CONTINUE.
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (pivmax + colmax == pivmax) go to 120
   pivmax = amax1(pivmax,colmax)
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    IF NECESSARY INTERCHANGE COLUMNS
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   pivot(j) = max
   if (j == max) go to 60
   do i1 = i,nrwtop
      swap = topblk(i1,j)
      topblk(i1,j) = topblk(i1,max)
      topblk(i1,max) = swap
   end do
   do i2 = 1,nrwbot
      swap = botblk(i2,j)
      botblk(i2,j) = botblk(i2,max)
      botblk(i2,max) = swap
   end do
60 continue
   if (j == novrlp) return
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    COMPUTE MULTIPLIERS AND PERFORM COLUMN
!          C            ELIMINATION
!          C
!          cccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   do j1 = jplus1,novrlp
      colmlt = topblk(i,j1)/topblk(i,j)
      topblk(i,j1) = colmlt
      if (i == nrwtop) go to 80
      iplus1 = i + 1
      do l1 = iplus1,nrwtop
         topblk(l1,j1) = topblk(l1,j1) - colmlt*topblk(l1,j)
      end do
80    continue
      do l1 = 1,nrwbot
         botblk(l1,j1) = botblk(l1,j1) - colmlt*botblk(l1,j)
      end do
   end do
end do
return
120 continue
!
!       Ccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       matrix is singular - Set iflag = -1.
!       C                            TERMINATE AT 110.
!       C
!       ccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
iflag = -1
end subroutine arcepc

subroutine arcesl(array, mtrstr, nmblks, pivot, b, x)
implicit none
integer :: mtrstr(3,*)
integer, intent(in) :: nmblks
real :: array(*)
real, intent(inout) :: b(*), x(*)
integer, intent(in) :: pivot(*)
integer :: indexa, indpiv, k, ll, nclblk, nclpiv, novrlp, nrwblk, &
   & nrwpiv
!
!***************************************************************
!
!  A R C E S L  supervises the solution of the linear system
!                          A*x = b
!  using the decomposition of the matrix  A  already generated
!  in  A R C E D C.  it involves two loops, the forward loop,
!  consisting of forward solution, forward modification, and
!  forward elimination, and the backward loop, consisting of
!  backward solution, backward modification, and backward
!  elimination.
!
!***************************************************************
!
!               *****  PARAMETERS  *****
!
!       *** On entry ...
!
!                array - real(NUMELS)
!                         where
!                          numels = sum(mtrstr(1,k)*mtrstr(2,k),
!                               k=1,nmblks).
!                         Output from A R C E D C
!
!               mtrstr - INTEGER(3,nmblks)
!                         describes the block structure of  A ...
!                           mtrstr(1,k)  = Number of rows in
!                                            block k.
!                           mtrstr(2,k)  = Number of columns in
!                                            block k.
!                           mtrstr(3,k)  = Number of columns
!                                          overlapped by block k
!                                          and block (k+1).
!
!                        The linear system is of order
!                           n  = sum(mtrstr(1,k),k=1,nmblks)
!
!               nmblks - INTEGER
!                         total number of blocks in  A
!
!                pivot - Integer(N)
!                         output from A R C E D C
!
!                    b - real(N)
!                         the right hand side vector
!
!                    x - real(N)
!                         work space
!
!       *** On return  ...
!
!
!                    x - real(N)
!                         the solution vector
!
!***************************************************************
!
!               *****  Auxiliary programs  *****
!
!
!       arcefs - Performs forward solution step
!
!       arcefm - Performs forward modification step
!
!       arcefe - Performs forward elimination step
!
!       arcebs - Performs backward solution step
!
!       arcebm - Performs backward modification step
!
!       arcebe - Performs backward elimination step
!
!***************************************************************
!
indpiv = 1
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C  internal parameters ...
!       C
!       C       indexa  POINTER TO 1ST ELEMENT OF BLOCK OF A.
!       C
!       C       INDEXB  POINTER TO 1ST ELEMENT OF BLOCK OF b.
!       C
!       C       indpiv,nrwblk,NRWPIV,nclblk,nclpiv,novrlp
!       C       ARE AS IN arcedc.
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
indexa = 1
nrwblk = mtrstr(1,1)
nclblk = mtrstr(2,1)
novrlp = mtrstr(3,1)
nrwpiv = nclblk - novrlp
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       CALL arcefe TO PERFORM FORWARD ELIMINATION.
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
if (nrwpiv > 0) call arcefe(array(indexa), nrwblk, nrwpiv, &
   & pivot(indpiv), b(indpiv))
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       FORWARD LOOP
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
do k = 2,nmblks
   indexa = indexa + nrwblk*nrwpiv
   nclpiv = nrwblk - nrwpiv
   indpiv = indpiv + nrwpiv
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    CALL arcefs TO PERFORM FORWARD SOLUTION
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (nclpiv > 0) call arcefs(array(indexa), nrwblk, nclpiv, &
      & novrlp, b(indpiv), x(indpiv))
   indexa = indexa + novrlp*nrwblk
   nrwblk = mtrstr(1,k)
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    CALL arcefm TO PERFORM FORWARD MODIFICATION
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (nclpiv > 0) call arcefm(array(indexa), nrwblk, nclpiv, &
      & b(indpiv), x(indpiv))
   indexa = indexa + nrwblk*nclpiv
   nclblk = mtrstr(2,k) - nclpiv
   novrlp = mtrstr(3,k)
   nrwpiv = nclblk - novrlp
   indpiv = indpiv + nclpiv
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    CALL arcefe TO PERFORM FORWARD ELIMINATION
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (nrwpiv > 0) call arcefe(array(indexa), nrwblk, nrwpiv, &
      & pivot(indpiv), b(indpiv))
end do
!     indexb = indpiv + nrwpiv - 1
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       BACKWARD LOOP
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
do ll = 2,nmblks
   k = nmblks - ll + 1
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    CALL arcebm TO PERFORM BACKWARD MODIFICATION
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (nrwpiv == 0) go to 20
   if (nrwpiv /= nclblk) call arcebm(array(indexa), nrwblk, &
      & nclblk, nrwpiv, b(indpiv), x(indpiv))
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    CALL arcebs TO PERFORM BACKWARD SOLUTION
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   call arcebs(array(indexa), nrwblk, nclblk, nrwpiv, b(indpiv), &
      & x(indpiv))
20 continue
   indexa = indexa - nrwblk*nclpiv
   nrwblk = mtrstr(1,k)
   novrlp = mtrstr(3,k)
   indexa = indexa - nrwblk*novrlp
   indpiv = indpiv - nclpiv
!
!          Ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!          C
!          C    CALL arcebe TO PERFORM BACKWARD ELIMINATION
!          C
!          ccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
   if (nclpiv > 0) call arcebe(array(indexa), nrwblk, nclpiv, &
      & novrlp, pivot(indpiv), x(indpiv))
   nrwpiv = nrwblk - nclpiv
   nclblk = novrlp + nrwpiv
   indexa = indexa - nrwblk*nrwpiv
   indpiv = indpiv - nrwpiv
   nclpiv = mtrstr(2,k) - nclblk
end do
!
!       Cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!       C
!       C       IF ROW ELIMINATIONS WERE DONE IN TOPBLOCK, CALL
!       C       arcebs TO PERFORM BACKWARD SOLUTION
!       C
!       cccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
if (nrwpiv == 0) return
if (nrwpiv /= nclblk) call arcebm(array(indexa), nrwblk, nclblk, &
   & nrwpiv, b(indpiv), x(indpiv))
call arcebs(array(indexa), nrwblk, nclblk, nrwpiv, b(indpiv), &
   & x(indpiv))
end subroutine arcesl

subroutine arcefs(block, nrwblk, nclpiv, novrlp, b, x)
implicit none
integer, intent(in) :: nclpiv, novrlp, nrwblk
real :: block(nrwblk,novrlp)
real, intent(inout) :: b(*), x(*)
integer :: i, iplusl, j, jplusl, l, long
real :: xj
!
!***************************************************************
!
!  A R C E F S performs the forward solution step in the
!  solution phase of  A R C E C O.
!
!***************************************************************
!
do j = 1,nclpiv
   i = nrwblk - nclpiv + j
   x(j) = b(j)/block(i,j)
   if (i == nrwblk) return
   long = nrwblk - i
   xj = x(j)
   do l = 1,long
      iplusl = i + l
      jplusl = j + l
      b(jplusl) = b(jplusl) - block(iplusl,j)*xj
   end do
end do
end subroutine arcefs

subroutine arcefm(block, nrwblk, nclpiv, b, x)
implicit none
integer, intent(in) :: nclpiv, nrwblk
real :: block(nrwblk,nclpiv)
real, intent(inout) :: b(*)
real :: x(*)
integer :: j, l, nclpvl
real :: xj
!
!***************************************************************
!
!  A R C E F M  performs the forward modification step in the
!  solution phase of  A R C E C O.
!
!***************************************************************
!
do j = 1,nclpiv
   xj = x(j)
   do l = 1,nrwblk
      nclpvl = nclpiv + l
      b(nclpvl) = b(nclpvl) - block(l,j)*xj
   end do
end do
end subroutine arcefm

subroutine arcefe(block, nrwblk, nrwpiv, pivot, b)
implicit none
integer, intent(in) :: nrwblk, nrwpiv
real :: block(nrwblk,nrwpiv)
real, intent(inout) :: b(*)
integer, intent(in) :: pivot(nrwpiv)
integer :: i, iplus1, l, pivoti
real :: bi, swap
!
!***************************************************************
!
!  A R C E F E  performs the forward elimination step in the
!  solution phase of  A R C E C O.
!
!***************************************************************
!
do i = 1,nrwpiv
   pivoti = pivot(i)
   if (pivoti == i) go to 10
   swap = b(i)
   b(i) = b(pivoti)
   b(pivoti) = swap
10 continue
   if (i == nrwblk) return
   bi = b(i)
   iplus1 = i + 1
   do l = iplus1,nrwblk
      b(l) = b(l) - block(l,i)*bi
   end do
end do
end subroutine arcefe

subroutine arcebs(block, nrwblk, nclblk, nrwpiv, b, x)
implicit none
integer, intent(in) :: nclblk, nrwblk, nrwpiv
real :: block(nrwblk,nclblk)
real, intent(inout) :: b(*), x(*)
integer :: j, jmin1, l, nj
real :: xj
!
!***************************************************************
!
!  A R C E b S performs the backward solution step in the
!  solution phase of  A R C E C O.
!
!***************************************************************
!
do nj = 1,nrwpiv
   j = nrwpiv - nj + 1
   x(j) = b(j)/block(j,j)
   if (j == 1) return
   jmin1 = j - 1
   xj = x(j)
   do l = 1,jmin1
      b(l) = b(l) - block(l,j)*xj
   end do
end do
end subroutine arcebs

subroutine arcebm(block, nrwblk, nclblk, nrwpiv, b, x)
implicit none
integer, intent(in) :: nclblk, nrwblk, nrwpiv
real :: block(nrwblk,nclblk)
real, intent(inout) :: b(*)
real :: x(*)
integer :: j, l, nrwpv1
real :: xj
!
!***************************************************************
!
!  A R C E b M  performs the backward modification step in the
!  solution phase of  A R C E C O.
!
!***************************************************************
!
nrwpv1 = nrwpiv + 1
do j = nrwpv1,nclblk
   xj = x(j)
   do l = 1,nrwpiv
      b(l) = b(l) - block(l,j)*xj
   end do
end do
end subroutine arcebm

subroutine arcebe(block, nrwblk, nclpiv, novrlp, pivot, x)
implicit none
integer, intent(in) :: nclpiv, novrlp, nrwblk
real :: block(nrwblk,novrlp)
real, intent(inout) :: x(*)
integer, intent(in) :: pivot(nrwblk)
integer :: i, j, j1, jplus1, nj, pivotj
real :: dotprd, swap
!
!***************************************************************
!
!  A R C E B E performs the backward elimination step in the
!  solution phase of  A R C E C O.
!
!***************************************************************
!
do nj = 1,nclpiv
   j = nclpiv + 1 - nj
   i = nrwblk + 1 - nj
   dotprd = x(j)
   if (j == novrlp) go to 20
   jplus1 = j + 1
   do j1 = jplus1,novrlp
      dotprd = dotprd - x(j1)*block(i,j1)
10    continue
   end do
20 continue
   x(j) = dotprd
   pivotj = pivot(j)
   if (pivotj == j) go to 30
   swap = x(pivotj)
   x(pivotj) = x(j)
   x(j) = swap
30 continue
40 continue
end do
end subroutine arcebe

subroutine btslv(mo, m, n, a, b, c, x, ip, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: mo, m
integer :: n
integer, intent(inout) :: ip(m,n)
real, intent(inout) :: a(m,m,n), b(m,m,n), c(m,m,n), x(*)
!
!     Decompose the coefficient matrix
!
if (mo /= 0) go to 10
call decbt(m, n, a, b, c, ip, ierr)
if (ierr /= 0) return
!
!     Solve the system of equations
!
10 call solbt(m, n, a, b, c, x, ip)
end subroutine btslv

subroutine decbt(m, n, a, b, c, ip, ier)
implicit none
integer, intent(in) :: m
integer :: n
integer, intent(inout) :: ip(m,n), ier
real, intent(inout) :: a(m,m,n), b(m,m,n), c(m,m,n)
integer :: nm1, nm2, km1, i, j, k, l
real :: dp
!-----------------------------------------------------------------------
! Block-tridiagonal matrix decomposition routine.
! Written by A. C. Hindmarsh.
! Latest revision January 26, 1977  (AG)
! reference.. UCID-30150
!             solution of block-tridiagonal systems of linear
!             algebraic equations
!             A.C. Hindmarsh
!             February 1977
! the input matrix contains three blocks of elements in each block-row,
! including blocks in the (1,3) and (n,n-2) block positions.
! decbt uses block Gauss elimination and subroutines dec and sol
! for solution of blocks.  Partial pivoting is done within
! block-rows only.
! Input..
!     m = Order of each block.
!     n = Number of blocks in each direction of the matrix.
!         n must be 4 or more.  The complete matrix HAS order m*n.
!     a = m by m by n array containing diagonal blocks.
!         a(i,j,k) contains the (i,j) element of the k-TH block.
!     b = m by m by n array containing the super-diagonal blocks
!         (in b(*,*,k) for k = 1,...,n-1) and the block in the (n,n-2)
!         block position (in b(*,*,n)).
!     c = m by m by n array containing the subdiagonal blocks
!         (in c(*,*,k) for k = 2,3,...,n) and the block in the
!         (1,3) block position (in c(*,*,1)).
!    ip = Integer array of length m*n for working storage.
! Output..
! A,b,c = m by m by n arrays containing the block LU decomposition
!         of the input matrix.
!    ip = m by n array of pivot information.  ip(*,k) contains
!         information for the k-TH DIGONAL block.
!   ier = 0  If no trouble occurred, or
!       = -1 If the input value of m or n was illegal, or
!       = k  if a singular matrix was found in the k-TH diagonal block.
! Use solbt to solve the associated linear system.
! decbt calls subroutines  dec(m,M0,a,ip,ier)  and  sol(m,M0,a,Y,ip)
! for solution of m by m linear systems.
!-----------------------------------------------------------------------
!
if (m < 1 .or. n < 4) go to 210
nm1 = n - 1
nm2 = n - 2
! Process the first block-row. -----------------------------------------
call dec(m, m, a, ip, ier)
k = 1
if (ier /= 0) go to 200
do j = 1,m
   call sol(m, m, a, b(1,j,1), ip)
   call sol(m, m, a, c(1,j,1), ip)
end do
! Adjust b(*,*,2). -----------------------------------------------------
do j = 1,m
   do i = 1,m
      dp = 0.
      do l = 1,m
20       dp = dp + c(i,l,2)*c(l,j,1)
      end do
      b(i,j,2) = b(i,j,2) - dp
   end do
end do
! Main loop.  Process block-rows 2 to n-1. -----------------------------
do k = 2,nm1
   km1 = k - 1
   do j = 1,m
      do i = 1,m
         dp = 0.
         do l = 1,m
50          dp = dp + c(i,l,k)*b(l,j,km1)
         end do
         a(i,j,k) = a(i,j,k) - dp
      end do
   end do
   call dec(m, m, a(1,1,k), ip(1,k), ier)
   if (ier /= 0) go to 200
   do j = 1,m
80    call sol(m, m, a(1,1,k), b(1,j,k), ip(1,k))
   end do
end do
! Process last block-row and return. -----------------------------------
do j = 1,m
   do i = 1,m
      dp = 0.
      do l = 1,m
110      dp = dp + b(i,l,n)*b(l,j,nm2)
      end do
      c(i,j,n) = c(i,j,n) - dp
   end do
end do
do j = 1,m
   do i = 1,m
      dp = 0.
      do l = 1,m
140      dp = dp + c(i,l,n)*b(l,j,nm1)
      end do
      a(i,j,n) = a(i,j,n) - dp
   end do
end do
call dec(m, m, a(1,1,n), ip(1,n), ier)
k = n
if (ier /= 0) go to 200
return
! Error returns. -------------------------------------------------------
200 ier = k
return
210 ier = -1
!-----------------------  End of subroutine decbt  ---------------------
end subroutine decbt

subroutine solbt(m, n, a, b, c, y, ip)
implicit none
integer, intent(in) :: m
integer :: n, ip(m,n)
real :: a(m,m,n)
real, intent(in) :: b(m,m,n), c(m,m,n)
real, intent(inout) :: y(m,n)
integer :: kb, kp1, nm1, nm2, km1, i, j, k
real :: dp
!-----------------------------------------------------------------------
! Solution of block-tridiagonal linear system.
! Coefficient matrix must have been previously processed by decbt.
! m, n, A, b, c, and ip  must not have been changed since call to decbt.
! Written by A. C. Hindmarsh.
! Input..
!     m = Order of each block.
!     n = Number of blocks in each direction of matrix.
! A,b,c = m by m by n arrays containing block LU decomposition
!         of coefficient matrix from decbt.
!    ip = m by n integer array of pivot information from decbt.
!     y = Array of length m*n containing the right-hand side vector
!         (treated as an m by n array here).
! Output..
!     y = Solution vector, of length m*n.
! solbt makes calls to subroutine sol(m,M0,a,y,ip)
! for solution of m by m linear systems.
!-----------------------------------------------------------------------
!
nm1 = n - 1
nm2 = n - 2
! Forward solution sweep. ----------------------------------------------
call sol(m, m, a, y, ip)
do k = 2,nm1
   km1 = k - 1
   do i = 1,m
      dp = 0.
      do j = 1,m
10       dp = dp + c(i,j,k)*y(j,km1)
      end do
      y(i,k) = y(i,k) - dp
   end do
   call sol(m, m, a(1,1,k), y(1,k), ip(1,k))
end do
do i = 1,m
   dp = 0.
   do j = 1,m
40    dp = dp + c(i,j,n)*y(j,nm1) + b(i,j,n)*y(j,nm2)
   end do
   y(i,n) = y(i,n) - dp
end do
call sol(m, m, a(1,1,n), y(1,n), ip(1,n))
! Backward solution sweep. ---------------------------------------------
do kb = 1,nm1
   k = n - kb
   kp1 = k + 1
   do i = 1,m
      dp = 0.
      do j = 1,m
60       dp = dp + b(i,j,k)*y(j,kp1)
      end do
      y(i,k) = y(i,k) - dp
   end do
end do
do i = 1,m
   dp = 0.
   do j = 1,m
90    dp = dp + c(i,j,1)*y(j,3)
   end do
   y(i,1) = y(i,1) - dp
end do
!-----------------------  End of subroutine solbt  ---------------------
end subroutine solbt

subroutine smslv(mo,n,m,a,b,kb,det,rcond,inert,ierr,ipvt,wk)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: kb, m, mo, n
real, intent(inout) :: a(*), b(*)
real, intent(inout) :: det(2), rcond
real, intent(inout) :: wk(n)
integer, intent(inout) :: inert(3), ipvt(n)
integer :: j, job, onej
real :: t
!     ------------------
!     ------------------
!
!          Matrix factorization and computation of rcond
!
ierr = 0
call sspco(a,n,ipvt,rcond,wk)
t = 1.0 + rcond
if (t == 1.0) go to 30
!
!                  Solution of the equation AX=b
!
if (m < 1) go to 20
onej = 1
do j = 1,m
   call sspsl(a,n,ipvt,b(onej))
10 onej = onej + kb
end do
!
!             Calculation of det and the inverse of A
!
20 job = 110
if (mo == 0) job = 111
call sspdi(a,n,ipvt,det,inert,wk,job)
return
!
!                  The problem cannot be solved
!
30 ierr = 1
end subroutine smslv

pure subroutine sspco(ap,n,kpvt,rcond,z)
implicit none
integer, intent(in) :: n
integer, intent(inout) :: kpvt(*)
real, intent(inout) :: ap(*), z(*)
real, intent(inout) :: rcond
real :: ak, akm1, bk, bkm1, denom, ek, t, anorm, s, ynorm
integer :: i, ij, ik, ikm1, ikp1, info, j, jm1, j1, k, kk, km1k, km1km1, kp, kps, ks
interface
   pure function sasum(n,sx,incx)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real :: sasum
   end function sasum
   pure subroutine saxpy(n,sa,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine saxpy
   pure function sdot(n,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(in) :: sy(*)
      integer, intent(in) :: incy
      real :: sdot
   end function sdot
   pure subroutine sscal(n,sa,sx,incx)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(inout) :: sx(*)
      integer, intent(in) :: incx
   end subroutine sscal
   pure subroutine sspfa(ap,n,kpvt,info)
      implicit none
      real, intent(inout) :: ap(*)
      integer, intent(in) :: n
      integer, intent(inout) :: kpvt(*)
      integer, intent(out) :: info
   end subroutine sspfa
end interface
!
!     sspco factors a real symmetric matrix stored in packed
!     form by elimination with symmetric pivoting and estimates
!     the condition of the matrix.
!
!     If  rcond  is not needed, sspfa is slightly faster.
!     To solve  A*X = B , follow sspco by sspsl.
!     To compute  inverse(A)*C , follow sspco by sspsl.
!     To compute  inverse(A) , follow sspco by sspdi.
!     To compute  determinant(A) , follow sspco by sspdi.
!     To compute  inertia(A), follow sspco by sspdi.
!
!     On entry
!
!        ap      real (n*(n+1)/2)
!                the packed form of A symmetric matrix  A .  The
!                columns of the upper triangle are stored sequentially
!                in a one-dimensional array of length  n*(n+1)/2 .
!                See comments below for details.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!     Output
!
!        ap      A BLOCK DIAGONAL MATRIX AND THE MULTIPLIERS WHICH
!                were used to obtain it stored in packed form.
!                The factorization can be written  A = U*D*trans(U)
!                where  U  is a product of permutation and unit
!                upper triangular matrices , trans(U) is the
!                transpose of  U , and  D  is block diagonal
!                with 1 by 1 and 2 by 2 blocks.
!
!        kpvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        rcond   REAL
!                an estimate of the reciprocal condition of  A .
!                For the system  A*X = B , relative perturbations
!                in  A  and  B  of size  epsilon  may cause
!                relative perturbations in  X  of size  epsilon/rcond .
!                If  rcond  is so small that the logical expression
!                           1.0 + rcond .EQ. 1.0
!                is true, then  A  may be singular to working
!                precision.  In particular,  rcond  is zero  if
!                exact singularity is detected or the estimate
!                underflows.
!
!        z       real(n)
!                a work vector whose contents are usually unimportant.
!                If  A  is close to a singular matrix, then  z  is
!                an approximate null vector in the sense that
!                norm(a*z) = rcond*norm(a)*norm(z) .
!
!     Packed storage
!
!          The following program segment will pack the upper
!          triangle of a symmetric matrix.
!
!                k = 0
!                do 20 j = 1, n
!                   do 10 i = 1, j
!                      k = k + 1
!                      ap(k) = a(i,j)
!             10    continue
!             20 continue
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     LINPACK sspfa
!     BLAS saxpy,sdot,sscal,sasum
!     Fortran abs,AMAX1,IABS,sign
!
!     Internal variables
!
!
!
!     Find norm of a using only upper half
!
j1 = 1
do j = 1, n
   z(j) = sasum(j,ap(j1),1)
   ij = j1
   j1 = j1 + j
   jm1 = j - 1
   if (jm1 < 1) go to 20
   do i = 1, jm1
      z(i) = z(i) + abs(ap(ij))
      ij = ij + 1
   end do
20 continue
end do
anorm = 0.0e0
do j = 1, n
   anorm = max(anorm,z(j))
end do
!
!     Factor
!
call sspfa(ap,n,kpvt,info)
!
!     rcond = 1/(norm(A)*(estimate of norm(inverse(A)))) .
!     ESTIMATE = NORM(z)/NORM(Y) WHERE  A*z = Y  AND  A*Y = E .
!     The components of  E  are chosen to cause maximum local
!     growth in the elements of W  where  U*D*W = E .
!     The vectors are frequently rescaled to avoid overflow.
!
!     SOLVE U*D*W = E
!
ek = 1.0e0
do j = 1, n
   z(j) = 0.0e0
end do
k = n
ik = (n*(n - 1))/2
60 if (k == 0) go to 120
kk = ik + k
ikm1 = ik - (k - 1)
ks = 1
if (kpvt(k) < 0) ks = 2
kp = abs(kpvt(k))
kps = k + 1 - ks
if (kp == kps) go to 70
t = z(kps)
z(kps) = z(kp)
z(kp) = t
70 continue
if (z(k) /= 0.0e0) ek = sign(ek,z(k))
z(k) = z(k) + ek
call saxpy(k - ks,z(k),ap(ik + 1),1,z(1),1)
if (ks == 1) go to 80
if (z(k - 1) /= 0.0e0) ek = sign(ek,z(k - 1))
z(k - 1) = z(k - 1) + ek
call saxpy(k - ks,z(k - 1),ap(ikm1 + 1),1,z(1),1)
80 continue
if (ks == 2) go to 100
if (abs(z(k)) <= abs(ap(kk))) go to 90
s = abs(ap(kk))/abs(z(k))
call sscal(n,s,z,1)
ek = s*ek
90 continue
if (ap(kk) /= 0.0e0) z(k) = z(k)/ap(kk)
if (ap(kk) == 0.0e0) z(k) = 1.0e0
go to 110
100 continue
km1k = ik + k - 1
km1km1 = ikm1 + k - 1
ak = ap(kk)/ap(km1k)
akm1 = ap(km1km1)/ap(km1k)
bk = z(k)/ap(km1k)
bkm1 = z(k - 1)/ap(km1k)
denom = ak*akm1 - 1.0e0
z(k) = (akm1*bk - bkm1)/denom
z(k - 1) = (ak*bkm1 - bk)/denom
110 continue
k = k - ks
ik = ik - k
if (ks == 2) ik = ik - (k + 1)
go to 60
120 continue
s = 1.0e0/sasum(n,z,1)
call sscal(n,s,z,1)
!
!     SOLVE TRANS(U)*Y = W
!
k = 1
ik = 0
130 if (k > n) go to 160
ks = 1
if (kpvt(k) < 0) ks = 2
if (k == 1) go to 150
z(k) = z(k) + sdot(k - 1,ap(ik + 1),1,z(1),1)
ikp1 = ik + k
if (ks == 2) &
   & z(k + 1) = z(k + 1) + sdot(k - 1,ap(ikp1 + 1),1,z(1),1)
kp = abs(kpvt(k))
if (kp == k) go to 140
t = z(k)
z(k) = z(kp)
z(kp) = t
140 continue
150 continue
ik = ik + k
if (ks == 2) ik = ik + (k + 1)
k = k + ks
go to 130
160 continue
s = 1.0e0/sasum(n,z,1)
call sscal(n,s,z,1)
!
ynorm = 1.0e0
!
!     SOLVE U*D*V = Y
!
k = n
ik = n*(n - 1)/2
170 if (k == 0) go to 230
kk = ik + k
ikm1 = ik - (k - 1)
ks = 1
if (kpvt(k) < 0) ks = 2
if (k == ks) go to 190
kp = abs(kpvt(k))
kps = k + 1 - ks
if (kp == kps) go to 180
t = z(kps)
z(kps) = z(kp)
z(kp) = t
180 continue
call saxpy(k - ks,z(k),ap(ik + 1),1,z(1),1)
if (ks == 2) call saxpy(k - ks,z(k - 1),ap(ikm1 + 1),1,z(1),1)
190 continue
if (ks == 2) go to 210
if (abs(z(k)) <= abs(ap(kk))) go to 200
s = abs(ap(kk))/abs(z(k))
call sscal(n,s,z,1)
ynorm = s*ynorm
200 continue
if (ap(kk) /= 0.0e0) z(k) = z(k)/ap(kk)
if (ap(kk) == 0.0e0) z(k) = 1.0e0
go to 220
210 continue
km1k = ik + k - 1
km1km1 = ikm1 + k - 1
ak = ap(kk)/ap(km1k)
akm1 = ap(km1km1)/ap(km1k)
bk = z(k)/ap(km1k)
bkm1 = z(k - 1)/ap(km1k)
denom = ak*akm1 - 1.0e0
z(k) = (akm1*bk - bkm1)/denom
z(k - 1) = (ak*bkm1 - bk)/denom
220 continue
k = k - ks
ik = ik - k
if (ks == 2) ik = ik - (k + 1)
go to 170
230 continue
s = 1.0e0/sasum(n,z,1)
call sscal(n,s,z,1)
ynorm = s*ynorm
!
!     SOLVE TRANS(U)*z = V
!
k = 1
ik = 0
240 if (k > n) go to 270
ks = 1
if (kpvt(k) < 0) ks = 2
if (k == 1) go to 260
z(k) = z(k) + sdot(k - 1,ap(ik + 1),1,z(1),1)
ikp1 = ik + k
if (ks == 2) &
   & z(k + 1) = z(k + 1) + sdot(k - 1,ap(ikp1 + 1),1,z(1),1)
kp = abs(kpvt(k))
if (kp == k) go to 250
t = z(k)
z(k) = z(kp)
z(kp) = t
250 continue
260 continue
ik = ik + k
if (ks == 2) ik = ik + (k + 1)
k = k + ks
go to 240
270 continue
!     MAKE ZNORM = 1.0
s = 1.0e0/sasum(n,z,1)
call sscal(n,s,z,1)
ynorm = s*ynorm
!
if (anorm /= 0.0e0) rcond = ynorm/anorm
if (anorm == 0.0e0) rcond = 0.0e0
end subroutine sspco

pure subroutine sspfa(ap,n,kpvt,info)
implicit none
integer, intent(in) :: n
integer, intent(inout) :: kpvt(*)
integer, intent(out) :: info
real, intent(inout) :: ap(*)
real :: ak, akm1, bk, bkm1, denom, mulk, mulkm1, t, absakk, alpha, colmax, rowmax
integer :: ij, ijj, ik, ikm1, im, imax, imaxp1, imim, imj, imk, j, jj, jk, jkm1, jmax, jmim, k, kk, km1, km1k, km1km1, km2, kstep
logical :: swap
interface
   pure function isamax(n,sx,incx)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      integer :: isamax
   end function isamax
   pure subroutine saxpy(n,sa,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine saxpy
   pure subroutine sswap(n,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(inout) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine sswap
end interface
!
!     sspfa factors a real symmetric matrix stored in
!     packed form by elimination with symmetric pivoting.
!
!     To solve  A*X = B , follow sspfa by sspsl.
!     To compute  inverse(A)*C , follow sspfa by sspsl.
!     To compute  determinant(A) , follow sspfa by sspdi.
!     To compute  inertia(A) , follow sspfa by sspdi.
!     To compute  inverse(A) , follow sspfa by sspdi.
!
!     On entry
!
!        ap      real (n*(n+1)/2)
!                the packed form of A symmetric matrix  A .  The
!                columns of the upper triangle are stored sequentially
!                in a one-dimensional array of length  n*(n+1)/2 .
!                See comments below for details.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!     Output
!
!        ap      A BLOCK DIAGONAL MATRIX AND THE MULTIPLIERS WHICH
!                were used to obtain it stored in packed form.
!                The factorization can be written  A = U*D*trans(U)
!                where  U  is a product of permutation and unit
!                upper triangular matrices , trans(U) is the
!                transpose of  U , and  D  is block diagonal
!                with 1 by 1 and 2 by 2 blocks.
!
!        kpvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        INFO    INTEGER
!                = 0  Normal value.
!                = k  if the k-TH pivot block is singular. This is
!                     not an error condition for this subroutine,
!                     but it does indicate that sspsl or sspdi may
!                     divide by zero if called.
!
!     Packed storage
!
!          The following program segment will pack the upper
!          triangle of a symmetric matrix.
!
!                k = 0
!                do 20 j = 1, n
!                   do 10 i = 1, j
!                      k = k + 1
!                      ap(k)  = a(i,j)
!             10    continue
!             20 continue
!
!     LINPACK. This version dated 08/14/78 .
!     James bunch, univ. Calif. San diego, argonne nat. Lab.
!
!     Subroutines and functions
!
!     BLAS saxpy,sswap,isamax
!     Fortran abs,AMAX1,sqrt
!
!     Internal variables
!
!
!
!     Initialize
!
!     alpha is used in choosing pivot block SIZE.
alpha = (1.0e0 + sqrt(17.0e0))/8.0e0
!
info = 0
!
!     Main loop on k, which goes from n to 1.
!
k = n
ik = (n*(n - 1))/2
10 continue
!
!        Leave the loop if k=0 Or k=1.
!
!     ...Exit
if (k == 0) go to 200
if (k > 1) go to 20
kpvt(1) = 1
if (ap(1) == 0.0e0) info = 1
!     ......Exit
go to 200
20 continue
!
!        This section of code determines the kind of
!        elimination to be performed.  When it is completed,
!        KSTEP will be set to the size of the pivot block, and
!        swap will be set to .TRUE. if an interchange is
!        required.
!
km1 = k - 1
kk = ik + k
absakk = abs(ap(kk))
!
!        Determine the largest off-diagonal element in
!        column k.
!
imax = isamax(k - 1,ap(ik + 1),1)
imk = ik + imax
colmax = abs(ap(imk))
if (absakk < alpha*colmax) go to 30
kstep = 1
swap = .false.
go to 90
30 continue
!
!           Determine the largest off-diagonal element in
!           row imax.
!
rowmax = 0.0e0
imaxp1 = imax + 1
im = imax*(imax - 1)/2
imj = im + 2*imax
do j = imaxp1, k
   rowmax = max(rowmax,abs(ap(imj)))
   imj = imj + j
end do
if (imax == 1) go to 50
jmax = isamax(imax - 1,ap(im + 1),1)
jmim = jmax + im
rowmax = max(rowmax,abs(ap(jmim)))
50 continue
imim = imax + im
if (abs(ap(imim)) < alpha*rowmax) go to 60
kstep = 1
swap = .true.
go to 80
60 continue
if (absakk < alpha*colmax*(colmax/rowmax)) go to 70
kstep = 1
swap = .false.
go to 80
70 continue
kstep = 2
swap = imax /= km1
80 continue
90 continue
if (max(absakk,colmax) /= 0.0e0) go to 100
!
!           Column k is zero.  Set info and iterate the loop.
!
kpvt(k) = k
info = k
go to 190
100 continue
if (kstep == 2) go to 140
!
!           1 X 1 pivot block.
!
if (.not.swap) go to 120
!
!              Perform an interchange.
!
call sswap(imax,ap(im + 1),1,ap(ik + 1),1)
imj = ik + imax
do jj = imax, k
   j = k + imax - jj
   jk = ik + j
   t = ap(jk)
   ap(jk) = ap(imj)
   ap(imj) = t
   imj = imj - (j - 1)
end do
120 continue
!
!           Perform the elimination.
!
ij = ik - (k - 1)
do jj = 1, km1
   j = k - jj
   jk = ik + j
   mulk = -ap(jk)/ap(kk)
   t = mulk
   call saxpy(j,t,ap(ik + 1),1,ap(ij + 1),1)
   ijj = ij + j
   ap(jk) = mulk
   ij = ij - (j - 1)
end do
!
!           Set the pivot array.
!
kpvt(k) = k
if (swap) kpvt(k) = imax
go to 190
140 continue
!
!           2 X 2 pivot block.
!
km1k = ik + k - 1
ikm1 = ik - (k - 1)
if (.not.swap) go to 160
!
!              Perform an interchange.
!
call sswap(imax,ap(im + 1),1,ap(ikm1 + 1),1)
imj = ikm1 + imax
do jj = imax, km1
   j = km1 + imax - jj
   jkm1 = ikm1 + j
   t = ap(jkm1)
   ap(jkm1) = ap(imj)
   ap(imj) = t
   imj = imj - (j - 1)
end do
t = ap(km1k)
ap(km1k) = ap(imk)
ap(imk) = t
160 continue
!
!           Perform the elimination.
!
km2 = k - 2
if (km2 == 0) go to 180
ak = ap(kk)/ap(km1k)
km1km1 = ikm1 + k - 1
akm1 = ap(km1km1)/ap(km1k)
denom = 1.0e0 - ak*akm1
ij = ik - (k - 1) - (k - 2)
do jj = 1, km2
   j = km1 - jj
   jk = ik + j
   bk = ap(jk)/ap(km1k)
   jkm1 = ikm1 + j
   bkm1 = ap(jkm1)/ap(km1k)
   mulk = (akm1*bk - bkm1)/denom
   mulkm1 = (ak*bkm1 - bk)/denom
   t = mulk
   call saxpy(j,t,ap(ik + 1),1,ap(ij + 1),1)
   t = mulkm1
   call saxpy(j,t,ap(ikm1 + 1),1,ap(ij + 1),1)
   ap(jk) = mulk
   ap(jkm1) = mulkm1
   ijj = ij + j
   ij = ij - (j - 1)
end do
180 continue
!
!           Set the pivot array.
!
kpvt(k) = 1 - k
if (swap) kpvt(k) = -imax
kpvt(k - 1) = kpvt(k)
190 continue
ik = ik - (k - 1)
if (kstep == 2) ik = ik - (k - 2)
k = k - kstep
go to 10
200 continue
end subroutine sspfa

pure subroutine sspsl(ap,n,kpvt,b)
implicit none
integer, intent(in) :: n, kpvt(*)
real, intent(in) :: ap(*)
real, intent(inout) :: b(*)
real :: ak, akm1, bk, bkm1, denom, temp
integer :: ik, ikm1, ikp1, k, kk, km1k, km1km1, kp
interface
   pure subroutine saxpy(n,sa,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine saxpy
   pure function sdot(n,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(in) :: sy(*)
      integer, intent(in) :: incy
      real :: sdot
   end function sdot
end interface
!
!     SSISL solves the real symmetric system
!     A * X = b
!     using the factors computed by sspfa.
!
!     On entry
!
!        ap      real(n*(n+1)/2)
!                the output from sspfa.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!        kpvt    INTEGER(n)
!                the pivot vector from sspfa.
!
!        b       real(n)
!                the right hand side vector.
!
!     On return
!
!        b       THE SOLUTION VECTOR  X .
!
!     Error condition
!
!        A division by zero may occur if  sspco  has set RCOND .EQ. 0.0
!        or  sspfa  has set info .NE. 0  .
!
!     To compute  inverse(A) * C  where  C  is a matrix
!     with  P  columns
!           call sspfa(ap,n,kpvt,info)
!           if (info .ne. 0) go to ...
!           do 10 j = 1, p
!              call sspsl(ap,n,kpvt,c(1,j))
!        10 continue
!
!     LINPACK. This version dated 08/14/78 .
!     James bunch, univ. Calif. San diego, argonne nat. Lab.
!
!     Subroutines and functions
!
!     BLAS saxpy,sdot
!     FORTRAN IABS
!
!     Internal variables.
!
!
!     Loop backward applying the transformations and
!     D inverse to b.
!
k = n
ik = (n*(n - 1))/2
10 if (k == 0) go to 80
kk = ik + k
if (kpvt(k) < 0) go to 40
!
!           1 X 1 pivot block.
!
if (k == 1) go to 30
kp = kpvt(k)
if (kp == k) go to 20
!
!                 Interchange.
!
temp = b(k)
b(k) = b(kp)
b(kp) = temp
20 continue
!
!              Apply the transformation.
!
call saxpy(k - 1,b(k),ap(ik + 1),1,b(1),1)
30 continue
!
!           Apply D inverse.
!
b(k) = b(k)/ap(kk)
k = k - 1
ik = ik - k
go to 70
40 continue
!
!           2 X 2 pivot block.
!
ikm1 = ik - (k - 1)
if (k == 2) go to 60
kp = abs(kpvt(k))
if (kp == k - 1) go to 50
!
!                 Interchange.
!
temp = b(k - 1)
b(k - 1) = b(kp)
b(kp) = temp
50 continue
!
!              Apply the transformation.
!
call saxpy(k - 2,b(k),ap(ik + 1),1,b(1),1)
call saxpy(k - 2,b(k - 1),ap(ikm1 + 1),1,b(1),1)
60 continue
!
!           Apply D inverse.
!
km1k = ik + k - 1
kk = ik + k
ak = ap(kk)/ap(km1k)
km1km1 = ikm1 + k - 1
akm1 = ap(km1km1)/ap(km1k)
bk = b(k)/ap(km1k)
bkm1 = b(k - 1)/ap(km1k)
denom = ak*akm1 - 1.0e0
b(k) = (akm1*bk - bkm1)/denom
b(k - 1) = (ak*bkm1 - bk)/denom
k = k - 2
ik = ik - (k + 1) - k
70 continue
go to 10
80 continue
!
!     Loop forward applying the transformations.
!
k = 1
ik = 0
90 if (k > n) go to 160
if (kpvt(k) < 0) go to 120
!
!           1 X 1 pivot block.
!
if (k == 1) go to 110
!
!              Apply the transformation.
!
b(k) = b(k) + sdot(k - 1,ap(ik + 1),1,b(1),1)
kp = kpvt(k)
if (kp == k) go to 100
!
!                 Interchange.
!
temp = b(k)
b(k) = b(kp)
b(kp) = temp
100 continue
110 continue
ik = ik + k
k = k + 1
go to 150
120 continue
!
!           2 X 2 pivot block.
!
if (k == 1) go to 140
!
!              Apply the transformation.
!
b(k) = b(k) + sdot(k - 1,ap(ik + 1),1,b(1),1)
ikp1 = ik + k
b(k + 1) = b(k + 1) + sdot(k - 1,ap(ikp1 + 1),1,b(1),1)
kp = abs(kpvt(k))
if (kp == k) go to 130
!
!                 Interchange.
!
temp = b(k)
b(k) = b(kp)
b(kp) = temp
130 continue
140 continue
ik = ik + k + k + 1
k = k + 2
150 continue
go to 90
160 continue
end subroutine sspsl

subroutine sspdi(ap,n,kpvt,det,inert,work,job)
implicit none
integer, intent(in) :: n, job
real, intent(inout) :: ap(*), work(*)
real, intent(inout) :: det(2)
integer, intent(in) :: kpvt(*)
integer, intent(inout) :: inert(3)
real :: akkp1, sdot, temp
real :: ten, d, t, ak, akp1
integer :: ij, ik, ikp1, iks, j, jb, jk, jkp1, k, kk, kkp1, km1, ks, ksj, kskp1, kstep
logical :: noinv, nodet, noert
!
!     sspdi computes the determinant, inertia and inverse
!     of a real symmetric matrix using the factors from sspfa,
!     where the matrix is stored in packed form.
!
!     On entry
!
!        ap      real (n*(n+1)/2)
!                the output from sspfa.
!
!        n       INTEGER
!                the order of the matrix A.
!
!        kpvt    INTEGER(n)
!                the pivot vector from sspfa.
!
!        WORK    real(n)
!                work vector.  Contents ignored.
!
!        JOB     INTEGER
!                job has the decimal expansion  abc  where
!                   if  C .NE. 0, the inverse is computed,
!                   if  B .NE. 0, the determinant is computed,
!                   if  A .NE. 0, the inertia is computed.
!
!                For example, job = 111  Gives all three.
!
!     On return
!
!        Variables not requested by job are not used.
!
!        ap     CONTAINS THE UPPER TRIANGLE OF THE INVERSE OF
!               the original matrix, stored in packed form.
!               The columns of the upper triangle are stored
!               sequentially in a one-dimensional array.
!
!        det    real(2)
!               determinant of original matrix.
!               determinant = det(1) * 10.0**det(2)
!               WITH 1.0 .LE. abs(det(1)) .LT. 10.0
!               OR det(1) = 0.0.
!
!        Inert  integer(3)
!               the inertia of the original matrix.
!               inert(1)  =  Number of positive eigenvalues.
!               inert(2)  =  Number of negative eigenvalues.
!               inert(3)  =  Number of zero eigenvalues.
!
!     Error condition
!
!        A division by zero will occur if the inverse is requested
!        and  sspco  has set RCOND .EQ. 0.0
!        or  sspfa  has set  info .NE. 0 .
!
!     LINPACK. This version dated 08/14/78 .
!     James bunch, univ. Calif. San diego, argonne nat. Lab.
!
!     Subroutines and functions
!
!     BLAS saxpy,scopy,sdot,sswap
!     Fortran abs,IABS,mod
!
!     Internal variables.
!
!
noinv = mod(job,10) == 0
nodet = mod(job,100)/10 == 0
noert = mod(job,1000)/100 == 0
!
if (nodet .and. noert) go to 140
if (noert) go to 10
inert(1) = 0
inert(2) = 0
inert(3) = 0
10 continue
if (nodet) go to 20
det(1) = 1.0e0
det(2) = 0.0e0
ten = 10.0e0
20 continue
t = 0.0e0
ik = 0
do k = 1, n
   kk = ik + k
   d = ap(kk)
!
!           Check if 1 by 1
!
   if (kpvt(k) > 0) go to 50
!
!              2 By 2 block
!              USE det (d  S)  =  (d/t * C - t) * t  ,  t = abs(S)
!                      (S  C)
!              to avoid underflow/overflow troubles.
!              Take two passes through scaling.  Use  t  for flag.
!
   if (t /= 0.0e0) go to 30
   ikp1 = ik + k
   kkp1 = ikp1 + k
   t = abs(ap(kkp1))
   d = (d/t)*ap(kkp1 + 1) - t
   go to 40
30 continue
   d = t
   t = 0.0e0
40 continue
50 continue
!
   if (noert) go to 60
   if (d > 0.0e0) inert(1) = inert(1) + 1
   if (d < 0.0e0) inert(2) = inert(2) + 1
   if (d == 0.0e0) inert(3) = inert(3) + 1
60 continue
!
   if (nodet) go to 120
   det(1) = d*det(1)
   if (det(1) == 0.0e0) go to 110
70 if (abs(det(1)) >= 1.0e0) go to 80
   det(1) = ten*det(1)
   det(2) = det(2) - 1.0e0
   go to 70
80 continue
90 if (abs(det(1)) < ten) go to 100
   det(1) = det(1)/ten
   det(2) = det(2) + 1.0e0
   go to 90
100 continue
110 continue
120 continue
   ik = ik + k
130 continue
end do
140 continue
!
!     Compute inverse(A)
!
if (noinv) go to 270
k = 1
ik = 0
150 if (k > n) go to 260
km1 = k - 1
kk = ik + k
ikp1 = ik + k
kkp1 = ikp1 + k
if (kpvt(k) < 0) go to 180
!
!              1 By 1
!
ap(kk) = 1.0e0/ap(kk)
if (km1 < 1) go to 170
call scopy(km1,ap(ik + 1),1,work,1)
ij = 0
do j = 1, km1
   jk = ik + j
   ap(jk) = sdot(j,ap(ij + 1),1,work,1)
   call saxpy(j - 1,work(j),ap(ij + 1),1,ap(ik + 1),1)
   ij = ij + j
end do
ap(kk) = ap(kk) + sdot(km1,work,1,ap(ik + 1),1)
170 continue
kstep = 1
go to 220
180 continue
!
!              2 By 2
!
t = abs(ap(kkp1))
ak = ap(kk)/t
akp1 = ap(kkp1 + 1)/t
akkp1 = ap(kkp1)/t
d = t*(ak*akp1 - 1.0e0)
ap(kk) = akp1/d
ap(kkp1 + 1) = ak/d
ap(kkp1) = -akkp1/d
if (km1 < 1) go to 210
call scopy(km1,ap(ikp1 + 1),1,work,1)
ij = 0
do j = 1, km1
   jkp1 = ikp1 + j
   ap(jkp1) = sdot(j,ap(ij + 1),1,work,1)
   call saxpy(j - 1,work(j),ap(ij + 1),1,ap(ikp1 + 1),1)
   ij = ij + j
end do
ap(kkp1 + 1) = ap(kkp1 + 1) &
   & + sdot(km1,work,1,ap(ikp1 + 1),1)
ap(kkp1) = ap(kkp1) &
   & + sdot(km1,ap(ik + 1),1,ap(ikp1 + 1),1)
call scopy(km1,ap(ik + 1),1,work,1)
ij = 0
do j = 1, km1
   jk = ik + j
   ap(jk) = sdot(j,ap(ij + 1),1,work,1)
   call saxpy(j - 1,work(j),ap(ij + 1),1,ap(ik + 1),1)
   ij = ij + j
end do
ap(kk) = ap(kk) + sdot(km1,work,1,ap(ik + 1),1)
210 continue
kstep = 2
220 continue
!
!           Swap
!
ks = abs(kpvt(k))
if (ks == k) go to 250
iks = (ks*(ks - 1))/2
call sswap(ks,ap(iks + 1),1,ap(ik + 1),1)
ksj = ik + ks
do jb = ks, k
   j = k + ks - jb
   jk = ik + j
   temp = ap(jk)
   ap(jk) = ap(ksj)
   ap(ksj) = temp
   ksj = ksj - (j - 1)
end do
if (kstep == 1) go to 240
kskp1 = ikp1 + ks
temp = ap(kskp1)
ap(kskp1) = ap(kkp1)
ap(kkp1) = temp
240 continue
250 continue
ik = ik + k
if (kstep == 2) ik = ik + k + 1
k = k + kstep
go to 150
260 continue
270 continue
end subroutine sspdi

subroutine dsmslv(mo,n,m,a,b,kb,det,rcond,inert,ierr,ipvt,wk)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: kb, m, mo, n
double precision, intent(inout) :: a(*), b(*)
double precision, intent(inout) :: det(2), rcond
double precision, intent(inout) :: wk(n)
integer, intent(inout) :: inert(3), ipvt(n)
integer :: j, job, onej
double precision :: t
!     ------------------
!     ------------------
!
!          Matrix factorization and computation of rcond
!
ierr = 0
call dspco(a,n,ipvt,rcond,wk)
t = 1.d0 + rcond
if (t == 1.d0) go to 30
!
!                  Solution of the equation AX=b
!
if (m < 1) go to 20
onej = 1
do j = 1,m
   call dspsl(a,n,ipvt,b(onej))
10 onej = onej + kb
end do
!
!             Calculation of det and the inverse of A
!
20 job = 110
if (mo == 0) job = 111
call dspdi(a,n,ipvt,det,inert,wk,job)
return
!
!                  The problem cannot be solved
!
30 ierr = 1
end subroutine dsmslv

pure subroutine dspco(ap,n,kpvt,rcond,z)
implicit none
integer, intent(in) :: n
integer, intent(inout) :: kpvt(*)
double precision, intent(inout) :: ap(*), z(*)
double precision, intent(inout) :: rcond
double precision :: ak, akm1, bk, bkm1, denom, ek, t, anorm, s, ynorm
integer :: i, ij, ik, ikm1, ikp1, info, j, jm1, j1, k, kk, km1k, km1km1, kp, kps, ks
interface
   pure function dasum(n,dx,incx)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision :: dasum
   end function dasum
   pure subroutine daxpy(n,da,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
   end subroutine daxpy
   pure function ddot(n,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(in) :: dy(*)
      integer, intent(in) :: incy
      double precision :: ddot
   end function ddot
   pure subroutine dscal(n,da,dx,incx)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(inout) :: dx(*)
      integer, intent(in) :: incx
   end subroutine dscal
   pure subroutine dspfa(ap,n,kpvt,info)
      implicit none
      double precision, intent(inout) :: ap(*)
      integer, intent(in) :: n
      integer, intent(inout) :: kpvt(*)
      integer, intent(out) :: info
   end subroutine dspfa
end interface
!
!     dspco factors a double precision symmetric matrix stored in
!     packed form by elimination with symmetric pivoting and estimates
!     the condition of the matrix.
!
!     If  rcond  is not needed, dspfa is slightly faster.
!     To solve  A*X = B , follow dspco by dspsl.
!     To compute  inverse(A)*C , follow dspco by dspsl.
!     To compute  inverse(A) , follow dspco by dspdi.
!     To compute  determinant(A) , follow dspco by dspdi.
!     To compute  inertia(A), follow dspco by dspdi.
!
!     On entry
!
!        ap      DOUBLE PRECISION (n*(n+1)/2)
!                the packed form of A symmetric matrix  A .  The
!                columns of the upper triangle are stored sequentially
!                in a one-dimensional array of length  n*(n+1)/2 .
!                See comments below for details.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!     Output
!
!        ap      A BLOCK DIAGONAL MATRIX AND THE MULTIPLIERS WHICH
!                were used to obtain it stored in packed form.
!                The factorization can be written  A = U*D*trans(U)
!                where  U  is a product of permutation and unit
!                upper triangular matrices , trans(U) is the
!                transpose of  U , and  D  is block diagonal
!                with 1 by 1 and 2 by 2 blocks.
!
!        kpvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        rcond   DOUBLE PRECISION
!                an estimate of the reciprocal condition of  A .
!                For the system  A*X = B , relative perturbations
!                in  A  and  B  of size  epsilon  may cause
!                relative perturbations in  X  of size  epsilon/rcond .
!                If  rcond  is so small that the logical expression
!                           1.0 + rcond .EQ. 1.0
!                is true, then  A  may be singular to working
!                precision.  In particular,  rcond  is zero  if
!                exact singularity is detected or the estimate
!                underflows.
!
!        z       DOUBLE PRECISION(n)
!                a work vector whose contents are usually unimportant.
!                If  A  is close to a singular matrix, then  z  is
!                an approximate null vector in the sense that
!                norm(a*z) = rcond*norm(a)*norm(z) .
!
!     Packed storage
!
!          The following program segment will pack the upper
!          triangle of a symmetric matrix.
!
!                k = 0
!                do 20 j = 1, n
!                   do 10 i = 1, j
!                      k = k + 1
!                      ap(k) = a(i,j)
!             10    continue
!             20 continue
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     LINPACK dspfa
!     BLAS daxpy,ddot,dscal,dasum
!     Fortran dabs,DMAX1,IABS,DSIGN
!
!     Internal variables
!
!
!
!     Find norm of a using only upper half
!
j1 = 1
do j = 1, n
   z(j) = dasum(j,ap(j1),1)
   ij = j1
   j1 = j1 + j
   jm1 = j - 1
   if (jm1 < 1) go to 20
   do i = 1, jm1
      z(i) = z(i) + abs(ap(ij))
      ij = ij + 1
   end do
20 continue
end do
anorm = 0.0d0
do j = 1, n
   anorm = max(anorm,z(j))
end do
!
!     Factor
!
call dspfa(ap,n,kpvt,info)
!
!     rcond = 1/(norm(A)*(estimate of norm(inverse(A)))) .
!     ESTIMATE = NORM(z)/NORM(Y) WHERE  A*z = Y  AND  A*Y = E .
!     The components of  E  are chosen to cause maximum local
!     growth in the elements of W  where  U*D*W = E .
!     The vectors are frequently rescaled to avoid overflow.
!
!     SOLVE U*D*W = E
!
ek = 1.0d0
do j = 1, n
   z(j) = 0.0d0
end do
k = n
ik = (n*(n - 1))/2
60 if (k == 0) go to 120
kk = ik + k
ikm1 = ik - (k - 1)
ks = 1
if (kpvt(k) < 0) ks = 2
kp = abs(kpvt(k))
kps = k + 1 - ks
if (kp == kps) go to 70
t = z(kps)
z(kps) = z(kp)
z(kp) = t
70 continue
if (z(k) /= 0.0d0) ek = sign(ek,z(k))
z(k) = z(k) + ek
call daxpy(k - ks,z(k),ap(ik + 1),1,z(1),1)
if (ks == 1) go to 80
if (z(k - 1) /= 0.0d0) ek = sign(ek,z(k - 1))
z(k - 1) = z(k - 1) + ek
call daxpy(k - ks,z(k - 1),ap(ikm1 + 1),1,z(1),1)
80 continue
if (ks == 2) go to 100
if (abs(z(k)) <= abs(ap(kk))) go to 90
s = abs(ap(kk))/abs(z(k))
call dscal(n,s,z,1)
ek = s*ek
90 continue
if (ap(kk) /= 0.0d0) z(k) = z(k)/ap(kk)
if (ap(kk) == 0.0d0) z(k) = 1.0d0
go to 110
100 continue
km1k = ik + k - 1
km1km1 = ikm1 + k - 1
ak = ap(kk)/ap(km1k)
akm1 = ap(km1km1)/ap(km1k)
bk = z(k)/ap(km1k)
bkm1 = z(k - 1)/ap(km1k)
denom = ak*akm1 - 1.0d0
z(k) = (akm1*bk - bkm1)/denom
z(k - 1) = (ak*bkm1 - bk)/denom
110 continue
k = k - ks
ik = ik - k
if (ks == 2) ik = ik - (k + 1)
go to 60
120 continue
s = 1.0d0/dasum(n,z,1)
call dscal(n,s,z,1)
!
!     SOLVE TRANS(U)*Y = W
!
k = 1
ik = 0
130 if (k > n) go to 160
ks = 1
if (kpvt(k) < 0) ks = 2
if (k == 1) go to 150
z(k) = z(k) + ddot(k - 1,ap(ik + 1),1,z(1),1)
ikp1 = ik + k
if (ks == 2) &
   & z(k + 1) = z(k + 1) + ddot(k - 1,ap(ikp1 + 1),1,z(1),1)
kp = abs(kpvt(k))
if (kp == k) go to 140
t = z(k)
z(k) = z(kp)
z(kp) = t
140 continue
150 continue
ik = ik + k
if (ks == 2) ik = ik + (k + 1)
k = k + ks
go to 130
160 continue
s = 1.0d0/dasum(n,z,1)
call dscal(n,s,z,1)
!
ynorm = 1.0d0
!
!     SOLVE U*D*V = Y
!
k = n
ik = n*(n - 1)/2
170 if (k == 0) go to 230
kk = ik + k
ikm1 = ik - (k - 1)
ks = 1
if (kpvt(k) < 0) ks = 2
if (k == ks) go to 190
kp = abs(kpvt(k))
kps = k + 1 - ks
if (kp == kps) go to 180
t = z(kps)
z(kps) = z(kp)
z(kp) = t
180 continue
call daxpy(k - ks,z(k),ap(ik + 1),1,z(1),1)
if (ks == 2) call daxpy(k - ks,z(k - 1),ap(ikm1 + 1),1,z(1),1)
190 continue
if (ks == 2) go to 210
if (abs(z(k)) <= abs(ap(kk))) go to 200
s = abs(ap(kk))/abs(z(k))
call dscal(n,s,z,1)
ynorm = s*ynorm
200 continue
if (ap(kk) /= 0.0d0) z(k) = z(k)/ap(kk)
if (ap(kk) == 0.0d0) z(k) = 1.0d0
go to 220
210 continue
km1k = ik + k - 1
km1km1 = ikm1 + k - 1
ak = ap(kk)/ap(km1k)
akm1 = ap(km1km1)/ap(km1k)
bk = z(k)/ap(km1k)
bkm1 = z(k - 1)/ap(km1k)
denom = ak*akm1 - 1.0d0
z(k) = (akm1*bk - bkm1)/denom
z(k - 1) = (ak*bkm1 - bk)/denom
220 continue
k = k - ks
ik = ik - k
if (ks == 2) ik = ik - (k + 1)
go to 170
230 continue
s = 1.0d0/dasum(n,z,1)
call dscal(n,s,z,1)
ynorm = s*ynorm
!
!     SOLVE TRANS(U)*z = V
!
k = 1
ik = 0
240 if (k > n) go to 270
ks = 1
if (kpvt(k) < 0) ks = 2
if (k == 1) go to 260
z(k) = z(k) + ddot(k - 1,ap(ik + 1),1,z(1),1)
ikp1 = ik + k
if (ks == 2) &
   & z(k + 1) = z(k + 1) + ddot(k - 1,ap(ikp1 + 1),1,z(1),1)
kp = abs(kpvt(k))
if (kp == k) go to 250
t = z(k)
z(k) = z(kp)
z(kp) = t
250 continue
260 continue
ik = ik + k
if (ks == 2) ik = ik + (k + 1)
k = k + ks
go to 240
270 continue
!     MAKE ZNORM = 1.0
s = 1.0d0/dasum(n,z,1)
call dscal(n,s,z,1)
ynorm = s*ynorm
!
if (anorm /= 0.0d0) rcond = ynorm/anorm
if (anorm == 0.0d0) rcond = 0.0d0
end subroutine dspco

pure subroutine dspfa(ap,n,kpvt,info)
implicit none
integer, intent(in) :: n
integer, intent(inout) :: kpvt(*)
integer, intent(out) :: info
double precision, intent(inout) :: ap(*)
double precision :: ak, akm1, bk, bkm1, denom, mulk, mulkm1, t, absakk, alpha, colmax, rowmax
integer :: ij, ijj, ik, ikm1, im, imax, imaxp1, imim, imj, imk, j, jj, jk, jkm1, jmax, jmim, k, kk, km1, km1k, km1km1, km2, kstep
logical :: swap
interface
   pure subroutine daxpy(n,da,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
   end subroutine daxpy
   pure subroutine dswap(n,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(inout) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
   end subroutine dswap
   pure function idamax(n,dx,incx)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      integer :: idamax
   end function idamax
end interface
!
!     dspfa factors a double precision symmetric matrix stored in
!     packed form by elimination with symmetric pivoting.
!
!     To solve  A*X = B , follow dspfa by dspsl.
!     To compute  inverse(A)*C , follow dspfa by dspsl.
!     To compute  determinant(A) , follow dspfa by dspdi.
!     To compute  inertia(A) , follow dspfa by dspdi.
!     To compute  inverse(A) , follow dspfa by dspdi.
!
!     On entry
!
!        ap      DOUBLE PRECISION (n*(n+1)/2)
!                the packed form of A symmetric matrix  A .  The
!                columns of the upper triangle are stored sequentially
!                in a one-dimensional array of length  n*(n+1)/2 .
!                See comments below for details.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!     Output
!
!        ap      A BLOCK DIAGONAL MATRIX AND THE MULTIPLIERS WHICH
!                were used to obtain it stored in packed form.
!                The factorization can be written  A = U*D*trans(U)
!                where  U  is a product of permutation and unit
!                upper triangular matrices , trans(U) is the
!                transpose of  U , and  D  is block diagonal
!                with 1 by 1 and 2 by 2 blocks.
!
!        kpvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        INFO    INTEGER
!                = 0  Normal value.
!                = k  if the k-TH pivot block is singular. This is
!                     not an error condition for this subroutine,
!                     but it does indicate that dspsl or dspdi may
!                     divide by zero if called.
!
!     Packed storage
!
!          The following program segment will pack the upper
!          triangle of a symmetric matrix.
!
!                k = 0
!                do 20 j = 1, n
!                   do 10 i = 1, j
!                      k = k + 1
!                      ap(k)  = a(i,j)
!             10    continue
!             20 continue
!
!     LINPACK. This version dated 08/14/78 .
!     James bunch, univ. Calif. San diego, argonne nat. Lab.
!
!     Subroutines and functions
!
!     BLAS daxpy,dswap,idamax
!     Fortran dabs,DMAX1,DSQRT
!
!     Internal variables
!
!
!
!     Initialize
!
!     alpha is used in choosing pivot block SIZE.
alpha = (1.0d0 + sqrt(17.0d0))/8.0d0
!
info = 0
!
!     Main loop on k, which goes from n to 1.
!
k = n
ik = (n*(n - 1))/2
10 continue
!
!        Leave the loop if k=0 Or k=1.
!
!     ...Exit
if (k == 0) go to 200
if (k > 1) go to 20
kpvt(1) = 1
if (ap(1) == 0.0d0) info = 1
!     ......Exit
go to 200
20 continue
!
!        This section of code determines the kind of
!        elimination to be performed.  When it is completed,
!        KSTEP will be set to the size of the pivot block, and
!        swap will be set to .TRUE. if an interchange is
!        required.
!
km1 = k - 1
kk = ik + k
absakk = abs(ap(kk))
!
!        Determine the largest off-diagonal element in
!        column k.
!
imax = idamax(k - 1,ap(ik + 1),1)
imk = ik + imax
colmax = abs(ap(imk))
if (absakk < alpha*colmax) go to 30
kstep = 1
swap = .false.
go to 90
30 continue
!
!           Determine the largest off-diagonal element in
!           row imax.
!
rowmax = 0.0d0
imaxp1 = imax + 1
im = imax*(imax - 1)/2
imj = im + 2*imax
do j = imaxp1, k
   rowmax = max(rowmax,abs(ap(imj)))
   imj = imj + j
end do
if (imax == 1) go to 50
jmax = idamax(imax - 1,ap(im + 1),1)
jmim = jmax + im
rowmax = max(rowmax,abs(ap(jmim)))
50 continue
imim = imax + im
if (abs(ap(imim)) < alpha*rowmax) go to 60
kstep = 1
swap = .true.
go to 80
60 continue
if (absakk < alpha*colmax*(colmax/rowmax)) go to 70
kstep = 1
swap = .false.
go to 80
70 continue
kstep = 2
swap = imax /= km1
80 continue
90 continue
if (max(absakk,colmax) /= 0.0d0) go to 100
!
!           Column k is zero.  Set info and iterate the loop.
!
kpvt(k) = k
info = k
go to 190
100 continue
if (kstep == 2) go to 140
!
!           1 X 1 pivot block.
!
if (.not.swap) go to 120
!
!              Perform an interchange.
!
call dswap(imax,ap(im + 1),1,ap(ik + 1),1)
imj = ik + imax
do jj = imax, k
   j = k + imax - jj
   jk = ik + j
   t = ap(jk)
   ap(jk) = ap(imj)
   ap(imj) = t
   imj = imj - (j - 1)
end do
120 continue
!
!           Perform the elimination.
!
ij = ik - (k - 1)
do jj = 1, km1
   j = k - jj
   jk = ik + j
   mulk = -ap(jk)/ap(kk)
   t = mulk
   call daxpy(j,t,ap(ik + 1),1,ap(ij + 1),1)
   ijj = ij + j
   ap(jk) = mulk
   ij = ij - (j - 1)
end do
!
!           Set the pivot array.
!
kpvt(k) = k
if (swap) kpvt(k) = imax
go to 190
140 continue
!
!           2 X 2 pivot block.
!
km1k = ik + k - 1
ikm1 = ik - (k - 1)
if (.not.swap) go to 160
!
!              Perform an interchange.
!
call dswap(imax,ap(im + 1),1,ap(ikm1 + 1),1)
imj = ikm1 + imax
do jj = imax, km1
   j = km1 + imax - jj
   jkm1 = ikm1 + j
   t = ap(jkm1)
   ap(jkm1) = ap(imj)
   ap(imj) = t
   imj = imj - (j - 1)
end do
t = ap(km1k)
ap(km1k) = ap(imk)
ap(imk) = t
160 continue
!
!           Perform the elimination.
!
km2 = k - 2
if (km2 == 0) go to 180
ak = ap(kk)/ap(km1k)
km1km1 = ikm1 + k - 1
akm1 = ap(km1km1)/ap(km1k)
denom = 1.0d0 - ak*akm1
ij = ik - (k - 1) - (k - 2)
do jj = 1, km2
   j = km1 - jj
   jk = ik + j
   bk = ap(jk)/ap(km1k)
   jkm1 = ikm1 + j
   bkm1 = ap(jkm1)/ap(km1k)
   mulk = (akm1*bk - bkm1)/denom
   mulkm1 = (ak*bkm1 - bk)/denom
   t = mulk
   call daxpy(j,t,ap(ik + 1),1,ap(ij + 1),1)
   t = mulkm1
   call daxpy(j,t,ap(ikm1 + 1),1,ap(ij + 1),1)
   ap(jk) = mulk
   ap(jkm1) = mulkm1
   ijj = ij + j
   ij = ij - (j - 1)
end do
180 continue
!
!           Set the pivot array.
!
kpvt(k) = 1 - k
if (swap) kpvt(k) = -imax
kpvt(k - 1) = kpvt(k)
190 continue
ik = ik - (k - 1)
if (kstep == 2) ik = ik - (k - 2)
k = k - kstep
go to 10
200 continue
end subroutine dspfa

pure subroutine dspsl(ap,n,kpvt,b)
implicit none
integer, intent(in) :: n, kpvt(*)
double precision, intent(in) :: ap(*)
double precision, intent(inout) :: b(*)
double precision :: ak, akm1, bk, bkm1, denom, temp
integer :: ik, ikm1, ikp1, k, kk, km1k, km1km1, kp
interface
   pure subroutine daxpy(n,da,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
   end subroutine daxpy
   pure function ddot(n,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(in) :: dy(*)
      integer, intent(in) :: incy
      double precision :: ddot
   end function ddot
end interface
!
!     DSISL solves the double precision symmetric system
!     A * X = b
!     using the factors computed by dspfa.
!
!     On entry
!
!        ap      DOUBLE PRECISION(n*(n+1)/2)
!                the output from dspfa.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!        kpvt    INTEGER(n)
!                the pivot vector from dspfa.
!
!        b       DOUBLE PRECISION(n)
!                the right hand side vector.
!
!     On return
!
!        b       THE SOLUTION VECTOR  X .
!
!     Error condition
!
!        A division by zero may occur if  dspco  has set RCOND .EQ. 0.0
!        or  dspfa  has set info .NE. 0  .
!
!     To compute  inverse(A) * C  where  C  is a matrix
!     with  P  columns
!           call dspfa(ap,n,kpvt,info)
!           if (info .ne. 0) go to ...
!           do 10 j = 1, p
!              call dspsl(ap,n,kpvt,c(1,j))
!        10 continue
!
!     LINPACK. This version dated 08/14/78 .
!     James bunch, univ. Calif. San diego, argonne nat. Lab.
!
!     Subroutines and functions
!
!     BLAS daxpy,ddot
!     FORTRAN IABS
!
!     Internal variables.
!
!
!     Loop backward applying the transformations and
!     D inverse to b.
!
k = n
ik = (n*(n - 1))/2
10 if (k == 0) go to 80
kk = ik + k
if (kpvt(k) < 0) go to 40
!
!           1 X 1 pivot block.
!
if (k == 1) go to 30
kp = kpvt(k)
if (kp == k) go to 20
!
!                 Interchange.
!
temp = b(k)
b(k) = b(kp)
b(kp) = temp
20 continue
!
!              Apply the transformation.
!
call daxpy(k - 1,b(k),ap(ik + 1),1,b(1),1)
30 continue
!
!           Apply D inverse.
!
b(k) = b(k)/ap(kk)
k = k - 1
ik = ik - k
go to 70
40 continue
!
!           2 X 2 pivot block.
!
ikm1 = ik - (k - 1)
if (k == 2) go to 60
kp = abs(kpvt(k))
if (kp == k - 1) go to 50
!
!                 Interchange.
!
temp = b(k - 1)
b(k - 1) = b(kp)
b(kp) = temp
50 continue
!
!              Apply the transformation.
!
call daxpy(k - 2,b(k),ap(ik + 1),1,b(1),1)
call daxpy(k - 2,b(k - 1),ap(ikm1 + 1),1,b(1),1)
60 continue
!
!           Apply D inverse.
!
km1k = ik + k - 1
kk = ik + k
ak = ap(kk)/ap(km1k)
km1km1 = ikm1 + k - 1
akm1 = ap(km1km1)/ap(km1k)
bk = b(k)/ap(km1k)
bkm1 = b(k - 1)/ap(km1k)
denom = ak*akm1 - 1.0d0
b(k) = (akm1*bk - bkm1)/denom
b(k - 1) = (ak*bkm1 - bk)/denom
k = k - 2
ik = ik - (k + 1) - k
70 continue
go to 10
80 continue
!
!     Loop forward applying the transformations.
!
k = 1
ik = 0
90 if (k > n) go to 160
if (kpvt(k) < 0) go to 120
!
!           1 X 1 pivot block.
!
if (k == 1) go to 110
!
!              Apply the transformation.
!
b(k) = b(k) + ddot(k - 1,ap(ik + 1),1,b(1),1)
kp = kpvt(k)
if (kp == k) go to 100
!
!                 Interchange.
!
temp = b(k)
b(k) = b(kp)
b(kp) = temp
100 continue
110 continue
ik = ik + k
k = k + 1
go to 150
120 continue
!
!           2 X 2 pivot block.
!
if (k == 1) go to 140
!
!              Apply the transformation.
!
b(k) = b(k) + ddot(k - 1,ap(ik + 1),1,b(1),1)
ikp1 = ik + k
b(k + 1) = b(k + 1) + ddot(k - 1,ap(ikp1 + 1),1,b(1),1)
kp = abs(kpvt(k))
if (kp == k) go to 130
!
!                 Interchange.
!
temp = b(k)
b(k) = b(kp)
b(kp) = temp
130 continue
140 continue
ik = ik + k + k + 1
k = k + 2
150 continue
go to 90
160 continue
end subroutine dspsl

subroutine dspdi(ap,n,kpvt,det,inert,work,job)
implicit none
integer, intent(in) :: n, job
double precision, intent(inout) :: ap(*), work(*)
double precision, intent(inout) :: det(2)
integer, intent(in) :: kpvt(*)
integer, intent(inout) :: inert(3)
double precision :: akkp1, ddot, temp
double precision :: ten, d, t, ak, akp1
integer :: ij, ik, ikp1, iks, j, jb, jk, jkp1, k, kk, kkp1, km1, ks, ksj, kskp1, kstep
logical :: noinv, nodet, noert
!
!     dspdi computes the determinant, inertia and inverse
!     of a double precision symmetric matrix using the factors from
!     dspfa, where the matrix is stored in packed form.
!
!     On entry
!
!        ap      DOUBLE PRECISION (n*(n+1)/2)
!                the output from dspfa.
!
!        n       INTEGER
!                the order of the matrix A.
!
!        kpvt    INTEGER(n)
!                the pivot vector from dspfa.
!
!        WORK    DOUBLE PRECISION(n)
!                work vector.  Contents ignored.
!
!        JOB     INTEGER
!                job has the decimal expansion  abc  where
!                   if  C .NE. 0, the inverse is computed,
!                   if  B .NE. 0, the determinant is computed,
!                   if  A .NE. 0, the inertia is computed.
!
!                For example, job = 111  Gives all three.
!
!     On return
!
!        Variables not requested by job are not used.
!
!        ap     CONTAINS THE UPPER TRIANGLE OF THE INVERSE OF
!               the original matrix, stored in packed form.
!               The columns of the upper triangle are stored
!               sequentially in a one-dimensional array.
!
!        det    DOUBLE PRECISION(2)
!               determinant of original matrix.
!               determinant = det(1) * 10.0**det(2)
!               WITH 1.0 .LE. dabs(det(1)) .LT. 10.0
!               OR det(1) = 0.0.
!
!        Inert  integer(3)
!               the inertia of the original matrix.
!               inert(1)  =  Number of positive eigenvalues.
!               inert(2)  =  Number of negative eigenvalues.
!               inert(3)  =  Number of zero eigenvalues.
!
!     Error condition
!
!        A division by zero will occur if the inverse is requested
!        and  dspco  has set RCOND .EQ. 0.0
!        or  dspfa  has set  info .NE. 0 .
!
!     LINPACK. This version dated 08/14/78 .
!     James bunch, univ. Calif. San diego, argonne nat. Lab.
!
!     Subroutines and functions
!
!     BLAS daxpy,dcopy,ddot,dswap
!     Fortran dabs,IABS,mod
!
!     Internal variables.
!
!
noinv = mod(job,10) == 0
nodet = mod(job,100)/10 == 0
noert = mod(job,1000)/100 == 0
!
if (nodet .and. noert) go to 140
if (noert) go to 10
inert(1) = 0
inert(2) = 0
inert(3) = 0
10 continue
if (nodet) go to 20
det(1) = 1.0d0
det(2) = 0.0d0
ten = 10.0d0
20 continue
t = 0.0d0
ik = 0
do k = 1, n
   kk = ik + k
   d = ap(kk)
!
!           Check if 1 by 1
!
   if (kpvt(k) > 0) go to 50
!
!              2 By 2 block
!              USE det (d  S)  =  (d/t * C - t) * t  ,  t = dabs(S)
!                      (S  C)
!              to avoid underflow/overflow troubles.
!              Take two passes through scaling.  Use  t  for flag.
!
   if (t /= 0.0d0) go to 30
   ikp1 = ik + k
   kkp1 = ikp1 + k
   t = abs(ap(kkp1))
   d = (d/t)*ap(kkp1 + 1) - t
   go to 40
30 continue
   d = t
   t = 0.0d0
40 continue
50 continue
!
   if (noert) go to 60
   if (d > 0.0d0) inert(1) = inert(1) + 1
   if (d < 0.0d0) inert(2) = inert(2) + 1
   if (d == 0.0d0) inert(3) = inert(3) + 1
60 continue
!
   if (nodet) go to 120
   det(1) = d*det(1)
   if (det(1) == 0.0d0) go to 110
70 if (abs(det(1)) >= 1.0d0) go to 80
   det(1) = ten*det(1)
   det(2) = det(2) - 1.0d0
   go to 70
80 continue
90 if (abs(det(1)) < ten) go to 100
   det(1) = det(1)/ten
   det(2) = det(2) + 1.0d0
   go to 90
100 continue
110 continue
120 continue
   ik = ik + k
130 continue
end do
140 continue
!
!     Compute inverse(A)
!
if (noinv) go to 270
k = 1
ik = 0
150 if (k > n) go to 260
km1 = k - 1
kk = ik + k
ikp1 = ik + k
kkp1 = ikp1 + k
if (kpvt(k) < 0) go to 180
!
!              1 By 1
!
ap(kk) = 1.0d0/ap(kk)
if (km1 < 1) go to 170
call dcopy(km1,ap(ik + 1),1,work,1)
ij = 0
do j = 1, km1
   jk = ik + j
   ap(jk) = ddot(j,ap(ij + 1),1,work,1)
   call daxpy(j - 1,work(j),ap(ij + 1),1,ap(ik + 1),1)
   ij = ij + j
end do
ap(kk) = ap(kk) + ddot(km1,work,1,ap(ik + 1),1)
170 continue
kstep = 1
go to 220
180 continue
!
!              2 By 2
!
t = abs(ap(kkp1))
ak = ap(kk)/t
akp1 = ap(kkp1 + 1)/t
akkp1 = ap(kkp1)/t
d = t*(ak*akp1 - 1.0d0)
ap(kk) = akp1/d
ap(kkp1 + 1) = ak/d
ap(kkp1) = -akkp1/d
if (km1 < 1) go to 210
call dcopy(km1,ap(ikp1 + 1),1,work,1)
ij = 0
do j = 1, km1
   jkp1 = ikp1 + j
   ap(jkp1) = ddot(j,ap(ij + 1),1,work,1)
   call daxpy(j - 1,work(j),ap(ij + 1),1,ap(ikp1 + 1),1)
   ij = ij + j
end do
ap(kkp1 + 1) = ap(kkp1 + 1) &
   & + ddot(km1,work,1,ap(ikp1 + 1),1)
ap(kkp1) = ap(kkp1) &
   & + ddot(km1,ap(ik + 1),1,ap(ikp1 + 1),1)
call dcopy(km1,ap(ik + 1),1,work,1)
ij = 0
do j = 1, km1
   jk = ik + j
   ap(jk) = ddot(j,ap(ij + 1),1,work,1)
   call daxpy(j - 1,work(j),ap(ij + 1),1,ap(ik + 1),1)
   ij = ij + j
end do
ap(kk) = ap(kk) + ddot(km1,work,1,ap(ik + 1),1)
210 continue
kstep = 2
220 continue
!
!           Swap
!
ks = abs(kpvt(k))
if (ks == k) go to 250
iks = (ks*(ks - 1))/2
call dswap(ks,ap(iks + 1),1,ap(ik + 1),1)
ksj = ik + ks
do jb = ks, k
   j = k + ks - jb
   jk = ik + j
   temp = ap(jk)
   ap(jk) = ap(ksj)
   ap(ksj) = temp
   ksj = ksj - (j - 1)
end do
if (kstep == 1) go to 240
kskp1 = ikp1 + ks
temp = ap(kskp1)
ap(kskp1) = ap(kkp1)
ap(kkp1) = temp
240 continue
250 continue
ik = ik + k
if (kstep == 2) ik = ik + k + 1
k = k + kstep
go to 150
260 continue
270 continue
end subroutine dspdi

subroutine pchol(mo,n,m,a,b,kb,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: kb, m, mo, n
real, intent(inout) :: a(*), b(*)
integer :: j, onej
real :: d(2)
!     -----------------
!     -----------------
!
!              Matrix factorization
!
call sppfa(a,n,ierr)
if (ierr /= 0) return
!
!          Solution of the equation AX=b
!
if (m < 1) go to 20
onej = 1
do j = 1,m
   call sppsl(a,n,b(onej))
10 onej = onej + kb
end do
!
!         Computation of the inverse of A
!
20 if (mo == 0) call sppdi(a,n,d,1)
end subroutine pchol

pure subroutine sppfa(ap,n,info)
implicit none
integer, intent(in) :: n
integer, intent(inout) :: info
real, intent(inout) :: ap(*)
real :: t, s
integer :: j, jj, jm1, k, kj, kk
interface
   pure function sdot(n,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(in) :: sy(*)
      integer, intent(in) :: incy
      real :: sdot
   end function sdot
end interface
!
!     sppfa factors a real symmetric positive definite matrix
!     stored in packed form.
!
!     sppfa is usually called by SPPCO, but it can be called
!     directly with a saving in time if  RCOND  is not needed.
!     (Time for SPPCO) = (1 + 18/n)*(time for sppfa) .
!
!     On entry
!
!        ap      real (n*(n+1)/2)
!                the packed form of A symmetric matrix  A .  The
!                columns of the upper triangle are stored sequentially
!                in a one-dimensional array of length  n*(n+1)/2 .
!                See comments below for details.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!     On return
!
!        ap      AN UPPER TRIANGULAR MATRIX  R , STORED IN PACKED
!                form, so that  A = Trans(R)*R .
!
!        INFO    INTEGER
!                = 0  For normal return.
!                = k  if the leading minor of order  k  is not
!                     positive definite.
!
!
!     Packed storage
!
!          The following program segment will pack the upper
!          triangle of a symmetric matrix.
!
!                k = 0
!                do 20 j = 1, n
!                   do 10 i = 1, j
!                      k = k + 1
!                      ap(k) = a(i,j)
!             10    continue
!             20 continue
!
!     LINPACK.  This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS sdot
!     Fortran sqrt
!
!     Internal variables
!
!     Begin block with ...exits to 40
!
!
jj = 0
do j = 1, n
   info = j
   s = 0.0e0
   jm1 = j - 1
   kj = jj
   kk = 0
   if (jm1 < 1) go to 20
   do k = 1, jm1
      kj = kj + 1
      t = ap(kj) - sdot(k - 1,ap(kk + 1),1,ap(jj + 1),1)
      kk = kk + k
      t = t/ap(kk)
      ap(kj) = t
      s = s + t*t
   end do
20 continue
   jj = jj + j
   s = ap(jj) - s
!     ......Exit
   if (s <= 0.0e0) go to 40
   ap(jj) = sqrt(s)
end do
info = 0
40 continue
end subroutine sppfa

pure subroutine sppsl(ap,n,b)
implicit none
integer, intent(in) :: n
real, intent(in) :: ap(*)
real, intent(inout) :: b(*)
real :: t
integer :: k, kb, kk
interface
   pure subroutine saxpy(n,sa,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine saxpy
   pure function sdot(n,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(in) :: sy(*)
      integer, intent(in) :: incy
      real :: sdot
   end function sdot
end interface
!
!     sppsl solves the real symmetric positive definite system
!     A * X = b
!     using the factors computed by SPPCO or sppfa.
!
!     On entry
!
!        ap      real (n*(n+1)/2)
!                the output from SPPCO or sppfa.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!        b       real(n)
!                the right hand side vector.
!
!     On return
!
!        b       THE SOLUTION VECTOR  X .
!
!     Error condition
!
!        A division by zero will occur if the input factor contains
!        a zero on the diagonal.  Technically this indicates
!        singularity but it is usually caused by improper subroutine
!        arguments.  It will not occur if the subroutines are called
!        correctly and  info .EQ. 0 .
!
!     To compute  inverse(A) * C  where  C  is a matrix
!     with  P  columns
!           call sppco(ap,n,rcond,z,info)
!           if (rcond is too small .or. info .ne. 0) go to ...
!           do 10 j = 1, p
!              call sppsl(ap,n,c(1,j))
!        10 continue
!
!     LINPACK.  This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS saxpy,sdot
!
!     Internal variables
!
!
kk = 0
do k = 1, n
   t = sdot(k - 1,ap(kk + 1),1,b(1),1)
   kk = kk + k
   b(k) = (b(k) - t)/ap(kk)
end do
do kb = 1, n
   k = n + 1 - kb
   b(k) = b(k)/ap(kk)
   kk = kk - k
   t = -b(k)
   call saxpy(k - 1,t,ap(kk + 1),1,b(1),1)
end do
end subroutine sppsl

subroutine sppdi(ap,n,det,job)
implicit none
integer, intent(in) :: n, job
real, intent(inout) :: ap(*)
real, intent(inout) :: det(2)
real :: t, s
integer :: i, ii, j, jj, jm1, j1, k, kj, kk, kp1, k1
!
!     sppdi computes the determinant and inverse
!     of a real symmetric positive definite matrix
!     using the factors computed by SPPCO or sppfa .
!
!     On entry
!
!        ap      real (n*(n+1)/2)
!                the output from SPPCO or sppfa.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!        JOB     INTEGER
!                = 11   Both determinant and inverse.
!                = 01   Inverse only.
!                = 10   Determinant only.
!
!     On return
!
!        ap      THE UPPER TRIANGULAR HALF OF THE INVERSE .
!
!        det     real(2)
!                determinant of original matrix IF requested.
!                Otherwise not referenced.
!                determinant = det(1) * 10.0**det(2)
!                WITH  1.0 .LE. det(1) .LT. 10.0
!                OR  det(1) .EQ. 0.0 .
!
!     Error condition
!
!        A division by zero will occur if the input factor contains
!        a zero on the diagonal and the inverse is requested.
!        It will not occur if the subroutines are called correctly
!        and if SPOCO or SPOFA has set info .EQ. 0 .
!
!     LINPACK.  This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS saxpy,sscal
!     Fortran mod
!
!     Internal variables
!
!
!     Compute determinant
!
if (job/10 == 0) go to 70
det(1) = 1.0e0
det(2) = 0.0e0
s = 10.0e0
ii = 0
do i = 1, n
   ii = ii + i
   det(1) = ap(ii)**2*det(1)
!        ...Exit
   if (det(1) == 0.0e0) go to 60
10 if (det(1) >= 1.0e0) go to 20
   det(1) = s*det(1)
   det(2) = det(2) - 1.0e0
   go to 10
20 continue
30 if (det(1) < s) go to 40
   det(1) = det(1)/s
   det(2) = det(2) + 1.0e0
   go to 30
40 continue
50 continue
end do
60 continue
70 continue
!
!     Compute inverse(R)
!
if (mod(job,10) == 0) go to 140
kk = 0
do k = 1, n
   k1 = kk + 1
   kk = kk + k
   ap(kk) = 1.0e0/ap(kk)
   t = -ap(kk)
   call sscal(k - 1,t,ap(k1),1)
   kp1 = k + 1
   j1 = kk + 1
   kj = kk + k
   if (n < kp1) go to 90
   do j = kp1, n
      t = ap(kj)
      ap(kj) = 0.0e0
      call saxpy(k,t,ap(k1),1,ap(j1),1)
      j1 = j1 + j
      kj = kj + j
   end do
90 continue
end do
!
!        Form  inverse(R) * trans(inverse(R))
!
jj = 0
do j = 1, n
   j1 = jj + 1
   jj = jj + j
   jm1 = j - 1
   k1 = 1
   kj = j1
   if (jm1 < 1) go to 120
   do k = 1, jm1
      t = ap(kj)
      call saxpy(k,t,ap(j1),1,ap(k1),1)
      k1 = k1 + k
      kj = kj + 1
   end do
120 continue
   t = ap(jj)
   call sscal(j,t,ap(j1),1)
end do
140 continue
end subroutine sppdi

subroutine dpchol(mo,n,m,a,b,kb,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: kb, m, mo, n
double precision, intent(inout) :: a(*), b(*)
integer :: j, onej
double precision :: d(2)
!     -----------------
!     -----------------
!
!              Matrix factorization
!
call dppfa(a,n,ierr)
if (ierr /= 0) return
!
!          Solution of the equation AX=b
!
if (m < 1) go to 20
onej = 1
do j = 1,m
   call dppsl(a,n,b(onej))
10 onej = onej + kb
end do
!
!         Computation of the inverse of A
!
20 if (mo == 0) call dppdi(a,n,d,1)
end subroutine dpchol

