subroutine dppdi(ap,n,det,job)
implicit none
integer, intent(in) :: n, job
double precision, intent(inout) :: ap(*)
double precision, intent(inout) :: det(2)
double precision :: t, s
integer :: i, ii, j, jj, jm1, j1, k, kj, kk, kp1, k1
!
!     dppdi computes the determinant and inverse
!     of a double precision symmetric positive definite matrix
!     using the factors computed by DPPCO or dppfa .
!
!     On entry
!
!        ap      DOUBLE PRECISION (n*(n+1)/2)
!                the output from DPPCO or dppfa.
!
!        n       INTEGER
!                the order of the matrix  A .
!
!        JOB     INTEGER
!                = 11   Both determinant and inverse.
!                = 01   Inverse only.
!                = 10   Determinant only.
!
!     On return
!
!        ap      THE UPPER TRIANGULAR HALF OF THE INVERSE .
!
!        det     DOUBLE PRECISION(2)
!                determinant of original matrix IF requested.
!                Otherwise not referenced.
!                determinant = det(1) * 10.0**det(2)
!                WITH  1.0 .LE. det(1) .LT. 10.0
!                OR  det(1) .EQ. 0.0 .
!
!     Error condition
!
!        A division by zero will occur if the input factor contains
!        a zero on the diagonal and the inverse is requested.
!        It will not occur if the subroutines are called correctly
!        and if DPOCO or DPOFA has set info .EQ. 0 .
!
!     LINPACK.  This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS daxpy,dscal
!     Fortran mod
!
!     Internal variables
!
!
!     Compute determinant
!
if (job/10 == 0) go to 70
det(1) = 1.0d0
det(2) = 0.0d0
s = 10.0d0
ii = 0
do i = 1, n
   ii = ii + i
   det(1) = ap(ii)**2*det(1)
!        ...Exit
   if (det(1) == 0.0d0) go to 60
10 if (det(1) >= 1.0d0) go to 20
   det(1) = s*det(1)
   det(2) = det(2) - 1.0d0
   go to 10
20 continue
30 if (det(1) < s) go to 40
   det(1) = det(1)/s
   det(2) = det(2) + 1.0d0
   go to 30
40 continue
50 continue
end do
60 continue
70 continue
!
!     Compute inverse(R)
!
if (mod(job,10) == 0) go to 140
kk = 0
do k = 1, n
   k1 = kk + 1
   kk = kk + k
   ap(kk) = 1.0d0/ap(kk)
   t = -ap(kk)
   call dscal(k - 1,t,ap(k1),1)
   kp1 = k + 1
   j1 = kk + 1
   kj = kk + k
   if (n < kp1) go to 90
   do j = kp1, n
      t = ap(kj)
      ap(kj) = 0.0d0
      call daxpy(k,t,ap(k1),1,ap(j1),1)
      j1 = j1 + j
      kj = kj + j
   end do
90 continue
end do
!
!        Form  inverse(R) * trans(inverse(R))
!
jj = 0
do j = 1, n
   j1 = jj + 1
   jj = jj + j
   jm1 = j - 1
   k1 = 1
   kj = j1
   if (jm1 < 1) go to 120
   do k = 1, jm1
      t = ap(kj)
      call daxpy(k,t,ap(j1),1,ap(k1),1)
      k1 = k1 + k
      kj = kj + 1
   end do
120 continue
   t = ap(jj)
   call dscal(j,t,ap(j1),1)
end do
140 continue
end subroutine dppdi

pure subroutine toplx(a, b, x, n, g, h, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n
real, intent(in) :: a(*), b(n)
real, intent(inout) :: x(n), g(n), h(n)
integer :: j, k, l, m, max, mp1, nml, npl
real :: c, c1, c2, gd, gj, gk, gn, hj, hk, hn, xd, xn
!-----------------------------------------------------------------------
!            Solution of the Toeplitz system of equations
!
!               sum(j = 1,...,n) a(n+I-j)*x(j) = b(I)
!
!     FOR I = 1,...,n.
!-----------------------------------------------------------------------
!     real a(2*n - 1)
!----------------------
!
if (a(n) == 0.0) go to 100
ierr = 0
x(1) = b(1)/a(n)
if (n == 1) return
g(1) = a(n - 1)/a(n)
h(1) = a(n + 1)/a(n)
mp1 = 1
!
!     Compute numerator and denominator of x(m+1)
!
10 m = mp1
mp1 = m + 1
xn = -b(mp1)
xd = -a(n)
do j = 1,m
   l = mp1 - j
   npl = n + l
   xn = xn + a(npl)*x(j)
20 xd = xd + a(npl)*g(l)
end do
if (xd == 0.0) go to 100
x(mp1) = xn/xd
!
!        Compute x
!
c = x(mp1)
do j = 1,m
   l = mp1 - j
30 x(j) = x(j) - c*g(l)
end do
if (mp1 == n) return
!
!     Compute numerator and denominator of g(m+1) and h(m+1)
!
l = n - mp1
gn = -a(l)
gd = -a(n)
l = n + mp1
hn = -a(l)
do j = 1,m
   l = mp1 - j
   nml = n - l
   npl = n + l
   gn = gn + a(nml)*g(j)
   gd = gd + a(nml)*h(l)
40 hn = hn + a(npl)*h(j)
end do
if (gd == 0.0) go to 100
g(mp1) = gn/gd
h(mp1) = hn/xd
!
!     Compute g and h
!
c1 = g(mp1)
c2 = h(mp1)
max = mp1/2
k = m
do j = 1,max
   gj = g(j)
   gk = g(k)
   hj = h(j)
   hk = h(k)
   g(j) = gj - c1*hk
   g(k) = gk - c1*hj
   h(j) = hj - c2*gk
   h(k) = hk - c2*gj
50 k = k - 1
end do
go to 10
!
!     Error return
!
100 ierr = 1
end subroutine toplx

pure subroutine dtoplx(a, b, x, n, g, h, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: n
double precision, intent(in) :: a(*), b(n)
double precision, intent(inout) :: x(n), g(n), h(n)
integer :: j, k, l, m, max, mp1, nml, npl
double precision :: c, c1, c2, gd, gj, gk, gn, hj, hk, hn, xd, xn
!-----------------------------------------------------------------------
!            Solution of the Toeplitz system of equations
!
!               sum(j = 1,...,n) a(n+I-j)*x(j) = b(I)
!
!     FOR I = 1,...,n.
!-----------------------------------------------------------------------
!     double precision a(2*n - 1)
!----------------------
!
if (a(n) == 0.d0) go to 100
ierr = 0
x(1) = b(1)/a(n)
if (n == 1) return
g(1) = a(n - 1)/a(n)
h(1) = a(n + 1)/a(n)
mp1 = 1
!
!     Compute numerator and denominator of x(m+1)
!
10 m = mp1
mp1 = m + 1
xn = -b(mp1)
xd = -a(n)
do j = 1,m
   l = mp1 - j
   npl = n + l
   xn = xn + a(npl)*x(j)
20 xd = xd + a(npl)*g(l)
end do
if (xd == 0.d0) go to 100
x(mp1) = xn/xd
!
!        Compute x
!
c = x(mp1)
do j = 1,m
   l = mp1 - j
30 x(j) = x(j) - c*g(l)
end do
if (mp1 == n) return
!
!     Compute numerator and denominator of g(m+1) and h(m+1)
!
l = n - mp1
gn = -a(l)
gd = -a(n)
l = n + mp1
hn = -a(l)
do j = 1,m
   l = mp1 - j
   nml = n - l
   npl = n + l
   gn = gn + a(nml)*g(j)
   gd = gd + a(nml)*h(l)
40 hn = hn + a(npl)*h(j)
end do
if (gd == 0.d0) go to 100
g(mp1) = gn/gd
h(mp1) = hn/xd
!
!     Compute g and h
!
c1 = g(mp1)
c2 = h(mp1)
max = mp1/2
k = m
do j = 1,max
   gj = g(j)
   gk = g(k)
   hj = h(j)
   hk = h(k)
   g(j) = gj - c1*hk
   g(k) = gk - c1*hj
   h(j) = hj - c2*gk
   h(k) = hk - c2*gj
50 k = k - 1
end do
go to 10
!
!     Error return
!
100 ierr = 1
end subroutine dtoplx

subroutine cmslv(mo,n,m,a,ka,b,kb,det,rcond,ierr,ipvt,wk)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, m, mo
integer :: n
complex, intent(inout) :: a(ka,n), b(*), det(2), wk(n)
real, intent(inout) :: rcond
integer, intent(inout) :: ipvt(n)
integer :: j, job, onej
real :: t
!-----------------------------------------------------------------------
!     Partial pivot Gauss procedure for inverting complex matrices
!     and solving complex equations
!-----------------------------------------------------------------------
!
!          Matrix factorization and computation of rcond
!
ierr = 0
call cgeco(a, ka, n, ipvt, rcond, wk)
t = 1.0 + rcond
if (t == 1.0) go to 30
!
!                  Solution of the equation AX=b
!
if (m < 1) go to 20
onej = 1
do j = 1,m
   call cgesl(a, ka, n, ipvt, b(onej), 0)
   onej = onej + kb
10 continue
end do
!
!             Calculation of det and the inverse of A
!
20 job = 10
if (mo == 0) job = 11
call cgedi(a, ka, n, ipvt, det, wk, job)
return
!
!                  The problem cannot be solved
!
30 ierr = 1
end subroutine cmslv

subroutine cmslv1(mo, n, m, a, ka, b, kb, ierr, ipvt, wk)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, m, mo
integer :: n
complex, intent(inout) :: a(ka,n), b(*), wk(*)
integer, intent(inout) :: ipvt(n)
integer :: j, onej
complex :: d(2)
!-----------------------------------------------------------------------
!     Partial pivot Gauss procedure for inverting complex matrices
!     and solving complex equations
!-----------------------------------------------------------------------
!
if (n < 1 .or. ka < n) go to 40
if (m <= 0) go to 10
if (kb < n) go to 40
!
!                      Matrix factorization
!
10 call cgefa(a, ka, n, ipvt, ierr)
if (ierr /= 0) return
!
!                 Solution of the equation AX = b
!
if (m <= 0) go to 30
onej = 1
do j = 1,m
   call cgesl(a, ka, n, ipvt, b(onej), 0)
   onej = onej + kb
end do
!
!                 Calculation of the inverse of A
!
30 if (mo == 0) call cgedi(a, ka, n, ipvt, d, wk, 1)
return
!
!                          Error return
!
40 ierr = -1
end subroutine cmslv1

subroutine cslvmp(mo, n, a, ka, b, x, wk, iwk, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, mo
integer :: n
complex, intent(in) :: a(ka,n), b(n)
complex, intent(inout) :: x(n), wk(*)
integer, intent(inout) :: iwk(n)
integer :: i, ir
!     ******************************************************************
!     Solution of complex linear equations with iterative improvement
!     ******************************************************************
!     -----------------
!     complex wk(n*n + n)
!     -----------------
if (mo /= 0) go to 10
!
!             Compute the LU decomposition of A
!
call cmcopy(n, n, a, ka, wk, n)
call cgefa(wk, n, n, iwk, ierr)
if (ierr == 0) go to 10
ierr = -ierr
return
!
!            Solve the system of equations AX = b
!
10 do i = 1,n
11 x(i) = b(i)
end do
!
ir = n*n + 1
call cgesl(wk, n, n, iwk, x, 0)
call cluimp(a, ka, n, wk(1), n, iwk, b, x, wk(ir), ierr)
end subroutine cslvmp

pure subroutine cluimp(a, ka, n, q, kq, ipvt, b, x, r, ind)
implicit none
integer, intent(out) :: ind
integer, intent(in) :: ka, kq, n
complex, intent(in) :: a(ka,n), q(kq,n), b(n)
complex, intent(inout) :: x(n), r(n)
integer, intent(in) :: ipvt(n)
integer :: i, j
real :: eps, eps2, rat, ratio, rnrm, xnrm
double precision :: ra, ia, rx, ix, rsum, isum
interface
   pure subroutine cgesl(a,lda,n,ipvt,b,job)
      implicit none
      integer, intent(in) :: lda
      complex, intent(in) :: a(lda,*)
      integer, intent(in) :: n
      integer, intent(in) :: ipvt(*)
      complex, intent(inout) :: b(*)
      integer, intent(in) :: job
   end subroutine cgesl
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
! ----------------------------------------------------------------------
!     Purpose
!       given an approximate solution x of a complex system AX = b
!       obtained using cgeco or cgefa. cluimp attempts to compute
!       an improved solution correct to machine precision.
!
!     Parameters
!
!       A    A COMPLEX ARRAY OF DIMENSION (ka,n) CONTAINING THE
!            matrix a of order n.
!       q    A COMPLEX ARRAY OF DIMENSION (kq,n) CONTAINING THE
!            LU decomposition of a produced by cgeco or cgefa.
!       ipvt an array of dimension n containing the permutation
!            information given by cgeco or cgefa.
!       b    the right hand side of the equation AX = b.
!       x    on input x is the approximate solution of AX = b to
!            be improved. On output x is the solution obtained.
!       r    A COMPLEX ARRAY FOR INTERNAL USE BY THE ROUTINE.
!       Ind  variable that reports the status of the results.
!            ind = 0 If improvement of x is successful with A
!            gain in accuracy of at least 50 per cent each
!            iteration. Otherwise ind = 1.
!
! ----------------------------------------------------------------------
!
!     ********** eps is a machine dependent parameter. Assign eps
!                the value U where U is the smallest floating point
!                number such that 1.0 + U .GT. 1.0.
!
eps = spmpar(1)
!
ind = 0
xnrm = 0.0
do i = 1,n
10 xnrm = xnrm + (real(x(i))**2 + aimag(x(i))**2)
end do
if (xnrm == 0.0) return
eps2 = eps*eps
ratio = 1.0
!
!                  Compute the residual vector
!
20 do i = 1,n
   rsum = dble(real(b(i)))
   isum = dble(aimag(b(i)))
   do j = 1,n
      ra = dble(real(a(i,j)))
      ia = dble(aimag(a(i,j)))
      rx = dble(real(x(j)))
      ix = dble(aimag(x(j)))
      rsum = rsum - ra*rx + ia*ix
21    isum = isum - ra*ix - ia*rx
   end do
22 r(i) = cmplx(sngl(rsum),sngl(isum))
end do
!
!                  Find the correction vector
!
call cgesl(q, kq, n, ipvt, r, 0)
rnrm = 0.0
do i = 1,n
30 rnrm = rnrm + (real(r(i))**2 + aimag(r(i))**2)
end do
if (rnrm <= eps2*xnrm) return
!
!                Form a new approximate solution
!
do i = 1,n
40 x(i) = x(i) + r(i)
end do
xnrm = 0.0
do i = 1,n
41 xnrm = xnrm + (real(x(i))**2 + aimag(x(i))**2)
end do
!
if (xnrm == 0.0) return
rat = ratio
ratio = rnrm/xnrm
if (ratio <= 0.25*rat) go to 20
!
if (ratio > min(rat,4.0*eps2)) ind = 1
end subroutine cluimp

subroutine cgeco(a,lda,n,ipvt,rcond,z)
implicit none
integer, intent(in) :: lda
integer :: n
integer, intent(inout) :: ipvt(*)
complex, intent(inout) :: a(lda,*), z(*)
real, intent(inout) :: rcond
complex :: cdotc, ek, t, wk, wkm
real :: anorm, s, scasum, sm, ynorm
integer :: info, j, k, kb, kp1, l
complex :: zdum, zdum1, zdum2, csign1
real :: cabs1
!
!     cgeco factors a complex matrix BY Gaussian elimination
!     and estimates the condition of the matrix.
!
!     If  rcond  is not needed, cgefa is slightly faster.
!     To solve  a*X = B , follow cgeco by cgesl.
!     To compute  inverse(a)*C , follow cgeco by cgesl.
!     To compute  determinant(a) , follow cgeco by cgedi.
!     To compute  inverse(a) , follow cgeco by cgedi.
!
!     On entry
!
!        A       COMPLEX(lda, n)
!                the matrix to be factored.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!     On return
!
!        A       AN UPPER TRIANGULAR MATRIX AND THE MULTIPLIERS
!                which were used to obtain it.
!                The factorization can be written  a = l*U  where
!                l  is a product of permutation and unit lower
!                triangular matrices and  U  is upper triangular.
!
!        ipvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        rcond   REAL
!                an estimate of the reciprocal condition of  A .
!                For the system  a*X = B , relative perturbations
!                in  A  and  B  of size  epsilon  may cause
!                relative perturbations in  X  of size  epsilon/rcond .
!                If  rcond  is so small that the logical expression
!                           1.0 + rcond .EQ. 1.0
!                is true, then  A  may be singular to working
!                precision.  In particular,  rcond  is zero  if
!                exact singularity is detected or the estimate
!                underflows.
!
!        z       COMPLEX(n)
!                a work vector whose contents are usually unimportant.
!                If  A  is close to a singular matrix, then  z  is
!                an approximate null vector in the sense that
!                norm(a*z) = rcond*norm(a)*norm(z) .
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     LINPACK cgefa
!     BLAS caxpy,cdotc,csscal,scasum
!     Fortran abs,aimag,AMAX1,cmplx,CONJG,real
!
!     Internal variables
!
!
cabs1(zdum) = abs(real(zdum)) + abs(aimag(zdum))
csign1(zdum1,zdum2) = cabs1(zdum1)*(zdum2/cabs1(zdum2))
!
!     Compute 1-norm of A
!
anorm = 0.0e0
do j = 1, n
   anorm = max(anorm,scasum(n,a(1,j),1))
end do
!
!     Factor
!
call cgefa(a,lda,n,ipvt,info)
!
!     rcond = 1/(norm(a)*(estimate of norm(inverse(a)))) .
!     ESTIMATE = NORM(z)/NORM(Y) WHERE  a*z = Y  AND  ctrans(a)*Y = E .
!     ctrans(a)  is the conjugate transpose of A .
!     The components of  E  are chosen to cause maximum local
!     growth in the elements of W  where  ctrans(U)*W = E .
!     The vectors are frequently rescaled to avoid overflow.
!
!     SOLVE ctrans(U)*W = E
!
ek = (1.0e0,0.0e0)
do j = 1, n
   z(j) = (0.0e0,0.0e0)
end do
do k = 1, n
   if (cabs1(z(k)) /= 0.0e0) ek = csign1(ek,-z(k))
   if (cabs1(ek - z(k)) <= cabs1(a(k,k))) go to 30
   s = cabs1(a(k,k))/cabs1(ek - z(k))
   call csscal(n,s,z,1)
   ek = cmplx(s,0.0e0)*ek
30 continue
   wk = ek - z(k)
   wkm = -ek - z(k)
   s = cabs1(wk)
   sm = cabs1(wkm)
   if (cabs1(a(k,k)) == 0.0e0) go to 40
   wk = wk/conjg(a(k,k))
   wkm = wkm/conjg(a(k,k))
   go to 50
40 continue
   wk = (1.0e0,0.0e0)
   wkm = (1.0e0,0.0e0)
50 continue
   kp1 = k + 1
   if (kp1 > n) go to 90
   do j = kp1, n
      sm = sm + cabs1(z(j) + wkm*conjg(a(k,j)))
      z(j) = z(j) + wk*conjg(a(k,j))
      s = s + cabs1(z(j))
   end do
   if (s >= sm) go to 80
   t = wkm - wk
   wk = wkm
   do j = kp1, n
      z(j) = z(j) + t*conjg(a(k,j))
   end do
80 continue
90 continue
   z(k) = wk
end do
s = 1.0e0/scasum(n,z,1)
call csscal(n,s,z,1)
!
!     SOLVE ctrans(l)*Y = W
!
do kb = 1, n
   k = n + 1 - kb
   if (k < n) z(k) = z(k) + cdotc(n - k,a(k + 1,k),1,z(k + 1),1)
   if (cabs1(z(k)) <= 1.0e0) go to 110
   s = 1.0e0/cabs1(z(k))
   call csscal(n,s,z,1)
110 continue
   l = ipvt(k)
   t = z(l)
   z(l) = z(k)
   z(k) = t
end do
s = 1.0e0/scasum(n,z,1)
call csscal(n,s,z,1)
!
ynorm = 1.0e0
!
!     SOLVE l*V = Y
!
do k = 1, n
   l = ipvt(k)
   t = z(l)
   z(l) = z(k)
   z(k) = t
   if (k < n) call caxpy(n - k,t,a(k + 1,k),1,z(k + 1),1)
   if (cabs1(z(k)) <= 1.0e0) go to 130
   s = 1.0e0/cabs1(z(k))
   call csscal(n,s,z,1)
   ynorm = s*ynorm
130 continue
end do
s = 1.0e0/scasum(n,z,1)
call csscal(n,s,z,1)
ynorm = s*ynorm
!
!     SOLVE  U*z = V
!
do kb = 1, n
   k = n + 1 - kb
   if (cabs1(z(k)) <= cabs1(a(k,k))) go to 150
   s = cabs1(a(k,k))/cabs1(z(k))
   call csscal(n,s,z,1)
   ynorm = s*ynorm
150 continue
   if (cabs1(a(k,k)) /= 0.0e0) z(k) = z(k)/a(k,k)
   if (cabs1(a(k,k)) == 0.0e0) z(k) = (1.0e0,0.0e0)
   t = -z(k)
   call caxpy(k - 1,t,a(1,k),1,z(1),1)
end do
!     MAKE ZNORM = 1.0
s = 1.0e0/scasum(n,z,1)
call csscal(n,s,z,1)
ynorm = s*ynorm
!
if (anorm /= 0.0e0) rcond = ynorm/anorm
if (anorm == 0.0e0) rcond = 0.0e0
end subroutine cgeco

subroutine cgefa(a,lda,n,ipvt,info)
implicit none
integer, intent(in) :: lda
integer :: n
integer, intent(inout) :: ipvt(*), info
complex, intent(inout) :: a(lda,*)
complex :: t
integer :: icamax, j, k, kp1, l, nm1
complex :: zdum
real :: cabs1
!
!     cgefa factors a complex matrix BY Gaussian elimination.
!
!     cgefa is usually called by cgeco, but it can be called
!     directly with a saving in time if  RCOND  is not needed.
!     (Time for cgeco) = (1 + 9/n)*(time for cgefa) .
!
!     On entry
!
!        A       COMPLEX(lda, n)
!                the matrix to be factored.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!     On return
!
!        A       AN UPPER TRIANGULAR MATRIX AND THE MULTIPLIERS
!                which were used to obtain it.
!                The factorization can be written  a = l*U  where
!                l  is a product of permutation and unit lower
!                triangular matrices and  U  is upper triangular.
!
!        ipvt    INTEGER(n)
!                an integer vector of pivot indices.
!
!        INFO    INTEGER
!                = 0  Normal value.
!                = k  if  U(k,k) .EQ. 0.0 .  this is not an error
!                     condition for this subroutine, but it does
!                     indicate that cgesl or cgedi will divide by zero
!                     if called.  Use  RCOND  in cgeco for a reliable
!                     indication of singularity.
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS caxpy,cscal,icamax
!     Fortran abs,aimag,real
!
!     Internal variables
!
!
cabs1(zdum) = abs(real(zdum)) + abs(aimag(zdum))
!
!     Gaussian elimination with partial pivoting
!
info = 0
nm1 = n - 1
if (nm1 < 1) go to 70
do k = 1, nm1
   kp1 = k + 1
!
!        Find l = Pivot index
!
   l = icamax(n - k + 1,a(k,k),1) + k - 1
   ipvt(k) = l
!
!        Zero pivot implies this column already triangularized
!
   if (cabs1(a(l,k)) == 0.0e0) go to 40
!
!           Interchange if necessary
!
   if (l == k) go to 10
   t = a(l,k)
   a(l,k) = a(k,k)
   a(k,k) = t
10 continue
!
!           Compute multipliers
!
   t = -(1.0e0,0.0e0)/a(k,k)
   call cscal(n - k,t,a(k + 1,k),1)
!
!           Row elimination with column indexing
!
   do j = kp1, n
      t = a(l,j)
      if (l == k) go to 20
      a(l,j) = a(k,j)
      a(k,j) = t
20    continue
      call caxpy(n - k,t,a(k + 1,k),1,a(k + 1,j),1)
   end do
   go to 50
40 continue
   info = k
50 continue
end do
70 continue
ipvt(n) = n
if (cabs1(a(n,n)) == 0.0e0) info = n
end subroutine cgefa

pure subroutine cgesl(a,lda,n,ipvt,b,job)
implicit none
integer, intent(in) :: lda, n, ipvt(*), job
complex, intent(in) :: a(lda,*)
complex, intent(inout) :: b(*)
complex :: t
integer :: k, kb, l, nm1
interface
   pure subroutine caxpy(n,ca,cx,incx,cy,incy)
      implicit none
      integer, intent(in) :: n
      complex, intent(in) :: ca
      complex, intent(in) :: cx(*)
      integer, intent(in) :: incx
      complex, intent(inout) :: cy(*)
      integer, intent(in) :: incy
   end subroutine caxpy
   pure function cdotc(n,cx,incx,cy,incy)
      implicit none
      integer, intent(in) :: n
      complex, intent(in) :: cx(*)
      integer, intent(in) :: incx
      complex, intent(in) :: cy(*)
      integer, intent(in) :: incy
      complex :: cdotc
   end function cdotc
end interface
!
!     cgesl solves the complex system
!     a * X = b  OR  ctrans(a) * X = b
!     using the factors computed by cgeco or cgefa.
!
!     On entry
!
!        A       COMPLEX(lda, n)
!                the output from cgeco or cgefa.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!        ipvt    INTEGER(n)
!                the pivot vector from cgeco or cgefa.
!
!        b       COMPLEX(n)
!                the right hand side vector.
!
!        JOB     INTEGER
!                = 0         To solve  a*X = b ,
!                = Nonzero   to solve  ctrans(a)*X = b  where
!                            ctrans(a)  is the conjugate transpose.
!
!     On return
!
!        b       THE SOLUTION VECTOR  X .
!
!     Error condition
!
!        A division by zero will occur if the input factor contains A
!        zero on the diagonal.  Technically this indicates singularity
!        but it is often caused by improper arguments or improper
!        setting of lda .  It will not occur if the subroutines are
!        called correctly and if cgeco has set RCOND .GT. 0.0
!        or cgefa has set info .EQ. 0 .
!
!     To compute  inverse(a) * C  where  C  is a matrix
!     with  P  columns
!           call cgeco(a,lda,n,ipvt,rcond,z)
!           if (rcond is too small) go to ...
!           do 10 j = 1, p
!              call cgesl(a,lda,n,ipvt,c(1,j),0)
!        10 continue
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS caxpy,cdotc
!     FORTRAN CONJG
!
!     Internal variables
!
!
nm1 = n - 1
if (job /= 0) go to 50
!
!        job = 0 , SOLVE  a * X = b
!        first solve  l*Y = b
!
if (nm1 < 1) go to 30
do k = 1, nm1
   l = ipvt(k)
   t = b(l)
   if (l == k) go to 10
   b(l) = b(k)
   b(k) = t
10 continue
   call caxpy(n - k,t,a(k + 1,k),1,b(k + 1),1)
end do
30 continue
!
!        Now solve  U*X = Y
!
do kb = 1, n
   k = n + 1 - kb
   b(k) = b(k)/a(k,k)
   t = -b(k)
   call caxpy(k - 1,t,a(1,k),1,b(1),1)
end do
go to 100
50 continue
!
!        job = NONZERO, SOLVE  ctrans(a) * X = b
!        first solve  ctrans(U)*Y = b
!
do k = 1, n
   t = cdotc(k - 1,a(1,k),1,b(1),1)
   b(k) = (b(k) - t)/conjg(a(k,k))
end do
!
!        Now solve ctrans(l)*X = Y
!
if (nm1 < 1) go to 90
do kb = 1, nm1
   k = n - kb
   b(k) = b(k) + cdotc(n - k,a(k + 1,k),1,b(k + 1),1)
   l = ipvt(k)
   if (l == k) go to 70
   t = b(l)
   b(l) = b(k)
   b(k) = t
70 continue
end do
90 continue
100 continue
end subroutine cgesl

subroutine cgedi(a,lda,n,ipvt,det,work,job)
implicit none
integer, intent(in) :: lda, n, ipvt(*), job
complex, intent(inout) :: a(lda,*), det(2), work(*)
complex :: t, zdum
real :: ten
integer :: i, j, k, kb, kp1, l, nm1
real :: cabs1
!
!     cgedi computes the determinant and inverse of a matrix
!     using the factors computed by cgeco or cgefa.
!
!     On entry
!
!        A       COMPLEX(lda, n)
!                the output from cgeco or cgefa.
!
!        lda     INTEGER
!                the leading dimension of the array  a .
!
!        n       INTEGER
!                the order of the matrix  a .
!
!        ipvt    INTEGER(n)
!                the pivot vector from cgeco or cgefa.
!
!        WORK    COMPLEX(n)
!                work vector.  Contents destroyed.
!
!        JOB     INTEGER
!                = 11   Both determinant and inverse.
!                = 01   Inverse only.
!                = 10   Determinant only.
!
!     On return
!
!        A       INVERSE OF ORIGINAL MATRIX IF REQUESTED.
!                Otherwise unchanged.
!
!        det     COMPLEX(2)
!                determinant of original matrix IF requested.
!                Otherwise not referenced.
!                determinant = det(1) * 10.0**det(2)
!                WITH  1.0 .LE. cabs1(det(1)) .LT. 10.0
!                OR  det(1) .EQ. 0.0 .
!
!     Error condition
!
!        A division by zero will occur if the input factor contains
!        a zero on the diagonal and the inverse is requested.
!        It will not occur if the subroutines are called correctly
!        and if cgeco has set RCOND .GT. 0.0 or cgefa has set
!        INFO .EQ. 0 .
!
!     LINPACK. This version dated 08/14/78 .
!     Cleve Moler, University of New Mexico, Argonne National Lab.
!
!     Subroutines and functions
!
!     BLAS caxpy,cscal,cswap
!     Fortran abs,aimag,cmplx,mod,real
!
!     Internal variables
!
!
cabs1(zdum) = abs(real(zdum)) + abs(aimag(zdum))
!
!     Compute determinant
!
if (job/10 == 0) go to 70
det(1) = (1.0e0,0.0e0)
det(2) = (0.0e0,0.0e0)
ten = 10.0e0
do i = 1, n
   if (ipvt(i) /= i) det(1) = -det(1)
   det(1) = a(i,i)*det(1)
!        ...Exit
   if (cabs1(det(1)) == 0.0e0) go to 60
10 if (cabs1(det(1)) >= 1.0e0) go to 20
   det(1) = cmplx(ten,0.0e0)*det(1)
   det(2) = det(2) - (1.0e0,0.0e0)
   go to 10
20 continue
30 if (cabs1(det(1)) < ten) go to 40
   det(1) = det(1)/cmplx(ten,0.0e0)
   det(2) = det(2) + (1.0e0,0.0e0)
   go to 30
40 continue
50 continue
end do
60 continue
70 continue
!
!     Compute inverse(U)
!
if (mod(job,10) == 0) go to 150
do k = 1, n
   a(k,k) = (1.0e0,0.0e0)/a(k,k)
   t = -a(k,k)
   call cscal(k - 1,t,a(1,k),1)
   kp1 = k + 1
   if (n < kp1) go to 90
   do j = kp1, n
      t = a(k,j)
      a(k,j) = (0.0e0,0.0e0)
      call caxpy(k,t,a(1,k),1,a(1,j),1)
   end do
90 continue
end do
!
!        Form inverse(U)*inverse(l)
!
nm1 = n - 1
if (nm1 < 1) go to 140
do kb = 1, nm1
   k = n - kb
   kp1 = k + 1
   do i = kp1, n
      work(i) = a(i,k)
      a(i,k) = (0.0e0,0.0e0)
   end do
   do j = kp1, n
      t = work(j)
      call caxpy(n,t,a(1,j),1,a(1,k),1)
   end do
   l = ipvt(k)
   if (l /= k) call cswap(n,a(1,k),1,a(1,l),1)
end do
140 continue
150 continue
end subroutine cgedi

subroutine dcmslv(mo,n,m,ar,ai,ka,br,bi,kb,ierr,ipvt,wk)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, m, mo
integer :: n
double precision, intent(inout) :: ar(ka,n), ai(ka,n), br(*), &
   & bi(*), wk(*)
integer, intent(inout) :: ipvt(n)
!-----------------------------------------------------------------------
!     Partial pivot Gauss procedure for inverting double precision
!     complex matrices and solving double precision complex equations
!-----------------------------------------------------------------------
!
if (n < 1 .or. ka < n) go to 30
if (m <= 0) go to 10
if (kb < n) go to 30
!
!                      Matrix factorization
!
10 call dcfact(ar, ai, ka, n, ipvt, ierr)
if (ierr /= 0) return
!
!                 Solution of the equation AX = B
!
if (m <= 0) go to 20
call dcsol(n, m, ar, ai, ka, br, bi, kb, ipvt)
!
!                 Calculation of the inverse of A
!
20 if (mo == 0) call dcminv(ar, ai, ka, n, ipvt, wk)
return
!
!                          Error return
!
30 ierr = -1
end subroutine dcmslv

pure subroutine dcfact(ar, ai, ka, n, ipvt, ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, n
double precision, intent(inout) :: ar(ka,n), ai(ka,n)
integer, intent(inout) :: ipvt(n)
integer :: i, j, k, kp1, l, nm1
double precision :: p, pr, pi, t, tr, ti
interface
   pure elemental subroutine cdivid(ar,ai,br,bi,cr,ci)
      implicit none
      double precision, intent(in) :: ar
      double precision, intent(in) :: ai
      double precision, intent(in) :: br
      double precision, intent(in) :: bi
      double precision, intent(inout) :: cr
      double precision, intent(inout) :: ci
   end subroutine cdivid
end interface
!-----------------------------------------------------------------------
!     Decomposes a complex matrix BY partial pivot Gauss elimination
!-----------------------------------------------------------------------
!
!     Input ...
!
!        ar and ai are the real and imaginary parts of the matrix A
!        to be decomposed.
!
!        ka = Declared row dimension of the arrays ar and ai
!
!        n  = Order of the matrix A
!
!     Output ...
!
!        ar and ai contain an upper triangular matrix U and the
!        multipliers needed to construct l so that A = l*U .
!
!        ipvt = The pivot vector.
!            ipvt(i) = The index of the k-TH pivot row (i .LT. n)
!            ipvt(n) = (-1)**(number of interchanges)
!
!        ierr is a variable that reports the status of the results.
!        ierr has one of the following values ...
!            ierr = 0   The decomposition of A was obtained.
!            ierr = k   the k-TH pivot element is 0.
!
!     If ierr = 0 Then the determinant of A has the value ...
!        det(a) = ipvt(n) * a(1,1) * a(2,2) * ... * a(n,n)
!-----------------------------------------------------------------------
!
ierr = 0
ipvt(n) = 1
if (n == 1) go to 50
nm1 = n - 1
!
do k = 1,nm1
   kp1 = k + 1
!
!               Search for the k-TH pivot element
!
   p = abs(ar(k,k)) + abs(ai(k,k))
   l = k
   do i = kp1,n
      t = abs(ar(i,k)) + abs(ai(i,k))
      if (p >= t) go to 10
      p = t
      l = i
10    continue
   end do
   if (p == 0.d0) go to 100
!
   pr = ar(l,k)
   pi = ai(l,k)
   ipvt(k) = l
   if (l == k) go to 20
   ipvt(n) = -ipvt(n)
   ar(l,k) = ar(k,k)
   ar(k,k) = pr
   ai(l,k) = ai(k,k)
   ai(k,k) = pi
!
!                    Compute the multipliers
!
20 call cdivid(1.d0, 0.d0, pr, pi, pr, pi)
   do i = kp1,n
      tr = ar(i,k)
      ti = ai(i,k)
      ar(i,k) = tr*pr - ti*pi
      ai(i,k) = tr*pi + ti*pr
   end do
!
!              Interchange and eliminate by columns
!
   do j = kp1,n
      tr = ar(l,j)
      ar(l,j) = ar(k,j)
      ar(k,j) = tr
      ti = ai(l,j)
      ai(l,j) = ai(k,j)
      ai(k,j) = ti
      if (abs(tr) + abs(ti) == 0.d0) go to 31
      do i = kp1,n
         ar(i,j) = ar(i,j) - ar(i,k)*tr + ai(i,k)*ti
         ai(i,j) = ai(i,j) - ar(i,k)*ti - ai(i,k)*tr
      end do
31    continue
   end do
end do
!
!                  Check the n-TH pivot element
!
50 if (abs(ar(n,n)) + abs(ai(n,n)) == 0.d0) ierr = n
return
!
!                    k-TH pivot element is 0
!
100 ierr = k
end subroutine dcfact

pure subroutine dcsol(n, m, ar, ai, ka, br, bi, kb, ipvt)
implicit none
integer, intent(in) :: ka, kb, m, n
double precision, intent(in) :: ar(ka,n), ai(ka,n)
double precision, intent(inout) :: br(kb,m), bi(kb,m)
integer, intent(in) :: ipvt(n)
integer :: i, j, k, km1, kp1, l, nm1
double precision :: pr, pi, tr, ti
interface
   pure elemental subroutine cdivid(ar,ai,br,bi,cr,ci)
      implicit none
      double precision, intent(in) :: ar
      double precision, intent(in) :: ai
      double precision, intent(in) :: br
      double precision, intent(in) :: bi
      double precision, intent(inout) :: cr
      double precision, intent(inout) :: ci
   end subroutine cdivid
end interface
!-----------------------------------------------------------------------
!     Solution of the system of m equations A*X = B using the
!     decomposition obtained by dcfact. This routine CANNOT be
!     used when dcfact terminates with nonzero IERR.
!-----------------------------------------------------------------------
!
!     Input ...
!
!        ar and ai contain the LU decomposition of the matrix
!        obtained by dcfact.
!
!        ka = Declared row dimension of the arrays ar and ai
!
!        n  = Order of the matrix
!
!        br and bi are the real and imaginary parts of the
!        right hand side matrix.
!
!        kb = Declared row dimension of the arrays br and bi
!
!        m  = Number of columns of B
!
!        ipvt = Pivot vector obtained from dcfact
!
!     Output ...
!
!        br and bi contain the real and imaginary parts of the
!        solution X.
!
!-----------------------------------------------------------------------
!
!                    Forward elimination
!
if (n == 1) go to 50
nm1 = n - 1
do k = 1, nm1
   kp1 = k + 1
   l = ipvt(k)
   do j = 1,m
      tr = br(l,j)
      br(l,j) = br(k,j)
      br(k,j) = tr
      ti = bi(l,j)
      bi(l,j) = bi(k,j)
      bi(k,j) = ti
      if (abs(tr) + abs(ti) == 0.d0) go to 11
      do i = kp1, n
         br(i,j) = br(i,j) - ar(i,k)*tr + ai(i,k)*ti
         bi(i,j) = bi(i,j) - ar(i,k)*ti - ai(i,k)*tr
      end do
11    continue
   end do
end do
!
!                   Backward elimination
!               for the last n - 1 Variables
!
do l = 1,nm1
   km1 = n - l
   k = km1 + 1
   call cdivid(1.d0, 0.d0, ar(k,k), ai(k,k), pr, pi)
   do j = 1,m
      tr = br(k,j)
      ti = bi(k,j)
      br(k,j) = tr*pr - ti*pi
      bi(k,j) = tr*pi + ti*pr
      tr = br(k,j)
      ti = bi(k,j)
      do i = 1, km1
         br(i,j) = br(i,j) - ar(i,k)*tr + ai(i,k)*ti
         bi(i,j) = bi(i,j) - ar(i,k)*ti - ai(i,k)*tr
      end do
   end do
end do
!
50 call cdivid(1.d0, 0.d0, ar(1,1), ai(1,1), pr, pi)
do j = 1,m
   tr = br(1,j)
   ti = bi(1,j)
   br(1,j) = tr*pr - ti*pi
   bi(1,j) = tr*pi + ti*pr
end do
end subroutine dcsol

subroutine dcminv(ar, ai, ka, n, ipvt, temp)
implicit none
integer, intent(in) :: ka
integer :: n
double precision, intent(inout) :: ar(ka,n), ai(ka,n), temp(2,n)
integer, intent(in) :: ipvt(n)
integer :: i, ip1, j, jb, k, kp1, l, nm1, nmi, nmk, np1
double precision :: sr, si, tr, ti
interface
   pure elemental subroutine cdivid(ar,ai,br,bi,cr,ci)
      implicit none
      double precision, intent(in) :: ar
      double precision, intent(in) :: ai
      double precision, intent(in) :: br
      double precision, intent(in) :: bi
      double precision, intent(inout) :: cr
      double precision, intent(inout) :: ci
   end subroutine cdivid
end interface
!-----------------------------------------------------------------------
!     Computation of the inverse of A matrix A using the LU
!     decomposition obtained by dcfact. This routine CANNOT
!     be used when dcfact terminates with nonzero IERR.
!-----------------------------------------------------------------------
!
!     Input ...
!
!        ar and ai contain the LU decomposition of the matrix
!        obtained by dcfact.
!
!        ka = Declared row dimension of the arrays ar and ai
!
!        n  = Order of the matrix
!
!        ipvt = Pivot vector obtained from dcfact
!
!        temp = Temporary storage area for the subroutine
!
!     Output ...
!
!        ar and ai contain the inverse of the matrix.
!
!-----------------------------------------------------------------------
!
call cdivid(1.d0, 0.d0, ar(n,n), ai(n,n), ar(n,n), ai(n,n))
if (n == 1) return
np1 = n + 1
nm1 = n - 1
!
!                Replace U with the inverse of U
!
do nmi = 1,nm1
   i = n - nmi
   ip1 = i + 1
   call cdivid(1.d0, 0.d0, ar(i,i), ai(i,i), tr, ti)
   do jb = 1,nmi
      j = np1 - jb
      sr = 0.d0
      si = 0.d0
      do l = ip1,j
         sr = sr + ar(i,l)*ar(l,j) - ai(i,l)*ai(l,j)
         si = si + ar(i,l)*ai(l,j) + ai(i,l)*ar(l,j)
      end do
      ar(i,j) = -sr*tr + si*ti
      ai(i,j) = -sr*ti - si*tr
   end do
   ar(i,i) = tr
   ai(i,i) = ti
end do
!
!                Compute  inverse(U)*inverse(l)
!
do nmk = 1,nm1
   k = n - nmk
   kp1 = k + 1
   do i = kp1,n
      temp(1,i) = ar(i,k)
      temp(2,i) = ai(i,k)
      ar(i,k) = 0.d0
      ai(i,k) = 0.d0
   end do
!
   do j = kp1,n
      tr = temp(1,j)
      ti = temp(2,j)
      do i = 1,n
         ar(i,k) = ar(i,k) - ar(i,j)*tr + ai(i,j)*ti
         ai(i,k) = ai(i,k) - ar(i,j)*ti - ai(i,j)*tr
      end do
   end do
!
   l = ipvt(k)
   if (k == l) go to 60
   do i = 1,n
      tr = ar(i,k)
      ar(i,k) = ar(i,l)
      ar(i,l) = tr
      ti = ai(i,k)
      ai(i,k) = ai(i,l)
50    ai(i,l) = ti
   end do
60 continue
end do
end subroutine dcminv

pure subroutine ssvdc(x,ldx,n,p,s,e,u,ldu,v,ldv,work,job,info)
implicit none
integer, intent(in) :: ldx, n, p, ldu, ldv, job
integer, intent(inout) :: info
real, intent(inout) :: x(ldx,*), s(*), e(*), u(ldu,*), v(ldv,*), &
   & work(*)
integer :: i, iter, j, jobu, k, kase, kk, l, ll, lls, lm1, lp1, &
   & ls, lu, m, maxit, mm, mm1, mp1, nct, nctp1, ncu, nrt, nrtp1
real :: t, b, c, cs, el, emm1, f, g, scale, shift, sl, sm, sn, smm1, t1, test, ztest
logical :: wantu, wantv
interface
   pure subroutine saxpy(n,sa,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine saxpy
   pure function sdot(n,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real, intent(in) :: sy(*)
      integer, intent(in) :: incy
      real :: sdot
   end function sdot
   pure function snrm2(n,sx,incx)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sx(*)
      integer, intent(in) :: incx
      real :: snrm2
   end function snrm2
   pure subroutine srot(n,sx,incx,sy,incy,c,s)
      implicit none
      integer, intent(in) :: n
      real, intent(inout) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
      real, intent(in) :: c
      real, intent(in) :: s
   end subroutine srot
   pure elemental subroutine srotg(sa,sb,sc,ss)
      implicit none
      real, intent(inout) :: sa
      real, intent(inout) :: sb
      real, intent(inout) :: sc
      real, intent(inout) :: ss
   end subroutine srotg
   pure subroutine sscal(n,sa,sx,incx)
      implicit none
      integer, intent(in) :: n
      real, intent(in) :: sa
      real, intent(inout) :: sx(*)
      integer, intent(in) :: incx
   end subroutine sscal
   pure subroutine sswap(n,sx,incx,sy,incy)
      implicit none
      integer, intent(in) :: n
      real, intent(inout) :: sx(*)
      integer, intent(in) :: incx
      real, intent(inout) :: sy(*)
      integer, intent(in) :: incy
   end subroutine sswap
end interface
!
!
!     ssvdc is a subroutine to reduce a real NXP matrix x by
!     orthogonal transformations u and v to diagonal form.  The
!     diagonal elements s(i) are the singular values of x.  the
!     columns of u are the corresponding left singular vectors,
!     and the columns of v the right singular vectors.
!
!     On entry
!
!         x         real(ldx,p), WHERE ldx.GE.N.
!                   x contains the matrix whose singular value
!                   decomposition is to be computed.  x is
!                   destroyed by ssvdc.
!
!         ldx       INTEGER.
!                   ldx is the leading dimension of the array x.
!
!         n         INTEGER.
!                   n is the number of rows of the matrix x.
!
!         p         INTEGER.
!                   p is the number of columns of the matrix x.
!
!         ldu       INTEGER.
!                   ldu is the leading dimension of the array u.
!                   (See below).
!
!         ldv       INTEGER.
!                   ldv is the leading dimension of the array v.
!                   (See below).
!
!         WORK      real(n).
!                   Work is a scratch array.
!
!         JOB       INTEGER.
!                   Job controls the computation of the singular
!                   vectors.  It has the decimal expansion AB
!                   with the following meaning
!
!                        A.EQ.0    do not compute the left singular
!                                  vectors.
!                        A.EQ.1    return the n left singular vectors
!                                  IN u.
!                        A.GE.2    return the first min(n,p) singular
!                                  vectors in u.
!                        b.EQ.0    do not compute the right singular
!                                  vectors.
!                        b.EQ.1    return the right singular vectors
!                                  IN v.
!
!     On return
!
!         s         real(MM), WHERE MM=min(n+1,p).
!                   The first min(n,p) entries of s contain the
!                   singular values of x arranged in descending
!                   order of magnitude.
!
!         e         real(p).
!                   e ordinarily contains zeros.  However see the
!                   discussion of info for exceptions.
!
!         u         real(ldu,k), WHERE ldu.GE.N.  IF JOBA.EQ.1 THEN
!                                   k.EQ.n, IF JOBA.GE.2 THEN
!                                   k.EQ.min(n,p).
!                   u contains the matrix of left singular vectors.
!                   u is not referenced if JOBA.EQ.0.  if n.LE.p
!                   or if JOBA.EQ.2, then u may be identified with x
!                   in the subroutine CALL.
!
!         v         real(ldv,p), WHERE ldv.GE.P.
!                   v contains the matrix of right singular vectors.
!                   v is not referenced if job.EQ.0.  if p.LE.n,
!                   then v may be identified with x in the
!                   subroutine CALL.
!
!         INFO      INTEGER.
!                   The singular values (and their corresponding
!                   singular vectors) s(info+1),s(info+2),...,s(M)
!                   are correct (here M=min(n,p)).  Thus if
!                   info.EQ.0, all the singular values and their
!                   vectors are correct.  In any event, the matrix
!                   b = Trans(u)*x*v is the bidiagonal matrix
!                   with the elements of s on its diagonal and the
!                   elements of e on its super-diagonal (trans(u)
!                   is the transpose of u).  Thus the singular
!                   values of x and b are the same.
!
!     LINPACK. This version dated 03/19/79 .
!     G.W. Stewart, university of maryland, Argonne National Lab.
!
!     ***** Uses the following functions and subprograms.
!
!     external srot
!     BLAS saxpy,sdot,sscal,sswap,snrm2,srotg
!     Fortran abs,AMAX1,MAX0,MIN0,mod,sqrt
!
!     Internal variables
!
!
!
!     Set the maximum number of iterations.
!
maxit = 30
!
!     Determine what is to be computed.
!
wantu = .false.
wantv = .false.
jobu = mod(job,100)/10
ncu = n
if (jobu > 1) ncu = min(n,p)
if (jobu /= 0) wantu = .true.
if (mod(job,10) /= 0) wantv = .true.
!
!     Reduce x to bidiagonal form, storing the diagonal elements
!     in s and the super-diagonal elements in e.
!
info = 0
nct = min(n - 1,p)
nrt = max(0,min(p - 2,n))
lu = max(nct,nrt)
if (lu < 1) go to 170
do l = 1, lu
   lp1 = l + 1
   if (l > nct) go to 20
!
!           Compute the transformation for the l-TH column and
!           place the l-TH diagonal in s(l).
!
   s(l) = snrm2(n - l + 1,x(l,l),1)
   if (s(l) == 0.0e0) go to 10
   if (x(l,l) /= 0.0e0) s(l) = sign(s(l),x(l,l))
   call sscal(n - l + 1,1.0e0/s(l),x(l,l),1)
   x(l,l) = 1.0e0 + x(l,l)
10 continue
   s(l) = -s(l)
20 continue
   if (p < lp1) go to 50
   do j = lp1, p
      if (l > nct) go to 30
      if (s(l) == 0.0e0) go to 30
!
!              Apply the transformation.
!
      t = -sdot(n - l + 1,x(l,l),1,x(l,j),1)/x(l,l)
      call saxpy(n - l + 1,t,x(l,l),1,x(l,j),1)
30    continue
!
!           Place the l-TH row of x into  e for the
!           subsequent calculation of the row transformation.
!
      e(j) = x(l,j)
40    continue
   end do
50 continue
   if (.not.wantu .or. l > nct) go to 70
!
!           Place the transformation in u for subsequent back
!           multiplication.
!
   do i = l, n
      u(i,l) = x(i,l)
   end do
70 continue
   if (l > nrt) go to 150
!
!           Compute the l-TH row transformation and place the
!           l-TH super-diagonal in e(l).
!
   e(l) = snrm2(p - l,e(lp1),1)
   if (e(l) == 0.0e0) go to 80
   if (e(lp1) /= 0.0e0) e(l) = sign(e(l),e(lp1))
   call sscal(p - l,1.0e0/e(l),e(lp1),1)
   e(lp1) = 1.0e0 + e(lp1)
80 continue
   e(l) = -e(l)
   if (lp1 > n .or. e(l) == 0.0e0) go to 120
!
!              Apply the transformation.
!
   do i = lp1, n
      work(i) = 0.0e0
   end do
   do j = lp1, p
      call saxpy(n - l,e(j),x(lp1,j),1,work(lp1),1)
100   continue
   end do
   do j = lp1, p
      call saxpy(n - l,-e(j)/e(lp1),work(lp1),1,x(lp1,j),1)
   end do
120 continue
   if (.not.wantv) go to 140
!
!              Place the transformation in v for subsequent
!              back multiplication.
!
   do i = lp1, p
      v(i,l) = e(i)
   end do
140 continue
150 continue
160 continue
end do
170 continue
!
!     Set up the final bidiagonal matrix of order M.
!
m = min(p,n + 1)
nctp1 = nct + 1
nrtp1 = nrt + 1
if (nct < p) s(nctp1) = x(nctp1,nctp1)
if (n < m) s(m) = 0.0e0
if (nrtp1 < m) e(nrtp1) = x(nrtp1,m)
e(m) = 0.0e0
!
!     If required, generate u.
!
if (.not.wantu) go to 300
if (ncu < nctp1) go to 200
do j = nctp1, ncu
   do i = 1, n
      u(i,j) = 0.0e0
   end do
   u(j,j) = 1.0e0
end do
200 continue
if (nct < 1) go to 290
do ll = 1, nct
   l = nct - ll + 1
   if (s(l) == 0.0e0) go to 250
   lp1 = l + 1
   if (ncu < lp1) go to 220
   do j = lp1, ncu
      t = -sdot(n - l + 1,u(l,l),1,u(l,j),1)/u(l,l)
      call saxpy(n - l + 1,t,u(l,l),1,u(l,j),1)
   end do
220 continue
   call sscal(n - l + 1,-1.0e0,u(l,l),1)
   u(l,l) = 1.0e0 + u(l,l)
   lm1 = l - 1
   if (lm1 < 1) go to 240
   do i = 1, lm1
      u(i,l) = 0.0e0
   end do
240 continue
   go to 270
250 continue
   do i = 1, n
      u(i,l) = 0.0e0
   end do
   u(l,l) = 1.0e0
270 continue
end do
290 continue
300 continue
!
!     If it is required, generate v.
!
if (.not.wantv) go to 350
do ll = 1, p
   l = p - ll + 1
   lp1 = l + 1
   if (l > nrt) go to 320
   if (e(l) == 0.0e0) go to 320
   do j = lp1, p
      t = -sdot(p - l,v(lp1,l),1,v(lp1,j),1)/v(lp1,l)
      call saxpy(p - l,t,v(lp1,l),1,v(lp1,j),1)
   end do
320 continue
   do i = 1, p
      v(i,l) = 0.0e0
   end do
   v(l,l) = 1.0e0
end do
350 continue
!
!     Main iteration loop for the singular values.
!
mm = m
iter = 0
360 continue
!
!        Quit if all the singular values have been found.
!
!     ...Exit
if (m == 0) go to 620
!
!        If too many iterations have been performed, set
!        flag and return.
!
if (iter < maxit) go to 370
info = m
!     ......Exit
go to 620
370 continue
!
!        This section of the program inspects for
!        negligible elements in the s and e arrays.  On
!        completion the variables kase and l are set as follows.
!
!           kase = 1     If s(M) and e(l-1) are negligible and l.LT.M
!           kase = 2     If s(l) is negligible and l.LT.M
!           kase = 3     If e(l-1) is negligible, l.LT.M, and
!                        s(l), ..., s(M) are not negligible (QR step).
!           kase = 4     If e(M-1) is negligible (convergence).
!
do ll = 1, m
   l = m - ll
!        ...Exit
   if (l == 0) go to 400
   test = abs(s(l)) + abs(s(l + 1))
   ztest = test + abs(e(l))
   if (ztest /= test) go to 380
   e(l) = 0.0e0
!        ......Exit
   go to 400
380 continue
end do
400 continue
if (l /= m - 1) go to 410
kase = 4
go to 480
410 continue
lp1 = l + 1
mp1 = m + 1
do lls = lp1, mp1
   ls = m - lls + lp1
!           ...Exit
   if (ls == l) go to 440
   test = 0.0e0
   if (ls /= m) test = test + abs(e(ls))
   if (ls /= l + 1) test = test + abs(e(ls - 1))
   ztest = test + abs(s(ls))
   if (ztest /= test) go to 420
   s(ls) = 0.0e0
!           ......Exit
   go to 440
420 continue
end do
440 continue
if (ls /= l) go to 450
kase = 3
go to 470
450 continue
if (ls /= m) go to 460
kase = 1
go to 470
460 continue
kase = 2
l = ls
470 continue
480 continue
l = l + 1
!
!        Perform the task indicated by kase.
!
go to (490,520,540,570), kase
!
!        Deflate negligible s(M).
!
490 continue
mm1 = m - 1
f = e(m - 1)
e(m - 1) = 0.0e0
do kk = l, mm1
   k = mm1 - kk + l
   t1 = s(k)
   call srotg(t1,f,cs,sn)
   s(k) = t1
   if (k == l) go to 500
   f = -sn*e(k - 1)
   e(k - 1) = cs*e(k - 1)
500 continue
   if (wantv) call srot(p,v(1,k),1,v(1,m),1,cs,sn)
end do
go to 610
!
!        Split at negligible s(l).
!
520 continue
f = e(l - 1)
e(l - 1) = 0.0e0
do k = l, m
   t1 = s(k)
   call srotg(t1,f,cs,sn)
   s(k) = t1
   f = -sn*e(k)
   e(k) = cs*e(k)
   if (wantu) call srot(n,u(1,k),1,u(1,l - 1),1,cs,sn)
end do
go to 610
!
!        Perform one QR step.
!
540 continue
!
!           Calculate the shift.
!
scale = max(abs(s(m)),abs(s(m - 1)),abs(e(m - 1)),abs(s(l)), &
   & abs(e(l)))
sm = s(m)/scale
smm1 = s(m - 1)/scale
emm1 = e(m - 1)/scale
sl = s(l)/scale
el = e(l)/scale
b = ((smm1 + sm)*(smm1 - sm) + emm1**2)/2.0e0
c = (sm*emm1)**2
shift = 0.0e0
if (b == 0.0e0 .and. c == 0.0e0) go to 550
shift = sqrt(b**2 + c)
if (b < 0.0e0) shift = -shift
shift = c/(b + shift)
550 continue
f = (sl + sm)*(sl - sm) - shift
g = sl*el
!
!           Chase zeros.
!
mm1 = m - 1
do k = l, mm1
   call srotg(f,g,cs,sn)
   if (k /= l) e(k - 1) = f
   f = cs*s(k) + sn*e(k)
   e(k) = cs*e(k) - sn*s(k)
   g = sn*s(k + 1)
   s(k + 1) = cs*s(k + 1)
   if (wantv) call srot(p,v(1,k),1,v(1,k + 1),1,cs,sn)
   call srotg(f,g,cs,sn)
   s(k) = f
   f = cs*e(k) + sn*s(k + 1)
   s(k + 1) = -sn*e(k) + cs*s(k + 1)
   g = sn*e(k + 1)
   e(k + 1) = cs*e(k + 1)
   if (wantu .and. k < n) &
      & call srot(n,u(1,k),1,u(1,k + 1),1,cs,sn)
end do
e(m - 1) = f
iter = iter + 1
go to 610
!
!        Convergence.
!
570 continue
!
!           Make the singular value  positive.
!
if (s(l) >= 0.0e0) go to 580
s(l) = -s(l)
if (wantv) call sscal(p,-1.0e0,v(1,l),1)
580 continue
!
!           Order the singular value.
!
590 if (l == mm) go to 600
!           ...Exit
if (s(l) >= s(l + 1)) go to 600
t = s(l)
s(l) = s(l + 1)
s(l + 1) = t
if (wantv .and. l < p) &
   & call sswap(p,v(1,l),1,v(1,l + 1),1)
if (wantu .and. l < n) &
   & call sswap(n,u(1,l),1,u(1,l + 1),1)
l = l + 1
go to 590
600 continue
iter = 0
m = m - 1
610 continue
go to 360
620 continue
end subroutine ssvdc

pure subroutine dsvdc(x,ldx,n,p,s,e,u,ldu,v,ldv,work,job,info)
implicit none
integer, intent(in) :: ldx, n, p, ldu, ldv, job
integer, intent(inout) :: info
double precision, intent(inout) :: x(ldx,*), s(*), e(*), u(ldu,*), &
   & v(ldv,*), work(*)
integer :: i, iter, j, jobu, k, kase, kk, l, ll, lls, lm1, lp1, &
   & ls, lu, m, maxit, mm, mm1, mp1, nct, nctp1, ncu, nrt, nrtp1
double precision :: t, b, c, cs, el, emm1, f, g, scale, shift, sl, sm, sn, smm1, t1, test, ztest
logical :: wantu, wantv
interface
   pure subroutine daxpy(n,da,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
   end subroutine daxpy
   pure function ddot(n,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(in) :: dy(*)
      integer, intent(in) :: incy
      double precision :: ddot
   end function ddot
   pure function dnrm2(n,dx,incx)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: dx(*)
      integer, intent(in) :: incx
      double precision :: dnrm2
   end function dnrm2
   pure subroutine drot(n,dx,incx,dy,incy,c,s)
      implicit none
      integer, intent(in) :: n
      double precision, intent(inout) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
      double precision, intent(in) :: c
      double precision, intent(in) :: s
   end subroutine drot
   pure elemental subroutine drotg(da,db,dc,ds)
      implicit none
      double precision, intent(inout) :: da
      double precision, intent(inout) :: db
      double precision, intent(inout) :: dc
      double precision, intent(inout) :: ds
   end subroutine drotg
   pure subroutine dscal(n,da,dx,incx)
      implicit none
      integer, intent(in) :: n
      double precision, intent(in) :: da
      double precision, intent(inout) :: dx(*)
      integer, intent(in) :: incx
   end subroutine dscal
   pure subroutine dswap(n,dx,incx,dy,incy)
      implicit none
      integer, intent(in) :: n
      double precision, intent(inout) :: dx(*)
      integer, intent(in) :: incx
      double precision, intent(inout) :: dy(*)
      integer, intent(in) :: incy
   end subroutine dswap
end interface
!
!
!     dsvdc is a subroutine to reduce a double precision NXP matrix x
!     by orthogonal transformations u and V to diagonal form.  The
!     diagonal elements s(i) are the singular values of x.  the
!     columns of u are the corresponding left singular vectors,
!     and the columns of V the right singular vectors.
!
!     On entry
!
!         x         DOUBLE PRECISION(ldx,p), WHERE ldx.GE.N.
!                   x contains the matrix whose singular value
!                   decomposition is to be computed.  x is
!                   destroyed by dsvdc.
!
!         ldx       INTEGER.
!                   ldx is the leading dimension of the array x.
!
!         n         INTEGER.
!                   n is the number of rows of the matrix x.
!
!         p         INTEGER.
!                   p is the number of columns of the matrix x.
!
!         ldu       INTEGER.
!                   ldu is the leading dimension of the array u.
!                   (See below).
!
!         ldv       INTEGER.
!                   ldv is the leading dimension of the array V.
!                   (See below).
!
!         WORK      DOUBLE PRECISION(n).
!                   Work is a scratch array.
!
!         JOB       INTEGER.
!                   Job controls the computation of the singular
!                   vectors.  It has the decimal expansion AB
!                   with the following meaning
!
!                        A.EQ.0    do not compute the left singular
!                                  vectors.
!                        A.EQ.1    return the n left singular vectors
!                                  IN u.
!                        A.GE.2    return the first min(n,p) singular
!                                  vectors in u.
!                        b.EQ.0    do not compute the right singular
!                                  vectors.
!                        b.EQ.1    return the right singular vectors
!                                  IN V.
!
!     On return
!
!         s         DOUBLE PRECISION(MM), WHERE MM=min(n+1,p).
!                   The first min(n,p) entries of s contain the
!                   singular values of x arranged in descending
!                   order of magnitude.
!
!         e         DOUBLE PRECISION(p).
!                   e ordinarily contains zeros.  However see the
!                   discussion of info for exceptions.
!
!         u         DOUBLE PRECISION(ldu,k), WHERE ldu.GE.N.  IF
!                                   JOBA.EQ.1 THEN k.EQ.n, IF JOBA.GE.2
!                                   THEN k.EQ.min(n,p).
!                   u contains the matrix of left singular vectors.
!                   u is not referenced if JOBA.EQ.0.  if n.LE.p
!                   or if JOBA.EQ.2, then u may be identified with x
!                   in the subroutine CALL.
!
!         V         DOUBLE PRECISION(ldv,p), WHERE ldv.GE.P.
!                   V contains the matrix of right singular vectors.
!                   V is not referenced if job.EQ.0.  if p.LE.n,
!                   then V may be identified with x in the
!                   subroutine CALL.
!
!         INFO      INTEGER.
!                   The singular values (and their corresponding
!                   singular vectors) s(info+1),s(info+2),...,s(M)
!                   are correct (here M=min(n,p)).  Thus if
!                   info.EQ.0, all the singular values and their
!                   vectors are correct.  In any event, the matrix
!                   b = Trans(u)*x*V is the bidiagonal matrix
!                   with the elements of s on its diagonal and the
!                   elements of e on its super-diagonal (trans(u)
!                   is the transpose of u).  Thus the singular
!                   values of x and b are the same.
!
!     LINPACK. This version dated 03/19/79 .
!     G.W. Stewart, university of maryland, Argonne National Lab.
!
!     dsvdc uses the following functions and subprograms.
!
!     external drot
!     BLAS daxpy,ddot,dscal,dswap,dnrm2,drotg
!     Fortran dabs,DMAX1,MAX0,MIN0,mod,DSQRT
!
!     Internal variables
!
!
!
!     Set the maximum number of iterations.
!
maxit = 30
!
!     Determine what is to be computed.
!
wantu = .false.
wantv = .false.
jobu = mod(job,100)/10
ncu = n
if (jobu > 1) ncu = min(n,p)
if (jobu /= 0) wantu = .true.
if (mod(job,10) /= 0) wantv = .true.
!
!     Reduce x to bidiagonal form, storing the diagonal elements
!     in s and the super-diagonal elements in e.
!
info = 0
nct = min(n - 1,p)
nrt = max(0,min(p - 2,n))
lu = max(nct,nrt)
if (lu < 1) go to 170
do l = 1, lu
   lp1 = l + 1
   if (l > nct) go to 20
!
!           Compute the transformation for the l-TH column and
!           place the l-TH diagonal in s(l).
!
   s(l) = dnrm2(n - l + 1,x(l,l),1)
   if (s(l) == 0.0d0) go to 10
   if (x(l,l) /= 0.0d0) s(l) = sign(s(l),x(l,l))
   call dscal(n - l + 1,1.0d0/s(l),x(l,l),1)
   x(l,l) = 1.0d0 + x(l,l)
10 continue
   s(l) = -s(l)
20 continue
   if (p < lp1) go to 50
   do j = lp1, p
      if (l > nct) go to 30
      if (s(l) == 0.0d0) go to 30
!
!              Apply the transformation.
!
      t = -ddot(n - l + 1,x(l,l),1,x(l,j),1)/x(l,l)
      call daxpy(n - l + 1,t,x(l,l),1,x(l,j),1)
30    continue
!
!           Place the l-TH row of x into  e for the
!           subsequent calculation of the row transformation.
!
      e(j) = x(l,j)
40    continue
   end do
50 continue
   if (.not.wantu .or. l > nct) go to 70
!
!           Place the transformation in u for subsequent back
!           multiplication.
!
   do i = l, n
      u(i,l) = x(i,l)
   end do
70 continue
   if (l > nrt) go to 150
!
!           Compute the l-TH row transformation and place the
!           l-TH super-diagonal in e(l).
!
   e(l) = dnrm2(p - l,e(lp1),1)
   if (e(l) == 0.0d0) go to 80
   if (e(lp1) /= 0.0d0) e(l) = sign(e(l),e(lp1))
   call dscal(p - l,1.0d0/e(l),e(lp1),1)
   e(lp1) = 1.0d0 + e(lp1)
80 continue
   e(l) = -e(l)
   if (lp1 > n .or. e(l) == 0.0d0) go to 120
!
!              Apply the transformation.
!
   do i = lp1, n
      work(i) = 0.0d0
   end do
   do j = lp1, p
      call daxpy(n - l,e(j),x(lp1,j),1,work(lp1),1)
100   continue
   end do
   do j = lp1, p
      call daxpy(n - l,-e(j)/e(lp1),work(lp1),1,x(lp1,j),1)
   end do
120 continue
   if (.not.wantv) go to 140
!
!              Place the transformation in V for subsequent
!              back multiplication.
!
   do i = lp1, p
      v(i,l) = e(i)
   end do
140 continue
150 continue
160 continue
end do
170 continue
!
!     Set up the final bidiagonal matrix of order M.
!
m = min(p,n + 1)
nctp1 = nct + 1
nrtp1 = nrt + 1
if (nct < p) s(nctp1) = x(nctp1,nctp1)
if (n < m) s(m) = 0.0d0
if (nrtp1 < m) e(nrtp1) = x(nrtp1,m)
e(m) = 0.0d0
!
!     If required, generate u.
!
if (.not.wantu) go to 300
if (ncu < nctp1) go to 200
do j = nctp1, ncu
   do i = 1, n
      u(i,j) = 0.0d0
   end do
   u(j,j) = 1.0d0
end do
200 continue
if (nct < 1) go to 290
do ll = 1, nct
   l = nct - ll + 1
   if (s(l) == 0.0d0) go to 250
   lp1 = l + 1
   if (ncu < lp1) go to 220
   do j = lp1, ncu
      t = -ddot(n - l + 1,u(l,l),1,u(l,j),1)/u(l,l)
      call daxpy(n - l + 1,t,u(l,l),1,u(l,j),1)
   end do
220 continue
   call dscal(n - l + 1,-1.0d0,u(l,l),1)
   u(l,l) = 1.0d0 + u(l,l)
   lm1 = l - 1
   if (lm1 < 1) go to 240
   do i = 1, lm1
      u(i,l) = 0.0d0
   end do
240 continue
   go to 270
250 continue
   do i = 1, n
      u(i,l) = 0.0d0
   end do
   u(l,l) = 1.0d0
270 continue
end do
290 continue
300 continue
!
!     If it is required, generate V.
!
if (.not.wantv) go to 350
do ll = 1, p
   l = p - ll + 1
   lp1 = l + 1
   if (l > nrt) go to 320
   if (e(l) == 0.0d0) go to 320
   do j = lp1, p
      t = -ddot(p - l,v(lp1,l),1,v(lp1,j),1)/v(lp1,l)
      call daxpy(p - l,t,v(lp1,l),1,v(lp1,j),1)
   end do
320 continue
   do i = 1, p
      v(i,l) = 0.0d0
   end do
   v(l,l) = 1.0d0
end do
350 continue
!
!     Main iteration loop for the singular values.
!
mm = m
iter = 0
360 continue
!
!        Quit if all the singular values have been found.
!
!     ...Exit
if (m == 0) go to 620
!
!        If too many iterations have been performed, set
!        flag and return.
!
if (iter < maxit) go to 370
info = m
!     ......Exit
go to 620
370 continue
!
!        This section of the program inspects for
!        negligible elements in the s and e arrays.  On
!        completion the variables kase and l are set as follows.
!
!           kase = 1     If s(M) and e(l-1) are negligible and l.LT.M
!           kase = 2     If s(l) is negligible and l.LT.M
!           kase = 3     If e(l-1) is negligible, l.LT.M, and
!                        s(l), ..., s(M) are not negligible (QR step).
!           kase = 4     If e(M-1) is negligible (convergence).
!
do ll = 1, m
   l = m - ll
!        ...Exit
   if (l == 0) go to 400
   test = abs(s(l)) + abs(s(l + 1))
   ztest = test + abs(e(l))
   if (ztest /= test) go to 380
   e(l) = 0.0d0
!        ......Exit
   go to 400
380 continue
end do
400 continue
if (l /= m - 1) go to 410
kase = 4
go to 480
410 continue
lp1 = l + 1
mp1 = m + 1
do lls = lp1, mp1
   ls = m - lls + lp1
!           ...Exit
   if (ls == l) go to 440
   test = 0.0d0
   if (ls /= m) test = test + abs(e(ls))
   if (ls /= l + 1) test = test + abs(e(ls - 1))
   ztest = test + abs(s(ls))
   if (ztest /= test) go to 420
   s(ls) = 0.0d0
!           ......Exit
   go to 440
420 continue
end do
440 continue
if (ls /= l) go to 450
kase = 3
go to 470
450 continue
if (ls /= m) go to 460
kase = 1
go to 470
460 continue
kase = 2
l = ls
470 continue
480 continue
l = l + 1
!
!        Perform the task indicated by kase.
!
go to (490,520,540,570), kase
!
!        Deflate negligible s(M).
!
490 continue
mm1 = m - 1
f = e(m - 1)
e(m - 1) = 0.0d0
do kk = l, mm1
   k = mm1 - kk + l
   t1 = s(k)
   call drotg(t1,f,cs,sn)
   s(k) = t1
   if (k == l) go to 500
   f = -sn*e(k - 1)
   e(k - 1) = cs*e(k - 1)
500 continue
   if (wantv) call drot(p,v(1,k),1,v(1,m),1,cs,sn)
end do
go to 610
!
!        Split at negligible s(l).
!
520 continue
f = e(l - 1)
e(l - 1) = 0.0d0
do k = l, m
   t1 = s(k)
   call drotg(t1,f,cs,sn)
   s(k) = t1
   f = -sn*e(k)
   e(k) = cs*e(k)
   if (wantu) call drot(n,u(1,k),1,u(1,l - 1),1,cs,sn)
end do
go to 610
!
!        Perform one QR step.
!
540 continue
!
!           Calculate the shift.
!
scale = max(abs(s(m)),abs(s(m - 1)),abs(e(m - 1)), &
   & abs(s(l)),abs(e(l)))
sm = s(m)/scale
smm1 = s(m - 1)/scale
emm1 = e(m - 1)/scale
sl = s(l)/scale
el = e(l)/scale
b = ((smm1 + sm)*(smm1 - sm) + emm1**2)/2.0d0
c = (sm*emm1)**2
shift = 0.0d0
if (b == 0.0d0 .and. c == 0.0d0) go to 550
shift = sqrt(b**2 + c)
if (b < 0.0d0) shift = -shift
shift = c/(b + shift)
550 continue
f = (sl + sm)*(sl - sm) - shift
g = sl*el
!
!           Chase zeros.
!
mm1 = m - 1
do k = l, mm1
   call drotg(f,g,cs,sn)
   if (k /= l) e(k - 1) = f
   f = cs*s(k) + sn*e(k)
   e(k) = cs*e(k) - sn*s(k)
   g = sn*s(k + 1)
   s(k + 1) = cs*s(k + 1)
   if (wantv) call drot(p,v(1,k),1,v(1,k + 1),1,cs,sn)
   call drotg(f,g,cs,sn)
   s(k) = f
   f = cs*e(k) + sn*s(k + 1)
   s(k + 1) = -sn*e(k) + cs*s(k + 1)
   g = sn*e(k + 1)
   e(k + 1) = cs*e(k + 1)
   if (wantu .and. k < n) &
      & call drot(n,u(1,k),1,u(1,k + 1),1,cs,sn)
end do
e(m - 1) = f
iter = iter + 1
go to 610
!
!        Convergence.
!
570 continue
!
!           Make the singular value  positive.
!
if (s(l) >= 0.0d0) go to 580
s(l) = -s(l)
if (wantv) call dscal(p,-1.0d0,v(1,l),1)
580 continue
!
!           Order the singular value.
!
590 if (l == mm) go to 600
!           ...Exit
if (s(l) >= s(l + 1)) go to 600
t = s(l)
s(l) = s(l + 1)
s(l + 1) = t
if (wantv .and. l < p) &
   & call dswap(p,v(1,l),1,v(1,l + 1),1)
if (wantu .and. l < n) &
   & call dswap(n,u(1,l),1,u(1,l + 1),1)
l = l + 1
go to 590
600 continue
iter = 0
m = m - 1
610 continue
go to 360
620 continue
end subroutine dsvdc

pure subroutine csvdc(x,ldx,n,p,s,e,u,ldu,v,ldv,work,job,info)
implicit none
integer, intent(in) :: ldx, n, p, ldu, ldv, job
integer, intent(inout) :: info
complex, intent(inout) :: x(ldx,*), s(*), e(*), u(ldu,*), &
   & v(ldv,*), work(*)
integer :: i, iter, j, jobu, k, kase, kk, l, ll, lls, lm1, lp1, &
   & ls, lu, m, maxit, mm, mm1, mp1, nct, nctp1, ncu, nrt, nrtp1
complex :: t, r
real :: b, c, cs, el, emm1, f, g, scale, shift, sl, sm, sn, smm1, t1, test, ztest
logical :: wantu, wantv
complex :: csign, zdum, zdum1, zdum2
real :: cabs1
interface
   pure subroutine caxpy(n,ca,cx,incx,cy,incy)
      implicit none
      integer, intent(in) :: n
      complex, intent(in) :: ca
      complex, intent(in) :: cx(*)
      integer, intent(in) :: incx
      complex, intent(inout) :: cy(*)
      integer, intent(in) :: incy
   end subroutine caxpy
   pure function cdotc(n,cx,incx,cy,incy)
      implicit none
      integer, intent(in) :: n
      complex, intent(in) :: cx(*)
      integer, intent(in) :: incx
      complex, intent(in) :: cy(*)
      integer, intent(in) :: incy
      complex :: cdotc
   end function cdotc
   pure subroutine cscal(n,ca,cx,incx)
      implicit none
      integer, intent(in) :: n
      complex, intent(in) :: ca
      complex, intent(inout) :: cx(*)
      integer, intent(in) :: incx
   end subroutine cscal
   pure subroutine csrot(n,cx,incx,cy,incy,c,s)
      implicit none
      integer, intent(in) :: n
      complex, intent(inout) :: cx(*)
      integer, intent(in) :: incx
      complex, intent(inout) :: cy(*)
      integer, intent(in) :: incy
      real, intent(in) :: c
      real, intent(in) :: s
   end subroutine csrot
   pure subroutine cswap(n,cx,incx,cy,incy)
      implicit none
      integer, intent(in) :: n
      complex, intent(inout) :: cx(*)
      integer, intent(in) :: incx
      complex, intent(inout) :: cy(*)
      integer, intent(in) :: incy
   end subroutine cswap
   pure function scnrm2(n,cx,incx)
      implicit none
      integer, intent(in) :: n
      complex, intent(in) :: cx(*)
      integer, intent(in) :: incx
      real :: scnrm2
   end function scnrm2
   pure elemental subroutine srotg(sa,sb,sc,ss)
      implicit none
      real, intent(inout) :: sa
      real, intent(inout) :: sb
      real, intent(inout) :: sc
      real, intent(inout) :: ss
   end subroutine srotg
end interface
!
!
!     csvdc is a subroutine to reduce a complex NXP matrix x by
!     unitary transformations u and V to diagonal form.  The
!     diagonal elements s(i) are the singular values of x.  the
!     columns of u are the corresponding left singular vectors,
!     and the columns of V the right singular vectors.
!
!     On entry
!
!         x         COMPLEX(ldx,p), WHERE ldx.GE.N.
!                   x contains the matrix whose singular value
!                   decomposition is to be computed.  x is
!                   destroyed by csvdc.
!
!         ldx       INTEGER.
!                   ldx is the leading dimension of the array x.
!
!         n         INTEGER.
!                   n is the number of rows of the matrix x.
!
!         p         INTEGER.
!                   p is the number of columns of the matrix x.
!
!         ldu       INTEGER.
!                   ldu is the leading dimension of the array u
!                   (see below).
!
!         ldv       INTEGER.
!                   ldv is the leading dimension of the array V
!                   (see below).
!
!         WORK      COMPLEX(n).
!                   Work is a scratch array.
!
!         JOB       INTEGER.
!                   Job controls the computation of the singular
!                   vectors.  It has the decimal expansion AB
!                   with the following meaning
!
!                        A.EQ.0    do not compute the left singular
!                                  vectors.
!                        A.EQ.1    return the n left singular vectors
!                                  IN u.
!                        A.GE.2    returns the first min(n,p)
!                                  left singular vectors in u.
!                        b.EQ.0    do not compute the right singular
!                                  vectors.
!                        b.EQ.1    return the right singular vectors
!                                  IN V.
!
!     On return
!
!         s         COMPLEX(MM), WHERE MM=min(n+1,p).
!                   The first min(n,p) entries of s contain the
!                   singular values of x arranged in descending
!                   order of magnitude.
!
!         e         COMPLEX(p).
!                   e ordinarily contains zeros.  However see the
!                   discussion of info for exceptions.
!
!         u         COMPLEX(ldu,k), WHERE ldu.GE.N.  IF JOBA.EQ.1 THEN
!                                   k.EQ.n, IF JOBA.GE.2 THEN
!                                   k.EQ.min(n,p).
!                   u contains the matrix of left singular vectors.
!                   u is not referenced if JOBA.EQ.0.  if n.LE.p
!                   or if JOBA.GT.2, then u may be identified with x
!                   in the subroutine CALL.
!
!         V         COMPLEX(ldv,p), WHERE ldv.GE.P.
!                   V contains the matrix of right singular vectors.
!                   V is not referenced if JOBB.EQ.0.  if p.LE.n,
!                   then V may be identified whth x in the
!                   subroutine CALL.
!
!         INFO      INTEGER.
!                   The singular values (and their corresponding
!                   singular vectors) s(info+1),s(info+2),...,s(M)
!                   are correct (here M=min(n,p)).  Thus if
!                   info.EQ.0, all the singular values and their
!                   vectors are correct.  In any event, the matrix
!                   b = ctrans(u)*x*V is the bidiagonal matrix
!                   with the elements of s on its diagonal and the
!                   elements of e on its super-diagonal (ctrans(u)
!                   is the conjugate-transpose of u).  Thus the
!                   singular values of x and b are the same.
!
!     LINPACK. This version dated 03/19/79 .
!     G.W. Stewart, university of maryland, Argonne National Lab.
!
!     csvdc uses the following functions and subprograms.
!
!     external csrot
!     BLAS caxpy,cdotc,cscal,cswap,scnrm2,srotg
!     Fortran abs,aimag,AMAX1,cabs,cmplx
!     Fortran CONJG,MAX0,MIN0,mod,real,sqrt
!
!     Internal variables
!
!
cabs1(zdum) = abs(real(zdum)) + abs(aimag(zdum))
csign(zdum1,zdum2) = abs(zdum1)*(zdum2/abs(zdum2))
!
!     Set the maximum number of iterations.
!
maxit = 30
!
!     Determine what is to be computed.
!
wantu = .false.
wantv = .false.
jobu = mod(job,100)/10
ncu = n
if (jobu > 1) ncu = min(n,p)
if (jobu /= 0) wantu = .true.
if (mod(job,10) /= 0) wantv = .true.
!
!     Reduce x to bidiagonal form, storing the diagonal elements
!     in s and the super-diagonal elements in e.
!
info = 0
nct = min(n - 1,p)
nrt = max(0,min(p - 2,n))
lu = max(nct,nrt)
if (lu < 1) go to 170
do l = 1, lu
   lp1 = l + 1
   if (l > nct) go to 20
!
!           Compute the transformation for the l-TH column and
!           place the l-TH diagonal in s(l).
!
   s(l) = cmplx(scnrm2(n - l + 1,x(l,l),1),0.0e0)
   if (cabs1(s(l)) == 0.0e0) go to 10
   if (cabs1(x(l,l)) /= 0.0e0) s(l) = csign(s(l),x(l,l))
   call cscal(n - l + 1,1.0e0/s(l),x(l,l),1)
   x(l,l) = (1.0e0,0.0e0) + x(l,l)
10 continue
   s(l) = -s(l)
20 continue
   if (p < lp1) go to 50
   do j = lp1, p
      if (l > nct) go to 30
      if (cabs1(s(l)) == 0.0e0) go to 30
!
!              Apply the transformation.
!
      t = -cdotc(n - l + 1,x(l,l),1,x(l,j),1)/x(l,l)
      call caxpy(n - l + 1,t,x(l,l),1,x(l,j),1)
30    continue
!
!           Place the l-TH row of x into  e for the
!           subsequent calculation of the row transformation.
!
      e(j) = conjg(x(l,j))
40    continue
   end do
50 continue
   if (.not.wantu .or. l > nct) go to 70
!
!           Place the transformation in u for subsequent back
!           multiplication.
!
   do i = l, n
      u(i,l) = x(i,l)
   end do
70 continue
   if (l > nrt) go to 150
!
!           Compute the l-TH row transformation and place the
!           l-TH super-diagonal in e(l).
!
   e(l) = cmplx(scnrm2(p - l,e(lp1),1),0.0e0)
   if (cabs1(e(l)) == 0.0e0) go to 80
   if (cabs1(e(lp1)) /= 0.0e0) e(l) = csign(e(l),e(lp1))
   call cscal(p - l,1.0e0/e(l),e(lp1),1)
   e(lp1) = (1.0e0,0.0e0) + e(lp1)
80 continue
   e(l) = -conjg(e(l))
   if (lp1 > n .or. cabs1(e(l)) == 0.0e0) go to 120
!
!              Apply the transformation.
!
   do i = lp1, n
      work(i) = (0.0e0,0.0e0)
   end do
   do j = lp1, p
      call caxpy(n - l,e(j),x(lp1,j),1,work(lp1),1)
100   continue
   end do
   do j = lp1, p
      call caxpy(n - l,conjg(-e(j)/e(lp1)),work(lp1),1, &
         & x(lp1,j),1)
   end do
120 continue
   if (.not.wantv) go to 140
!
!              Place the transformation in V for subsequent
!              back multiplication.
!
   do i = lp1, p
      v(i,l) = e(i)
   end do
140 continue
150 continue
160 continue
end do
170 continue
!
!     Set up the final bidiagonal matrix of order M.
!
m = min(p,n + 1)
nctp1 = nct + 1
nrtp1 = nrt + 1
if (nct < p) s(nctp1) = x(nctp1,nctp1)
if (n < m) s(m) = (0.0e0,0.0e0)
if (nrtp1 < m) e(nrtp1) = x(nrtp1,m)
e(m) = (0.0e0,0.0e0)
!
!     If required, generate u.
!
if (.not.wantu) go to 300
if (ncu < nctp1) go to 200
do j = nctp1, ncu
   do i = 1, n
      u(i,j) = (0.0e0,0.0e0)
   end do
   u(j,j) = (1.0e0,0.0e0)
end do
200 continue
if (nct < 1) go to 290
do ll = 1, nct
   l = nct - ll + 1
   if (cabs1(s(l)) == 0.0e0) go to 250
   lp1 = l + 1
   if (ncu < lp1) go to 220
   do j = lp1, ncu
      t = -cdotc(n - l + 1,u(l,l),1,u(l,j),1)/u(l,l)
      call caxpy(n - l + 1,t,u(l,l),1,u(l,j),1)
   end do
220 continue
   call cscal(n - l + 1,(-1.0e0,0.0e0),u(l,l),1)
   u(l,l) = (1.0e0,0.0e0) + u(l,l)
   lm1 = l - 1
   if (lm1 < 1) go to 240
   do i = 1, lm1
      u(i,l) = (0.0e0,0.0e0)
   end do
240 continue
   go to 270
250 continue
   do i = 1, n
      u(i,l) = (0.0e0,0.0e0)
   end do
   u(l,l) = (1.0e0,0.0e0)
270 continue
end do
290 continue
300 continue
!
!     If it is required, generate V.
!
if (.not.wantv) go to 350
do ll = 1, p
   l = p - ll + 1
   lp1 = l + 1
   if (l > nrt) go to 320
   if (cabs1(e(l)) == 0.0e0) go to 320
   do j = lp1, p
      t = -cdotc(p - l,v(lp1,l),1,v(lp1,j),1)/v(lp1,l)
      call caxpy(p - l,t,v(lp1,l),1,v(lp1,j),1)
   end do
320 continue
   do i = 1, p
      v(i,l) = (0.0e0,0.0e0)
   end do
   v(l,l) = (1.0e0,0.0e0)
end do
350 continue
!
!     Transform s and e so that they are real.
!
do i = 1, m
   if (cabs1(s(i)) == 0.0e0) go to 360
   t = cmplx(abs(s(i)),0.0e0)
   r = s(i)/t
   s(i) = t
   if (i < m) e(i) = e(i)/r
   if (wantu) call cscal(n,r,u(1,i),1)
360 continue
!     ...Exit
   if (i == m) go to 390
   if (cabs1(e(i)) == 0.0e0) go to 370
   t = cmplx(abs(e(i)),0.0e0)
   r = t/e(i)
   e(i) = t
   s(i + 1) = s(i + 1)*r
   if (wantv) call cscal(p,r,v(1,i + 1),1)
370 continue
end do
390 continue
!
!     Main iteration loop for the singular values.
!
mm = m
iter = 0
400 continue
!
!        Quit if all the singular values have been found.
!
!     ...Exit
if (m == 0) go to 660
!
!        If too many iterations have been performed, set
!        flag and return.
!
if (iter < maxit) go to 410
info = m
!     ......Exit
go to 660
410 continue
!
!        This section of the program inspects for
!        negligible elements in the s and e arrays.  On
!        completion the variables kase and l are set as follows.
!
!           kase = 1     If s(M) and e(l-1) are negligible and l.LT.M
!           kase = 2     If s(l) is negligible and l.LT.M
!           kase = 3     If e(l-1) is negligible, l.LT.M, and
!                        s(l), ..., s(M) are not negligible (QR step).
!           kase = 4     If e(M-1) is negligible (convergence).
!
do ll = 1, m
   l = m - ll
!        ...Exit
   if (l == 0) go to 440
   test = abs(s(l)) + abs(s(l + 1))
   ztest = test + abs(e(l))
   if (ztest /= test) go to 420
   e(l) = (0.0e0,0.0e0)
!        ......Exit
   go to 440
420 continue
end do
440 continue
if (l /= m - 1) go to 450
kase = 4
go to 520
450 continue
lp1 = l + 1
mp1 = m + 1
do lls = lp1, mp1
   ls = m - lls + lp1
!           ...Exit
   if (ls == l) go to 480
   test = 0.0e0
   if (ls /= m) test = test + abs(e(ls))
   if (ls /= l + 1) test = test + abs(e(ls - 1))
   ztest = test + abs(s(ls))
   if (ztest /= test) go to 460
   s(ls) = (0.0e0,0.0e0)
!           ......Exit
   go to 480
460 continue
end do
480 continue
if (ls /= l) go to 490
kase = 3
go to 510
490 continue
if (ls /= m) go to 500
kase = 1
go to 510
500 continue
kase = 2
l = ls
510 continue
520 continue
l = l + 1
!
!        Perform the task indicated by kase.
!
go to (530, 560, 580, 610), kase
!
!        Deflate negligible s(M).
!
530 continue
mm1 = m - 1
f = real(e(m - 1))
e(m - 1) = (0.0e0,0.0e0)
do kk = l, mm1
   k = mm1 - kk + l
   t1 = real(s(k))
   call srotg(t1,f,cs,sn)
   s(k) = cmplx(t1,0.0e0)
   if (k == l) go to 540
   f = -sn*real(e(k - 1))
   e(k - 1) = cs*e(k - 1)
540 continue
   if (wantv) call csrot(p,v(1,k),1,v(1,m),1,cs,sn)
end do
go to 650
!
!        Split at negligible s(l).
!
560 continue
f = real(e(l - 1))
e(l - 1) = (0.0e0,0.0e0)
do k = l, m
   t1 = real(s(k))
   call srotg(t1,f,cs,sn)
   s(k) = cmplx(t1,0.0e0)
   f = -sn*real(e(k))
   e(k) = cs*e(k)
   if (wantu) call csrot(n,u(1,k),1,u(1,l - 1),1,cs,sn)
end do
go to 650
!
!        Perform one QR step.
!
580 continue
!
!           Calculate the shift.
!
scale = max(abs(s(m)),abs(s(m - 1)),abs(e(m - 1)), &
   & abs(s(l)),abs(e(l)))
sm = real(s(m))/scale
smm1 = real(s(m - 1))/scale
emm1 = real(e(m - 1))/scale
sl = real(s(l))/scale
el = real(e(l))/scale
b = ((smm1 + sm)*(smm1 - sm) + emm1**2)/2.0e0
c = (sm*emm1)**2
shift = 0.0e0
if (b == 0.0e0 .and. c == 0.0e0) go to 590
shift = sqrt(b**2 + c)
if (b < 0.0e0) shift = -shift
shift = c/(b + shift)
590 continue
f = (sl + sm)*(sl - sm) - shift
g = sl*el
!
!           Chase zeros.
!
mm1 = m - 1
do k = l, mm1
   call srotg(f,g,cs,sn)
   if (k /= l) e(k - 1) = cmplx(f,0.0e0)
   f = cs*real(s(k)) + sn*real(e(k))
   e(k) = cs*e(k) - sn*s(k)
   g = sn*real(s(k + 1))
   s(k + 1) = cs*s(k + 1)
   if (wantv) call csrot(p,v(1,k),1,v(1,k + 1),1,cs,sn)
   call srotg(f,g,cs,sn)
   s(k) = cmplx(f,0.0e0)
   f = cs*real(e(k)) + sn*real(s(k + 1))
   s(k + 1) = -sn*e(k) + cs*s(k + 1)
   g = sn*real(e(k + 1))
   e(k + 1) = cs*e(k + 1)
   if (wantu .and. k < n) &
      & call csrot(n,u(1,k),1,u(1,k + 1),1,cs,sn)
end do
e(m - 1) = cmplx(f,0.0e0)
iter = iter + 1
go to 650
!
!        Convergence.
!
610 continue
!
!           Make the singular value  positive
!
if (real(s(l)) >= 0.0e0) go to 620
s(l) = -s(l)
if (wantv) call cscal(p,(-1.0e0,0.0e0),v(1,l),1)
620 continue
!
!           Order the singular value.
!
630 if (l == mm) go to 640
!           ...Exit
if (real(s(l)) >= real(s(l + 1))) go to 640
t = s(l)
s(l) = s(l + 1)
s(l + 1) = t
if (wantv .and. l < p) &
   & call cswap(p,v(1,l),1,v(1,l + 1),1)
if (wantu .and. l < n) &
   & call cswap(n,u(1,l),1,u(1,l + 1),1)
l = l + 1
go to 630
640 continue
iter = 0
m = m - 1
650 continue
go to 400
660 continue
end subroutine csvdc

function det(a,ka,n,x)
implicit none
integer, intent(in) :: ka, n
real, intent(inout) :: a(ka,n)
real, intent(in) :: x
integer :: i, j, k, kp1, l, nm1
real :: c, pivot, s
real :: det
!     -------------------
!     Evaluation of the determinant of a-xi where A is an NXN matrix,
!     x is a scalar, and i is the NXN identity matrix.
!     -------------------
!     ka is the row dimension of A in the calling program. It is
!     assumed that ka is greater than or equal to n.
!     -------------------
if (n >= 2) go to 10
det = a(1,1) - x
return
!
!              Replace A with a-xi
!
10 if (x == 0.0) go to 20
do k = 1,n
11 a(k,k) = a(k,k) - x
end do
!
!                Initialization
!
20 det = 1.0
nm1 = n - 1
do k = 1,nm1
   kp1 = k + 1
!
!       Search for the k-TH pivot element
!
   s = abs(a(k,k))
   l = k
   do i = kp1,n
      c = abs(a(i,k))
      if (s >= c) go to 30
      s = c
      l = i
30    continue
   end do
   pivot = a(l,k)
!
!         Update the calculation of det
!
   det = det*pivot
   if (det == 0.0) return
   if (k == l) go to 50
   det = -det
!
!          Interchanging rows k and l
!
   do j = k,n
      c = a(k,j)
      a(k,j) = a(l,j)
40    a(l,j) = c
   end do
!
!        Reduction of the non-pivot rows
!
50 do i = kp1,n
      c = a(i,k)/pivot
      do j = kp1,n
51       a(i,j) = a(i,j) - c*a(k,j)
      end do
   end do
end do
!
!         Final determinant calculation
!
det = det*a(n,n)
end function det

double precision function dpdet(a,ka,n,x)
implicit none
integer, intent(in) :: ka, n
double precision, intent(inout) :: a(ka,n)
double precision, intent(in) :: x
integer :: i, j, k, kp1, l, nm1
double precision :: pivot, s, c
!     -------------------
!     Evaluation of the determinant of a-xi where A is an NXN matrix,
!     x is a scalar, and i is the NXN identity matrix.
!     -------------------
!     ka is the row dimension of A in the calling program. It is
!     assumed that ka is greater than or equal to n.
!     -------------------
if (n >= 2) go to 10
dpdet = a(1,1) - x
return
!
!              Replace A with a-xi
!
10 if (x == 0.d0) go to 20
do k = 1,n
11 a(k,k) = a(k,k) - x
end do
!
!                Initialization
!
20 dpdet = 1.d0
nm1 = n - 1
do k = 1,nm1
   kp1 = k + 1
!
!       Search for the k-TH pivot element
!
   s = abs(a(k,k))
   l = k
   do i = kp1,n
      c = abs(a(i,k))
      if (s >= c) go to 30
      s = c
      l = i
30    continue
   end do
   pivot = a(l,k)
!
!         Update the calculation of det
!
   dpdet = dpdet*pivot
   if (dpdet == 0.d0) return
   if (k == l) go to 50
   dpdet = -dpdet
!
!          Interchanging rows k and l
!
   do j = k,n
      c = a(k,j)
      a(k,j) = a(l,j)
40    a(l,j) = c
   end do
!
!        Reduction of the non-pivot rows
!
50 do i = kp1,n
      c = a(i,k)/pivot
      do j = kp1,n
51       a(i,j) = a(i,j) - c*a(k,j)
      end do
   end do
end do
!
!         Final determinant calculation
!
dpdet = dpdet*a(n,n)
end function dpdet

complex function cdet(a,ka,n,x)
implicit none
integer, intent(in) :: ka, n
complex, intent(inout) :: a(ka,n)
complex, intent(in) :: x
integer :: i, j, k, kp1, l, nm1
complex :: pivot, t
real :: s, c
complex, parameter :: zero = (0.0,0.0)
!     -------------------
!     Evaluation of the determinant of a-xi where A is an NXN matrix,
!     x is a scalar, and i is the NXN identity matrix.
!     -------------------
!     ka is the row dimension of A in the calling program. It is
!     assumed that ka is greater than or equal to n.
!     -------------------
!
if (n >= 2) go to 10
cdet = a(1,1) - x
return
!
!              Replace A with a-xi
!
10 if (x == zero) go to 20
do k = 1,n
11 a(k,k) = a(k,k) - x
end do
!
!                Initialization
!
20 cdet = (1.0,0.0)
nm1 = n - 1
do k = 1,nm1
   kp1 = k + 1
!
!       Search for the k-TH pivot element
!
   s = abs(real(a(k,k))) + abs(aimag(a(k,k)))
   l = k
   do i = kp1,n
      c = abs(real(a(i,k))) + abs(aimag(a(i,k)))
      if (s >= c) go to 30
      s = c
      l = i
30    continue
   end do
   pivot = a(l,k)
!
!         Update the calculation of cdet
!
   cdet = cdet*pivot
   if (cdet == zero) return
   if (k == l) go to 50
   cdet = -cdet
!
!          Interchanging rows k and l
!
   do j = k,n
      t = a(k,j)
      a(k,j) = a(l,j)
40    a(l,j) = t
   end do
!
!        Reduction of the non-pivot rows
!
50 do i = kp1,n
      t = a(i,k)/pivot
      do j = kp1,n
51       a(i,j) = a(i,j) - t*a(k,j)
      end do
   end do
end do
!
!         Final determinant calculation
!
cdet = cdet*a(n,n)
end function cdet

subroutine abslv(mo,m,n,a,na,b,nb,c,nc,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer :: m
integer, intent(in) :: mo
integer :: n
integer, intent(in) :: na, nb, nc
real, intent(inout) :: a(na,m), b(nb,n), c(nc,n), wk(*)
integer :: iu, iv, iw
! ----------------------------------------------------------------------
!     abslv solves the real matrix equation AX + XB = c. A is reduced
!     to lower Schur form, b is reduced to upper Schur form, and the
!     transformed system is solved by back substitution.
! ----------------------------------------------------------------------
!        mo is an input argument which specifies if the routine is
!     being called for the first time. On an initial call mo = 0 And
!     we have the following setup.
!
!        a(na,m)
!           A is a matrix of order m. it is assumed that
!           na .GE. m .GE. 1.
!
!        b(nb,n)
!           b is a matrix of order n. it is assumed that
!           nb .GE. n .GE. 1.
!
!        c(nc,n)
!           c is a matrix having m rows and n columns.
!           It is assumed that nc .GE. m.
!
!        wk(---)
!           wk is an array of dimension m**2  + n**2 + 2K
!           WHERE K = max(m,n). wk IS A GENERAL STORAGE
!           area for the routine.
!
!     ierr is a variable that reports the status of the results. When
!     the routine terminates, ierr has one of the following values...
!
!        ierr =  0  The solution was obtained and stored in c.
!        ierr =  1  The equations are inconsistent for A and b.
!                   The problem cannot be solved.
!        ierr = -1  A could not be reduced to lower Schur form.
!                   The problem cannot be solved.
!        ierr = -2  b could not be reduced to upper Schur form.
!                   The problem cannot be solved.
!
!     When ierr = 0, a contains the lower Schur form of the matrix a,
!     b contains the upper Schur form of the matrix b, and wk contains
!     the orthonal matrices involved in the Schur decompositions of
!     A and b. this information can be reused to solve a new set of
!     equations AX + XB = c without having to redecompose A and b.
!     The following options are available...
!
!        mo = 1      New matrices A and c are given. The data for b
!                    is reused in solving the new set of equations.
!
!        mo = 2      New matrices b and c are given. The data for A
!                    is reused in solving the new set of equations.
!
!     mo .NE. 0,1,2  a new matrix c is given. The data for A and b
!                    is reused in solving the new set of equations.
!
!     When abslv is recalled, it is assumed that m, n, and wk have
!     not been modified.
! ----------------------------------------------------------------------
!     This subroutine is a modification by
!        Alfred H. Morris, Jr.
!        naval surface weapons center
!        Dahlgren, Virginia
!     of the subroutine axpxb written by
!        R.H. Bartels and G.W.Stewart
!        University of Texas at Austin.
!
!     Reference. Bartels, R.H. and Stewart, G.W., algorithm 432,
!        solution of the matrix equation AX + XB = c, comm. ACM
!        15 (1972), PP. 820-826.
! ----------------------------------------------------------------------
iu = 1
iv = m*m + 1
iw = n*n + iv
call abslv1(mo,m,n,a,na,wk(iu),m,b,nb,wk(iv),n, &
   & c,nc,wk(iw),ierr)
end subroutine abslv

subroutine abslv1(mo,m,n,a,na,u,nu,b,nb,v,nv,c,nc,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer :: m
integer, intent(in) :: mo
integer :: n
integer, intent(in) :: na, nb, nc, nu, nv
real, intent(inout) :: a(na,m), b(nb,n), c(nc,n)
real, intent(inout) :: u(nu,m), v(nv,n)
real, intent(inout) :: wk(*)
integer :: i, j, k
real :: temp
! ----------------------------------------------------------------------
!     abslv1 solves the real matrix equation AX + XB = c. A is reduced
!     to lower Schur form, b is reduced to upper Schur form, and the
!     transformed system is solved by back substitution.
! ----------------------------------------------------------------------
!
!     If required, reduce A to lower real Schur form
!
if (mo /= 0 .and. mo /= 1) go to 35
do i = 1,m
   do j = i,m
      temp = a(i,j)
      a(i,j) = a(j,i)
      a(j,i) = temp
   end do
end do
call orthes(na,m,1,m,a,wk)
call ortrn1(m,1,m,a,na,u,nu,wk)
!
if (m == 1) go to 20
call schur(m,1,m,a,na,u,nu,wk(1),wk(m + 1),ierr)
if (ierr /= 0) go to 200
!
20 do i = 1,m
   do j = i,m
      temp = a(i,j)
      a(i,j) = a(j,i)
      a(j,i) = temp
   end do
end do
!
!     If required, reduce b to upper real Schur form
!
35 if (mo /= 0 .and. mo /= 2) go to 45
call orthes(nb,n,1,n,b,wk)
call ortrn1(n,1,n,b,nb,v,nv,wk)
!
if (n == 1) go to 45
call schur(n,1,n,b,nb,v,nv,wk(1),wk(n + 1),ierr)
if (ierr /= 0) go to 210
!
!     Transform c
!
45 do j = 1,n
   do i = 1,m
      wk(i) = 0.0
      do k = 1,m
         wk(i) = wk(i) + u(k,i)*c(k,j)
      end do
   end do
   do i = 1,m
      c(i,j) = wk(i)
   end do
end do
!
do i = 1,m
   do j = 1,n
      wk(j) = 0.0
      do k = 1,n
         wk(j) = wk(j) + c(i,k)*v(k,j)
      end do
   end do
   do j = 1,n
      c(i,j) = wk(j)
   end do
end do
!
!     Solve the transformed system
!
call shrslv(a,b,c,m,n,na,nb,nc,ierr)
if (ierr /= 0) go to 220
!
!     Transform c back to the solution
!
do j = 1,n
   do i = 1,m
      wk(i) = 0.0
      do k = 1,m
         wk(i) = wk(i) + u(i,k)*c(k,j)
      end do
   end do
   do i = 1,m
      c(i,j) = wk(i)
   end do
end do
!
do i = 1,m
   do j = 1,n
      wk(j) = 0.0
      do k = 1,n
         wk(j) = wk(j) + c(i,k)*v(j,k)
      end do
   end do
   do j = 1,n
      c(i,j) = wk(j)
   end do
end do
return
!
!     Error return
!
200 ierr = -1
return
210 ierr = -2
return
220 ierr = 1
end subroutine abslv1

pure subroutine schur(n, low, igh, h, nh, z, nz, wr, wi, ierr)
implicit none
integer, intent(in) :: n
integer, intent(in) :: nh, nz, igh
integer, intent(in) :: low
integer, intent(out) :: ierr
real, intent(inout) :: h(nh,n), wr(n), wi(n), z(nz,n)
integer :: ip1, i, j, k, l, m, en, ll, mm, na, its, mp2, enm2
real :: p, q, r, s, t, w, x, y, zz, norm, s1, s2
logical :: notlas
! ----------------------------------------------------------------------
!     It is assumed that h is an upper Hessenberg matrix. Schur
!     obtains an orthogonal matrix q for which transpose(q)*h*q
!     is in Schur form. The eigenvalues of h are also computed.
!
!     On input-
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n, (balanc is an EISPACK subroutine).
!
!        h contains the upper Hessenberg matrix,
!
!        nh is the first dimension of h,
!
!        z contains a matrix of order n,
!
!        nz is the first dimension of z.
!
!     On output-
!
!        h contains the transformed matrix in upper Schur form,
!
!        z contains the matrix z*q where q is the orthogonal
!          matrix which reduces h to upper Schur form,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n.
!
!        ierr is set to
!          0          FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
! -----------------
!     Written by jack dongarra
!          Argonne National Laboratory
!          may 1961
!     modified by A.H. Morris (NSWC)
! ----------------------------------------------------------------------
!     This subroutine is a modification of the EISPACK subroutine
!     hqr2,  which is based on the Algol procedure hqr by peters
!     and Wilkinson, NUM. Math. 16 (1970), PP.181-204.
! ----------------------------------------------------------------------
!     real sqrt, abs
!     integer min0
!
ierr = 0
norm = 0.0
k = 1
!     ********** Store roots isolated by balanc
!                and compute matrix norm **********
do i = 1,n
!
   do j = k,n
      norm = norm + abs(h(i,j))
10    continue
   end do
!
   k = i
   if (i >= low .and. i <= igh) go to 20
   wr(i) = h(i,i)
   wi(i) = 0.0
20 continue
end do
!
en = igh
t = 0.0
!     ********** Search for next eigenvalues **********
30 if (en < low) go to 300
its = 0
na = en - 1
enm2 = na - 1
!     ********** Look for single small sub-diagonal element
!                for l=en step -1 Until low do -- **********
40 do ll = low,en
   l = en + low - ll
   if (l == low) go to 60
   s = abs(h(l - 1,l - 1)) + abs(h(l,l))
   if (s == 0.0) s = norm
   s1 = s
   s2 = s1 + abs(h(l,l - 1))
   if (s1 == s2) go to 60
end do
!     ********** Form shift **********
60 x = h(en,en)
if (l == en) go to 220
y = h(na,na)
w = h(en,na)*h(na,en)
if (l == na) go to 230
if (its == 30) go to 290
if (its /= 10 .and. its /= 20) go to 80
!     ********** Form exceptional shift **********
t = t + x
!
do i = low,en
   h(i,i) = h(i,i) - x
end do
!
s = abs(h(en,na)) + abs(h(na,enm2))
x = 0.75*s
y = x
w = -0.4375*s*s
80 its = its + 1
!     ********** Look for two consecutive small
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l,enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r*s - w)/h(m + 1,m) + h(m,m + 1)
   q = h(m + 1,m + 1) - zz - r - s
   r = h(m + 2,m + 1)
   s = abs(p) + abs(q) + abs(r)
   p = p/s
   q = q/s
   r = r/s
   if (m == l) go to 100
   s1 = abs(p)*(abs(h(m - 1,m - 1)) + abs(zz) + abs(h(m + 1,m + 1)))
   s2 = s1 + abs(h(m,m - 1))*(abs(q) + abs(r))
   if (s1 == s2) go to 100
end do
!
100 mp2 = m + 2
!
do i = mp2,en
   h(i,i - 2) = 0.0
   if (i == mp2) go to 110
   h(i,i - 3) = 0.0
110 continue
end do
!     ********** Double QR step involving rows l to en and
!                COLUMNS m TO en **********
do k = m,na
   notlas = k /= na
   if (k == m) go to 120
   p = h(k,k - 1)
   q = h(k + 1,k - 1)
   r = 0.0
   if (notlas) r = h(k + 2,k - 1)
   x = abs(p) + abs(q) + abs(r)
   if (x == 0.0) go to 210
   p = p/x
   q = q/x
   r = r/x
120 s = sqrt(p*p + q*q + r*r)
   if (p < 0.0) s = -s
   if (k == m) go to 130
   h(k,k - 1) = -s*x
   go to 140
130 if (l /= m) h(k,k - 1) = -h(k,k - 1)
140 p = p + s
   x = p/s
   y = q/s
   zz = r/s
   q = q/p
   r = r/p
!     ********** Row modification **********
   do j = k,n
      p = h(k,j) + q*h(k + 1,j)
      if (.not.notlas) go to 150
      p = p + r*h(k + 2,j)
      h(k + 2,j) = h(k + 2,j) - p*zz
150   h(k + 1,j) = h(k + 1,j) - p*y
      h(k,j) = h(k,j) - p*x
   end do
!
   j = min(en,k + 3)
!     ********** Column modification **********
   do i = 1,j
      p = x*h(i,k) + y*h(i,k + 1)
      if (.not.notlas) go to 170
      p = p + zz*h(i,k + 2)
      h(i,k + 2) = h(i,k + 2) - p*r
170   h(i,k + 1) = h(i,k + 1) - p*q
      h(i,k) = h(i,k) - p
   end do
!     ********** Accumulate transformations **********
   do i = low,igh
      p = x*z(i,k) + y*z(i,k + 1)
      if (.not.notlas) go to 190
      p = p + zz*z(i,k + 2)
      z(i,k + 2) = z(i,k + 2) - p*r
190   z(i,k + 1) = z(i,k + 1) - p*q
      z(i,k) = z(i,k) - p
   end do
!
210 continue
end do
!
go to 40
!     ********** One root found **********
220 h(en,en) = x + t
wr(en) = h(en,en)
wi(en) = 0.0
en = na
go to 30
!     ********** Two roots found **********
230 p = (y - x)/2.0
q = p*p + w
zz = sqrt(abs(q))
h(en,en) = x + t
x = h(en,en)
h(na,na) = y + t
if (q < 0.0) go to 270
!     ********** Real pair **********
if (p < 0.0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz /= 0.0) wr(en) = x - w/zz
wi(na) = 0.0
wi(en) = 0.0
x = h(en,na)
s = abs(x) + abs(zz)
p = x/s
q = zz/s
r = sqrt(p*p + q*q)
p = p/r
q = q/r
!     ********** Row modification **********
do j = na,n
   zz = h(na,j)
   h(na,j) = q*zz + p*h(en,j)
   h(en,j) = q*h(en,j) - p*zz
end do
!     ********** Column modification **********
do i = 1,en
   zz = h(i,na)
   h(i,na) = q*zz + p*h(i,en)
   h(i,en) = q*h(i,en) - p*zz
end do
!     ********** Accumulate transformations **********
do i = low,igh
   zz = z(i,na)
   z(i,na) = q*zz + p*z(i,en)
   z(i,en) = q*z(i,en) - p*zz
end do
!
go to 280
!     ********** Complex pair **********
270 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
280 en = enm2
go to 30
!     ********** Set error -- no convergence to an
!                eigenvalue after 30 iterations **********
290 ierr = en
return
300 do i = 1,n
   ip1 = i + 1
   if (abs(wi(i)) /= 0.0) ip1 = ip1 + 1
   if (ip1 > n) go to 320
   do j = ip1,n
      h(j,i) = 0.0
   end do
320 continue
end do
end subroutine schur

pure subroutine shrslv(a,b,c,m,n,na,nb,nc,ierr)
implicit none
!     ------------------------------------------------------------------
!     shrslv solves the matrix equation AX + XB = c where
!     A is in lower Schur form and b in upper Schur form.
!     ------------------------------------------------------------------
integer, intent(in) :: m, n, na, nb, nc
integer, intent(inout) :: ierr
real, intent(in) :: a(na,m), b(nb,n)
real, intent(inout) :: c(nc,n)
real :: sum, p(4), t(4,4)
integer :: dk, dl, i, ib, j, ja, k, km1, kk, l, lm1, ll
interface
   pure subroutine slv(n,m,a,ka,b,kb,ierr)
      implicit none
      integer, intent(in) :: kb
      integer, intent(in) :: ka
      integer, intent(in) :: m
      integer, intent(in) :: n
      real, intent(inout) :: a(ka,n)
      real, intent(inout) :: b(kb,m)
      integer, intent(out) :: ierr
   end subroutine slv
end interface
!
l = 1
10 lm1 = l - 1
dl = 1
if (l == n) go to 15
if (b(l + 1,l) /= 0.0) dl = 2
15 ll = l + dl - 1
if (l == 1) go to 30
!
do j = l,ll
   do i = 1,m
      sum = c(i,j)
      do ib = 1,lm1
20       sum = sum - c(i,ib)*b(ib,j)
      end do
21    c(i,j) = sum
   end do
end do
!
30 k = 1
40 km1 = k - 1
dk = 1
if (k == m) go to 45
if (a(k,k + 1) /= 0.0) dk = 2
45 kk = k + dk - 1
if (k == 1) go to 60
!
do i = k,kk
   do j = l,ll
      sum = c(i,j)
      do ja = 1,km1
50       sum = sum - a(i,ja)*c(ja,j)
      end do
51    c(i,j) = sum
   end do
end do
!
60 if (dl == 2) go to 80
if (dk == 2) go to 70
t(1,1) = a(k,k) + b(l,l)
if (t(1,1) == 0.0) go to 200
c(k,l) = c(k,l)/t(1,1)
ierr = 0
go to 100
!
70 t(1,1) = a(k,k) + b(l,l)
t(1,2) = a(k,kk)
t(2,1) = a(kk,k)
t(2,2) = a(kk,kk) + b(l,l)
p(1) = c(k,l)
p(2) = c(kk,l)
call slv(2, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(k,l) = p(1)
c(kk,l) = p(2)
go to 100
!
80 if (dk == 2) go to 90
t(1,1) = a(k,k) + b(l,l)
t(1,2) = b(ll,l)
t(2,1) = b(l,ll)
t(2,2) = a(k,k) + b(ll,ll)
p(1) = c(k,l)
p(2) = c(k,ll)
call slv(2, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(k,l) = p(1)
c(k,ll) = p(2)
go to 100
!
90 t(1,1) = a(k,k) + b(l,l)
t(1,2) = a(k,kk)
t(1,3) = b(ll,l)
t(1,4) = 0.0
t(2,1) = a(kk,k)
t(2,2) = a(kk,kk) + b(l,l)
t(2,3) = 0.0
t(2,4) = t(1,3)
t(3,1) = b(l,ll)
t(3,2) = 0.0
t(3,3) = a(k,k) + b(ll,ll)
t(3,4) = t(1,2)
t(4,1) = 0.0
t(4,2) = t(3,1)
t(4,3) = t(2,1)
t(4,4) = a(kk,kk) + b(ll,ll)
p(1) = c(k,l)
p(2) = c(kk,l)
p(3) = c(k,ll)
p(4) = c(kk,ll)
call slv(4, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(k,l) = p(1)
c(kk,l) = p(2)
c(k,ll) = p(3)
c(kk,ll) = p(4)
!
100 k = k + dk
if (k <= m) go to 40
l = l + dl
if (l <= n) go to 10
return
!
!     Error return
!
200 ierr = 1
end subroutine shrslv

subroutine dabslv(mo,m,n,a,na,b,nb,c,nc,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer :: m
integer, intent(in) :: mo
integer :: n
integer, intent(in) :: na, nb, nc
double precision, intent(inout) :: a(na,m), b(nb,n), c(nc,n), &
   & wk(*)
integer :: iu, iv, iw
! ----------------------------------------------------------------------
!     dabslv solves the real matrix equation AX + XB = c. A is reduced
!     to lower Schur form, b is reduced to upper Schur form, and the
!     transformed system is solved by back substitution.
! ----------------------------------------------------------------------
!        mo is an input argument which specifies if the routine is
!     being called for the first time. On an initial call mo = 0 And
!     we have the following setup.
!
!        a(na,m)
!           A is a matrix of order m. it is assumed that
!           na .GE. m .GE. 1.
!
!        b(nb,n)
!           b is a matrix of order n. it is assumed that
!           nb .GE. n .GE. 1.
!
!        c(nc,n)
!           c is a matrix having m rows and n columns.
!           It is assumed that nc .GE. m.
!
!        WK(---)
!           WK is an array of dimension m**2  + n**2 + 2K
!           WHERE K = max(m,n). WK IS A GENERAL STORAGE
!           area for the routine.
!
!     ierr is a variable that reports the status of the results. When
!     the routine terminates, ierr has one of the following values...
!
!        ierr =  0  The solution was obtained and stored in c.
!        ierr =  1  The equations are inconsistent for A and b.
!                   The problem cannot be solved.
!        ierr = -1  A could not be reduced to lower Schur form.
!                   The problem cannot be solved.
!        ierr = -2  b could not be reduced to upper Schur form.
!                   The problem cannot be solved.
!
!     When ierr = 0, a contains the lower Schur form of the matrix a,
!     b contains the upper Schur form of the matrix b, and WK contains
!     the orthonal matrices involved in the Schur decompositions of
!     A and b. this information can be reused to solve a new set of
!     equations AX + XB = c without having to redecompose A and b.
!     The following options are available...
!
!        mo = 1      New matrices A and c are given. The data for b
!                    is reused in solving the new set of equations.
!
!        mo = 2      New matrices b and c are given. The data for A
!                    is reused in solving the new set of equations.
!
!     mo .NE. 0,1,2  a new matrix c is given. The data for A and b
!                    is reused in solving the new set of equations.
!
!     When dabslv is recalled, it is assumed that m, n, and WK have
!     not been modified.
! ----------------------------------------------------------------------
!     This subroutine is a modification by
!        Alfred H. Morris, Jr.
!        naval surface weapons center
!        Dahlgren, Virginia
!     of the subroutine axpxb written by
!        R.H. Bartels and G.W.Stewart
!        University of Texas at Austin.
!
!     Reference. Bartels, R.H. and Stewart, G.W., algorithm 432,
!        solution of the matrix equation AX + XB = c, comm. ACM
!        15 (1972), PP. 820-826.
! ----------------------------------------------------------------------
iu = 1
iv = m*m + 1
iw = n*n + iv
call dabsv1(mo,m,n,a,na,wk(iu),m,b,nb,wk(iv),n, &
   & c,nc,wk(iw),ierr)
end subroutine dabslv

subroutine dabsv1(mo,m,n,a,na,u,nu,b,nb,v,nv,c,nc,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer :: m
integer, intent(in) :: mo
integer :: n
integer, intent(in) :: na, nb, nc, nu, nv
double precision, intent(inout) :: a(na,m), b(nb,n), c(nc,n)
double precision, intent(inout) :: u(nu,m), v(nv,n)
double precision, intent(inout) :: wk(*)
integer :: i, j, k
double precision :: temp
! ----------------------------------------------------------------------
!     dabsv1 solves the real matrix equation AX + XB = c. A is reduced
!     to lower Schur form, b is reduced to upper Schur form, and the
!     transformed system is solved by back substitution.
! ----------------------------------------------------------------------
!
!     If required, reduce A to lower real Schur form
!
if (mo /= 0 .and. mo /= 1) go to 35
do i = 1,m
   do j = i,m
      temp = a(i,j)
      a(i,j) = a(j,i)
      a(j,i) = temp
   end do
end do
call dorth(na,m,1,m,a,wk)
call drtrn1(m,1,m,a,na,u,nu,wk)
!
if (m == 1) go to 20
call dschur(m,1,m,a,na,u,nu,wk(1),wk(m + 1),ierr)
if (ierr /= 0) go to 200
!
20 do i = 1,m
   do j = i,m
      temp = a(i,j)
      a(i,j) = a(j,i)
      a(j,i) = temp
   end do
end do
!
!     If required, reduce b to upper real Schur form
!
35 if (mo /= 0 .and. mo /= 2) go to 45
call dorth(nb,n,1,n,b,wk)
call drtrn1(n,1,n,b,nb,v,nv,wk)
!
if (n == 1) go to 45
call dschur(n,1,n,b,nb,v,nv,wk(1),wk(n + 1),ierr)
if (ierr /= 0) go to 210
!
!     Transform c
!
45 do j = 1,n
   do i = 1,m
      wk(i) = 0.d0
      do k = 1,m
         wk(i) = wk(i) + u(k,i)*c(k,j)
      end do
   end do
   do i = 1,m
      c(i,j) = wk(i)
   end do
end do
!
do i = 1,m
   do j = 1,n
      wk(j) = 0.d0
      do k = 1,n
         wk(j) = wk(j) + c(i,k)*v(k,j)
      end do
   end do
   do j = 1,n
      c(i,j) = wk(j)
   end do
end do
!
!     Solve the transformed system
!
call dshslv(a,b,c,m,n,na,nb,nc,ierr)
if (ierr /= 0) go to 220
!
!     Transform c back to the solution
!
do j = 1,n
   do i = 1,m
      wk(i) = 0.d0
      do k = 1,m
         wk(i) = wk(i) + u(i,k)*c(k,j)
      end do
   end do
   do i = 1,m
      c(i,j) = wk(i)
   end do
end do
!
do i = 1,m
   do j = 1,n
      wk(j) = 0.d0
      do k = 1,n
         wk(j) = wk(j) + c(i,k)*v(j,k)
      end do
   end do
   do j = 1,n
      c(i,j) = wk(j)
   end do
end do
return
!
!     Error return
!
200 ierr = -1
return
210 ierr = -2
return
220 ierr = 1
end subroutine dabsv1

pure subroutine dschur(n, low, igh, h, nh, z, nz, wr, wi, ierr)
implicit none
integer, intent(in) :: n
integer, intent(in) :: nh, nz, igh
integer, intent(in) :: low
integer, intent(out) :: ierr
double precision, intent(inout) :: h(nh,n), wr(n), wi(n), z(nz,n)
integer :: ip1, i, j, k, l, m, en, ll, mm, na, its, mp2, enm2
double precision :: p, q, r, s, t, w, x, y, zz, norm, s1, s2
logical :: notlas
! ----------------------------------------------------------------------
!     It is assumed that h is an upper Hessenberg matrix. dschur
!     obtains an orthogonal matrix q for which  transpose(q)*h*q
!     is in Schur form. The eigenvalues of h are also computed.
!
!     On input-
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If  dbal  has not been used, set
!          low = 1, igh = n.
!
!        h contains the upper Hessenberg matrix,
!
!        nh is the first dimension of h,
!
!        z contains a matrix of order n,
!
!        nz is the first dimension of z.
!
!     On output-
!
!        h contains the transformed matrix in upper Schur form,
!
!        z contains the matrix z*q where q is the orthogonal
!          matrix which reduces h to upper Schur form,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n.
!
!        ierr is set to
!          0          FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 50 iterations.
!
! -----------------
!     Written by jack dongarra
!          Argonne National Laboratory
!          may 1961
!     modified by A.H. Morris (NSWC)
! ----------------------------------------------------------------------
!     This subroutine is a modification of the EISPACK subroutine
!     hqr2,  which is based on the Algol procedure hqr by peters
!     and Wilkinson, NUM. Math. 16 (1970), PP.181-204.
! ----------------------------------------------------------------------
!     double precision dsqrt, dabs
!     integer min0
!
ierr = 0
norm = 0.d0
k = 1
!     ********** Store roots isolated by balanc
!                and compute matrix norm **********
do i = 1,n
!
   do j = k,n
      norm = norm + abs(h(i,j))
10    continue
   end do
!
   k = i
   if (i >= low .and. i <= igh) go to 20
   wr(i) = h(i,i)
   wi(i) = 0.d0
20 continue
end do
!
en = igh
t = 0.d0
!     ********** Search for next eigenvalues **********
30 if (en < low) go to 300
its = 0
na = en - 1
enm2 = na - 1
!     ********** Look for single small sub-diagonal element
!                for l=en step -1 Until low do -- **********
40 do ll = low,en
   l = en + low - ll
   if (l == low) go to 60
   s = abs(h(l - 1,l - 1)) + abs(h(l,l))
   if (s == 0.d0) s = norm
   s1 = s
   s2 = s1 + abs(h(l,l - 1))
   if (s1 == s2) go to 60
50 continue
end do
!     ********** Form shift **********
60 x = h(en,en)
if (l == en) go to 220
y = h(na,na)
w = h(en,na)*h(na,en)
if (l == na) go to 230
if (its == 50) go to 290
if (its /= 10 .and. its /= 20 .and. its /= 30) go to 80
!     ********** Form exceptional shift **********
t = t + x
!
do i = low,en
   h(i,i) = h(i,i) - x
end do
!
s = abs(h(en,na)) + abs(h(na,enm2))
x = 0.75d0*s
y = x
w = -0.4375d0*s*s
80 its = its + 1
!     ********** Look for two consecutive small
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l,enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r*s - w)/h(m + 1,m) + h(m,m + 1)
   q = h(m + 1,m + 1) - zz - r - s
   r = h(m + 2,m + 1)
   s = abs(p) + abs(q) + abs(r)
   p = p/s
   q = q/s
   r = r/s
   if (m == l) go to 100
   s1 = abs(p)*(abs(h(m - 1,m - 1)) + abs(zz) + abs(h(m + 1,m + 1)))
   s2 = s1 + abs(h(m,m - 1))*(abs(q) + abs(r))
   if (s1 == s2) go to 100
end do
!
100 mp2 = m + 2
!
do i = mp2,en
   h(i,i - 2) = 0.d0
   if (i == mp2) go to 110
   h(i,i - 3) = 0.d0
110 continue
end do
!     ********** Double QR step involving rows l to en and
!                COLUMNS m TO en **********
do k = m,na
   notlas = k /= na
   if (k == m) go to 120
   p = h(k,k - 1)
   q = h(k + 1,k - 1)
   r = 0.d0
   if (notlas) r = h(k + 2,k - 1)
   x = abs(p) + abs(q) + abs(r)
   if (x == 0.d0) go to 210
   p = p/x
   q = q/x
   r = r/x
120 s = sqrt(p*p + q*q + r*r)
   if (p < 0.d0) s = -s
   if (k == m) go to 130
   h(k,k - 1) = -s*x
   go to 140
130 if (l /= m) h(k,k - 1) = -h(k,k - 1)
140 p = p + s
   x = p/s
   y = q/s
   zz = r/s
   q = q/p
   r = r/p
!     ********** Row modification **********
   do j = k,n
      p = h(k,j) + q*h(k + 1,j)
      if (.not.notlas) go to 150
      p = p + r*h(k + 2,j)
      h(k + 2,j) = h(k + 2,j) - p*zz
150   h(k + 1,j) = h(k + 1,j) - p*y
      h(k,j) = h(k,j) - p*x
   end do
!
   j = min(en,k + 3)
!     ********** Column modification **********
   do i = 1,j
      p = x*h(i,k) + y*h(i,k + 1)
      if (.not.notlas) go to 170
      p = p + zz*h(i,k + 2)
      h(i,k + 2) = h(i,k + 2) - p*r
170   h(i,k + 1) = h(i,k + 1) - p*q
      h(i,k) = h(i,k) - p
   end do
!     ********** Accumulate transformations **********
   do i = low,igh
      p = x*z(i,k) + y*z(i,k + 1)
      if (.not.notlas) go to 190
      p = p + zz*z(i,k + 2)
      z(i,k + 2) = z(i,k + 2) - p*r
190   z(i,k + 1) = z(i,k + 1) - p*q
      z(i,k) = z(i,k) - p
   end do
!
210 continue
end do
!
go to 40
!     ********** One root found **********
220 h(en,en) = x + t
wr(en) = h(en,en)
wi(en) = 0.d0
en = na
go to 30
!     ********** Two roots found **********
230 p = (y - x)/2.d0
q = p*p + w
zz = sqrt(abs(q))
h(en,en) = x + t
x = h(en,en)
h(na,na) = y + t
if (q < 0.d0) go to 270
!     ********** Real pair **********
if (p < 0.d0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz /= 0.d0) wr(en) = x - w/zz
wi(na) = 0.d0
wi(en) = 0.d0
x = h(en,na)
s = abs(x) + abs(zz)
p = x/s
q = zz/s
r = sqrt(p*p + q*q)
p = p/r
q = q/r
!     ********** Row modification **********
do j = na,n
   zz = h(na,j)
   h(na,j) = q*zz + p*h(en,j)
   h(en,j) = q*h(en,j) - p*zz
end do
!     ********** Column modification **********
do i = 1,en
   zz = h(i,na)
   h(i,na) = q*zz + p*h(i,en)
   h(i,en) = q*h(i,en) - p*zz
end do
!     ********** Accumulate transformations **********
do i = low,igh
   zz = z(i,na)
   z(i,na) = q*zz + p*z(i,en)
   z(i,en) = q*z(i,en) - p*zz
end do
!
go to 280
!     ********** Complex pair **********
270 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
280 en = enm2
go to 30
!     ********** Set error -- no convergence to an
!                eigenvalue after 50 iterations **********
290 ierr = en
return
300 do i = 1,n
   ip1 = i + 1
   if (abs(wi(i)) /= 0.d0) ip1 = ip1 + 1
   if (ip1 > n) go to 320
   do j = ip1,n
      h(j,i) = 0.d0
   end do
320 continue
end do
end subroutine dschur

pure subroutine dshslv(a,b,c,m,n,na,nb,nc,ierr)
implicit none
!     ------------------------------------------------------------------
!     dshslv solves the matrix equation AX + XB = c where
!     A is in lower Schur form and b in upper Schur form.
!     ------------------------------------------------------------------
integer, intent(in) :: m, n, na, nb, nc
integer, intent(inout) :: ierr
double precision, intent(in) :: a(na,m), b(nb,n)
double precision, intent(inout) :: c(nc,n)
double precision :: sum, p(4), t(4,4)
integer :: dk, dl, i, ib, j, ja, k, km1, kk, l, lm1, ll
interface
   pure subroutine dpslv(n,m,a,ka,b,kb,ierr)
      implicit none
      integer, intent(in) :: kb
      integer, intent(in) :: ka
      integer, intent(in) :: m
      integer, intent(in) :: n
      double precision, intent(inout) :: a(ka,n)
      double precision, intent(inout) :: b(kb,m)
      integer, intent(out) :: ierr
   end subroutine dpslv
end interface
!
l = 1
10 lm1 = l - 1
dl = 1
if (l == n) go to 15
if (b(l + 1,l) /= 0.d0) dl = 2
15 ll = l + dl - 1
if (l == 1) go to 30
!
do j = l,ll
   do i = 1,m
      sum = c(i,j)
      do ib = 1,lm1
20       sum = sum - c(i,ib)*b(ib,j)
      end do
21    c(i,j) = sum
   end do
end do
!
30 k = 1
40 km1 = k - 1
dk = 1
if (k == m) go to 45
if (a(k,k + 1) /= 0.d0) dk = 2
45 kk = k + dk - 1
if (k == 1) go to 60
!
do i = k,kk
   do j = l,ll
      sum = c(i,j)
      do ja = 1,km1
50       sum = sum - a(i,ja)*c(ja,j)
      end do
51    c(i,j) = sum
   end do
end do
!
60 if (dl == 2) go to 80
if (dk == 2) go to 70
t(1,1) = a(k,k) + b(l,l)
if (t(1,1) == 0.d0) go to 200
c(k,l) = c(k,l)/t(1,1)
ierr = 0
go to 100
!
70 t(1,1) = a(k,k) + b(l,l)
t(1,2) = a(k,kk)
t(2,1) = a(kk,k)
t(2,2) = a(kk,kk) + b(l,l)
p(1) = c(k,l)
p(2) = c(kk,l)
call dpslv(2, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(k,l) = p(1)
c(kk,l) = p(2)
go to 100
!
80 if (dk == 2) go to 90
t(1,1) = a(k,k) + b(l,l)
t(1,2) = b(ll,l)
t(2,1) = b(l,ll)
t(2,2) = a(k,k) + b(ll,ll)
p(1) = c(k,l)
p(2) = c(k,ll)
call dpslv(2, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(k,l) = p(1)
c(k,ll) = p(2)
go to 100
!
90 t(1,1) = a(k,k) + b(l,l)
t(1,2) = a(k,kk)
t(1,3) = b(ll,l)
t(1,4) = 0.d0
t(2,1) = a(kk,k)
t(2,2) = a(kk,kk) + b(l,l)
t(2,3) = 0.d0
t(2,4) = t(1,3)
t(3,1) = b(l,ll)
t(3,2) = 0.d0
t(3,3) = a(k,k) + b(ll,ll)
t(3,4) = t(1,2)
t(4,1) = 0.d0
t(4,2) = t(3,1)
t(4,3) = t(2,1)
t(4,4) = a(kk,kk) + b(ll,ll)
p(1) = c(k,l)
p(2) = c(kk,l)
p(3) = c(k,ll)
p(4) = c(kk,ll)
call dpslv(4, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(k,l) = p(1)
c(kk,l) = p(2)
c(k,ll) = p(3)
c(kk,ll) = p(4)
!
100 k = k + dk
if (k <= m) go to 40
l = l + dl
if (l <= n) go to 10
return
!
!     Error return
!
200 ierr = 1
end subroutine dshslv

subroutine taslv(mo,n,a,na,c,nc,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: mo
integer :: n
integer, intent(in) :: na, nc
real, intent(inout) :: a(na,n), c(nc,n), wk(*)
integer :: iw
! ----------------------------------------------------------------------
!     taslv solves the real matrix equation transpose(a)*X + X*a = c
!     where c is a symmetric matrix. A is reduced to upper Schur form
!     and the transformed system is solved.
! ----------------------------------------------------------------------
!        mo is an input argument which specifies if the routine is
!     being called for the first time. On an initial call mo = 0 And
!     we have the following setup.
!
!        a(na,n)
!           A is a matrix of order n. it is assumed that
!           na .GE. n .GE. 1.
!
!        c(nc,n)
!           c is a symmetric matrix of order n. it is
!           assumed that nc .GE. n.
!
!        wk(---)
!           wk is an array of dimension n**2 + 2n that
!           is a general storage area for the routine.
!
!     ierr is a variable that reports the status of the results. When
!     the routine terminates, ierr has one of the following values...
!
!        ierr =  0  The solution was obtained and stored in c.
!        ierr =  1  The equations are inconsistent for A. the
!                   problem cannot be solved.
!        ierr = -1  A could not be REDUCEDTO upper Schur form.
!                   The problem cannot be solved.
!
!     When ierr = 0, a contains the upper Schur form of the matrix
!     A and wk contains the orthogonal matrix involved in the Schur
!     decomposition of A. this information can be reused to solve A
!     new set of equations transpose(a)*X + X*a = c without having
!     to redecompose A. in this case, the input argument mo may be
!     set to any nonzero value. When mo .NE. 0, it is assumed that
!     only c has been modified. On output the solution for the new
!     set of equations is stored in c.
! ----------------------------------------------------------------------
!     This subroutine is a modification by
!        Alfred H. Morris, Jr.
!        naval surface weapons center
!        Dahlgren, Virginia
!     of the subroutine atxpxa written by
!        R.H. Bartels and G.W. Stewart
!        University of Texas at Austin.
!
!     Reference. Bartels, R.H. and Stewart, G.W., algorithm 432,
!        solution of the matrix equation AX + XB = c, comm. ACM
!        15 (1972), PP. 820-826.
! ----------------------------------------------------------------------
iw = n*n + 1
call taslv1(mo,n,a,na,wk(1),n,c,nc,wk(iw),ierr)
end subroutine taslv

subroutine taslv1(mo,n,a,na,u,nu,c,nc,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: mo
integer :: n
integer, intent(in) :: na, nc, nu
real, intent(inout) :: a(na,n), u(nu,n), c(nc,n), wk(*)
integer :: i, j, k
! ----------------------------------------------------------------------
!     taslv1 solves the real matrix equation transpose(a)*X + X*a = c
!     where c is a symmetric matrix. A is reduced to upper Schur form
!     and the transformed system is solved.
! ----------------------------------------------------------------------
!
!    If required, reduce A to upper real Schur form
!
if (mo /= 0) go to 10
call orthes(na,n,1,n,a,wk)
call ortrn1(n,1,n,a,na,u,nu,wk)
call schur(n,1,n,a,na,u,nu,wk(1),wk(n + 1),ierr)
if (ierr /= 0) go to 200
!
!     Transform c
!
10 do i = 1,n
   c(i,i) = c(i,i)/2.0
end do
!
do i = 1,n
   do j = 1,n
      wk(j) = 0.0
      do k = i,n
         wk(j) = wk(j) + c(i,k)*u(k,j)
      end do
   end do
   do j = 1,n
      c(i,j) = wk(j)
   end do
end do
!
do j = 1,n
   do i = 1,n
      wk(i) = 0.0
      do k = 1,n
         wk(i) = wk(i) + u(k,i)*c(k,j)
      end do
   end do
   do i = 1,n
      c(i,j) = wk(i)
   end do
end do
!
do i = 1,n
   do j = i,n
      c(i,j) = c(i,j) + c(j,i)
      c(j,i) = c(i,j)
   end do
end do
!
!     Solve the transformed system
!
call symslv(a,c,n,na,nc,ierr)
if (ierr /= 0) go to 210
!
!     Transform c back to the solution
!
do i = 1,n
   c(i,i) = c(i,i)/2.0
end do
!
do i = 1,n
   do j = 1,n
      wk(j) = 0.0
      do k = i,n
         wk(j) = wk(j) + c(i,k)*u(j,k)
      end do
   end do
   do j = 1,n
      c(i,j) = wk(j)
   end do
end do
!
do j = 1,n
   do i = 1,n
      wk(i) = 0.0
      do k = 1,n
         wk(i) = wk(i) + u(i,k)*c(k,j)
      end do
   end do
   do i = 1,n
      c(i,j) = wk(i)
   end do
end do
!
do i = 1,n
   do j = i,n
      c(i,j) = c(i,j) + c(j,i)
      c(j,i) = c(i,j)
   end do
end do
return
!
!     Error return
!
200 ierr = -1
return
210 ierr = 1
end subroutine taslv1

pure subroutine symslv(a,c,n,na,nc,ierr)
implicit none
! ----------------------------------------------------------------------
!     symslv solves the matrix equation transpose(a)*X + X*a = c
!     where A is in upper Schur form and c is symmetric.
! ----------------------------------------------------------------------
integer, intent(in) :: n, na, nc
integer, intent(inout) :: ierr
real, intent(in) :: a(na,n)
real, intent(inout) :: c(nc,n)
real :: sum, p(4), t(4,4)
integer :: dk, dl, i, ia, j, k, kk, km1, l, ll, ldl
interface
   pure subroutine slv(n,m,a,ka,b,kb,ierr)
      implicit none
      integer, intent(in) :: kb
      integer, intent(in) :: ka
      integer, intent(in) :: m
      integer, intent(in) :: n
      real, intent(inout) :: a(ka,n)
      real, intent(inout) :: b(kb,m)
      integer, intent(out) :: ierr
   end subroutine slv
end interface
!
l = 1
10 dl = 1
if (l == n) go to 20
if (a(l + 1,l) /= 0.0) dl = 2
20 ll = l + dl - 1
!
k = l
30 km1 = k - 1
dk = 1
if (k == n) go to 35
if (a(k + 1,k) /= 0.0) dk = 2
35 kk = k + dk - 1
if (k == l) go to 45
!
do i = k,kk
   do j = l,ll
      sum = c(i,j)
      do ia = l,km1
40       sum = sum - a(ia,i)*c(ia,j)
      end do
41    c(i,j) = sum
   end do
end do
!
45 if (dl == 2) go to 60
if (dk == 2 ) go to 50
t(1,1) = a(k,k) + a(l,l)
if (t(1,1) == 0.0) go to 200
c(k,l) = c(k,l)/t(1,1)
ierr = 0
go to 90
!
50 t(1,1) = a(k,k) + a(l,l)
t(1,2) = a(kk,k)
t(2,1) = a(k,kk)
t(2,2) = a(kk,kk) + a(l,l)
p(1) = c(k,l)
p(2) = c(kk,l)
call slv(2, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(k,l) = p(1)
c(kk,l) = p(2)
go to 90
!
60 if (dk == 2) go to 70
t(1,1) = a(k,k) + a(l,l)
t(1,2) = a(ll,l)
t(2,1) = a(l,ll)
t(2,2) = a(k,k) + a(ll,ll)
p(1) = c(k,l)
p(2) = c(k,ll)
call slv(2, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(k,l) = p(1)
c(k,ll) = p(2)
go to 90
!
70 if (k /= l) go to 80
t(1,1) = a(l,l)
t(1,2) = a(ll,l)
t(1,3) = 0.0
t(2,1) = a(l,ll)
t(2,2) = a(l,l) + a(ll,ll)
t(2,3) = t(1,2)
t(3,1) = 0.0
t(3,2) = t(2,1)
t(3,3) = a(ll,ll)
p(1) = c(l,l)/2.0
p(2) = c(ll,l)
p(3) = c(ll,ll)/2.0
call slv(3, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(l,l) = p(1)
c(ll,l) = p(2)
c(l,ll) = p(2)
c(ll,ll) = p(3)
go to 90
!
80 t(1,1) = a(k,k) + a(l,l)
t(1,2) = a(kk,k)
t(1,3) = a(ll,l)
t(1,4) = 0.0
t(2,1) = a(k,kk)
t(2,2) = a(kk,kk) + a(l,l)
t(2,3) = 0.0
t(2,4) = t(1,3)
t(3,1) = a(l,ll)
t(3,2) = 0.0
t(3,3) = a(k,k) + a(ll,ll)
t(3,4) = t(1,2)
t(4,1) = 0.0
t(4,2) = t(3,1)
t(4,3) = t(2,1)
t(4,4) = a(kk,kk) + a(ll,ll)
p(1) = c(k,l)
p(2) = c(kk,l)
p(3) = c(k,ll)
p(4) = c(kk,ll)
call slv(4, 1, t, 4, p, 4, ierr)
if (ierr /= 0) go to 200
c(k,l) = p(1)
c(kk,l) = p(2)
c(k,ll) = p(3)
c(kk,ll) = p(4)
!
90 k = k + dk
if (k <= n) go to 30
ldl = l + dl
if (ldl > n) return
!
do j = ldl,n
   do i = l,ll
      c(i,j) = c(j,i)
   end do
   do i = j,n
      do k = l,ll
110      c(i,j) = c(i,j) - c(i,k)*a(k,j) - a(k,i)*c(k,j)
      end do
120   c(j,i) = c(i,j)
   end do
end do
l = ldl
go to 10
!
!     Error return
!
200 ierr = 1
end subroutine symslv

subroutine dtaslv(mo,n,a,na,c,nc,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: mo
integer :: n
integer, intent(in) :: na, nc
double precision, intent(inout) :: a(na,n), c(nc,n), wk(*)
integer :: iw
! ----------------------------------------------------------------------
!     dtaslv solves the real matrix equation transpose(a)*X + X*a = c
!     where c is a symmetric matrix. A is reduced to upper Schur form
!     and the transformed system is solved.
! ----------------------------------------------------------------------
!        mo is an input argument which specifies if the routine is
!     being called for the first time. On an initial call mo = 0 And
!     we have the following setup.
!
!        a(na,n)
!           A is a matrix of order n. it is assumed that
!           na .GE. n .GE. 1.
!
!        c(nc,n)
!           c is a symmetric matrix of order n. it is
!           assumed that nc .GE. n.
!
!        wk(---)
!           wk is an array of dimension n**2 + 2n that
!           is a general storage area for the routine.
!
!     ierr is a variable that reports the status of the results. When
!     the routine terminates, ierr has one of the following values...
!
!        ierr =  0  The solution was obtained and stored in c.
!        ierr =  1  The equations are inconsistent for A. the
!                   problem cannot be solved.
!        ierr = -1  A could not be REDUCEDTO upper Schur form.
!                   The problem cannot be solved.
!
!     When ierr = 0, a contains the upper Schur form of the matrix
!     A and wk contains the orthogonal matrix involved in the Schur
!     decomposition of A. this information can be reused to solve A
!     new set of equations transpose(a)*X + X*a = c without having
!     to redecompose A. in this case, the input argument mo may be
!     set to any nonzero value. When mo .NE. 0, it is assumed that
!     only c has been modified. On output the solution for the new
!     set of equations is stored in c.
! ----------------------------------------------------------------------
!     This subroutine is a modification by
!        Alfred H. Morris, Jr.
!        naval surface weapons center
!        Dahlgren, Virginia
!     of the subroutine atxpxa written by
!        R.H. Bartels and G.W. Stewart
!        University of Texas at Austin.
!
!     Reference. Bartels, R.H. and Stewart, G.W., algorithm 432,
!        solution of the matrix equation AX + XB = c, comm. ACM
!        15 (1972), PP. 820-826.
! ----------------------------------------------------------------------
iw = n*n + 1
call dtasv1(mo,n,a,na,wk(1),n,c,nc,wk(iw),ierr)
end subroutine dtaslv

subroutine dtasv1(mo,n,a,na,u,nu,c,nc,wk,ierr)
