   m = k
   if (k < n) go to 70
   if (c(k) == zero) go to 200
   d(last) = bk/c(k)
   go to 90
!
!     Find the pivot
!
70 s = abs(real(c(k))) + abs(aimag(c(k)))
   do i = kp1,n
      si = abs(real(c(i))) + abs(aimag(c(i)))
      if (si <= s) go to 71
      m = i
      s = si
71    continue
   end do
!
   ip(k) = m
   ck = c(m)
   c(m) = c(k)
   c(k) = ck
   if (c(k) == zero) go to 200
!
!     Find the k-TH elementary matrix
!
   ik = last
   do i = kp1,n
      d(ik) = -c(i)/c(k)
80    ik = ik + 1
   end do
   d(ik) = bk/c(k)
!
!     Form the product of the elementary matrices
!
90 do j = 1,km1
      kjold = j*lcolp1 + k - np1
      mjold = kjold + m - k
      ij = (j - 1)*lcol
      ijold = ij + j
      if (j /= km1) go to 100
!
      kjold = lastm1
      mjold = lastm1 + m - k
      ijold = lastm1
!
100   ik = last - 1
      dkj = d(mjold)
      d(mjold) = d(kjold)
      do i = kp1,np1
         ij = ij + 1
         ijold = ijold + 1
         ik = ik + 1
         d(ij) = d(ijold) + d(ik)*dkj
110      continue
      end do
   end do
end do
!
last = max
if (iflag < 0) last = max - 2
d(n) = d(last)
!
!     Insert the solution in c
!
do i = 1,n
130 c(i) = d(i)
end do
!
nm1 = n - 1
do i = 1,nm1
   k = n - i
   m = ip(k)
   ck = c(k)
   c(k) = c(m)
140 c(m) = ck
end do
