pure subroutine cvbr(b,kb,m,n,ml,mu,a,ka)
implicit none
integer, intent(in) :: ka, kb, m, ml, mu, n
real, intent(inout) :: a(ka,n)
real, intent(in) :: b(kb,*)
integer :: i, imax, imax0, imin, j, jj, jmax, jmin, k, l
!-----------------------------------------------------------------------
!           Conversion of real matrices from banded to
!                         standard form
!-----------------------------------------------------------------------
!
!     Store the nonzero data of the first ml rows
!
if (ml == 0) go to 20
do i = 1,ml
   jmax = min(n,i + mu)
   k = ml + 1 - i
   do j = 1,jmax
      k = k + 1
10    a(i,j) = b(i,k)
   end do
end do
!
!     Store the remaining nonzero data
!
20 imin = ml + 1
imax = min(m,ml + n)
l = 0
do i = imin,imax
   jmin = i - ml
   jmax = min(n,i + mu)
   j = jmax
   do jj = jmin,jmax
      k = j - l
      a(i,j) = b(i,k)
21    j = j - 1
   end do
   l = l + 1
end do
!
!     Insert zeros in the upper right corner
!
jmin = mu + 2
if (jmin > n) go to 40
imax0 = 1
do j = jmin,n
   do i = 1,imax0
30    a(i,j) = 0.0
   end do
   imax0 = min(imax,imax0 + 1)
end do
!
!     Insert zeros in the lower left corner
!
40 if (imin == imax) go to 50
jmax = imax - imin
do j = 1,jmax
   imin = imin + 1
   do i = imin,imax
41    a(i,j) = 0.0
   end do
end do
!
!     Store zeros in the final m-imax rows
!
50 if (imax == m) return
imin = imax + 1
do j = 1,n
   do i = imin,m
51    a(i,j) = 0.0
   end do
end do
end subroutine cvbr

