end do
!
!     Store zeros in the final m-imax rows
!
50 if (imax == m) return
imin = imax + 1
do j = 1,n
   do i = imin,m
51    a(i,j) = (0.0,0.0)
   end do
end do
end subroutine cvbc

pure subroutine cvcb(a,ka,m,n,ml,mu,b,kb)
implicit none
integer, intent(in) :: ka, kb, m, ml, mu, n
complex, intent(in) :: a(ka,n)
complex, intent(inout) :: b(kb,*)
integer :: i, imax, imin, j, jj, jmax, jmin, k, l
!-----------------------------------------------------------------------
!        Conversion of complex matrices from standard to banded
!                    form when ml and mu are given
!-----------------------------------------------------------------------
!
!     Store the nonzero data of the first ml rows
!
if (ml == 0) go to 30
l = ml
do i = 1,ml
   jmax = min(n,i + mu)
   j = jmax
   do jj = 1,jmax
      k = j + l
      b(i,k) = a(i,j)
10    j = j - 1
   end do
   l = l - 1
end do
!
!     Insert zeros in the upper left corner
!
imax = ml
do j = 1,ml
   do i = 1,imax
20    b(i,j) = (0.0,0.0)
   end do
   imax = imax - 1
end do
!
!     Store the remaining nonzero data
!
30 imin = ml + 1
imax = min(m,ml + n)
do i = imin,imax
   jmin = i - ml
   jmax = min(n,i + mu)
   k = 0
   do j = jmin,jmax
      k = k + 1
31    b(i,k) = a(i,j)
   end do
end do
!
!     Insert zeros in the lower right corner
!
jmax = ml + mu + 1
if (k == jmax) go to 50
jmin = k + 1
imin = imax
do j = jmin,jmax
   do i = imin,imax
40    b(i,j) = (0.0,0.0)
   end do
   imin = imin - 1
end do
!
!     Store zeros in the final m-imax rows
!
50 if (imax == m) return
imin = imax + 1
do j = 1,jmax
   do i = imin,m
51    b(i,j) = (0.0,0.0)
   end do
end do
end subroutine cvcb

pure subroutine cvcb1(a,ka,m,n,ml,mu,b,kb,nb,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, m
integer, intent(inout) :: ml, mu
integer, intent(in) :: n, nb
complex, intent(in) :: a(ka,n)
complex, intent(inout) :: b(kb,nb)
integer :: i, imax, imin, j, jmax, jmin, kmax, l, mm1, nm1
interface
   pure subroutine cvcb(a,ka,m,n,ml,mu,b,kb)
      implicit none
      integer, intent(in) :: kb
      integer, intent(in) :: n
      integer, intent(in) :: ka
      complex, intent(in) :: a(ka,n)
      integer, intent(in) :: m
      integer, intent(in) :: ml
      integer, intent(in) :: mu
      complex, intent(inout) :: b(kb,*)
   end subroutine cvcb
end interface
!-----------------------------------------------------------------------
!           Conversion of complex matrices from standard
!                          to banded form
!-----------------------------------------------------------------------
!
!     Computation of ml and mu
!
nm1 = n - 1
imin = m
if (m == 1) go to 20
do l = 2,m
   j = 1
   imax = min(m,imin + nm1)
   do i = imin,imax
      if (a(i,j) /= (0.0,0.0)) go to 20
10    j = j + 1
   end do
   imin = imin - 1
end do
!
20 mm1 = m - 1
jmin = n
if (n == 1) go to 30
do l = 2,n
   i = 1
   jmax = min(n,jmin + mm1)
   do j = jmin,jmax
      if (a(i,j) /= (0.0,0.0)) go to 30
21    i = i + 1
   end do
   jmin = jmin - 1
end do
!
30 ml = imin - 1
mu = jmin - 1
kmax = ml + mu + 1
if (kmax > nb) go to 40
!
!     Store the matrix in b
!
ierr = 0
call cvcb(a,ka,m,n,ml,mu,b,kb)
return
!
!     Error return
!
40 ierr = kmax
end subroutine cvcb1

pure subroutine mcvbs(a,ka,m,n,ml,mu,b,ib,jb,num,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, m, ml, mu, n, num
real, intent(in) :: a(ka,*)
real, intent(inout) :: b(*)
integer, intent(inout) :: ib(*), jb(*)
integer :: i, imax, imin, j0, k, kmax, kmin, l, mp1
!-----------------------------------------------------------------------
!                Conversion of real matrices from banded
!                            to sparse form
!-----------------------------------------------------------------------
!
l = 1
kmax = ml + mu + 1
!
!     Store the nonzero data of the first ml rows
!
j0 = ml
if (ml == 0) go to 20
do i = 1,ml
   ib(i) = l
   kmin = 1 + j0
   do k = kmin,kmax
      if (a(i,k) == 0.0) go to 10
      if (l > num) go to 40
      b(l) = a(i,k)
      jb(l) = k - j0
      l = l + 1
10    continue
   end do
   j0 = j0 - 1
end do
!
!     Store the remaining nonzero data
!
20 imin = ml + 1
imax = min(m,ml + n)
do i = imin,imax
   ib(i) = l
   do k = 1,kmax
      if (a(i,k) == 0.0) go to 21
      if (l > num) go to 40
      b(l) = a(i,k)
      jb(l) = k - j0
      l = l + 1
21    continue
   end do
   j0 = j0 - 1
end do
ierr = 0
!
!     Set up the remaining m-imax rows
!
imin = imax + 1
mp1 = m + 1
do i = imin,mp1
   ib(i) = l
end do
return
!
!     Error return
!
40 ierr = i
end subroutine mcvbs

