subroutine mcvsb(a,ia,ja,m,n,b,kb,nb,ml,mu,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: kb, m
integer, intent(out) :: ml, mu
integer, intent(in) :: n, nb
real, intent(in) :: a(*)
real, intent(inout) :: b(kb,nb)
integer, intent(in) :: ia(*), ja(*)
integer :: i, j0, k, kmax, l, lmax, lmin
!-----------------------------------------------------------------------
!                Conversion of real matrices from sparse
!                            to banded form
!-----------------------------------------------------------------------
!
!     Computation of ml and mu
!
ml = 0
mu = 0
do i = 1,m
   lmin = ia(i)
   lmax = ia(i + 1) - 1
   if (lmin > lmax) go to 11
   do l = lmin,lmax
      if (a(l) == 0.0) go to 10
      k = ja(l) - i
      mu = max(mu,k)
      ml = max(ml,-k)
10    continue
   end do
11 continue
end do
!
!     Set b = 0 If b provides sufficient storage
!
kmax = ml + mu + 1
if (kmax > nb) go to 40
!
ierr = 0
do k = 1,kmax
   do i = 1,m
20    b(i,k) = 0.0
   end do
end do
!
!     Store the matrix in b
!
j0 = ml
do i = 1,m
   lmin = ia(i)
   lmax = ia(i + 1) - 1
   if (lmin > lmax) go to 31
   do l = lmin,lmax
      if (a(l) == 0.0) go to 30
      k = ja(l) + j0
      b(i,k) = a(l)
30    continue
   end do
   j0 = j0 - 1
31 continue
end do
return
!
!     Error return
!
40 ierr = kmax
end subroutine mcvsb

