do j = 1,num
   do i = 1,m
      b(i,j) = a(i,j)
   end do
end do
end subroutine bcvdr

pure subroutine breal(a, ka, m, n, ml, mu, b, kb, l, nl, nu, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, l, m, ml, mu, n
integer, intent(out) :: nl
integer, intent(inout) :: nu
complex, intent(in) :: a(ka,*)
real, intent(inout) :: b(kb,l)
integer :: i, imin, j, k, num
!-----------------------------------------------------------------------
!              Real part of a banded complex matrix
!-----------------------------------------------------------------------
!
!     Computation of nl and nu
!
nl = ml
if (ml == 0) go to 30
imin = ml + 1
do j = 1,ml
   do i = imin,m
      if (real(a(i,j)) /= 0.0) go to 30
   end do
   nl = nl - 1
   imin = imin - 1
end do
!
30 nu = mu
if (mu == 0) go to 60
j = ml + mu + 1
do k = 1,mu
   do i = 1,m
      if (real(a(i,j)) /= 0.0) go to 60
   end do
   nu = nu - 1
   j = j - 1
end do
!
!     Store the real part of A in b
!
60 num = nl + nu + 1
if (num > l) go to 100
ierr = 0
k = ml - nl
do j = 1,num
   k = k + 1
   do i = 1,m
      b(i,j) = real(a(i,k))
   end do
end do
return
!
!     Error return
!
100 ierr = num
end subroutine breal

pure subroutine bimag(a, ka, m, n, ml, mu, b, kb, l, nl, nu, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, l, m, ml, mu, n
integer, intent(out) :: nl
integer, intent(inout) :: nu
complex, intent(in) :: a(ka,*)
real, intent(inout) :: b(kb,l)
integer :: i, imin, j, k, num
!-----------------------------------------------------------------------
!            Imaginary part of a banded complex matrix
!-----------------------------------------------------------------------
!
!     Computation of nl and nu
!
nl = ml
if (ml == 0) go to 30
imin = ml + 1
do j = 1,ml
   do i = imin,m
      if (aimag(a(i,j)) /= 0.0) go to 30
   end do
   nl = nl - 1
   imin = imin - 1
end do
!
30 nu = mu
if (mu == 0) go to 60
j = ml + mu + 1
do k = 1,mu
   do i = 1,m
      if (aimag(a(i,j)) /= 0.0) go to 60
   end do
   nu = nu - 1
   j = j - 1
end do
!
!     Store the imaginary part of A in b
!
60 num = nl + nu + 1
if (num > l) go to 100
ierr = 0
k = ml - nl
do j = 1,num
   k = k + 1
   do i = 1,m
      b(i,j) = aimag(a(i,k))
   end do
end do
return
!
!     Error return
!
100 ierr = num
end subroutine bimag

pure subroutine bcvrc(m,n,a,ka,ml,mu,b,kb,nl,nu,c,kc,l,mcl,mcu,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, kb, kc, l, m
integer, intent(out) :: mcl, mcu
integer, intent(in) :: ml, mu, n, nl, nu
real, intent(in) :: a(ka,*), b(kb,*)
complex, intent(inout) :: c(kc,l)
integer :: i, j, ja, jb, jc, jmax, k, num
!-----------------------------------------------------------------------
!        Compute a + bi for the banded real matrices A and b
!-----------------------------------------------------------------------
!
mcl = max(ml,nl)
mcu = max(mu,nu)
num = mcl + mcu + 1
if (num > l) go to 200
!
ierr = 0
k = min(mu,nu) + 1
!
!     Insert the first abs(ml - nl) diagonals
!
if (nl >= ml) go to 30
ja = ml - nl
jb = 0
jc = ja
jmax = nl + k
do j = 1,jc
   do i = 1,m
      c(i,j) = cmplx(a(i,j),0.0)
   end do
end do
go to 60
!
30 ja = 0
jb = nl - ml
jc = jb
jmax = ml + k
if (jc == 0) go to 60
do j = 1,jc
   do i = 1,m
      c(i,j) = cmplx(0.0,b(i,j))
   end do
end do
!
!     Addition of the common diagonals
!
60 do j = 1,jmax
   ja = ja + 1
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = cmplx(a(i,ja),b(i,jb))
   end do
end do
!
!     Insertion of the remaining diagonals
!
if (nu >= mu) go to 120
jmax = mu - nu
do j = 1,jmax
   ja = ja + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = cmplx(a(i,ja),0.0)
   end do
end do
return
!
120 jmax = nu - mu
if (jmax == 0) return
do j = 1,jmax
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = cmplx(0.0,b(i,jb))
   end do
end do
return
!
!     Error return
!
200 ierr = num
end subroutine bcvrc

pure subroutine bpose(a, ka, m, n, ml, mu, b, kb)
implicit none
integer, intent(in) :: ka, kb, m, ml, mu, n
real, intent(in) :: a(ka,*)
real, intent(inout) :: b(kb,*)
integer :: i, imax, imin, j, jmin, k, l, lj, lp1, ndiag
!-----------------------------------------------------------------------
!                Transposition of real banded matrices
!-----------------------------------------------------------------------
!
l = ml + mu + 1
lp1 = l + 1
if (mu == 0) go to 40
!
!     Define the first mu columns of b
!
ndiag = mu
do j = 1,mu
   do i = 1,ndiag
      b(i,j) = 0.0
   end do
!
   lj = lp1 - j
   imax = min(m,n - ndiag)
   do i = 1,imax
      k = ndiag + i
      b(k,j) = a(i,lj)
   end do
!
   if (k == n) go to 31
   imin = k + 1
   do i = imin,n
      b(i,j) = 0.0
   end do
31 ndiag = ndiag - 1
end do
!
!     Define the remaining columns of b
!
40 jmin = mu + 1
ndiag = 0
do j = jmin,l
   lj = lp1 - j
   imax = min(m - ndiag,n)
   do i = 1,imax
      k = ndiag + i
      b(i,j) = a(k,lj)
   end do
!
   if (imax == n) go to 61
   imin = imax + 1
   do i = imin,n
      b(i,j) = 0.0
   end do
61 ndiag = ndiag + 1
end do
end subroutine bpose

pure subroutine dbpose(a, ka, m, n, ml, mu, b, kb)
implicit none
integer, intent(in) :: ka, kb, m, ml, mu, n
double precision, intent(in) :: a(ka,*)
double precision, intent(inout) :: b(kb,*)
integer :: i, imax, imin, j, jmin, k, l, lj, lp1, ndiag
!-----------------------------------------------------------------------
!          Transposition of double precision banded matrices
!-----------------------------------------------------------------------
!
l = ml + mu + 1
lp1 = l + 1
if (mu == 0) go to 40
!
!     Define the first mu columns of b
!
ndiag = mu
do j = 1,mu
   do i = 1,ndiag
      b(i,j) = 0.d0
   end do
!
   lj = lp1 - j
   imax = min(m,n - ndiag)
   do i = 1,imax
      k = ndiag + i
      b(k,j) = a(i,lj)
   end do
!
   if (k == n) go to 31
   imin = k + 1
   do i = imin,n
      b(i,j) = 0.d0
   end do
31 ndiag = ndiag - 1
end do
!
!     Define the remaining columns of b
!
40 jmin = mu + 1
ndiag = 0
do j = jmin,l
   lj = lp1 - j
   imax = min(m - ndiag,n)
   do i = 1,imax
      k = ndiag + i
      b(i,j) = a(k,lj)
   end do
!
   if (imax == n) go to 61
   imin = imax + 1
   do i = imin,n
      b(i,j) = 0.d0
   end do
61 ndiag = ndiag + 1
end do
end subroutine dbpose

pure subroutine cbpose(a, ka, m, n, ml, mu, b, kb)
implicit none
integer, intent(in) :: ka, kb, m, ml, mu, n
complex, intent(in) :: a(ka,*)
complex, intent(inout) :: b(kb,*)
integer :: i, imax, imin, j, jmin, k, l, lj, lp1, ndiag
!-----------------------------------------------------------------------
!              Transposition of complex banded matrices
!-----------------------------------------------------------------------
!
l = ml + mu + 1
lp1 = l + 1
if (mu == 0) go to 40
!
!     Define the first mu columns of b
!
ndiag = mu
do j = 1,mu
   do i = 1,ndiag
      b(i,j) = (0.0,0.0)
   end do
!
   lj = lp1 - j
   imax = min(m,n - ndiag)
   do i = 1,imax
      k = ndiag + i
      b(k,j) = a(i,lj)
   end do
!
   if (k == n) go to 31
   imin = k + 1
   do i = imin,n
      b(i,j) = (0.0,0.0)
   end do
31 ndiag = ndiag - 1
end do
!
!     Define the remaining columns of b
!
40 jmin = mu + 1
ndiag = 0
do j = jmin,l
   lj = lp1 - j
   imax = min(m - ndiag,n)
   do i = 1,imax
      k = ndiag + i
      b(i,j) = a(k,lj)
   end do
!
   if (imax == n) go to 61
   imin = imax + 1
   do i = imin,n
      b(i,j) = (0.0,0.0)
   end do
61 ndiag = ndiag + 1
end do
end subroutine cbpose

pure subroutine badd(m,n,a,ka,ml,mu,b,kb,nl,nu,c,kc,l,mcl,mcu,ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, kc, l, m
integer, intent(inout) :: mcl, mcu
integer, intent(in) :: ml, mu, n, nl, nu
real, intent(in) :: a(ka,*), b(kb,*)
real, intent(inout) :: c(kc,l)
integer :: i, imin, j, ja, jb, jc, jmax, la, lb, num, nswc_ai_i4
!-----------------------------------------------------------------------
!                 Addition of real banded matrices
!-----------------------------------------------------------------------
!
ierr = 0
nswc_ai_i4 = nl - ml
if ( nswc_ai_i4 < 0 ) go to 10
if ( nswc_ai_i4 == 0 ) go to 30
go to 20
!
!     Insert the first abs(ml - nl) diagonals
!
10 mcl = ml
if (ml >= l) go to 50
ja = ml - nl
jb = 0
jc = ja
jmax = nl + 1
do j = 1,jc
   do i = 1,m
11    c(i,j) = a(i,j)
   end do
end do
go to 50
!
20 mcl = nl
if (nl >= l) go to 50
ja = 0
jb = nl - ml
jc = jb
jmax = ml + 1
do j = 1,jc
   do i = 1,m
21    c(i,j) = b(i,j)
   end do
end do
go to 50
!
!     COMPUTE mcl WHEN ml = nl
!
30 mcl = ml
if (ml == 0) go to 40
imin = ml + 1
do j = 1,ml
   do i = imin,m
      if ((a(i,j) + b(i,j)) /= 0.0) go to 40
   end do
   mcl = mcl - 1
   imin = imin - 1
end do
!
40 ja = ml - mcl
jb = ja
jc = 0
jmax = mcl + 1
!
50 nswc_ai_i4 = nu - mu
if ( nswc_ai_i4 < 0 ) go to 100
if ( nswc_ai_i4 == 0 ) go to 160
go to 130
!
!     Insertion of the remaining diagonals when mu .NE. nu
!
100 mcu = mu
num = mcl + mcu + 1
if (num > l) go to 200
!
jmax = jmax + nu
do j = 1,jmax
   ja = ja + 1
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = a(i,ja) + b(i,jb)
   end do
end do
!
jmax = mu - nu
do j = 1,jmax
   ja = ja + 1
   jc = jc + 1
   do i = 1,m
120   c(i,jc) = a(i,ja)
   end do
end do
return
!
130 mcu = nu
num = mcl + mcu + 1
if (num > l) go to 200
!
jmax = jmax + mu
do j = 1,jmax
   ja = ja + 1
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = a(i,ja) + b(i,jb)
   end do
end do
!
jmax = nu - mu
do j = 1,jmax
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
150   c(i,jc) = b(i,jb)
   end do
end do
return
!
!     Compute mcu when mu = nu
!
160 mcu = mu
if (mu == 0) go to 170
la = ml + mu + 1
lb = nl + nu + 1
do j = 1,mu
   do i = 1,m
      if ((a(i,la) + b(i,lb)) /= 0.0) go to 170
   end do
   mcu = mcu - 1
   la = la - 1
   lb = lb - 1
end do
!
!     Addition of the remaining columns when mu = nu
!
170 num = mcl + mcu + 1
if (num > l) go to 200
!
jmax = jmax + mcu
do j = 1,jmax
   ja = ja + 1
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = a(i,ja) + b(i,jb)
   end do
end do
return
!
!     Error return
!
200 ierr = num
end subroutine badd

