   do i = 1,m
11    c(i,j) = a(i,j)
   end do
end do
go to 50
!
20 mcl = nl
if (nl >= l) go to 50
ja = 0
jb = nl - ml
jc = jb
jmax = ml + 1
do j = 1,jc
   do i = 1,m
21    c(i,j) = -b(i,j)
   end do
end do
go to 50
!
!     COMPUTE mcl WHEN ml = nl
!
30 mcl = ml
if (ml == 0) go to 40
imin = ml + 1
do j = 1,ml
   do i = imin,m
      if ((a(i,j) - b(i,j)) /= (0.0,0.0)) go to 40
   end do
   mcl = mcl - 1
   imin = imin - 1
end do
!
40 ja = ml - mcl
jb = ja
jc = 0
jmax = mcl + 1
!
50 nswc_ai_i4 = nu - mu
if ( nswc_ai_i4 < 0 ) go to 100
if ( nswc_ai_i4 == 0 ) go to 160
go to 130
!
!     Insertion of the remaining diagonals when mu .NE. nu
!
100 mcu = mu
num = mcl + mcu + 1
if (num > l) go to 200
!
jmax = jmax + nu
do j = 1,jmax
   ja = ja + 1
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = a(i,ja) - b(i,jb)
   end do
end do
!
jmax = mu - nu
do j = 1,jmax
   ja = ja + 1
   jc = jc + 1
   do i = 1,m
120   c(i,jc) = a(i,ja)
   end do
end do
return
!
130 mcu = nu
num = mcl + mcu + 1
if (num > l) go to 200
!
jmax = jmax + mu
do j = 1,jmax
   ja = ja + 1
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = a(i,ja) - b(i,jb)
   end do
end do
!
jmax = nu - mu
do j = 1,jmax
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
150   c(i,jc) = -b(i,jb)
   end do
end do
return
!
!     Compute mcu when mu = nu
!
160 mcu = mu
if (mu == 0) go to 170
la = ml + mu + 1
lb = nl + nu + 1
do j = 1,mu
   do i = 1,m
      if ((a(i,la) - b(i,lb)) /= (0.0,0.0)) go to 170
   end do
   mcu = mcu - 1
   la = la - 1
   lb = lb - 1
end do
!
!     Addition of the remaining columns when mu = nu
!
170 num = mcl + mcu + 1
if (num > l) go to 200
!
jmax = jmax + mcu
do j = 1,jmax
   ja = ja + 1
   jb = jb + 1
   jc = jc + 1
   do i = 1,m
      c(i,jc) = a(i,ja) - b(i,jb)
   end do
end do
return
!
!     Error return
!
200 ierr = num
end subroutine cbsubt

pure subroutine bprod(m, n, l, a, ka, ml, mu, b, kb, nl, nu, &
   & c, kc, nc, mcl, mcu, ierr)
implicit none
integer, intent(out) :: ierr
integer, intent(in) :: ka, kb, kc, l, m
integer, intent(inout) :: mcl, mcu
integer, intent(in) :: ml, mu, n, nc, nl, nu
real, intent(in) :: a(ka,*), b(kb,*)
real, intent(inout) :: c(kc,nc)
integer :: i, imax, imj, j, jc, jj, jmax, jmi, k, kk, kmax, kmin, &
   & last, maxd, mind, mlp1, ndiag, nlp1, npml, npnu
real :: sum
!-----------------------------------------------------------------------
!                Multiplication of real banded matrices
!-----------------------------------------------------------------------
!
ierr = 0
do j = 1,nc
   do i = 1,m
10    c(i,j) = 0.0
   end do
end do
!
mlp1 = ml + 1
nlp1 = nl + 1
npml = n + ml
npnu = n + nu
mcl = min(m - 1,ml + nl)
jc = 0
if (mcl == 0) go to 100
!
!     Find the first nonzero lower diagonal
!
maxd = mcl
do ndiag = 1,maxd
   imj = maxd + 1 - ndiag
   jmax = min(l,m - imj,npml - imj,npnu)
   do j = 1,jmax
      i = j + imj
      sum = 0.0
      kmin = max(1,i - ml,j - nu)
      kmax = min(n,i + mu,j + nl)
      kk = mlp1 - i + kmin
      jj = nlp1 + j - kmin
      do k = kmin,kmax
         sum = sum + a(i,kk)*b(k,jj)
         kk = kk + 1
         jj = jj - 1
      end do
      c(i,1) = sum
   end do
!
   do j = 1,jmax
      i = j + imj
      if (c(i,1) /= 0.0) go to 40
   end do
   mcl = mcl - 1
end do
go to 100
!
40 if (mcl >= nc) go to 100
jc = 1
if (mcl == 1) go to 100
!
!     Compute the remaining lower diagonals
!
mind = ndiag + 1
do ndiag = mind,maxd
   jc = jc + 1
   imj = maxd + 1 - ndiag
   jmax = min(l,m - imj,npml - imj,npnu)
   do j = 1,jmax
      i = j + imj
      sum = 0.0
      kmin = max(1,i - ml,j - nu)
      kmax = min(n,i + mu,j + nl)
      kk = mlp1 - i + kmin
      jj = nlp1 + j - kmin
      do k = kmin,kmax
         sum = sum + a(i,kk)*b(k,jj)
         kk = kk + 1
         jj = jj - 1
      end do
      c(i,jc) = sum
   end do
end do
!
!     Find the last nonzero upper diagonal
!
100 jc = jc + 1
mcu = min(l - 1,mu + nu)
if (mcu == 0) go to 130
!
maxd = mcu
do ndiag = 1,maxd
   jmi = maxd + 1 - ndiag
   imax = min(m,l - jmi,npml,npnu - jmi)
   do i = 1,imax
      j = i + jmi
      sum = 0.0
      kmin = max(1,i - ml,j - nu)
      kmax = min(n,i + mu,j + nl)
      kk = mlp1 - i + kmin
      jj = nlp1 + j - kmin
      do k = kmin,kmax
         sum = sum + a(i,kk)*b(k,jj)
         kk = kk + 1
         jj = jj - 1
      end do
      c(i,jc) = sum
   end do
!
   do i = 1,imax
      if (c(i,jc) /= 0.0) go to 130
   end do
   mcu = mcu - 1
end do
!
130 last = mcl + mcu + 1
if (last > nc) go to 200
if (mcu == 0) go to 140
do i = 1,imax
   c(i,last) = c(i,jc)
   c(i,jc) = 0.0
end do
!
!     Compute the main diagonal and the remaining upper diagonals
!
140 maxd = max(1,mcu)
do ndiag = 1,maxd
   jmi = ndiag - 1
   imax = min(m,l - jmi,npml,npnu - jmi)
   do i = 1,imax
      j = i + jmi
      sum = 0.0
      kmin = max(1,i - ml,j - nu)
      kmax = min(n,i + mu,j + nl)
      kk = mlp1 - i + kmin
      jj = nlp1 + j - kmin
      do k = kmin,kmax
         sum = sum + a(i,kk)*b(k,jj)
         kk = kk + 1
         jj = jj - 1
      end do
      c(i,jc) = sum
   end do
   jc = jc + 1
end do
return
!
!     Error return
!
200 ierr = last
end subroutine bprod

