real :: sum
!-----------------------------------------------------------------------
!        Setting y = a*x + y where A is a real banded matrix
!                     and x,y are real vectors
!-----------------------------------------------------------------------
!
!     Compute the first ml components
!
mlp1 = ml + 1
if (ml == 0) go to 20
jmin = mlp1
do i = 1,ml
   kmax = min(n,i + mu)
   kk = jmin
   sum = y(i)
   do k = 1,kmax
      sum = sum + a(i,kk)*x(k)
      kk = kk + 1
   end do
   y(i) = sum
   jmin = jmin - 1
end do
!
!     Compute the remaining components
!
20 imax = min(m,n + ml)
do i = mlp1,imax
   kmin = i - ml
   kmax = min(n,i + mu)
   kk = 1
   sum = y(i)
   do k = kmin,kmax
      sum = sum + a(i,kk)*x(k)
      kk = kk + 1
   end do
   y(i) = sum
end do
end subroutine bvprd1

