complex, intent(in) :: a(ka,*), x(n)
complex, intent(inout) :: y(m)
integer :: i, imax, imin, jmin, k, kk, kmax, kmin, mlp1
complex :: sum
!-----------------------------------------------------------------------
!        Product of a complex banded matrix and a complex vector
!-----------------------------------------------------------------------
!
!     Compute the first ml components
