      kk = kk + 1
   end do
   y(i) = sum
   jmin = jmin - 1
end do
!
!     Compute the remaining nonzero components
!
20 imax = min(m,n + ml)
do i = mlp1,imax
   kmin = i - ml
   kmax = min(n,i + mu)
   kk = 1
   sum = (0.0,0.0)
   do k = kmin,kmax
      sum = sum + a(i,kk)*x(k)
      kk = kk + 1
   end do
   y(i) = sum
end do
!
!     Store zeros in the final m-imax components
!
if (imax == m) return
imin = imax + 1
do i = imin,m
   y(i) = (0.0,0.0)
end do
end subroutine cbvpd

