   pure subroutine snbsl(a,lda,n,ml,mu,ipvt,b,job)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: lda
      real, intent(in) :: a(lda,*)
      integer, intent(in) :: ml
      integer, intent(in) :: mu
      integer, intent(in) :: ipvt(n)
      real, intent(inout) :: b(n)
