subroutine csreal(a, ia, ja, b, ib, jb, m)
implicit none
integer, intent(in) :: m
complex, intent(in) :: a(*)
real, intent(inout) :: b(*)
integer, intent(in) :: ia(*), ja(*)
integer, intent(inout) :: ib(*), jb(*)
integer :: i, ibeg, iend, ip, l
real :: t
!-----------------------------------------------------------------------
!              Real part of a sparse complex matrix
!-----------------------------------------------------------------------
!
l = 1
do i = 1,m
   ib(i) = l
   ibeg = ia(i)
   iend = ia(i + 1) - 1
   if (ibeg > iend) go to 20
   do ip = ibeg,iend
      t = real(a(ip))
      if (t == 0.0) go to 10
      b(l) = t
      jb(l) = ja(ip)
      l = l + 1
10    continue
   end do
20 continue
end do
ib(m + 1) = l
end subroutine csreal

