integer, intent(in) :: ia(*), ja(*)
integer, intent(inout) :: ib(*), jb(*)
integer :: i, ibeg, iend, ip, l
real :: t
!-----------------------------------------------------------------------
!            Imaginary part of a sparse complex matrix
!-----------------------------------------------------------------------
!
l = 1
do i = 1,m
   ib(i) = l
   ibeg = ia(i)
   iend = ia(i + 1) - 1
   if (ibeg > iend) go to 20
   do ip = ibeg,iend
      t = aimag(a(ip))
      if (t == 0.0) go to 10
      b(l) = t
      jb(l) = ja(ip)
      l = l + 1
10    continue
   end do
20 continue
end do
ib(m + 1) = l
end subroutine csimag

subroutine scvrc(a,ia,ja,b,ib,jb,c,ic,jc,m,n,num,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: m, n, num
real, intent(in) :: a(*), b(*)
real, intent(inout) :: wk(n)
complex, intent(inout) :: c(*)
integer, intent(in) :: ia(*), ja(*), ib(*), jb(*)
integer, intent(inout) :: ic(*), jc(*)
integer :: i, ip, j, l, maxa, maxb, mina, minb
complex :: t
!-----------------------------------------------------------------------
!       Compute a + bi for the sparse real matrices A and b
!-----------------------------------------------------------------------
!-------------------------
do j = 1,n
   wk(j) = 0.0
end do
!
!                  Compute the i-TH row of c
!
ip = 1
do i = 1,m
   ic(i) = ip
   mina = ia(i)
   maxa = ia(i + 1) - 1
   if (mina > maxa) go to 30
   do l = mina,maxa
      j = ja(l)
      wk(j) = a(l)
   end do
!
30 minb = ib(i)
   maxb = ib(i + 1) - 1
   if (minb > maxb) go to 40
   do l = minb,maxb
      if (b(l) == 0.0) go to 31
      j = jb(l)
      t = cmplx (wk(j), b(l))
      wk(j) = 0.0
      if (ip > num) go to 50
      c(ip) = t
      jc(ip) = j
      ip = ip + 1
31    continue
   end do
!
40 if (mina > maxa) go to 42
   do l = mina,maxa
      j = ja(l)
      if (wk(j) == 0.0) go to 41
      if (ip > num) go to 50
      c(ip) = cmplx (wk(j), 0.0)
      wk(j) = 0.0
      jc(ip) = j
      ip = ip + 1
41    continue
   end do
42 continue
end do
ic(m + 1) = ip
ierr = 0
return
!
!                        Error return
!
50 ierr = i
end subroutine scvrc

