do ip = ipmin,ipmax
   j = ja(ip)
   ib(j) = ib(j) + 1
end do
!
!          Compute the row pointers of the transpose matrix
!                and store them in ib(2),...,ib(n+1)
!
num = ia(m + 1) - ia(1) + 1
j = n
do jj = 1,n
   num = num - ib(j)
   ib(j + 1) = num
   j = j - 1
end do
!
!                Store the i-TH row of A in b and jb
!                  and update the pointers in ib
!
do i = 1,m
   ii = p(i)
   ipmin = ia(ii)
   ipmax = ia(ii + 1) - 1
   if (ipmin > ipmax) go to 31
   do ip = ipmin,ipmax
      j = ja(ip)
      jp = ib(j + 1)
      jb(jp) = i
      b(jp) = a(ip)
      ib(j + 1) = jp + 1
   end do
31 continue
end do
ib(1) = 1
return
!
!                    Transpose a zero matrix a
!
40 np1 = n + 1
do j = 1,np1
   ib(j) = 1
end do
end subroutine dpose1

