subroutine sadd(a,ia,ja,b,ib,jb,c,ic,jc,m,n,num,wk,ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: m, n, num
real, intent(in) :: a(*), b(*)
real, intent(inout) :: c(*), wk(n)
integer, intent(in) :: ia(*), ja(*), ib(*), jb(*)
integer, intent(inout) :: ic(*), jc(*)
integer :: i, ip, j, l, maxa, maxb, mina, minb
real :: t
!-----------------------------------------------------------------------
!               Addition of sparse real matrices
!-----------------------------------------------------------------------
!-------------------------
do j = 1,n
   wk(j) = 0.0
end do
!
!                  Compute the i-TH row of c
!
ip = 1
do i = 1,m
   ic(i) = ip
   mina = ia(i)
   maxa = ia(i + 1) - 1
   if (mina > maxa) go to 30
   do l = mina,maxa
      j = ja(l)
      wk(j) = a(l)
   end do
!
30 minb = ib(i)
   maxb = ib(i + 1) - 1
   if (minb > maxb) go to 40
   do l = minb,maxb
      j = jb(l)
      t = wk(j) + b(l)
      wk(j) = 0.0
      if (t == 0.0) go to 31
      if (ip > num) go to 50
      c(ip) = t
      jc(ip) = j
      ip = ip + 1
31    continue
   end do
!
40 if (mina > maxa) go to 42
   do l = mina,maxa
      j = ja(l)
      if (wk(j) == 0.0) go to 41
      if (ip > num) go to 50
      c(ip) = wk(j)
      wk(j) = 0.0
      jc(ip) = j
      ip = ip + 1
41    continue
   end do
42 continue
end do
ic(m + 1) = ip
ierr = 0
return
!
!                        Error return
!
50 ierr = i
end subroutine sadd

