real, intent(inout) :: y(m)
integer, intent(in) :: ia(*), ja(*)
integer :: i, j, l, lmax, lmin
real :: sum
!-----------------------------------------------------------------------
!     Set y = a*x + y where A is a sparse matrix and x,y are vectors
!-----------------------------------------------------------------------
!
do i = 1,m
   sum = y(i)
   lmin = ia(i)
   lmax = ia(i + 1) - 1
   if (lmin > lmax) go to 11
   do l = lmin,lmax
      j = ja(l)
      sum = sum + a(l)*x(j)
   end do
11 y(i) = sum
end do
end subroutine mvprd1

subroutine mtprd(m, n, a, ia, ja, x, y)
implicit none
