!
do i = 1,m
   t = x(i)
   lmin = ia(i)
   lmax = ia(i + 1) - 1
   if (lmin > lmax) go to 21
   do l = lmin,lmax
      j = ja(l)
      y(j) = y(j) + t*a(l)
   end do
21 continue
end do
end subroutine mtprd

