      real, intent(inout) :: a(nm,n)
      integer, intent(inout) :: low
      integer, intent(inout) :: igh
      real, intent(inout) :: scale(n)
   end subroutine balanc
   pure subroutine hqr(nm,n,low,igh,h,wr,wi,ierr)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      integer, intent(in) :: igh
      real, intent(inout) :: h(nm,n)
      real, intent(inout) :: wr(n)
      real, intent(inout) :: wi(n)
      integer, intent(out) :: ierr
   end subroutine hqr
   pure subroutine orthes(nm,n,low,igh,a,ort)
      implicit none
      integer, intent(in) :: igh
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      real, intent(inout) :: a(nm,n)
      real, intent(inout) :: ort(igh)
   end subroutine orthes
end interface
!-----------------------------------------------------------------------
!                    Eigenvalues of real matrices
!-----------------------------------------------------------------------
!
low = 1
igh = n
if (ibal /= 0) call balanc(ka,n,a,low,igh,wr)
call orthes(ka,n,low,igh,a,wr)
call hqr(ka,n,low,igh,a,wr,wi,ierr)
end subroutine eig1

pure subroutine eigv(ibal,a,ka,n,wr,wi,zr,zi,ierr)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
real, intent(inout) :: a(ka,n), wr(n), wi(n), zr(ka,n), zi(ka,n)
integer :: igh, j, k, kp1, low
real :: nswc_ai_r4
interface
   pure subroutine balanc(nm,n,a,low,igh,scale)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      real, intent(inout) :: a(nm,n)
      integer, intent(inout) :: low
      integer, intent(inout) :: igh
      real, intent(inout) :: scale(n)
   end subroutine balanc
   pure subroutine balbak(nm,n,low,igh,scale,m,z)
      implicit none
      integer, intent(in) :: m
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      integer, intent(in) :: igh
      real, intent(in) :: scale(n)
      real, intent(inout) :: z(nm,m)
   end subroutine balbak
   pure subroutine elmhs0(nm,n,low,igh,a,int)
      implicit none
      integer, intent(in) :: igh
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      real, intent(inout) :: a(nm,n)
      real, intent(inout) :: int(igh)
   end subroutine elmhs0
   pure subroutine eltrn0(nm,n,low,igh,a,int,z)
      implicit none
      integer, intent(in) :: igh
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      real, intent(in) :: a(nm,igh)
      real, intent(in) :: int(igh)
      real, intent(inout) :: z(nm,n)
   end subroutine eltrn0
   pure subroutine hqr2(nm,n,low,igh,h,wr,wi,z,ierr)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      integer, intent(in) :: igh
      real, intent(inout) :: h(nm,n)
      real, intent(inout) :: wr(n)
      real, intent(inout) :: wi(n)
      real, intent(inout) :: z(nm,n)
      integer, intent(out) :: ierr
   end subroutine hqr2
end interface
!-----------------------------------------------------------------------
!           Eigenvalues and eigenvectors of real matrices
!-----------------------------------------------------------------------
!
low = 1
igh = n
if (ibal /= 0) call balanc(ka,n,a,low,igh,zi)
call elmhs0(ka,n,low,igh,a,wr)
call eltrn0(ka,n,low,igh,a,wr,zr)
call hqr2(ka,n,low,igh,a,wr,wi,zr,ierr)
if (ierr /= 0) return
if (ibal /= 0) call balbak(ka,n,low,igh,zi,n,zr)
!
do k = 1,n
   nswc_ai_r4 = wi ( k )
   if ( nswc_ai_r4 < 0 ) go to 30
   if ( nswc_ai_r4 == 0 ) go to 10
   go to 20
10 do j = 1,n
11    zi(j,k) = 0.0
   end do
   go to 30
20 kp1 = k + 1
   do j = 1,n
      zi(j,k) = zr(j,kp1)
      zr(j,kp1) = zr(j,k)
21    zi(j,kp1) = -zi(j,k)
   end do
30 continue
end do
end subroutine eigv

pure subroutine eigv1(ibal,a,ka,n,wr,wi,zr,zi,ierr)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
real, intent(inout) :: a(ka,n), wr(n), wi(n), zr(ka,n), zi(ka,n)
integer :: igh, j, k, kp1, low
real :: nswc_ai_r4
interface
   pure subroutine balanc(nm,n,a,low,igh,scale)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      real, intent(inout) :: a(nm,n)
      integer, intent(inout) :: low
      integer, intent(inout) :: igh
      real, intent(inout) :: scale(n)
   end subroutine balanc
   pure subroutine balbak(nm,n,low,igh,scale,m,z)
      implicit none
      integer, intent(in) :: m
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      integer, intent(in) :: igh
      real, intent(in) :: scale(n)
      real, intent(inout) :: z(nm,m)
   end subroutine balbak
   pure subroutine hqr2(nm,n,low,igh,h,wr,wi,z,ierr)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      integer, intent(in) :: igh
      real, intent(inout) :: h(nm,n)
      real, intent(inout) :: wr(n)
      real, intent(inout) :: wi(n)
      real, intent(inout) :: z(nm,n)
      integer, intent(out) :: ierr
   end subroutine hqr2
   pure subroutine orthes(nm,n,low,igh,a,ort)
      implicit none
      integer, intent(in) :: igh
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      real, intent(inout) :: a(nm,n)
      real, intent(inout) :: ort(igh)
   end subroutine orthes
   pure subroutine ortran(nm,n,low,igh,a,ort,z)
      implicit none
      integer, intent(in) :: igh
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      real, intent(in) :: a(nm,igh)
      real, intent(inout) :: ort(igh)
      real, intent(inout) :: z(nm,n)
   end subroutine ortran
end interface
!-----------------------------------------------------------------------
!           Eigenvalues and eigenvectors of real matrices
!-----------------------------------------------------------------------
!
low = 1
igh = n
if (ibal /= 0) call balanc(ka,n,a,low,igh,zi)
call orthes(ka,n,low,igh,a,wr)
call ortran(ka,n,low,igh,a,wr,zr)
call hqr2(ka,n,low,igh,a,wr,wi,zr,ierr)
if (ierr /= 0) return
if (ibal /= 0) call balbak(ka,n,low,igh,zi,n,zr)
!
do k = 1,n
   nswc_ai_r4 = wi ( k )
   if ( nswc_ai_r4 < 0 ) go to 30
   if ( nswc_ai_r4 == 0 ) go to 10
   go to 20
10 do j = 1,n
11    zi(j,k) = 0.0
   end do
   go to 30
20 kp1 = k + 1
   do j = 1,n
      zi(j,k) = zr(j,kp1)
      zr(j,kp1) = zr(j,k)
21    zi(j,kp1) = -zi(j,k)
   end do
30 continue
end do
end subroutine eigv1

pure subroutine balanc(nm,n,a,low,igh,scale)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm
integer, intent(inout) :: igh, low
real, intent(inout) :: a(nm,n), scale(n)
integer :: i, j, k, l, m, jj, iexc
real :: c, f, g, r, s, b2, radix
logical :: noconv
interface
   pure elemental function ipmpar(i)
      implicit none
      integer, intent(in) :: i
      integer :: ipmpar
   end function ipmpar
end interface
!     real abs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure balance,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.II-linear algebra, 315-326(1971).
!
!     This subroutine balances a real matrix and isolates
!     eigenvalues whenever possible.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        A contains the input matrix to be balanced.
!
!     On output-
!
!        A contains the balanced matrix,
!
!        Low and igh are two integers such that a(i,j)
!          is equal to zero if
!           (1) i is greater than j and
!           (2) j=1,...,low-1 OR i=igh+1,...,n,
!
!        Scale contains information determining the
!           permutations and scaling factors used.
!
!     Suppose that the principal submatrix in rows low through igh
!     has been balanced, that P(j) denotes the index interchanged
!     with j during the permutation step, and that the elements
!     of the diagonal matrix used are denoted by D(i,j).  Then
!        scale(j) = P(j),    FOR j = 1,...,low-1
!                 = D(j,j),      j = low,...,igh
!                 = P(j)         j = igh+1,...,n.
!     The order in which the interchanges are made is n to igh+1,
!     then 1 to low-1.
!
!     Note that 1 is returned for igh if igh is zero formally.
!
!     The Algol procedure exc contained in balance appears in
!     balanc  in line.  (Note that the Algol roles of identifiers
!     k,l have been reversed.)
!
!-----------------------------------------------------------------------
!
!     ********** radix is a machine dependent parameter specifying
!                the base of the machine floating point representation.
!
radix = ipmpar(4)
!
!                **********
!
b2 = radix * radix
k = 1
l = n
go to 100
!     ********** In-line procedure for row and
!                column exchange **********
20 scale(m) = j
if (j == m) go to 50
!
do i = 1, l
   f = a(i,j)
   a(i,j) = a(i,m)
   a(i,m) = f
end do
!
do i = k, n
   f = a(j,i)
   a(j,i) = a(m,i)
   a(m,i) = f
end do
!
50 go to (80,130), iexc
!     ********** Search for rows isolating an eigenvalue
!                and push them down **********
80 if (l == 1) go to 280
l = l - 1
!     ********** FOR j=l STEP -1 UNTIL 1 DO -- **********
100 do jj = 1, l
   j = l + 1 - jj
!
   do i = 1, l
      if (i == j) go to 110
      if (a(j,i) /= 0.0) go to 120
110   continue
   end do
!
   m = l
   iexc = 1
   go to 20
120 continue
end do
!
go to 140
!     ********** Search for columns isolating an eigenvalue
!                and push them left **********
130 k = k + 1
!
140 do j = k, l
!
   do i = k, l
      if (i == j) go to 150
      if (a(i,j) /= 0.0) go to 170
150   continue
   end do
!
   m = k
   iexc = 2
   go to 20
170 continue
end do
!     ********** Now balance the submatrix in rows k to l **********
do i = k, l
180 scale(i) = 1.0
end do
!     ********** Iterative loop for norm reduction **********
190 noconv = .false.
!
do i = k, l
   c = 0.0
   r = 0.0
!
   do j = k, l
      if (j == i) go to 200
      c = c + abs(a(j,i))
      r = r + abs(a(i,j))
200   continue
   end do
!     ********** Guard against zero c or r due to underflow **********
   if (c == 0.0 .or. r == 0.0) go to 270
   g = r / radix
   f = 1.0
   s = c + r
210 if (c >= g) go to 220
   f = f * radix
   c = c * b2
   go to 210
220 g = r * radix
230 if (c < g) go to 240
   f = f / radix
   c = c / b2
   go to 230
!     ********** Now balance **********
240 if ((c + r) / f >= 0.95 * s) go to 270
   g = 1.0 / f
   scale(i) = scale(i) * f
   noconv = .true.
!
   do j = k, n
250   a(i,j) = a(i,j) * g
   end do
!
   do j = 1, l
260   a(j,i) = a(j,i) * f
   end do
!
270 continue
end do
!
if (noconv) go to 190
!
280 low = k
igh = l
end subroutine balanc

pure subroutine balinv(nz,n,z,low,igh,scale)
implicit none
integer, intent(in) :: n
integer, intent(in) :: nz, igh, low
real, intent(inout) :: z(nz,n)
real, intent(in) :: scale(n)
integer :: i, j, k, ii
real :: s
!-----------------------------------------------------------------------
!        Given A matrix A of order n. balanc transforms A into
!     the matrix B by the similarity transformation
!             b = d**(-1)*transpose(p)*a*p*d
!     where D is a diagonal matrix and P a permutation matrix.
!     The information concerning D and P is stored in igh, low,
!     and scale. The order in which the interchanges were made
!     is n to igh + 1, and then 1 to low - 1.
!
!        z is a matrix of order n. balinv transforms z into the
!     matrix W using the inverse similarity transform
!             w = p*d*z*d**(-1)*transpose(p)
!
!     On input-
!
!        nz is the row dimension of the matrix z in the calling
!          program,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by  balanc,
!
!        Scale contains information determining the permutations
!          and scaling factors used by  balanc,
!
!     On output-
!
!        z contains the transformed matrix W
!
!-----------------------------------------------------------------------
!
if (igh == low) go to 30
!
do i = low, igh
   s = scale(i)
   do j = 1, n
10    z(i,j) = z(i,j) * s
   end do
end do
!
do j = low, igh
   s = 1.0/scale(j)
   do i = 1, n
20    z(i,j) = z(i,j) * s
   end do
end do
!
!     ********- FOR i=low-1 STEP -1 UNTIL 1,
!               igh+1 STEP 1 UNTIL n DO -- **********
!
30 do ii = 1, n
   i = ii
   if (i >= low .and. i <= igh) go to 60
   if (i < low) i = low - ii
   k = scale(i)
   if (k == i) go to 60
!
   do j = 1, n
      s = z(i,j)
      z(i,j) = z(k,j)
40    z(k,j) = s
   end do
!
   do j = 1, n
      s = z(j,i)
      z(j,i) = z(j,k)
50    z(j,k) = s
   end do
60 continue
end do
end subroutine balinv

pure subroutine elmhes(nm,n,low,igh,a,int)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh
integer, intent(in) :: low
real, intent(inout) :: a(nm,n)
integer, intent(inout) :: int(igh)
integer :: i, j, m, la, kp1, mm1, mp1
real :: x, y
!     real abs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure elmhes,
!     NUM. Math. 12, 349-368(1968) By Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 339-358(1971).
!
!     Given a real general matrix, this subroutine
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     stabilized elementary similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n,
!
!        A contains the input matrix.
!
!     On output-
!
!        A contains the Hessenberg matrix.  The multipliers
!          which were used in the reduction are stored in the
!          remaining triangle under the Hessenberg matrix,
!
!        Int contains information on the rows and columns
!          interchanged in the reduction.
!          Only elements low through igh are used.
!
!-----------------------------------------------------------------------
!
la = igh - 1
kp1 = low + 1
if (la < kp1) go to 200
!
do m = kp1, la
   mm1 = m - 1
   x = 0.0
   i = m
!
   do j = m, igh
      if (abs(a(j,mm1)) <= abs(x)) go to 100
      x = a(j,mm1)
      i = j
100   continue
   end do
!
   int(m) = i
   if (i == m) go to 130
!    ********** Interchange rows and columns of a **********
   do j = mm1, n
      y = a(i,j)
      a(i,j) = a(m,j)
      a(m,j) = y
   end do
!
   do j = 1, igh
      y = a(j,i)
      a(j,i) = a(j,m)
      a(j,m) = y
   end do
!    ********** End interchange **********
130 if (x == 0.0) go to 180
   mp1 = m + 1
!
   do i = mp1, igh
      y = a(i,mm1)
      if (y == 0.0) go to 160
      y = y / x
      a(i,mm1) = y
!
      do j = m, n
140      a(i,j) = a(i,j) - y * a(m,j)
      end do
!
      do j = 1, igh
150      a(j,m) = a(j,m) + y * a(j,i)
      end do
!
160   continue
   end do
!
180 continue
end do
!
200 return
end subroutine elmhes

pure subroutine elmhs0(nm,n,low,igh,a,int)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh
integer, intent(in) :: low
real, intent(inout) :: a(nm,n)
real, intent(inout) :: int(igh)
integer :: i, j, m, la, kp1, mm1, mp1
real :: x, y
!     real abs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure elmhes,
!     NUM. Math. 12, 349-368(1968) By Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 339-358(1971).
!
!     Given a real general matrix, this subroutine
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     stabilized elementary similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n,
!
!        A contains the input matrix.
!
!     On output-
!
!        A contains the Hessenberg matrix.  The multipliers
!          which were used in the reduction are stored in the
!          remaining triangle under the Hessenberg matrix,
!
!        Int contains information on the rows and columns
!          interchanged in the reduction.
!          Only elements low through igh are used.
!
!-----------------------------------------------------------------------
!
la = igh - 1
kp1 = low + 1
if (la < kp1) go to 200
!
do m = kp1, la
   mm1 = m - 1
   x = 0.0
   i = m
!
   do j = m, igh
      if (abs(a(j,mm1)) <= abs(x)) go to 100
      x = a(j,mm1)
      i = j
100   continue
   end do
!
   int(m) = i
   if (i == m) go to 130
!    ********** Interchange rows and columns of a **********
   do j = mm1, n
      y = a(i,j)
      a(i,j) = a(m,j)
      a(m,j) = y
   end do
!
   do j = 1, igh
      y = a(j,i)
      a(j,i) = a(j,m)
      a(j,m) = y
   end do
!    ********** End interchange **********
130 if (x == 0.0) go to 180
   mp1 = m + 1
!
   do i = mp1, igh
      y = a(i,mm1)
      if (y == 0.0) go to 160
      y = y / x
      a(i,mm1) = y
!
      do j = m, n
140      a(i,j) = a(i,j) - y * a(m,j)
      end do
!
      do j = 1, igh
150      a(j,m) = a(j,m) + y * a(j,i)
      end do
!
160   continue
   end do
!
180 continue
end do
!
200 return
end subroutine elmhs0

pure subroutine orthes(nm,n,low,igh,a,ort)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh
integer, intent(in) :: low
real, intent(inout) :: a(nm,n), ort(igh)
integer :: i, j, m, ii, jj, la, mp, kp1
real :: f, g, h, scale
!     real sqrt,abs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure orthes,
!     NUM. Math. 12, 349-368(1968) By Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 339-358(1971).
!
!     Given a real general matrix, this subroutine
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     orthogonal similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n,
!
!        A contains the input matrix.
!
!     On output-
!
!        A contains the Hessenberg matrix.  Information about
!          the orthogonal transformations used in the reduction
!          is stored in the remaining triangle under the
!          Hessenberg matrix,
!
!        Ort contains further information about the transformations.
!          Only elements low through igh are used.
!
!-----------------------------------------------------------------------
!
la = igh - 1
kp1 = low + 1
if (la < kp1) go to 200
!
do m = kp1, la
   h = 0.0
   ort(m) = 0.0
   scale = 0.0
!     ********** scale COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do i = m, igh
90    scale = scale + abs(a(i,m - 1))
   end do
!
   if (scale == 0.0) go to 180
   mp = m + igh
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
   do ii = m, igh
      i = mp - ii
      ort(i) = a(i,m - 1) / scale
      h = h + ort(i) * ort(i)
   end do
!
   g = sqrt(h)
   if (ort(m) >= 0.0) g = -g
   h = h - ort(m) * g
   ort(m) = ort(m) - g
!     ********** FORM (i-(U*UT)/h) * a **********
   do j = m, n
      f = 0.0
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
      do ii = m, igh
         i = mp - ii
         f = f + ort(i) * a(i,j)
      end do
!
      f = f / h
!
      do i = m, igh
120      a(i,j) = a(i,j) - f * ort(i)
      end do
!
   end do
!     ********** FORM (i-(U*UT)/h)*a*(i-(U*UT)/h) **********
   do i = 1, igh
      f = 0.0
!     ********** FOR j=igh STEP -1 UNTIL m DO -- **********
      do jj = m, igh
         j = mp - jj
         f = f + ort(j) * a(i,j)
      end do
!
      f = f / h
!
      do j = m, igh
150      a(i,j) = a(i,j) - f * ort(j)
      end do
!
   end do
!
   ort(m) = scale * ort(m)
   a(m,m - 1) = scale * g
180 continue
end do
!
200 return
end subroutine orthes

pure subroutine hqr(nm,n,low,igh,h,wr,wi,ierr)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh
integer, intent(in) :: low
integer, intent(out) :: ierr
real, intent(inout) :: h(nm,n), wr(n), wi(n)
integer :: i, j, k, l, m, en, ll, mm, na, its, mp2, enm2
real :: p, q, r, s, t, w, x, y, zz, norm, machep
logical :: notlas
interface
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!     real sqrt,abs
!     integer min0
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure hqr,
!     NUM. Math. 14, 219-231(1970) By Martin, peters, and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 359-371(1971).
!
!     This subroutine finds the eigenvalues of a real
!     upper Hessenberg matrix BY the QR method.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n,
!
!        h contains the upper Hessenberg matrix.  Information about
!          the transformations used in the reduction to Hessenberg
!          form by  elmhes  or  orthes, if performed, is stored
!          in the remaining triangle under the Hessenberg matrix.
!
!     On output-
!
!        h has been destroyed.  Therefore, it must be saved
!          before calling  hqr  if subsequent calculation and
!          back transformation of eigenvectors is to be performed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep is a machine dependent parameter. Assign
!                machep the value U where U is the smallest positive
!                floating point number such that 1.0 + U .GT. 1.0 .
!
machep = spmpar(1)
!
!                **********
!
ierr = 0
norm = 0.0
k = 1
!     ********** Store roots isolated by balanc
!                and compute matrix norm **********
do i = 1, n
!
   do j = k, n
40    norm = norm + abs(h(i,j))
   end do
!
   k = i
   if (i >= low .and. i <= igh) go to 50
   wr(i) = h(i,i)
   wi(i) = 0.0
50 continue
end do
!
en = igh
t = 0.0
!     ********** Search for next eigenvalues **********
60 if (en < low) go to 1001
its = 0
na = en - 1
enm2 = na - 1
!     ********** Look for single small sub-diagonal element
!                for l=en step -1 Until low do -- **********
70 do ll = low, en
   l = en + low - ll
   if (l == low) go to 100
   s = abs(h(l - 1,l - 1)) + abs(h(l,l))
   if (s == 0.0) s = norm
   if (abs(h(l,l - 1)) <= machep * s) go to 100
end do
!     ********** Form shift **********
100 x = h(en,en)
if (l == en) go to 270
y = h(na,na)
w = h(en,na) * h(na,en)
if (l == na) go to 280
if (its == 30) go to 1000
if (its /= 10 .and. its /= 20) go to 130
!     ********** Form exceptional shift **********
t = t + x
!
do i = low, en
120 h(i,i) = h(i,i) - x
end do
!
s = abs(h(en,na)) + abs(h(na,enm2))
x = 0.75 * s
y = x
w = -0.4375 * s * s
130 its = its + 1
!     ********** Look for two consecutive small
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l, enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r * s - w) / h(m + 1,m) + h(m,m + 1)
   q = h(m + 1,m + 1) - zz - r - s
   r = h(m + 2,m + 1)
   s = abs(p) + abs(q) + abs(r)
   p = p / s
   q = q / s
   r = r / s
   if (m == l) go to 150
   if (abs(h(m,m - 1)) * (abs(q) + abs(r)) <= machep * abs(p) &
      & * (abs(h(m - 1,m - 1)) + abs(zz) + abs(h(m + 1,m + 1)))) go to 150
end do
!
150 mp2 = m + 2
!
do i = mp2, en
   h(i,i - 2) = 0.0
   if (i == mp2) go to 160
   h(i,i - 3) = 0.0
160 continue
end do
!     ********** Double QR step involving rows l to en and
!                COLUMNS m TO en **********
do k = m, na
   notlas = k /= na
   if (k == m) go to 170
   p = h(k,k - 1)
   q = h(k + 1,k - 1)
   r = 0.0
   if (notlas) r = h(k + 2,k - 1)
   x = abs(p) + abs(q) + abs(r)
   if (x == 0.0) go to 260
   p = p / x
   q = q / x
   r = r / x
170 s = sqrt(p*p + q*q + r*r)
   if (p < 0.0) s = -s
   if (k == m) go to 180
   h(k,k - 1) = -s * x
   go to 190
180 if (l /= m) h(k,k - 1) = -h(k,k - 1)
190 p = p + s
   x = p / s
   y = q / s
   zz = r / s
   q = q / p
   r = r / p
!     ********** Row modification **********
   do j = k, en
      p = h(k,j) + q * h(k + 1,j)
      if (.not. notlas) go to 200
      p = p + r * h(k + 2,j)
      h(k + 2,j) = h(k + 2,j) - p * zz
200   h(k + 1,j) = h(k + 1,j) - p * y
      h(k,j) = h(k,j) - p * x
   end do
!
   j = min(en,k + 3)
!     ********** Column modification **********
   do i = l, j
      p = x * h(i,k) + y * h(i,k + 1)
      if (.not. notlas) go to 220
      p = p + zz * h(i,k + 2)
      h(i,k + 2) = h(i,k + 2) - p * r
220   h(i,k + 1) = h(i,k + 1) - p * q
      h(i,k) = h(i,k) - p
   end do
!
260 continue
end do
!
go to 70
!     ********** One root found **********
270 wr(en) = x + t
wi(en) = 0.0
en = na
go to 60
!     ********** Two roots found **********
280 p = (y - x) / 2.0
q = p * p + w
zz = sqrt(abs(q))
x = x + t
if (q < 0.0) go to 320
!     ********** Real pair **********
if (p < 0.0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz /= 0.0) wr(en) = x - w / zz
wi(na) = 0.0
wi(en) = 0.0
go to 330
!     ********** Complex pair **********
320 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
330 en = enm2
go to 60
!     ********** Set error -- no convergence to an
!                eigenvalue after 30 iterations **********
1000 ierr = en
1001 return
end subroutine hqr

pure subroutine balbak(nm,n,low,igh,scale,m,z)
implicit none
!
integer, intent(in) :: m, n
integer, intent(in) :: nm, igh, low
real, intent(in) :: scale(n)
real, intent(inout) :: z(nm,m)
integer :: i, j, k, ii
real :: s
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure balbak,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 315-326(1971).
!
!     This subroutine forms the eigenvectors of a real general
!     matrix BY back transforming those of the corresponding
!     balanced matrix determined by  balanc.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by  balanc,
!
!        Scale contains information determining the permutations
!          and scaling factors used by  balanc,
!
!        m is the number of columns of z to be back transformed,
!
!        z contains the real and imaginary parts of the eigen-
!          vectors to be back transformed in its first m columns.
!
!     On output-
!
!        z contains the real and imaginary parts of the
!          transformed eigenvectors in its first m columns.
!
!-----------------------------------------------------------------------
!
if (m == 0) go to 200
if (igh == low) go to 120
!
do i = low, igh
   s = scale(i)
!     ********** Left hand eigenvectors are back transformed
!                if the foregoing statement is replaced by
!                s=1.0/scale(i). **********
   do j = 1, m
100   z(i,j) = z(i,j) * s
   end do
!
end do
!     ********- FOR i=low-1 STEP -1 UNTIL 1,
!               igh+1 STEP 1 UNTIL n DO -- **********
120 do ii = 1, n
   i = ii
   if (i >= low .and. i <= igh) go to 140
   if (i < low) i = low - ii
   k = scale(i)
   if (k == i) go to 140
!
   do j = 1, m
      s = z(i,j)
      z(i,j) = z(k,j)
      z(k,j) = s
   end do
!
140 continue
end do
!
200 return
end subroutine balbak

pure subroutine eltran(nm,n,low,igh,a,int,z)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh, low
real, intent(in) :: a(nm,igh)
real, intent(inout) :: z(nm,n)
integer, intent(in) :: int(igh)
integer :: i, j, kl, mm, mp, mp1
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ELMTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the stabilized elementary
!     similarity transformations used in the reduction of A
!     real general matrix to upper Hessenberg form by  elmhes.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n,
!
!        A contains the multipliers which were used in the
!          reduction by  elmhes  in its lower triangle
!          below the subdiagonal,
!
!        Int contains information on the rows and columns
!          interchanged in the reduction by  elmhes.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by  elmhes.
!
!-----------------------------------------------------------------------
!
!     ********** Initialize z to identity matrix **********
do i = 1, n
!
   do j = 1, n
60    z(i,j) = 0.0
   end do
!
   z(i,i) = 1.0
end do
!
kl = igh - low - 1
if (kl < 1) go to 200
!     ********** For mp=igh-1 step -1 Until low+1 do -- **********
do mm = 1, kl
   mp = igh - mm
   mp1 = mp + 1
!
   do i = mp1, igh
100   z(i,mp) = a(i,mp - 1)
   end do
!
   i = int(mp)
   if (i == mp) go to 140
!
   do j = mp, igh
      z(mp,j) = z(i,j)
      z(i,j) = 0.0
   end do
!
   z(i,mp) = 1.0
140 continue
end do
!
200 return
end subroutine eltran

pure subroutine eltrn0(nm,n,low,igh,a,int,z)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh, low
real, intent(in) :: a(nm,igh)
real, intent(inout) :: z(nm,n)
real, intent(in) :: int(igh)
integer :: i, j, kl, mm, mp, mp1
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ELMTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the stabilized elementary
!     similarity transformations used in the reduction of A
!     real general matrix to upper Hessenberg form by  elmhs0.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n,
!
!        A contains the multipliers which were used in the
!          reduction by  elmhs0  in its lower triangle
!          below the subdiagonal,
!
!        Int contains information on the rows and columns
!          interchanged in the reduction by  elmhs0.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by  elmhs0.
!
!-----------------------------------------------------------------------
!
!     ********** Initialize z to identity matrix **********
do i = 1, n
!
   do j = 1, n
60    z(i,j) = 0.0
   end do
!
   z(i,i) = 1.0
end do
!
kl = igh - low - 1
if (kl < 1) go to 200
!     ********** For mp=igh-1 step -1 Until low+1 do -- **********
do mm = 1, kl
   mp = igh - mm
   mp1 = mp + 1
!
   do i = mp1, igh
100   z(i,mp) = a(i,mp - 1)
   end do
!
   i = int(mp)
   if (i == mp) go to 140
!
   do j = mp, igh
      z(mp,j) = z(i,j)
      z(i,j) = 0.0
   end do
!
   z(i,mp) = 1.0
140 continue
end do
!
200 return
end subroutine eltrn0

pure subroutine ortran(nm,n,low,igh,a,ort,z)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh, low
real, intent(in) :: a(nm,igh)
real, intent(inout) :: ort(igh), z(nm,n)
integer :: i, j, kl, mm, mp, mp1
real :: g
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ORTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the orthogonal similarity
!     transformations used in the reduction of a real general
!     matrix to upper Hessenberg form by  orthes.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n,
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction by  orthes
!          in its strict lower triangle,
!
!        Ort contains further information about the trans-
!          formations used in the reduction by  orthes.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by  orthes,
!
!        Ort has been altered.
!
!-----------------------------------------------------------------------
!
!     ********** Initialize z to identity matrix **********
do i = 1, n
!
   do j = 1, n
60    z(i,j) = 0.0
   end do
!
   z(i,i) = 1.0
end do
!
kl = igh - low - 1
if (kl < 1) go to 200
!     ********** For mp=igh-1 step -1 Until low+1 do -- **********
do mm = 1, kl
   mp = igh - mm
   if (a(mp,mp - 1) == 0.0) go to 140
   mp1 = mp + 1
!
   do i = mp1, igh
100   ort(i) = a(i,mp - 1)
   end do
!
   do j = mp, igh
      g = 0.0
!
      do i = mp, igh
110      g = g + ort(i) * z(i,j)
      end do
!     ********** Divisor below is negative of H formed in orthes.
!                Double division avoids possible underflow **********
      g = (g / ort(mp)) / a(mp,mp - 1)
!
      do i = mp, igh
120      z(i,j) = z(i,j) + g * ort(i)
      end do
!
   end do
!
140 continue
end do
!
200 return
end subroutine ortran

pure subroutine ortrn1(n,low,igh,a,na,z,nz,ort)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: na, igh, low
integer, intent(in) :: nz
real, intent(in) :: a(na,igh)
real, intent(inout) :: ort(igh), z(nz,n)
integer :: i, j, kl, mm, mp, mp1
real :: g
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ORTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the orthogonal similarity
!     transformations used in the reduction of a real general
!     matrix to upper Hessenberg form by  orthes.
!
!     On input-
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n,
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction by  orthes
!          in its strict lower triangle,
!
!        na must be set to the row dimension of the 2-dimensional
!          array parameter  a  as declared in the calling program
!          dimension statement,
!
!        nz must be set to the row dimension of the 2-dimensional
!          array parameter  z  as declared in the calling program
!          dimension statement,
!
!        Ort contains further information about the trans-
!          formations used in the reduction by  orthes.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by  orthes,
!
!        Ort has been altered.
!
!-----------------------------------------------------------------------
!
!     ********** Initialize z to identity matrix **********
do i = 1, n
!
   do j = 1, n
60    z(i,j) = 0.0
   end do
!
   z(i,i) = 1.0
end do
!
kl = igh - low - 1
if (kl < 1) go to 200
!     ********** For mp=igh-1 step -1 Until low+1 do -- **********
do mm = 1, kl
   mp = igh - mm
   if (a(mp,mp - 1) == 0.0) go to 140
   mp1 = mp + 1
!
   do i = mp1, igh
100   ort(i) = a(i,mp - 1)
   end do
!
   do j = mp, igh
      g = 0.0
!
      do i = mp, igh
110      g = g + ort(i) * z(i,j)
      end do
!     ********** Divisor below is negative of H formed in orthes.
!                Double division avoids possible underflow **********
      g = (g / ort(mp)) / a(mp,mp - 1)
!
      do i = mp, igh
120      z(i,j) = z(i,j) + g * ort(i)
      end do
!
   end do
!
140 continue
end do
!
200 return
end subroutine ortrn1

pure subroutine hqr2(nm,n,low,igh,h,wr,wi,z,ierr)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm
integer, intent(in) :: igh
integer, intent(in) :: low
integer, intent(out) :: ierr
real, intent(inout) :: h(nm,n), wr(n), wi(n), z(nm,n)
integer :: i, j, k, l, m, en, ii, jj, ll, mm, na, nn, its, mp2, enm2
real :: p, q, r, s, t, w, x, y, ra, sa, vi, vr, zz, norm, machep, nswc_ai_r4
logical :: notlas
complex :: z3
interface
   pure elemental function spmpar(i)
      implicit none
      integer, intent(in) :: i
      real :: spmpar
   end function spmpar
end interface
!     real sqrt,abs
!     integer min0
!     complex cmplx
!     real real,aimag
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure hqr2,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 372-395(1971).
!
!     This subroutine finds the eigenvalues and eigenvectors
!     of a real upper Hessenberg matrix BY the QR method.  The
!     eigenvectors of a real general matrix can also be found
!     if  elmhes  and  eltran  or  orthes  and  ortran  have
!     been used to reduce this general matrix to Hessenberg form
!     and to accumulate the similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine  balanc.  If  balanc  has not been used,
!          set low=1, igh=n,
!
!        h contains the upper Hessenberg matrix,
!
!        z contains the transformation matrix produced by  eltran
!          after the reduction by  elmhes, or by  ortran  after the
!          reduction by  orthes, if performed.  If the eigenvectors
!          of the Hessenberg matrix are desired, z must contain the
!          identity matrix.
!
!     On output-
!
!        h has been destroyed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        z contains the real and imaginary parts of the eigenvectors.
!          If the i-TH eigenvalue is real, the i-TH column of z
!          contains its eigenvector.  If the i-TH eigenvalue is complex
!          with positive imaginary part, the i-TH and (i+1)-TH
!          columns of z contain the real and imaginary parts of its
!          eigenvector.  The eigenvectors are unnormalized.  If an
!          error exit is made, none of the eigenvectors has been found,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 30 iterations.
!
!     Arithmetic is real except for the replacement of the Algol
!     procedure cdiv by complex division.
!
!-----------------------------------------------------------------------
!
!     ********** machep is a machine dependent parameter. Assign
!                machep the value U where U is the smallest positive
!                floating point number such that 1.0 + U .GT. 1.0 .
!
machep = spmpar(1)
!
!                **********
!
ierr = 0
norm = 0.0
k = 1
!     ********** Store roots isolated by balanc
!                and compute matrix norm **********
do i = 1, n
!
   do j = k, n
40    norm = norm + abs(h(i,j))
   end do
!
   k = i
   if (i >= low .and. i <= igh) go to 50
   wr(i) = h(i,i)
   wi(i) = 0.0
50 continue
end do
!
en = igh
t = 0.0
!     ********** Search for next eigenvalues **********
60 if (en < low) go to 340
its = 0
na = en - 1
enm2 = na - 1
!     ********** Look for single small sub-diagonal element
!                for l=en step -1 Until low do -- **********
70 do ll = low, en
   l = en + low - ll
   if (l == low) go to 100
   s = abs(h(l - 1,l - 1)) + abs(h(l,l))
   if (s == 0.0) s = norm
   if (abs(h(l,l - 1)) <= machep * s) go to 100
end do
!     ********** Form shift **********
100 x = h(en,en)
if (l == en) go to 270
y = h(na,na)
w = h(en,na) * h(na,en)
if (l == na) go to 280
if (its == 30) go to 1000
if (its /= 10 .and. its /= 20) go to 130
!     ********** Form exceptional shift **********
t = t + x
!
do i = low, en
120 h(i,i) = h(i,i) - x
end do
!
s = abs(h(en,na)) + abs(h(na,enm2))
x = 0.75 * s
y = x
w = -0.4375 * s * s
130 its = its + 1
!     ********** Look for two consecutive small
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l, enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r * s - w) / h(m + 1,m) + h(m,m + 1)
   q = h(m + 1,m + 1) - zz - r - s
   r = h(m + 2,m + 1)
   s = abs(p) + abs(q) + abs(r)
   p = p / s
   q = q / s
   r = r / s
   if (m == l) go to 150
   if (abs(h(m,m - 1)) * (abs(q) + abs(r)) <= machep * abs(p) &
      & * (abs(h(m - 1,m - 1)) + abs(zz) + abs(h(m + 1,m + 1)))) go to 150
end do
!
150 mp2 = m + 2
!
do i = mp2, en
   h(i,i - 2) = 0.0
   if (i == mp2) go to 160
   h(i,i - 3) = 0.0
160 continue
end do
!     ********** Double QR step involving rows l to en and
!                COLUMNS m TO en **********
do k = m, na
   notlas = k /= na
   if (k == m) go to 170
   p = h(k,k - 1)
   q = h(k + 1,k - 1)
   r = 0.0
   if (notlas) r = h(k + 2,k - 1)
   x = abs(p) + abs(q) + abs(r)
   if (x == 0.0) go to 260
   p = p / x
   q = q / x
   r = r / x
170 s = sqrt(p*p + q*q + r*r)
   if (p < 0.0) s = -s
   if (k == m) go to 180
   h(k,k - 1) = -s * x
   go to 190
180 if (l /= m) h(k,k - 1) = -h(k,k - 1)
190 p = p + s
   x = p / s
   y = q / s
   zz = r / s
   q = q / p
   r = r / p
!     ********** Row modification **********
   do j = k, n
      p = h(k,j) + q * h(k + 1,j)
      if (.not. notlas) go to 200
      p = p + r * h(k + 2,j)
      h(k + 2,j) = h(k + 2,j) - p * zz
200   h(k + 1,j) = h(k + 1,j) - p * y
      h(k,j) = h(k,j) - p * x
   end do
!
   j = min(en,k + 3)
!     ********** Column modification **********
   do i = 1, j
      p = x * h(i,k) + y * h(i,k + 1)
      if (.not. notlas) go to 220
      p = p + zz * h(i,k + 2)
      h(i,k + 2) = h(i,k + 2) - p * r
220   h(i,k + 1) = h(i,k + 1) - p * q
      h(i,k) = h(i,k) - p
   end do
!     ********** Accumulate transformations **********
   do i = low, igh
      p = x * z(i,k) + y * z(i,k + 1)
      if (.not. notlas) go to 240
      p = p + zz * z(i,k + 2)
      z(i,k + 2) = z(i,k + 2) - p * r
240   z(i,k + 1) = z(i,k + 1) - p * q
      z(i,k) = z(i,k) - p
   end do
!
260 continue
end do
!
go to 70
!     ********** One root found **********
270 h(en,en) = x + t
wr(en) = h(en,en)
wi(en) = 0.0
en = na
go to 60
!     ********** Two roots found **********
280 p = (y - x) / 2.0
q = p * p + w
zz = sqrt(abs(q))
h(en,en) = x + t
x = h(en,en)
h(na,na) = y + t
if (q < 0.0) go to 320
!     ********** Real pair **********
if (p < 0.0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz /= 0.0) wr(en) = x - w / zz
wi(na) = 0.0
wi(en) = 0.0
x = h(en,na)
s = abs(x) + abs(zz)
p = x / s
q = zz / s
r = sqrt(p*p + q*q)
p = p / r
q = q / r
!     ********** Row modification **********
do j = na, n
   zz = h(na,j)
   h(na,j) = q * zz + p * h(en,j)
   h(en,j) = q * h(en,j) - p * zz
end do
!     ********** Column modification **********
do i = 1, en
   zz = h(i,na)
   h(i,na) = q * zz + p * h(i,en)
   h(i,en) = q * h(i,en) - p * zz
end do
!     ********** Accumulate transformations **********
do i = low, igh
   zz = z(i,na)
   z(i,na) = q * zz + p * z(i,en)
   z(i,en) = q * z(i,en) - p * zz
end do
!
go to 330
!     ********** Complex pair **********
320 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
330 en = enm2
go to 60
!     ********** All roots found.  Backsubstitute to find
!                vectors of upper triangular form **********
340 if (norm == 0.0) go to 1001
!     ********** FOR en=n STEP -1 UNTIL 1 DO -- **********
do nn = 1, n
   en = n + 1 - nn
   p = wr(en)
   q = wi(en)
   na = en - 1
   nswc_ai_r4 = q
   if ( nswc_ai_r4 < 0 ) go to 710
   if ( nswc_ai_r4 == 0 ) go to 600
   go to 800
!     ********** Real vector **********
600 m = en
   h(en,en) = 1.0
   if (na == 0) go to 800
!     ********** FOR i=en-1 STEP -1 UNTIL 1 DO -- **********
   do ii = 1, na
      i = en - ii
      w = h(i,i) - p
      r = h(i,en)
      if (m > na) go to 620
!
      do j = m, na
610      r = r + h(i,j) * h(j,en)
      end do
!
620   if (wi(i) >= 0.0) go to 630
      zz = w
      s = r
      go to 700
630   m = i
      if (wi(i) /= 0.0) go to 640
      t = w
      if (w == 0.0) t = machep * norm
      h(i,en) = -r / t
      go to 700
!     ********** Solve real equations **********
640   x = h(i,i + 1)
      y = h(i + 1,i)
      q = (wr(i) - p) * (wr(i) - p) + wi(i) * wi(i)
      t = (x * s - zz * r) / q
      h(i,en) = t
      if (abs(x) <= abs(zz)) go to 650
      h(i + 1,en) = (-r - w * t) / x
      go to 700
650   h(i + 1,en) = (-s - y * t) / zz
700   continue
   end do
!     ********** End real vector **********
   go to 800
!     ********** Complex vector **********
710 m = na
!     ********** Last vector component chosen imaginary so that
!                eigenvector matrix is triangular **********
   if (abs(h(en,na)) <= abs(h(na,en))) go to 720
   h(na,na) = q / h(en,na)
   h(na,en) = -(h(en,en) - p) / h(en,na)
   go to 730
720 z3 = cmplx(0.0,-h(na,en)) / cmplx(h(na,na) - p,q)
   h(na,na) = real(z3)
   h(na,en) = aimag(z3)
730 h(en,na) = 0.0
   h(en,en) = 1.0
   enm2 = na - 1
   if (enm2 == 0) go to 800
!     ********** FOR i=en-2 STEP -1 UNTIL 1 DO -- **********
   do ii = 1, enm2
      i = na - ii
      w = h(i,i) - p
      ra = 0.0
      sa = h(i,en)
!
      do j = m, na
         ra = ra + h(i,j) * h(j,na)
         sa = sa + h(i,j) * h(j,en)
      end do
!
      if (wi(i) >= 0.0) go to 770
      zz = w
      r = ra
      s = sa
      go to 790
770   m = i
      if (wi(i) /= 0.0) go to 780
      z3 = cmplx(-ra,-sa) / cmplx(w,q)
      h(i,na) = real(z3)
      h(i,en) = aimag(z3)
      go to 790
!     ********** Solve complex equations **********
780   x = h(i,i + 1)
      y = h(i + 1,i)
      vr = (wr(i) - p) * (wr(i) - p) + wi(i) * wi(i) - q * q
      vi = (wr(i) - p) * 2.0 * q
      if (vr == 0.0 .and. vi == 0.0) vr = machep * norm &
         & * (abs(w) + abs(q) + abs(x) + abs(y) + abs(zz))
      z3 = cmplx(x*r - zz*ra + q*sa,x*s - zz*sa - q*ra) / cmplx(vr,vi)
      h(i,na) = real(z3)
      h(i,en) = aimag(z3)
      if (abs(x) <= abs(zz) + abs(q)) go to 785
      h(i + 1,na) = (-ra - w * h(i,na) + q * h(i,en)) / x
      h(i + 1,en) = (-sa - w * h(i,en) - q * h(i,na)) / x
      go to 790
785   z3 = cmplx(-r - y*h(i,na),-s - y*h(i,en)) / cmplx(zz,q)
      h(i + 1,na) = real(z3)
      h(i + 1,en) = aimag(z3)
790   continue
   end do
!     ********** End complex vector **********
800 continue
end do
!     ********** End back substitution.
!                Vectors of isolated roots **********
do i = 1, n
   if (i >= low .and. i <= igh) go to 840
!
   do j = i, n
820   z(i,j) = h(i,j)
   end do
!
840 continue
end do
!     ********** Multiply by transformation matrix to give
!                vectors of original full matrix.
!                For j=n step -1 Until low do -- **********
do jj = low, n
   j = n + low - jj
   m = min(j,igh)
!
   do i = low, igh
      zz = 0.0
!
      do k = low, m
860      zz = zz + z(i,k) * h(k,j)
      end do
!
      z(i,j) = zz
880   continue
   end do
end do
!
go to 1001
!     ********** Set error -- no convergence to an
!                eigenvalue after 30 iterations **********
1000 ierr = en
1001 return
end subroutine hqr2

pure subroutine deig(ibal,a,ka,n,wr,wi,ierr)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
double precision, intent(inout) :: a(ka,n), wr(n), wi(n)
integer :: igh, low
interface
   pure subroutine dbal(nm,n,a,low,igh,scale)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      double precision, intent(inout) :: a(nm,n)
      integer, intent(inout) :: low
      integer, intent(inout) :: igh
      double precision, intent(inout) :: scale(n)
   end subroutine dbal
   pure subroutine dhqr(nm,n,low,igh,h,wr,wi,ierr)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      integer, intent(in) :: igh
      double precision, intent(inout) :: h(nm,n)
      double precision, intent(inout) :: wr(n)
      double precision, intent(inout) :: wi(n)
      integer, intent(out) :: ierr
   end subroutine dhqr
   pure subroutine dorth(nm,n,low,igh,a,ort)
      implicit none
      integer, intent(in) :: igh
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      double precision, intent(inout) :: a(nm,n)
      double precision, intent(inout) :: ort(igh)
   end subroutine dorth
end interface
!-----------------------------------------------------------------------
!                Eigenvalues of double precision matrices
!-----------------------------------------------------------------------
!
low = 1
igh = n
if (ibal /= 0) call dbal(ka,n,a,low,igh,wr)
call dorth(ka,n,low,igh,a,wr)
call dhqr(ka,n,low,igh,a,wr,wi,ierr)
end subroutine deig

pure subroutine deigv(ibal,a,ka,n,wr,wi,zr,zi,ierr)
implicit none
integer, intent(in) :: ibal
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
double precision, intent(inout) :: a(ka,n), wr(n), wi(n), &
   & zr(ka,n), zi(ka,n)
integer :: igh, j, k, kp1, low
double precision :: nswc_ai_r8
interface
   pure subroutine dbabk(nm,n,low,igh,scale,m,z)
      implicit none
      integer, intent(in) :: m
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      integer, intent(in) :: igh
      double precision, intent(in) :: scale(n)
      double precision, intent(inout) :: z(nm,m)
   end subroutine dbabk
   pure subroutine dbal(nm,n,a,low,igh,scale)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      double precision, intent(inout) :: a(nm,n)
      integer, intent(inout) :: low
      integer, intent(inout) :: igh
      double precision, intent(inout) :: scale(n)
   end subroutine dbal
   pure subroutine dhqr2(nm,n,low,igh,h,wr,wi,z,ierr)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      integer, intent(in) :: igh
      double precision, intent(inout) :: h(nm,n)
      double precision, intent(inout) :: wr(n)
      double precision, intent(inout) :: wi(n)
      double precision, intent(inout) :: z(nm,n)
      integer, intent(out) :: ierr
   end subroutine dhqr2
   pure subroutine dorth(nm,n,low,igh,a,ort)
      implicit none
      integer, intent(in) :: igh
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      double precision, intent(inout) :: a(nm,n)
      double precision, intent(inout) :: ort(igh)
   end subroutine dorth
   pure subroutine dortrn(nm,n,low,igh,a,ort,z)
      implicit none
      integer, intent(in) :: igh
      integer, intent(in) :: n
      integer, intent(in) :: nm
      integer, intent(in) :: low
      double precision, intent(in) :: a(nm,igh)
      double precision, intent(inout) :: ort(igh)
      double precision, intent(inout) :: z(nm,n)
   end subroutine dortrn
end interface
!-----------------------------------------------------------------------
!     Eigenvalues and eigenvectors of double precision matrices
!-----------------------------------------------------------------------
!
low = 1
igh = n
if (ibal /= 0) call dbal(ka,n,a,low,igh,zi)
call dorth(ka,n,low,igh,a,wr)
call dortrn(ka,n,low,igh,a,wr,zr)
call dhqr2(ka,n,low,igh,a,wr,wi,zr,ierr)
if (ierr /= 0) return
if (ibal /= 0) call dbabk(ka,n,low,igh,zi,n,zr)
!
do k = 1,n
   nswc_ai_r8 = wi ( k )
   if ( nswc_ai_r8 < 0 ) go to 30
   if ( nswc_ai_r8 == 0 ) go to 10
   go to 20
10 do j = 1,n
11    zi(j,k) = 0.d0
   end do
   go to 30
20 kp1 = k + 1
   do j = 1,n
      zi(j,k) = zr(j,kp1)
      zr(j,kp1) = zr(j,k)
21    zi(j,kp1) = -zi(j,k)
   end do
30 continue
end do
end subroutine deigv

pure subroutine dbal(nm,n,a,low,igh,scale)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm
integer, intent(inout) :: igh, low
double precision, intent(inout) :: a(nm,n), scale(n)
integer :: i, j, k, l, m, jj, iexc
double precision :: c, f, g, r, s, b2, radix
logical :: noconv
interface
   pure elemental function ipmpar(i)
      implicit none
      integer, intent(in) :: i
      integer :: ipmpar
   end function ipmpar
end interface
!     double precision dabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure balance,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.II-linear algebra, 315-326(1971).
!
!     Dbal balances a double precision real matrix and isolates
!     eigenvalues whenever possible.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        A contains the input matrix to be balanced.
!
!     On output-
!
!        A contains the balanced matrix,
!
!        Low and igh are two integers such that a(i,j)
!          is equal to zero if
!           (1) i is greater than j and
!           (2) j=1,...,low-1 OR i=igh+1,...,n,
!
!        Scale contains information determining the
!           permutations and scaling factors used.
!
!     Suppose that the principal submatrix in rows low through igh
!     has been balanced, that P(j) denotes the index interchanged
!     with j during the permutation step, and that the elements
!     of the diagonal matrix used are denoted by D(i,j).  Then
!        scale(j) = P(j),    FOR j = 1,...,low-1
!                 = D(j,j),      j = low,...,igh
!                 = P(j)         j = igh+1,...,n.
!     The order in which the interchanges are made is n to igh+1,
!     then 1 to low-1.
!
!     Note that 1 is returned for igh if igh is zero formally.
!
!     The Algol procedure exc contained in balance appears in
!     dbal in line.  (Note that the Algol roles of identifiers
!     k,l have been reversed.)
!
!-----------------------------------------------------------------------
!
!     ********** radix is a machine dependent parameter specifying
!                the base of the machine floating point representation.
!
radix = ipmpar(4)
!
!                **********
!
b2 = radix * radix
k = 1
l = n
go to 100
!     ********** In-line procedure for row and
!                column exchange **********
20 scale(m) = j
if (j == m) go to 50
!
do i = 1, l
   f = a(i,j)
   a(i,j) = a(i,m)
   a(i,m) = f
end do
!
do i = k, n
   f = a(j,i)
   a(j,i) = a(m,i)
   a(m,i) = f
end do
!
50 go to (80,130), iexc
!     ********** Search for rows isolating an eigenvalue
!                and push them down **********
80 if (l == 1) go to 280
l = l - 1
!     ********** FOR j=l STEP -1 UNTIL 1 DO -- **********
100 do jj = 1, l
   j = l + 1 - jj
!
   do i = 1, l
      if (i == j) go to 110
      if (a(j,i) /= 0.d0) go to 120
110   continue
   end do
!
   m = l
   iexc = 1
   go to 20
120 continue
end do
!
go to 140
!     ********** Search for columns isolating an eigenvalue
!                and push them left **********
130 k = k + 1
!
140 do j = k, l
!
   do i = k, l
      if (i == j) go to 150
      if (a(i,j) /= 0.d0) go to 170
150   continue
   end do
!
   m = k
   iexc = 2
   go to 20
170 continue
end do
!     ********** Now balance the submatrix in rows k to l **********
do i = k, l
180 scale(i) = 1.d0
end do
!     ********** Iterative loop for norm reduction **********
190 noconv = .false.
!
do i = k, l
   c = 0.d0
   r = 0.d0
!
   do j = k, l
      if (j == i) go to 200
      c = c + abs(a(j,i))
      r = r + abs(a(i,j))
200   continue
   end do
!     ********** Guard against zero c or r due to underflow **********
   if (c == 0.d0 .or. r == 0.d0) go to 270
   g = r / radix
   f = 1.d0
   s = c + r
210 if (c >= g) go to 220
   f = f * radix
   c = c * b2
   go to 210
220 g = r * radix
230 if (c < g) go to 240
   f = f / radix
   c = c / b2
   go to 230
!     ********** Now balance **********
240 if ((c + r) / f >= 0.95d0 * s) go to 270
   g = 1.d0 / f
   scale(i) = scale(i) * f
   noconv = .true.
!
   do j = k, n
250   a(i,j) = a(i,j) * g
   end do
!
   do j = 1, l
260   a(j,i) = a(j,i) * f
   end do
!
270 continue
end do
!
if (noconv) go to 190
!
280 low = k
igh = l
end subroutine dbal

pure subroutine dbalnv(nz,n,z,low,igh,scale)
implicit none
integer, intent(in) :: n
integer, intent(in) :: nz, igh, low
double precision, intent(inout) :: z(nz,n)
double precision, intent(in) :: scale(n)
integer :: i, j, k, ii
double precision :: s
!-----------------------------------------------------------------------
!        Given A matrix A of order n. dbal transforms A into
!     the matrix B by the similarity transformation
!             b = d**(-1)*transpose(p)*a*p*d
!     where D is a diagonal matrix and P a permutation matrix.
!     The information concerning D and P is stored in igh, low,
!     and scale. The order in which the interchanges were made
!     is n to igh + 1, and then 1 to low - 1.
!
!        z is a matrix of order n. dbalnv transforms z into the
!     matrix W using the inverse similarity transform
!             w = p*d*z*d**(-1)*transpose(p)
!
!     On input-
!
!        nz is the row dimension of the matrix z in the calling
!          program,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by  dbal,
!
!        Scale contains information determining the permutations
!          and scaling factors used by  dbal,
!
!     On output-
!
!        z contains the transformed matrix W
!
!-----------------------------------------------------------------------
!
if (igh == low) go to 30
!
do i = low, igh
   s = scale(i)
   do j = 1, n
10    z(i,j) = z(i,j) * s
   end do
end do
!
do j = low, igh
   s = 1.d0/scale(j)
   do i = 1, n
20    z(i,j) = z(i,j) * s
   end do
end do
!
!     ********- FOR i=low-1 STEP -1 UNTIL 1,
!               igh+1 STEP 1 UNTIL n DO -- **********
!
30 do ii = 1, n
   i = ii
   if (i >= low .and. i <= igh) go to 60
   if (i < low) i = low - ii
   k = scale(i)
   if (k == i) go to 60
!
   do j = 1, n
      s = z(i,j)
      z(i,j) = z(k,j)
40    z(k,j) = s
   end do
!
   do j = 1, n
      s = z(j,i)
      z(j,i) = z(j,k)
50    z(j,k) = s
   end do
60 continue
end do
end subroutine dbalnv

pure subroutine dorth(nm,n,low,igh,a,ort)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh
integer, intent(in) :: low
double precision, intent(inout) :: a(nm,n), ort(igh)
integer :: i, j, m, ii, jj, la, mp, kp1
double precision :: f, g, h, scale
!     double precision dsqrt,dabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure orthes,
!     NUM. Math. 12, 349-368(1968) By Martin and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 339-358(1971).
!
!     Given a real general matrix, this subroutine
!     reduces a submatrix situated in rows and columns
!     low through igh to upper Hessenberg form by
!     orthogonal similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          set low=1, igh=n,
!
!        A contains the input matrix.
!
!     On output-
!
!        A contains the Hessenberg matrix.  Information about
!          the orthogonal transformations used in the reduction
!          is stored in the remaining triangle under the
!          Hessenberg matrix,
!
!        Ort contains further information about the transformations.
!          Only elements low through igh are used.
!
!-----------------------------------------------------------------------
!
la = igh - 1
kp1 = low + 1
if (la < kp1) go to 200
!
do m = kp1, la
   h = 0.d0
   ort(m) = 0.d0
   scale = 0.d0
!     ********** scale COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do i = m, igh
90    scale = scale + abs(a(i,m - 1))
   end do
!
   if (scale == 0.d0) go to 180
   mp = m + igh
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
   do ii = m, igh
      i = mp - ii
      ort(i) = a(i,m - 1) / scale
      h = h + ort(i) * ort(i)
   end do
!
   g = sqrt(h)
   if (ort(m) >= 0.d0) g = -g
   h = h - ort(m) * g
   ort(m) = ort(m) - g
!     ********** FORM (i-(U*UT)/h) * a **********
   do j = m, n
      f = 0.d0
!     ********** FOR i=igh STEP -1 UNTIL m DO -- **********
      do ii = m, igh
         i = mp - ii
         f = f + ort(i) * a(i,j)
      end do
!
      f = f / h
!
      do i = m, igh
120      a(i,j) = a(i,j) - f * ort(i)
      end do
!
   end do
!     ********** FORM (i-(U*UT)/h)*a*(i-(U*UT)/h) **********
   do i = 1, igh
      f = 0.d0
!     ********** FOR j=igh STEP -1 UNTIL m DO -- **********
      do jj = m, igh
         j = mp - jj
         f = f + ort(j) * a(i,j)
      end do
!
      f = f / h
!
      do j = m, igh
150      a(i,j) = a(i,j) - f * ort(j)
      end do
!
   end do
!
   ort(m) = scale * ort(m)
   a(m,m - 1) = scale * g
180 continue
end do
!
200 return
end subroutine dorth

pure subroutine dhqr(nm,n,low,igh,h,wr,wi,ierr)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh
integer, intent(in) :: low
integer, intent(out) :: ierr
double precision, intent(inout) :: h(nm,n), wr(n), wi(n)
integer :: i, j, k, l, m, en, ll, mm, na, its, mp2, enm2
double precision :: p, q, r, s, t, w, x, y, zz, norm, machep
logical :: notlas
interface
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
end interface
!     double precision dsqrt,dabs
!     integer min0
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure hqr,
!     NUM. Math. 14, 219-231(1970) By Martin, peters, and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 359-371(1971).
!
!     dhqr finds the eigenvalues of a double precision real
!     upper Hessenberg matrix BY the QR method.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          set low=1, igh=n,
!
!        h contains the upper Hessenberg matrix.  Information about
!          the transformations used in the reduction to Hessenberg
!          form by dorth, if performed, is stored
!          in the remaining triangle under the Hessenberg matrix.
!
!     On output-
!
!        h has been destroyed.  Therefore, it must be saved
!          before calling  hqr  if subsequent calculation and
!          back transformation of eigenvectors is to be performed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 50 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep is a machine dependent parameter. Assign
!                machep the value U where U is the smallest positive
!                floating point number such that 1.0 + U .GT. 1.0
!                in the double precision arithmetic being used.
!
machep = dpmpar(1)
!
!                **********
!
ierr = 0
norm = 0.d0
k = 1
!     ********** Store roots isolated by dbal
!                and compute matrix norm **********
do i = 1, n
!
   do j = k, n
40    norm = norm + abs(h(i,j))
   end do
!
   k = i
   if (i >= low .and. i <= igh) go to 50
   wr(i) = h(i,i)
   wi(i) = 0.d0
50 continue
end do
!
en = igh
t = 0.d0
!     ********** Search for next eigenvalues **********
60 if (en < low) go to 1001
its = 0
na = en - 1
enm2 = na - 1
!     ********** Look for single small sub-diagonal element
!                for l=en step -1 Until low do -- **********
70 do ll = low, en
   l = en + low - ll
   if (l == low) go to 100
   s = abs(h(l - 1,l - 1)) + abs(h(l,l))
   if (s == 0.d0) s = norm
   if (abs(h(l,l - 1)) <= machep * s) go to 100
end do
!     ********** Form shift **********
100 x = h(en,en)
if (l == en) go to 270
y = h(na,na)
w = h(en,na) * h(na,en)
if (l == na) go to 280
if (its == 50) go to 1000
if (its /= 10 .and. its /= 20 .and. its /= 30) go to 130
!     ********** Form exceptional shift **********
t = t + x
!
do i = low, en
120 h(i,i) = h(i,i) - x
end do
!
s = abs(h(en,na)) + abs(h(na,enm2))
x = .75d0 * s
y = x
w = -.4375d0 * s * s
130 its = its + 1
!     ********** Look for two consecutive small
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l, enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r * s - w) / h(m + 1,m) + h(m,m + 1)
   q = h(m + 1,m + 1) - zz - r - s
   r = h(m + 2,m + 1)
   s = abs(p) + abs(q) + abs(r)
   p = p / s
   q = q / s
   r = r / s
   if (m == l) go to 150
   if (abs(h(m,m - 1)) * (abs(q) + abs(r)) <= machep * abs(p) &
      & * (abs(h(m - 1,m - 1)) + abs(zz) + abs(h(m + 1,m + 1)))) go to 150
end do
!
150 mp2 = m + 2
!
do i = mp2, en
   h(i,i - 2) = 0.d0
   if (i == mp2) go to 160
   h(i,i - 3) = 0.d0
160 continue
end do
!     ********** Double QR step involving rows l to en and
!                COLUMNS m TO en **********
do k = m, na
   notlas = k /= na
   if (k == m) go to 170
   p = h(k,k - 1)
   q = h(k + 1,k - 1)
   r = 0.d0
   if (notlas) r = h(k + 2,k - 1)
   x = abs(p) + abs(q) + abs(r)
   if (x == 0.d0) go to 260
   p = p / x
   q = q / x
   r = r / x
170 s = sqrt(p*p + q*q + r*r)
   if (p < 0.d0) s = -s
   if (k == m) go to 180
   h(k,k - 1) = -s * x
   go to 190
180 if (l /= m) h(k,k - 1) = -h(k,k - 1)
190 p = p + s
   x = p / s
   y = q / s
   zz = r / s
   q = q / p
   r = r / p
!     ********** Row modification **********
   do j = k, en
      p = h(k,j) + q * h(k + 1,j)
      if (.not. notlas) go to 200
      p = p + r * h(k + 2,j)
      h(k + 2,j) = h(k + 2,j) - p * zz
200   h(k + 1,j) = h(k + 1,j) - p * y
      h(k,j) = h(k,j) - p * x
   end do
!
   j = min(en,k + 3)
!     ********** Column modification **********
   do i = l, j
      p = x * h(i,k) + y * h(i,k + 1)
      if (.not. notlas) go to 220
      p = p + zz * h(i,k + 2)
      h(i,k + 2) = h(i,k + 2) - p * r
220   h(i,k + 1) = h(i,k + 1) - p * q
      h(i,k) = h(i,k) - p
   end do
!
260 continue
end do
!
go to 70
!     ********** One root found **********
270 wr(en) = x + t
wi(en) = 0.d0
en = na
go to 60
!     ********** Two roots found **********
280 p = (y - x) / 2.d0
q = p * p + w
zz = sqrt(abs(q))
x = x + t
if (q < 0.d0) go to 320
!     ********** Real pair **********
if (p < 0.d0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz /= 0.d0) wr(en) = x - w / zz
wi(na) = 0.d0
wi(en) = 0.d0
go to 330
!     ********** Complex pair **********
320 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
330 en = enm2
go to 60
!     ********** Set error -- no convergence to an
!                eigenvalue after 50 iterations **********
1000 ierr = en
1001 return
end subroutine dhqr

pure subroutine dbabk(nm,n,low,igh,scale,m,z)
implicit none
!
integer, intent(in) :: m, n
integer, intent(in) :: nm, igh, low
double precision, intent(in) :: scale(n)
double precision, intent(inout) :: z(nm,m)
integer :: i, j, k, ii
double precision :: s
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure balbak,
!     NUM. Math. 13, 293-304(1969) By Parlett and Reinsch.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 315-326(1971).
!
!     This subroutine forms the eigenvectors of a real general
!     matrix BY back transforming those of the corresponding
!     balanced matrix determined by dbal.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by dbal,
!
!        Scale contains information determining the permutations
!          and scaling factors used by dbal,
!
!        m is the number of columns of z to be back transformed,
!
!        z contains the real and imaginary parts of the eigen-
!          vectors to be back transformed in its first m columns.
!
!     On output-
!
!        z contains the real and imaginary parts of the
!          transformed eigenvectors in its first m columns.
!
!-----------------------------------------------------------------------
!
if (m == 0) go to 200
if (igh == low) go to 120
!
do i = low, igh
   s = scale(i)
!     ********** Left hand eigenvectors are back transformed
!                if the foregoing statement is replaced by
!                s=1.0/scale(i). **********
   do j = 1, m
100   z(i,j) = z(i,j) * s
   end do
!
end do
!     ********- FOR i=low-1 STEP -1 UNTIL 1,
!               igh+1 STEP 1 UNTIL n DO -- **********
120 do ii = 1, n
   i = ii
   if (i >= low .and. i <= igh) go to 140
   if (i < low) i = low - ii
   k = scale(i)
   if (k == i) go to 140
!
   do j = 1, m
      s = z(i,j)
      z(i,j) = z(k,j)
      z(k,j) = s
   end do
!
140 continue
end do
!
200 return
end subroutine dbabk

pure subroutine dortrn(nm,n,low,igh,a,ort,z)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm, igh, low
double precision, intent(in) :: a(nm,igh)
double precision, intent(inout) :: ort(igh), z(nm,n)
integer :: i, j, kl, mm, mp, mp1
double precision :: g
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ORTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the orthogonal similarity
!     transformations used in the reduction of a real double
!     precision matrix to upper Hessenberg form by dorth.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          set low=1, igh=n,
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction by dorth
!          in its strict lower triangle,
!
!        Ort contains further information about the trans-
!          formations used in the reduction by dorth.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by dorth,
!
!        Ort has been altered.
!
!-----------------------------------------------------------------------
!
!     ********** Initialize z to identity matrix **********
do i = 1, n
!
   do j = 1, n
60    z(i,j) = 0.d0
   end do
!
   z(i,i) = 1.d0
end do
!
kl = igh - low - 1
if (kl < 1) go to 200
!     ********** For mp=igh-1 step -1 Until low+1 do -- **********
do mm = 1, kl
   mp = igh - mm
   if (a(mp,mp - 1) == 0.d0) go to 140
   mp1 = mp + 1
!
   do i = mp1, igh
100   ort(i) = a(i,mp - 1)
   end do
!
   do j = mp, igh
      g = 0.d0
!
      do i = mp, igh
110      g = g + ort(i) * z(i,j)
      end do
!     ********** Divisor below is negative of H formed in orthes.
!                Double division avoids possible underflow **********
      g = (g / ort(mp)) / a(mp,mp - 1)
!
      do i = mp, igh
120      z(i,j) = z(i,j) + g * ort(i)
      end do
!
   end do
!
140 continue
end do
!
200 return
end subroutine dortrn

pure subroutine drtrn1(n,low,igh,a,na,z,nz,ort)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: na, igh, low
integer, intent(in) :: nz
double precision, intent(in) :: a(na,igh)
double precision, intent(inout) :: ort(igh), z(nz,n)
integer :: i, j, kl, mm, mp, mp1
double precision :: g
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure ORTRANS,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.II-linear algebra, 372-395(1971).
!
!     This subroutine accumulates the orthogonal similarity
!     transformations used in the reduction of a real double
!     precision matrix to upper Hessenberg form by dorth.
!
!     On input-
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          set low=1, igh=n,
!
!        A contains information about the orthogonal trans-
!          formations used in the reduction by dorth
!          in its strict lower triangle,
!
!        na must be set to the row dimension of the 2-dimensional
!          array parameter  a  as declared in the calling program
!          dimension statement,
!
!        nz must be set to the row dimension of the 2-dimensional
!          array parameter  z  as declared in the calling program
!          dimension statement,
!
!        Ort contains further information about the trans-
!          formations used in the reduction by dorth.
!          Only elements low through igh are used.
!
!     On output-
!
!        z contains the transformation matrix produced in the
!          reduction by dorth,
!
!        Ort has been altered.
!
!-----------------------------------------------------------------------
!
!     ********** Initialize z to identity matrix **********
do i = 1, n
!
   do j = 1, n
60    z(i,j) = 0.d0
   end do
!
   z(i,i) = 1.d0
end do
!
kl = igh - low - 1
if (kl < 1) go to 200
!     ********** For mp=igh-1 step -1 Until low+1 do -- **********
do mm = 1, kl
   mp = igh - mm
   if (a(mp,mp - 1) == 0.d0) go to 140
   mp1 = mp + 1
!
   do i = mp1, igh
100   ort(i) = a(i,mp - 1)
   end do
!
   do j = mp, igh
      g = 0.d0
!
      do i = mp, igh
110      g = g + ort(i) * z(i,j)
      end do
!     ********** Divisor below is negative of H formed in orthes.
!                Double division avoids possible underflow **********
      g = (g / ort(mp)) / a(mp,mp - 1)
!
      do i = mp, igh
120      z(i,j) = z(i,j) + g * ort(i)
      end do
!
   end do
!
140 continue
end do
!
200 return
end subroutine drtrn1

pure subroutine dhqr2(nm,n,low,igh,h,wr,wi,z,ierr)
implicit none
!
integer, intent(in) :: n
integer, intent(in) :: nm
integer, intent(in) :: igh
integer, intent(in) :: low
integer, intent(out) :: ierr
double precision, intent(inout) :: h(nm,n), wr(n), wi(n), z(nm,n)
integer :: i, j, k, l, m, en, ii, jj, ll, mm, na, nn, its, mp2, enm2
double precision :: a, b, d, p, q, r, s, t, u, w, x, y, ra, sa, vi, vr, zz, norm, machep, nswc_ai_r8
logical :: notlas
interface
   pure elemental function dpmpar(i)
      implicit none
      integer, intent(in) :: i
      double precision :: dpmpar
   end function dpmpar
end interface
!     integer min0
!     double precision dsqrt,dabs
!-----------------------------------------------------------------------
!
!     This subroutine is a translation of the Algol procedure hqr2,
!     NUM. Math. 16, 181-204(1970) By peters and Wilkinson.
!     Handbook for auto. Comp., Vol.ii-linear algebra, 372-395(1971).
!
!     This subroutine finds the eigenvalues and eigenvectors
!     of a real double precision upper Hessenberg matrix BY the
!     QR method.  The eigenvectors of a real general matrix can
!     also be found if dorth and dortrn have been used to reduce
!     this general matrix to Hessenberg form and to accumulate
!     the similarity transformations.
!
!     On input-
!
!        nm must be set to the row dimension of two-dimensional
!          array parameters as declared in the calling program
!          dimension statement,
!
!        n is the order of the matrix,
!
!        Low and igh are integers determined by the balancing
!          subroutine dbal.  If dbal has not been used then
!          set low=1, igh=n,
!
!        h contains the upper Hessenberg matrix,
!
!        z contains the transformation matrix produced by dortrn
!          after the reduction by dorth, if performed. If the
!          eigenvectors of the Hessenberg matrix are desired,
!          z must contain the identity matrix.
!
!     On output-
!
!        h has been destroyed,
!
!        wr and wi contain the real and imaginary parts,
!          respectively, of the eigenvalues.  The eigenvalues
!          are unordered except that complex conjugate pairs
!          of values appear consecutively with the eigenvalue
!          having the positive imaginary part first.  If an
!          error exit is made, the eigenvalues should be correct
!          for indices ierr+1,...,n,
!
!        z contains the real and imaginary parts of the eigenvectors.
!          If the i-TH eigenvalue is real, the i-TH column of z
!          contains its eigenvector.  If the i-TH eigenvalue is complex
!          with positive imaginary part, the i-TH and (i+1)-TH
!          columns of z contain the real and imaginary parts of its
!          eigenvector.  The eigenvectors are unnormalized.  If an
!          error exit is made, none of the eigenvectors has been found,
!
!        ierr is set to
!          ZERO       FOR NORMAL RETURN,
!          j          IF THE j-TH EIGENVALUE HAS NOT BEEN
!                     determined after 50 iterations.
!
!-----------------------------------------------------------------------
!
!     ********** machep is a machine dependent parameter. Assign
!                machep the value u where u is the smallest positive
!                floating point number such that 1.0 + u .GT. 1.0
!                in the double precision arithmetic being used.
!
machep = dpmpar(1)
!
!                **********
!
ierr = 0
norm = 0.d0
k = 1
!     ********** Store roots isolated by dbal
!                and compute matrix norm **********
do i = 1, n
!
   do j = k, n
40    norm = norm + abs(h(i,j))
   end do
!
   k = i
   if (i >= low .and. i <= igh) go to 50
   wr(i) = h(i,i)
   wi(i) = 0.d0
50 continue
end do
!
en = igh
t = 0.d0
!     ********** Search for next eigenvalues **********
60 if (en < low) go to 340
its = 0
na = en - 1
enm2 = na - 1
!     ********** Look for single small sub-diagonal element
!                for l=en step -1 Until low do -- **********
70 do ll = low, en
   l = en + low - ll
   if (l == low) go to 100
   s = abs(h(l - 1,l - 1)) + abs(h(l,l))
   if (s == 0.d0) s = norm
   if (abs(h(l,l - 1)) <= machep * s) go to 100
end do
!     ********** Form shift **********
100 x = h(en,en)
if (l == en) go to 270
y = h(na,na)
w = h(en,na) * h(na,en)
if (l == na) go to 280
if (its == 50) go to 1000
if (its /= 10 .and. its /= 20 .and. its /= 30) go to 130
!     ********** Form exceptional shift **********
t = t + x
!
do i = low, en
120 h(i,i) = h(i,i) - x
end do
!
s = abs(h(en,na)) + abs(h(na,enm2))
x = .75d0 * s
y = x
w = -.4375d0 * s * s
130 its = its + 1
!     ********** Look for two consecutive small
!                sub-diagonal elements.
!                FOR m=en-2 STEP -1 UNTIL l DO -- **********
do mm = l, enm2
   m = enm2 + l - mm
   zz = h(m,m)
   r = x - zz
   s = y - zz
   p = (r * s - w) / h(m + 1,m) + h(m,m + 1)
   q = h(m + 1,m + 1) - zz - r - s
   r = h(m + 2,m + 1)
   s = abs(p) + abs(q) + abs(r)
   p = p / s
   q = q / s
   r = r / s
   if (m == l) go to 150
   if (abs(h(m,m - 1)) * (abs(q) + abs(r)) <= machep * abs(p) &
      & * (abs(h(m - 1,m - 1)) + abs(zz) + abs(h(m + 1,m + 1)))) go to 150
end do
!
150 mp2 = m + 2
!
do i = mp2, en
   h(i,i - 2) = 0.d0
   if (i == mp2) go to 160
   h(i,i - 3) = 0.d0
160 continue
end do
!     ********** Double QR step involving rows l to en and
!                COLUMNS m TO en **********
do k = m, na
   notlas = k /= na
   if (k == m) go to 170
   p = h(k,k - 1)
   q = h(k + 1,k - 1)
   r = 0.d0
   if (notlas) r = h(k + 2,k - 1)
   x = abs(p) + abs(q) + abs(r)
   if (x == 0.d0) go to 260
   p = p / x
   q = q / x
   r = r / x
170 s = sqrt(p*p + q*q + r*r)
   if (p < 0.d0) s = -s
   if (k == m) go to 180
   h(k,k - 1) = -s * x
   go to 190
180 if (l /= m) h(k,k - 1) = -h(k,k - 1)
190 p = p + s
   x = p / s
   y = q / s
   zz = r / s
   q = q / p
   r = r / p
!     ********** Row modification **********
   do j = k, n
      p = h(k,j) + q * h(k + 1,j)
      if (.not. notlas) go to 200
      p = p + r * h(k + 2,j)
      h(k + 2,j) = h(k + 2,j) - p * zz
200   h(k + 1,j) = h(k + 1,j) - p * y
      h(k,j) = h(k,j) - p * x
   end do
!
   j = min(en,k + 3)
!     ********** Column modification **********
   do i = 1, j
      p = x * h(i,k) + y * h(i,k + 1)
      if (.not. notlas) go to 220
      p = p + zz * h(i,k + 2)
      h(i,k + 2) = h(i,k + 2) - p * r
220   h(i,k + 1) = h(i,k + 1) - p * q
      h(i,k) = h(i,k) - p
   end do
!     ********** Accumulate transformations **********
   do i = low, igh
      p = x * z(i,k) + y * z(i,k + 1)
      if (.not. notlas) go to 240
      p = p + zz * z(i,k + 2)
      z(i,k + 2) = z(i,k + 2) - p * r
240   z(i,k + 1) = z(i,k + 1) - p * q
      z(i,k) = z(i,k) - p
   end do
!
260 continue
end do
!
go to 70
!     ********** One root found **********
270 h(en,en) = x + t
wr(en) = h(en,en)
wi(en) = 0.d0
en = na
go to 60
!     ********** Two roots found **********
280 p = (y - x) / 2.d0
q = p * p + w
zz = sqrt(abs(q))
h(en,en) = x + t
x = h(en,en)
h(na,na) = y + t
if (q < 0.d0) go to 320
!     ********** Real pair **********
if (p < 0.d0) zz = -zz
zz = p + zz
wr(na) = x + zz
wr(en) = wr(na)
if (zz /= 0.d0) wr(en) = x - w / zz
wi(na) = 0.d0
wi(en) = 0.d0
x = h(en,na)
s = abs(x) + abs(zz)
p = x / s
q = zz / s
r = sqrt(p*p + q*q)
p = p / r
q = q / r
!     ********** Row modification **********
do j = na, n
   zz = h(na,j)
   h(na,j) = q * zz + p * h(en,j)
   h(en,j) = q * h(en,j) - p * zz
end do
!     ********** Column modification **********
do i = 1, en
   zz = h(i,na)
   h(i,na) = q * zz + p * h(i,en)
   h(i,en) = q * h(i,en) - p * zz
end do
!     ********** Accumulate transformations **********
do i = low, igh
   zz = z(i,na)
   z(i,na) = q * zz + p * z(i,en)
   z(i,en) = q * z(i,en) - p * zz
end do
!
go to 330
!     ********** Complex pair **********
320 wr(na) = x + p
wr(en) = x + p
wi(na) = zz
wi(en) = -zz
330 en = enm2
go to 60
!     ********** All roots found.  Backsubstitute to find
!                vectors of upper triangular form **********
340 if (norm == 0.d0) go to 1001
!     ********** FOR en=n STEP -1 UNTIL 1 DO -- **********
do nn = 1, n
   en = n + 1 - nn
   p = wr(en)
   q = wi(en)
   na = en - 1
   nswc_ai_r8 = q
   if ( nswc_ai_r8 < 0 ) go to 710
   if ( nswc_ai_r8 == 0 ) go to 600
   go to 800
!     ********** Real vector **********
600 m = en
   h(en,en) = 1.d0
   if (na == 0) go to 800
!     ********** FOR i=en-1 STEP -1 UNTIL 1 DO -- **********
   do ii = 1, na
      i = en - ii
      w = h(i,i) - p
      r = h(i,en)
      if (m > na) go to 620
!
      do j = m, na
610      r = r + h(i,j) * h(j,en)
      end do
!
620   if (wi(i) >= 0.d0) go to 630
      zz = w
      s = r
      go to 700
630   m = i
      if (wi(i) /= 0.d0) go to 640
      t = w
      if (w == 0.d0) t = machep * norm
      h(i,en) = -r / t
      go to 700
!     ********** Solve real equations **********
640   x = h(i,i + 1)
      y = h(i + 1,i)
      q = (wr(i) - p) * (wr(i) - p) + wi(i) * wi(i)
      t = (x * s - zz * r) / q
      h(i,en) = t
      if (abs(x) <= abs(zz)) go to 650
      h(i + 1,en) = (-r - w * t) / x
      go to 700
650   h(i + 1,en) = (-s - y * t) / zz
700   continue
   end do
!     ********** End real vector **********
   go to 800
!     ********** Complex vector **********
710 m = na
!     ********** Last vector component chosen imaginary so that
!                eigenvector matrix is triangular **********
   if (abs(h(en,na)) <= abs(h(na,en))) go to 720
   h(na,na) = q / h(en,na)
   h(na,en) = -(h(en,en) - p) / h(en,na)
   go to 730
720 u = h(na,na) - p
   b = -h(na,en) / (u * u + q * q)
   h(na,na) = b * q
   h(na,en) = b * u
730 h(en,na) = 0.d0
   h(en,en) = 1.d0
   enm2 = na - 1
   if (enm2 == 0) go to 800
!     ********** FOR i=en-2 STEP -1 UNTIL 1 DO -- **********
   do ii = 1, enm2
      i = na - ii
      w = h(i,i) - p
      ra = 0.d0
      sa = h(i,en)
!
      do j = m, na
         ra = ra + h(i,j) * h(j,na)
         sa = sa + h(i,j) * h(j,en)
      end do
!
      if (wi(i) >= 0.d0) go to 770
      zz = w
      r = ra
      s = sa
      go to 790
770   m = i
      if (wi(i) /= 0.d0) go to 780
      d = w * w + q * q
      h(i,na) = -(ra * w + sa * q) / d
      h(i,en) = (ra * q - sa * w) / d
      go to 790
!     ********** Solve complex equations **********
780   x = h(i,i + 1)
      y = h(i + 1,i)
      vr = (wr(i) - p) * (wr(i) - p) + wi(i) * wi(i) - q * q
      vi = (wr(i) - p) * 2.d0 * q
      if (vr == 0.d0 .and. vi == 0.d0) vr = machep * norm &
         & * (abs(w) + abs(q) + abs(x) + abs(y) + abs(zz))
      a = x * r - zz * ra + q * sa
      b = x * s - zz * sa - q * ra
      d = vr * vr + vi * vi
      h(i,na) = (a * vr + b * vi) / d
      h(i,en) = (b * vr - a * vi) / d
      if (abs(x) <= abs(zz) + abs(q)) go to 785
      h(i + 1,na) = (-ra - w * h(i,na) + q * h(i,en)) / x
      h(i + 1,en) = (-sa - w * h(i,en) - q * h(i,na)) / x
      go to 790
785   a = -r - y * h(i,na)
      b = -s - y * h(i,en)
      d = zz * zz + q * q
      h(i + 1,na) = (a * zz + b * q) / d
      h(i + 1,en) = (b * zz - a * q) / d
790   continue
   end do
!     ********** End complex vector **********
800 continue
end do
!     ********** End back substitution.
!                Vectors of isolated roots **********
do i = 1, n
   if (i >= low .and. i <= igh) go to 840
!
   do j = i, n
820   z(i,j) = h(i,j)
   end do
!
840 continue
end do
!     ********** Multiply by transformation matrix to give
!                vectors of original full matrix.
!                For j=n step -1 Until low do -- **********
do jj = low, n
   j = n + low - jj
   m = min(j,igh)
!
   do i = low, igh
      zz = 0.d0
!
      do k = low, m
860      zz = zz + z(i,k) * h(k,j)
      end do
!
      z(i,j) = zz
880   continue
   end do
end do
!
go to 1001
!     ********** Set error -- no convergence to an
!                eigenvalue after 50 iterations **********
1000 ierr = en
1001 return
end subroutine dhqr2

subroutine seig(a, ka, n, w, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka
integer :: n
real, intent(inout) :: a(*), w(n), t(*)
integer :: l
!-----------------------------------------------------------------------
!               Eigenvalues of symmetric real matrices
!-----------------------------------------------------------------------
!
if (ka == 0) go to 10
call tred1(ka, n, a, w, t(n + 1), t(1))
call tqlrat(n, w, t, ierr)
return
10 l = n*(n + 1)
l = l/2
call tred3(n, l, a, w, t(n + 1), t(1))
call tqlrat(n, w, t, ierr)
end subroutine seig

pure subroutine seig1(a, ka, n, w, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
real, intent(inout) :: a(*), w(n), t(n)
integer :: l
interface
   pure subroutine imtql1(n,d,e,ierr)
      implicit none
      integer, intent(in) :: n
      real, intent(inout) :: d(n)
      real, intent(inout) :: e(n)
      integer, intent(out) :: ierr
   end subroutine imtql1
   pure subroutine tred1(nm,n,a,d,e,e2)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      real, intent(inout) :: a(nm,n)
      real, intent(inout) :: d(n)
      real, intent(inout) :: e(n)
      real, intent(inout) :: e2(n)
   end subroutine tred1
   pure subroutine tred3(n,nv,a,d,e,e2)
      implicit none
      integer, intent(in) :: nv
      integer, intent(in) :: n
      real, intent(inout) :: a(nv)
      real, intent(inout) :: d(n)
      real, intent(inout) :: e(n)
      real, intent(inout) :: e2(n)
   end subroutine tred3
end interface
!-----------------------------------------------------------------------
!               Eigenvalues of symmetric real matrices
!-----------------------------------------------------------------------
!
if (ka == 0) go to 10
call tred1(ka, n, a, w, t, t)
call imtql1(n, w, t, ierr)
return
10 l = n*(n + 1)
l = l/2
call tred3(n, l, a, w, t, t)
call imtql1(n, w, t, ierr)
end subroutine seig1

pure subroutine seigv(a, ka, n, w, z, t, ierr)
implicit none
integer, intent(inout) :: ierr
integer, intent(in) :: ka, n
real, intent(in) :: a(ka,n)
real, intent(inout) :: w(n), z(ka,n), t(n)
interface
   pure subroutine tql2(nm,n,d,e,z,ierr)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      real, intent(inout) :: d(n)
      real, intent(inout) :: e(n)
      real, intent(inout) :: z(nm,n)
      integer, intent(out) :: ierr
   end subroutine tql2
   pure subroutine tred2(nm,n,a,d,e,z)
      implicit none
      integer, intent(in) :: n
      integer, intent(in) :: nm
      real, intent(in) :: a(nm,n)
      real, intent(inout) :: d(n)
      real, intent(inout) :: e(n)
      real, intent(inout) :: z(nm,n)
   end subroutine tred2
end interface
!-----------------------------------------------------------------------
!        Eigenvalues and eigenvectors of symmetric real matrices
!-----------------------------------------------------------------------
!
call tred2(ka, n, a, w, t, z)
call tql2(ka, n, w, t, z, ierr)
end subroutine seigv

pure subroutine seigv1(a, ka, n, w, z, t, ierr)
implicit none
integer, intent(inout) :: ierr
