pure subroutine rnor(ix, a, n, ierr)
implicit none
integer, intent(inout) :: ierr, ix
integer, intent(in) :: n
real, intent(inout) :: a(n)
integer :: i, m
real :: r, s, u, v, t(2)
integer, parameter :: max = 2147483647
interface
   pure subroutine rcir1(n,ix,x,kx,y,ky,ierr)
      implicit none
      integer, intent(in) :: n
      integer, intent(inout) :: ix
      real, intent(inout) :: x(*)
      integer, intent(in) :: kx
      real, intent(inout) :: y(*)
      integer, intent(in) :: ky
      integer, intent(inout) :: ierr
   end subroutine rcir1
end interface
!-----------------------------------------------------------------------
!                 Normal random number generator
!-----------------------------------------------------------------------
!---------------------
!---------------------
if (n <= 0) go to 100
if (ix <= 0 .or. ix >= max) go to 110
ierr = 0
!
if (n == 1) go to 20
m = n/2
call rcir1(m, ix, a(1), 2, a(2), 2, ierr)
m = m + m
!
!                  Obtain the first m variates
!
do i = 1,m,2
   u = a(i)
   v = a(i + 1)
   r = u*u + v*v
   s = sqrt(-2.0*log(r)/r)
   a(i) = s*u
   a(i + 1) = s*v
end do
if (m == n) return
!
!            Obtain the last variate (when n is odd)
!
20 call rcir1(1, ix, t(1), 1, t(2), 1, ierr)
r = t(1)*t(1) + t(2)*t(2)
s = sqrt(-2.0*log(r)/r)
a(n) = s*t(1)
return
!
!                         Error return
!
100 ierr = 1
return
110 ierr = 2
end subroutine rnor

pure subroutine drnor(ix, a, n, ierr)
implicit none
integer, intent(inout) :: ierr, ix
integer, intent(in) :: n
double precision, intent(inout) :: a(n)
integer :: i, m
double precision :: r, s, u, v, t(2)
integer, parameter :: max = 2147483647
interface
   pure subroutine drcir1(n,ix,x,kx,y,ky,ierr)
      implicit none
      integer, intent(in) :: n
      integer, intent(inout) :: ix
      double precision, intent(inout) :: x(*)
      integer, intent(in) :: kx
      double precision, intent(inout) :: y(*)
      integer, intent(in) :: ky
      integer, intent(inout) :: ierr
   end subroutine drcir1
end interface
!-----------------------------------------------------------------------
!                 Normal random number generator
!-----------------------------------------------------------------------
!---------------------
!---------------------
if (n <= 0) go to 100
if (ix <= 0 .or. ix >= max) go to 110
ierr = 0
!
if (n == 1) go to 20
m = n/2
call drcir1(m, ix, a(1), 2, a(2), 2, ierr)
m = m + m
!
!                  Obtain the first m variates
!
do i = 1,m,2
   u = a(i)
   v = a(i + 1)
   r = u*u + v*v
   s = sqrt(-2.d0*log(r)/r)
   a(i) = s*u
   a(i + 1) = s*v
end do
if (m == n) return
!
!            Obtain the last variate (when n is odd)
!
20 call drcir1(1, ix, t(1), 1, t(2), 1, ierr)
r = t(1)*t(1) + t(2)*t(2)
s = sqrt(-2.d0*log(r)/r)
a(n) = s*t(1)
return
!
!                         Error return
!
100 ierr = 1
return
110 ierr = 2
end subroutine drnor

pure subroutine nrng(ix, a, n, ierr)
implicit none
integer, intent(inout) :: ierr, ix
integer, intent(in) :: n
real, intent(inout) :: a(n)
integer :: i, m
real :: phi, r, temp(1)
real, parameter :: pi2 = 6.2831853071796
interface
   pure subroutine urng(ix,x,n,ierr)
      implicit none
      integer, intent(in) :: n
      integer, intent(inout) :: ix
      real, intent(inout) :: x(n)
      integer, intent(inout) :: ierr
   end subroutine urng
end interface
!-----------------------------------------------------------------------
!                 Gaussian random number generator
!-----------------------------------------------------------------------
!
call urng(ix,a,n,ierr)
if (ierr /= 0) return
if (n == 1) go to 20
!
m = n/2
m = m + m
do i = 1,m,2
   r = sqrt(-2.0*log(a(i)))
   phi = pi2*a(i + 1)
   a(i) = r*cos(phi)
10 a(i + 1) = r*sin(phi)
end do
if (m == n) return
!
20 call urng(ix,temp,1,ierr)
r = sqrt(-2.0*log(a(n)))
a(n) = r*cos(pi2*temp(1))
end subroutine nrng

